function convertTime(time) {
  // Split the time string into hours, minutes, and seconds
  var timeArr = time.split(':');
  var hours = parseInt(timeArr[0]);
  var minutes = parseInt(timeArr[1]);
  var seconds = parseInt(timeArr[2]);

  // Determine the AM/PM indicator
  var indicator = (hours >= 12) ? 'PM' : 'AM';

  // Convert hours to 12-hour format
  hours = (hours > 12) ? (hours - 12) : hours;
  hours = (hours === 0) ? 12 : hours;

  // Format the converted time as a string
  var convertedTime = hours + ':' + (minutes < 10 ? '0' + minutes : minutes) + ':' + (seconds < 10 ? '0' + seconds : seconds) + ' ' + indicator;

  return convertedTime;
}

