public class AcademicRecord {
    private String name;
    private int age;
    private int[] grades;

    public AcademicRecord(String name, int age) {
        this.name = name;
        this.age = age;
        this.grades = new int[5];
    }

    public double calculateAverageGrade() {
        int sum = 0;
        int count = 0;
        for (int grade : grades) {
            sum += grade;
            if (grade != 0) {
                count++;
            }
        }
        if (count == 0) {
            return 0;
        }
        double average = (double) sum / count;
        return Math.round(average * 100.0) / 100.0;
    }

    public int getGradeByIndex(int index) {
        if (validateIndex(index)) {
            return grades[index];
        } else {
            throw new IllegalArgumentException("Invalid index");
        }
    }

    public void setGradeByIndex(int index, int grade) {
        if (validateIndex(index) && validateGrade(grade)) {
            grades[index] = grade;
        } else {
            throw new IllegalArgumentException("Invalid index or grade");
        }
    }

    public boolean validateGrade(int grade) {
        return grade >= 0 && grade <= 100;
    }

    public boolean validateIndex(int index) {
        return index >= 0 && index < grades.length;
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        sb.append("Name: ").append(name).append("\n");
        sb.append("Age: ").append(age).append("\n");
        sb.append("Grades: ").append("\n");
        for (int i = 0; i < grades.length; i++) {
            sb.append("Subject ").append(i + 1).append(": ").append(grades[i]).append("\n");
        }
        sb.append("Average Grade: ").append(calculateAverageGrade()).append("\n");
        return sb.toString();
    }
}
