```python
class Rectangle:
    def __init__(self, length, width):
        if length <= 0 or width <= 0:
            raise ValueError("Length and width must be positive integers.")
        self.length = length
        self.width = width

    def area(self):
        return self.length * self.width

    def perimeter(self):
        return 2 * (self.length + self.width)

    def diagonal(self):
        return (self.length**2 + self.width**2)**0.5

    def is_square(self):
        if self.length == self.width and self.length > 0:
            return True
        else:
            return False
