Here's an example of a program in Python that can find all prime numbers up to a given limit n and determine the sum of their prime factors:

```python
def is_prime(num):
    if num <= 1:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def sum_prime_factors(num):
    prime_factors = []
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0 and is_prime(i):
            prime_factors.append(i)
    return sum(prime_factors)

def find_prime_numbers(n):
    primes = []
    for num in range(2, n+1):
        if is_prime(num):
            primes.append(num)
            print("Prime Number:", num)
            print("Sum of Prime Factors:", sum_prime_factors(num))
            print("------------------------")
    return primes

