    this.hands = [];
    this.currentHandIndex = 0;
    this.bankroll = 100;
    this.bet = 0;
  }

  addHand(hand) {
    this.hands.push(hand);
  }

  getCurrentHand() {
    return this.hands[this.currentHandIndex];
  }

  splitHand() {
    const currentHand = this.getCurrentHand();
    const newHand = new Hand();
    newHand.addCard(currentHand.cards.pop());
    this.addHand(newHand);
    this.bet += this.bet;
    this.bankroll -= this.bet;
  }

  doubleDown(deck) {
    const currentHand = this.getCurrentHand();
    this.bet += this.bet;
    this.bankroll -= this.bet;
    currentHand.addCard(deck.dealCard());
    this.stand(deck);
  }

  hit(deck) {
    const currentHand = this.getCurrentHand();
    currentHand.addCard(deck.dealCard());
    currentHand.adjustForAce();
    if (currentHand.total > 21) {
      this.stand(deck);
    }
  }

  stand(deck) {
    this.currentHandIndex++;
    if (this.currentHandIndex === this.hands.length) {
      this.dealerPlay(deck);
    }
  }

  dealerPlay(deck) {
    const dealerHand = new Hand();
    while (dealerHand.total < 17) {
      dealerHand.addCard(deck.dealCard());
      dealerHand.adjustForAce();
    }
    this.compareHands(dealerHand);
  }

  compareHands(dealerHand) {
    for (let hand of this.hands) {
      if (hand.total > 21) {
        console.log('You busted!');
      } else if (dealerHand.total > 21) {
