```java
public static int countVowels(String input) {
    // Initialize a counter variable to keep track of the number of vowels
    int count = 0;

    // Convert the input string to lowercase to simplify comparison
    String lowercaseInput = input.toLowerCase();

    // Iterate through each character in the input string
    for (int i = 0; i < lowercaseInput.length(); i++) {
        // Get the current character
        char c = lowercaseInput.charAt(i);

        // Check if the character is a vowel
        if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') {
            // If the character is a vowel, increment the count
            count++;
        }
    }

    // Return the total count of vowels in the input string
    return count;
}
