```java
public class BankAccount {
    private String accountNumber;
    private String accountHolderName;
    private double accountBalance;
    private boolean isActive;

    public BankAccount(String accountNumber, String accountHolderName) {
        this.accountNumber = accountNumber;
        this.accountHolderName = accountHolderName;
        this.accountBalance = Math.random() * (10000 - 1000 + 1) + 1000;
        this.isActive = true;
    }

    public String getAccountNumber() {
        return accountNumber;
    }

    public void setAccountNumber(String accountNumber) {
        this.accountNumber = accountNumber;
    }

    public String getAccountHolderName() {
        return accountHolderName;
    }

    public void setAccountHolderName(String accountHolderName) {
        this.accountHolderName = accountHolderName;
    }

    public double getAccountBalance() {
        return accountBalance;
    }

    public void setAccountBalance(double accountBalance) throws InvalidBalanceException {
        if (accountBalance < 0 || accountBalance > 1000000) {
            throw new InvalidBalanceException("Invalid balance amount");
        }
        this.accountBalance = accountBalance;
    }

    public boolean isActive() {
        return isActive;
    }

    public void setActive(boolean isActive) {
        this.isActive = isActive;
    }

    public void deposit(double amount) throws InvalidAmountException {
        if (amount < 0 || amount > 10000) {
            throw new InvalidAmountException("Invalid deposit amount");
        }
        accountBalance += amount;
    }

    public void withdraw(double amount) throws InvalidAmountException, InvalidBalanceException {
        if (amount < 0 || amount > 10000) {
            throw new InvalidAmountException("Invalid withdrawal amount");
        }
        if (accountBalance - amount < 0) {
            throw new InvalidBalanceException("Insufficient balance");
        }
        accountBalance -= amount;
    }
}
