Here is the implementation of the Car class with the requested features:

```python
class Car:
    valid_colors = ['red', 'blue', 'green', 'yellow', 'black', 'white', 'silver', 'gray']

    def __init__(self, make, model, year, color, mileage):
        self.make = self.validate_string(make, "Make")
        self.model = self.validate_string(model, "Model")
        self.year = self.validate_positive_integer(year, "Year")
        self.color = self.validate_color(color, "Color")
        self.mileage = self.validate_non_negative_float(mileage, "Mileage")
        self.isRunning = False

    def start(self):
        self.isRunning = True

    def validate_string(self, value, attribute):
        if not value:
            raise ValueError(attribute + " must be a non-empty string")
        if not value.isalnum():
            raise ValueError(attribute + " must be an alphanumeric string")
        return value

    def validate_positive_integer(self, value, attribute):
        if not isinstance(value, int) or value <= 0:
            raise ValueError(attribute + " must be a positive integer")
        return value

    def validate_color(self, value, attribute):
        if not value or value.lower() not in self.valid_colors:
            raise ValueError(attribute + " must be a valid color")
        return value

    def validate_non_negative_float(self, value, attribute):
        if not isinstance(value, float) or value < 0:
            raise ValueError(attribute + " must be a non-negative float")
        return value
```

