// Function to check if a year is a leap year
bool isLeapYear(int year) {
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}

// Function to check if a date is valid
bool isValidDate(int month, int day, int year) {
    if (year < 1900 || year > 2099) {
        return false;
    }
    if (month < 1 || month > 12) {
        return false;
    }
    if (day < 1 || day > 31) {
        return false;
    }
    if (month == 2) {
        if (isLeapYear(year)) {
            return day <= 29;
        } else {
            return day <= 28;
        }
    }
    if (month == 4 || month == 6 || month == 9 || month == 11) {
        return day <= 30;
    }
    return true;
}

// Function to convert a date to the format mm/dd/yyyy
std::string formatDate(int month, int day, int year) {
    std::ostringstream oss;
    oss << std::setw(2) << std::setfill('0') << month << '/';
    oss << std::setw(2) << std::setfill('0') << day << '/';
    oss << year;
    return oss.str();
}

// Function to check if a string is a valid date in the format mm/dd/yyyy
bool isValidDateFormat(const std::string& date) {
    std::vector<std::string> validFormats = { "mm/dd/yyyy", "dd-mm-yyyy", "yyyy-mm-dd" };
    for (const std::string& format : validFormats) {
        if (date.length() == format.length()) {
            bool isValid = true;
            for (size_t i = 0; i < date.length(); i++) {
                if (format[i] == 'm' || format[i] == 'd' || format[i] == 'y') {
                    if (!isdigit(date[i])) {
                        isValid = false;
                        break;
                    }
                } else if (date[i] != format[i]) {
                    isValid = false;
                    break;
                }
            }
            if (isValid) {
                return true;
            }
        }
    }
    return false;
}

// Function to convert a date from a given format to mm/dd/yyyy format
std::string convertToDateFormat(const std::string& date) {
    std::string format = "";
    std::string separators = "";
    for (char c : date) {
        if (isdigit(c)) {
            format += 'y';
        } else {
            format += c;
            if (isalpha(c)) {
                separators += c;
            }
        }
    }
    std::istringstream iss(date);
    std::string token;
    std::vector<std::string> tokens;
    while (getline(iss, token, separators[0])) {
        tokens.push_back(token);
    }
    int month, day, year;
    if (format == "mm/dd/yyyy") {
        month = stoi(tokens[0]);
        day = stoi(tokens[1]);
        year = stoi(tokens[2]);
    } else if (format == "dd-mm-yyyy") {
        day = stoi(tokens[0]);
        month = stoi(tokens[1]);
        year = stoi(tokens[2]);
    } else if (format == "yyyy-mm-dd") {
        year = stoi(tokens[0]);
        month = stoi(tokens[1]);
        day = stoi(tokens[2]);
    }
    return formatDate(month, day, year);
}

int main() {
    std::string date;
    std::cout << "Enter a date in any valid format (mm/dd/yyyy, dd-mm-yyyy, yyyy-mm-dd): ";
    std::cin >> date;
    if (!isValidDateFormat(date)) {
        std::cout << "Invalid date format!" << std::endl;
        return 0;
    }
    std::string formattedDate = convertToDateFormat(date);
    std::istringstream iss(formattedDate);
    int month, day, year;
    char separator;
    iss >> month >> separator >> day >> separator >> year;
    if (!isValidDate(month, day, year)) {
        std::cout << "Invalid date!" << std::endl;
        return 0;
    }
    std::cout << "Formatted date: " << formattedDate << std::endl;
    return 0;
}
