    if (typeof hobby !== "string" || hobby.trim() === "") {
      throw new Error("Hobby should be a non-empty string");
    }
    if (this.hobbies.includes(hobby)) {
      throw new Error("Hobby already exists in the list");
    }
    this.hobbies.push(hobby);
  }

  removeHobby(hobby) {
    if (typeof hobby !== "string" || hobby.trim() === "") {
      throw new Error("Hobby should be a non-empty string");
    }
    if (!this.hobbies.includes(hobby)) {
      throw new Error("Hobby does not exist in the list");
    }
    this.hobbies = this.hobbies.filter((h) => h !== hobby);
  }

  getHobbies() {
    return this.hobbies;
  }

  static getAverageAge(people) {
    const sum = people.reduce((total, person) => total + person.age, 0);
    const average = sum / people.length;
    return Math.round(average);
  }

  static getMostCommonHobby(people) {
    const hobbyCounts = {};
    let maxCount = 0;
    let mostCommonHobby = "";

    for (const person of people) {
      for (const hobby of person.hobbies) {
        if (hobbyCounts[hobby]) {
          hobbyCounts[hobby]++;
        } else {
          hobbyCounts[hobby] = 1;
        }
        if (hobbyCounts[hobby] > maxCount) {
          maxCount = hobbyCounts[hobby];
          mostCommonHobby = hobby;
        }
      }
    }

