Here is a C++ program that implements the modified Caesar cipher algorithm:

```cpp
#include <iostream>
#include <string>

std::string caesarCipher(const std::string& str, int shift) {
    std::string encryptedString = "";

    for (char c : str) {
        if (isupper(c)) {
            // Apply positive shift to uppercase letters
            char encryptedChar = ((c - 'A' + shift) % 26) + 'A';
            encryptedString += encryptedChar;
        } else if (islower(c)) {
            // Apply negative shift to lowercase letters
            char encryptedChar = ((c - 'a' - shift) % 26) + 'a';
            encryptedString += encryptedChar;
        } else {
            // Leave other characters unchanged
            encryptedString += c;
        }
    }

    return encryptedString;
}

int main() {
    std::string str;
    int shift;

    std::cout << "Enter the string to encrypt: ";
    std::getline(std::cin, str);

    std::cout << "Enter the shift value: ";
    std::cin >> shift;

    std::string encryptedStr = caesarCipher(str, shift);
    std::cout << "Encrypted string: " << encryptedStr << std::endl;

    return 0;
}
```

In this program, the `caesarCipher` function takes a string and a shift value as input and returns the encrypted string. The function iterates over each character in the input string and applies the shift value based on the character's case. The resulting encrypted characters are concatenated to form the encrypted string.

