def isAnagram(str1, str2):
    # Check if both strings are empty
    if not str1 and not str2:
        return False

    # Convert the strings to lowercase and remove any spaces
    str1 = str1.lower().replace(" ", "")
    str2 = str2.lower().replace(" ", "")

    # Check if the lengths of the strings are different
    if len(str1) != len(str2):
        return False

    # Check if both strings contain at least one vowel and one consonant
    vowels = set("aeiou")
    consonants = set("bcdfghjklmnpqrstvwxyz")
    has_vowel = False
    has_consonant = False

    for char in str1:
        if char in vowels:
            has_vowel = True
        elif char in consonants:
            has_consonant = True

        if has_vowel and has_consonant:
            break

    if not (has_vowel and has_consonant):
        return False

    for char in str2:
        if char in vowels:
            has_vowel = True
        elif char in consonants:
            has_consonant = True

        if has_vowel and has_consonant:
            break

    if not (has_vowel and has_consonant):
        return False

    # Check if the strings are anagrams of each other
    return sorted(str1) == sorted(str2)
