def sum_round(num1: float, num2: float, decimal_places: int = None, round_halfway: str = None, error_message: str = None) -> int:
    # Check if input numbers are within the range of -1000 to 1000
    if num1 < -1000 or num1 > 1000 or num2 < -1000 or num2 > 1000:
        if error_message:
            raise Exception(error_message)
        else:
            raise Exception("Input numbers are outside the range of -1000 to 1000")

    # Calculate the sum of the two numbers
    sum_result = num1 + num2

    # Round the result to the specified decimal places if provided
    if decimal_places is not None:
        sum_result = round(sum_result, decimal_places)
    else:
        sum_result = round(sum_result)

    # Check if the result is exactly halfway between two integers and round accordingly if round_halfway parameter is provided
    if round_halfway == "up" or round_halfway == "down":
        fraction = sum_result % 1
        if fraction == 0.5:
            if round_halfway == "up":
                sum_result = round(sum_result + 0.1)
            else:
                sum_result = round(sum_result - 0.1)

    return int(sum_result)
