Here's a JavaScript code that prints the pyramid pattern as described:

```javascript
function printPyramidPattern(rows) {
  let currentRow = 1;
  let primeNumbers = [];
  let spaceCount = rows - 1;

  while (currentRow <= rows) {
    // Find the next prime number
    let primeNumber = getNextPrime(primeNumbers);

    // Calculate the sum of all numbers in the row
    let rowSum = primeNumber;

    for (let i = 1; i < currentRow; i++) {
      primeNumber += 2;
      rowSum += primeNumber;
    }

    // Check if the sum is a perfect square
    let squareRoot = Math.sqrt(rowSum);
    if (Math.floor(squareRoot) === squareRoot) {
      // Print the row with spaces
      let rowOutput = ' '.repeat(spaceCount);

      for (let i = 0; i < currentRow; i++) {
        rowOutput += primeNumbers[i] + ' ';
        primeNumbers[i] += 2;
      }

      console.log(rowOutput.trim());
      currentRow++;
      spaceCount--;
    }
  }
}

function getNextPrime(primeNumbers) {
  let number = primeNumbers.length > 0 ? primeNumbers[primeNumbers.length - 1] + 2 : 3;

  while (true) {
    if (isPrime(number)) {
      primeNumbers.push(number);
      return number;
    }
    number += 2;
  }
}

function isPrime(number) {
  for (let i = 2, sqrt = Math.sqrt(number); i <= sqrt; i++) {
    if (number % i === 0) {
      return false;
    }
  }
  return number > 1;
}

// Example usage
printPyramidPattern(5);
```

