func fibonacciWithPrimes(count: Int) -> [Int] {
    var fibonacciSequence: [Int] = [0, 1]
    var primeNumbers: [Int] = []

    while primeNumbers.count < count {
        let nextFibonacciNumber = fibonacciSequence[fibonacciSequence.count - 1] + fibonacciSequence[fibonacciSequence.count - 2]
