```javascript
function camelToSnake(camelCase) {
  let snakeCase = '';

  for (let i = 0; i < camelCase.length; i++) {
    const char = camelCase[i];

    if (char === char.toLowerCase()) {
      snakeCase += char;
    } else {
      snakeCase += '_' + char.toLowerCase();
    }
  }

  return snakeCase;
}
