import java.util.Scanner;

public class BaseConverter {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter the number to convert: ");
        String numberString = scanner.nextLine();

        System.out.print("Enter the base of the number: ");
        int baseFrom = scanner.nextInt();

        System.out.print("Enter the base to convert to: ");
        int baseTo = scanner.nextInt();

        System.out.print("Enter the precision for decimal numbers: ");
        int precision = scanner.nextInt();

        System.out.print("Choose little-endian (1) or big-endian (2) representation: ");
        int endianOption = scanner.nextInt();
        boolean isLittleEndian = endianOption == 1;

        try {
            if (baseFrom == 10 && baseTo == 10) {
                convertDecimalToDecimal(numberString, precision);
            } else if (baseFrom == 10) {
                convertDecimalToBase(numberString, baseTo, precision, isLittleEndian);
            } else if (baseTo == 10) {
                convertBaseToDecimal(numberString, baseFrom, precision);
            } else {
                convertBaseToBase(numberString, baseFrom, baseTo, precision, isLittleEndian);
            }
        } catch (IllegalArgumentException e) {
            System.out.println("Invalid input: " + e.getMessage());
        }
    }

    private static void convertDecimalToDecimal(String numberString, int precision) {
        double number = Double.parseDouble(numberString);
        System.out.printf("Converted number: %." + precision + "f%n", number);
    }

    private static void convertDecimalToBase(String numberString, int baseTo, int precision, boolean isLittleEndian) {
        int integerPart = Integer.parseInt(numberString.split("\\.")[0]);
        String decimalPart = numberString.split("\\.")[1];

        StringBuilder convertedInteger = new StringBuilder();
        while (integerPart != 0) {
            int remainder = integerPart % baseTo;
            convertedInteger.append(remainder);
            integerPart /= baseTo;
        }

        String convertedFraction = convertFractionToBase(decimalPart, baseTo, precision);

        if (isLittleEndian) {
            System.out.println("Converted number: " + convertedFraction + "." + convertedInteger.reverse());
        } else {
            System.out.println("Converted number: " + convertedInteger.reverse() + "." + convertedFraction);
        }
    }

    private static String convertFractionToBase(String fractionPart, int baseTo, int precision) {
        StringBuilder convertedFraction = new StringBuilder();

        double fraction = Double.parseDouble("0." + fractionPart);
        for (int i = 0; i < precision; i++) {
            fraction *= baseTo;
            int digit = (int) fraction;
            convertedFraction.append(digit);
            fraction -= digit;
        }

        return convertedFraction.toString();
    }

    private static void convertBaseToDecimal(String numberString, int baseFrom, int precision) {
        int integerPart = 0;
        String decimalPart = "";

        if (numberString.contains(".")) {
            integerPart = Integer.parseInt(numberString.split("\\.")[0]);
            decimalPart = numberString.split("\\.")[1];
        } else {
            integerPart = Integer.parseInt(numberString);
        }

        int convertedInteger = 0;
        int power = 0;
        while (integerPart != 0) {
            int digit = integerPart % 10;
            if (digit >= baseFrom) {
                throw new IllegalArgumentException("Invalid digit in the number: " + digit);
            }
            convertedInteger += digit * Math.pow(baseFrom, power);
            integerPart /= 10;
            power++;
        }

        double convertedFraction = convertFractionToDecimal(decimalPart, baseFrom, precision);

        double convertedNumber = convertedInteger + convertedFraction;

        System.out.printf("Converted number: %." + precision + "f%n", convertedNumber);
    }

    private static double convertFractionToDecimal(String fractionPart, int baseFrom, int precision) {
        double convertedFraction = 0;

        for (int i = 0; i < fractionPart.length(); i++) {
            int digit = Character.getNumericValue(fractionPart.charAt(i));
            if (digit >= baseFrom) {
                throw new IllegalArgumentException("Invalid digit in the fraction part: " + digit);
            }
            convertedFraction += digit / Math.pow(baseFrom, i + 1);
        }

        return convertedFraction;
    }

    private static void convertBaseToBase(String numberString, int baseFrom, int baseTo, int precision, boolean isLittleEndian) {
        if (baseFrom == 10) {
            convertDecimalToBase(numberString, baseTo, precision, isLittleEndian);
        } else if (baseTo == 10) {
            convertBaseToDecimal(numberString, baseFrom, precision);
        } else {
            convertBaseToBaseRecursive(numberString, baseFrom, baseTo, precision, isLittleEndian);
        }
    }

    private static void convertBaseToBaseRecursive(String numberString, int baseFrom, int baseTo, int precision, boolean isLittleEndian) {
        int integerPart = Integer.parseInt(numberString.split("\\.")[0]);
        String decimalPart = numberString.split("\\.")[1];

        StringBuilder convertedInteger = new StringBuilder();
        while (integerPart != 0) {
            int remainder = integerPart % baseTo;
            convertedInteger.append(remainder);
            integerPart /= baseTo;
        }

        String convertedFraction = convertFractionToBaseRecursive(decimalPart, baseFrom, baseTo, precision);

        if (isLittleEndian) {
            System.out.println("Converted number: " + convertedFraction + "." + convertedInteger.reverse());
        } else {
            System.out.println("Converted number: " + convertedInteger.reverse() + "." + convertedFraction);
        }
    }

    private static String convertFractionToBaseRecursive(String fractionPart, int baseFrom, int baseTo, int precision) {
        if (fractionPart.isEmpty()) {
            return "";
        }

        double fraction = 0;
        int digit = Character.getNumericValue(fractionPart.charAt(0));
        if (digit >= baseFrom) {
            throw new IllegalArgumentException("Invalid digit in the fraction part: " + digit);
        }
        fraction += digit / Math.pow(baseFrom, 1);

        String convertedDigit = Integer.toString((int) (fraction * baseTo));

        return convertedDigit + convertFractionToBaseRecursive(fractionPart.substring(1), baseFrom, baseTo, precision);
    }
}
```

