```java
import java.util.Arrays;

public class SortedArrayMerger {

    public static int[] mergeArrays(int[] arr1, int[] arr2) {
        int n = arr1.length;
        int m = arr2.length;
        int[] mergedArray = new int[n + m];

        if (n == 0) {
            return arr2;
        }
        if (m == 0) {
            return arr1;
        }

        int i = 0, j = 0, k = 0;
        while (i < n && j < m) {
            if (arr1[i] == arr2[j]) {
                mergedArray[k++] = arr1[i++];
                j++;
            } else if (arr1[i] < arr2[j]) {
                mergedArray[k++] = arr1[i++];
            } else {
                mergedArray[k++] = arr2[j++];
            }
        }

        while (i < n) {
            mergedArray[k++] = arr1[i++];
        }
        while (j < m) {
            mergedArray[k++] = arr2[j++];
        }

        int[] sortedArray = Arrays.copyOf(mergedArray, k);
        Arrays.sort(sortedArray);

        if (countNegativeNumbers(arr1) > countNegativeNumbers(arr2)) {
            reverseArray(sortedArray);
        }

        return removeDuplicates(sortedArray);
    }

    private static int countNegativeNumbers(int[] arr) {
        int count = 0;
        for (int num : arr) {
            if (num < 0) {
                count++;
            }
        }
        return count;
    }

    private static void reverseArray(int[] arr) {
        int i = 0, j = arr.length - 1;
        while (i < j) {
            int temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
            i++;
            j--;
        }
    }

    private static int[] removeDuplicates(int[] arr) {
        int n = arr.length;
        if (n <= 1) {
            return arr;
        }

        int k = 0;
        for (int i = 1; i < n; i++) {
            if (arr[i] != arr[k]) {
                arr[++k] = arr[i];
            }
        }

        return Arrays.copyOf(arr, k + 1);
    }
}
```

In this implementation, we first handle the cases where either `arr1` or `arr2` is empty. Then, we merge the two arrays into a new array `mergedArray` by comparing the elements one by one and copying the smaller element to `mergedArray`. After merging, we sort `mergedArray` and remove duplicates using the `removeDuplicates` method. Finally, if there are more negative numbers in `arr1`, we reverse `mergedArray` using the `reverseArray` method.

Note that the time complexity of this implementation is O(n + m) because we iterate through both `arr1` and `arr2` exactly once in the merging process. The sorting step and duplicate removal step take O(n + m) time as well.

