```python
import tkinter as tk
from tkinter import messagebox


# Base class for object creation and common operations
class Shape:
    def __init__(self):
        self.validate_input()

    def validate_input(self):
        raise NotImplementedError

    def calculate_area(self):
        raise NotImplementedError

    def calculate_volume(self):
        raise NotImplementedError


# Derived class for creating a Circle object
class Circle(Shape):
    def __init__(self, radius):
        self.radius = radius
        super().__init__()

    def validate_input(self):
        if not isinstance(self.radius, (int, float)):
            raise ValueError("Radius must be a number.")
        if self.radius <= 0:
            raise ValueError("Radius must be greater than zero.")

    def calculate_area(self):
        return 3.14159 * self.radius ** 2


# Derived class for creating a Rectangle object
class Rectangle(Shape):
    def __init__(self, length, width):
        self.length = length
        self.width = width
        super().__init__()

    def validate_input(self):
        if not isinstance(self.length, (int, float)):
            raise ValueError("Length must be a number.")
        if self.length <= 0:
            raise ValueError("Length must be greater than zero.")
        if not isinstance(self.width, (int, float)):
            raise ValueError("Width must be a number.")
        if self.width <= 0:
            raise ValueError("Width must be greater than zero.")

    def calculate_area(self):
        return self.length * self.width


# Composition class for handling GUI interface
class GUI:
    def __init__(self):
        self.window = tk.Tk()
        self.input_frame = tk.Frame(self.window)
        self.input_frame.pack()

        self.length_entry = tk.Entry(self.input_frame)
        self.length_entry.pack(side=tk.LEFT)
        self.width_entry = tk.Entry(self.input_frame)
        self.width_entry.pack(side=tk.LEFT)
        self.radius_entry = tk.Entry(self.input_frame)
        self.radius_entry.pack(side=tk.LEFT)

        self.create_button = tk.Button(self.window, text="Create", command=self.create_object)
        self.create_button.pack()

    def create_object(self):
        try:
            length = float(self.length_entry.get())
            width = float(self.width_entry.get())
            radius = float(self.radius_entry.get())

            rectangle = Rectangle(length, width)
            circle = Circle(radius)

            messagebox.showinfo("Area", f"Rectangle area: {rectangle.calculate_area()}\nCircle area: {circle.calculate_area()}")

        except Exception as e:
