```php
function extractSubstring($string, $start, $length) {
    $result = '';
    $stringLength = mb_strlen($string);

    if ($start >= $stringLength || $start + $length <= 0) {
        return $result;
    }

    if ($start < 0) {
        $start = max(0, $stringLength + $start);
    }

    if ($length < 0) {
        $length = max(0, $stringLength - $start + $length);
    }

    for ($i = $start; $i < $start + $length && $i < $stringLength; $i++) {
        $char = mb_substr($string, $i, 1);

        if (ctype_alpha($char)) {
            $result .= mb_strtolower($char);
        }
    }

    return strrev($result);
}

// Example usage:
