Here's a C++ program that checks whether a number is prime or not using the Miller-Rabin primality test. It also includes a function to generate a large prime number using the Rabin-Miller algorithm:

```cpp
#include <iostream>
#include <cmath>
#include <chrono>
#include <random>

using namespace std;

// Function to check if a number is prime using Miller-Rabin primality test
bool isPrime(int n, int k) {
    // Check if n is a power of 2
    if (n <= 1 || n == 4) {
        return false;
    }
    if (n <= 3) {
        return true;
    }

    // Find r such that n = 2^d * r + 1 for some r >= 1
    int d = n - 1;
    while (d % 2 == 0) {
        d /= 2;
    }

    // Run Miller-Rabin primality test k times
    for (int i = 0; i < k; i++) {
        // Generate a random number between 2 and n-2
        int a = 2 + rand() % (n - 3);

        // Compute a^d % n
        int x = pow(a, d) % n;

        // Check if x is 1 or n-1
        if (x == 1 || x == n - 1) {
            continue;
        }

        // Repeat squaring x for d times
        while (d != n - 1) {
            x = (x * x) % n;
            d *= 2;

            // If x is 1, then n is composite
            if (x == 1) {
                return false;
            }

            // If x is n-1, then continue with next iteration
            if (x == n - 1) {
                break;
            }
        }

        // If none of the above conditions are satisfied, then n is composite
        if (x != n - 1) {
            return false;
        }
    }

    // If all iterations passed, then n is probably prime
    return true;
}

// Function to generate a large prime number using Rabin-Miller algorithm
int generateLargePrime(int bits, int k) {
    // Generate a random number with specified number of bits
    random_device rd;
    mt19937 gen(rd());
    uniform_int_distribution<unsigned long long> dist(0, pow(2, bits) - 1);
    int n = dist(gen);

    // Keep incrementing n until a prime number is found
    while (!isPrime(n, k)) {
        n++;
    }

    return n;
}

int main() {
    int num;

    // Validate user input to ensure it is a positive integer greater than 1
    while (true) {
        cout << "Enter a positive integer greater than 1: ";
        cin >> num;

        if (num <= 1) {
            cout << "Invalid input. Please try again." << endl;
        } else {
            break;
        }
    }

    // Check if the number is prime using Miller-Rabin primality test
    auto start = chrono::high_resolution_clock::now();
    bool prime = isPrime(num, 5);
    auto end = chrono::high_resolution_clock::now();
    auto duration = chrono::duration_cast<chrono::microseconds>(end - start);

    // Display the result and time taken
    if (prime) {
        cout << num << " is a prime number." << endl;
    } else {
        cout << num << " is not a prime number." << endl;
    }
    cout << "Time taken: " << duration.count() << " microseconds" << endl;

    // Generate a large prime number using Rabin-Miller algorithm
    int largePrime = generateLargePrime(1024, 5);
    cout << "Generated large prime number: " << largePrime << endl;

    return 0;
}
```

Note: The program uses the `rand()` function to generate random numbers. For better random number generation, you can use the `<random>` library as shown in the `generateLargePrime` function.

