```jsx
import React, { useState, useEffect } from 'react';

const Table = ({ data }) => {
  const [sortedData, setSortedData] = useState([]);
  const [filteredData, setFilteredData] = useState([]);
  const [currentPage, setCurrentPage] = useState(1);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [searchTerm, setSearchTerm] = useState('');
  const [sortColumns, setSortColumns] = useState([]);

  useEffect(() => {
    setSortedData(data);
    setFilteredData(data);
  }, [data]);

  useEffect(() => {
    const filterData = () => {
      const filtered = data.filter((person) => {
        return Object.values(person).some((value) =>
          String(value).toLowerCase().includes(searchTerm.toLowerCase())
        );
      });
      setFilteredData(filtered);
    };

    const sortData = () => {
      const sorted = [...filteredData];
      sorted.sort((a, b) => {
        for (let i = 0; i < sortColumns.length; i++) {
          const { column, direction } = sortColumns[i];
          if (a[column] < b[column]) {
            return direction === 'asc' ? -1 : 1;
          }
          if (a[column] > b[column]) {
            return direction === 'asc' ? 1 : -1;
          }
        }
        return 0;
      });
      setSortedData(sorted);
    };

    filterData();
    sortData();
  }, [searchTerm, sortColumns]);

  const handleSort = (column) => {
    let newSortColumns = [...sortColumns];
    const existingSort = sortColumns.find((sort) => sort.column === column);

    if (existingSort) {
      const newDirection = existingSort.direction === 'asc' ? 'desc' : 'asc';
      existingSort.direction = newDirection;
    } else {
      newSortColumns = [{ column, direction: 'asc' }, ...sortColumns];
    }

    setSortColumns(newSortColumns);
  };

  const handleSearch = (e) => {
    setSearchTerm(e.target.value);
  };

  const handlePageChange = (page) => {
    setCurrentPage(page);
  };

  const handleRowsPerPageChange = (e) => {
    setRowsPerPage(Number(e.target.value));
    setCurrentPage(1);
  };

  const indexOfLastRow = currentPage * rowsPerPage;
  const indexOfFirstRow = indexOfLastRow - rowsPerPage;
  const currentRows = sortedData.slice(indexOfFirstRow, indexOfLastRow);

  const renderTableHeader = () => {
    return (
      <tr>
        <th onClick={() => handleSort('name')}>Name</th>
        <th onClick={() => handleSort('age')}>Age</th>
        <th onClick={() => handleSort('job')}>Job</th>
      </tr>
    );
  };

  const renderTableBody = () => {
    return currentRows.map((person, index) => (
      <tr key={index}>
        <td>{person.name}</td>
        <td>{person.age}</td>
        <td>{person.job}</td>
      </tr>
    ));
  };

  const renderPagination = () => {
    const pageNumbers = Math.ceil(sortedData.length / rowsPerPage);

    if (pageNumbers <= 1) {
      return null;
    }

    const pages = [];
    for (let i = 1; i <= pageNumbers; i++) {
      pages.push(
        <button
          key={i}
          onClick={() => handlePageChange(i)}
          disabled={i === currentPage}
        >
          {i}
        </button>
      );
    }

    return (
      <div>
        {pages}
        <select value={rowsPerPage} onChange={handleRowsPerPageChange}>
          <option value={10}>10</option>
          <option value={20}>20</option>
          <option value={30}>30</option>
        </select>
      </div>
    );
  };

  return (
    <div>
      <input type="text" placeholder="Search..." onChange={handleSearch} />
      <table>
        <thead>{renderTableHeader()}</thead>
        <tbody>{renderTableBody()}</tbody>
      </table>
      {renderPagination()}
    </div>
  );
};

export default Table;
```

