  let colStart = 0;
  let colEnd = n - 1;

  while (rowStart <= rowEnd && colStart <= colEnd) {
    // Print numbers in top row
    for (let i = colStart; i <= colEnd; i++) {
      pattern[rowStart][i] = num++;
    }
    rowStart++;

    // Print numbers in right column
