function validatePhoneNumber(phoneNumber) {
  // Remove any spaces or dashes
  phoneNumber = phoneNumber.replace(/\s+/g, '').replace(/-/g, '');

  // Check if the phone number starts with a plus sign and optional country code
  if (phoneNumber.charAt(0) === '+') {
    // If it starts with a plus sign, the next character should be an opening parenthesis
    if (phoneNumber.charAt(1) !== '(') {
      return false;
    }

    // Find the index of the closing parenthesis
    var closingParenthesisIndex = phoneNumber.indexOf(')');

    // Check if there is a closing parenthesis and if it is at the correct position
    if (closingParenthesisIndex === -1 || closingParenthesisIndex !== 4) {
      return false;
    }

    // Check if the country code and area code (inside the parentheses) are valid
    var countryCode = phoneNumber.substring(2, 4);
    var areaCode = phoneNumber.substring(5, closingParenthesisIndex);
    if (!isValidNumber(countryCode) || !isValidNumber(areaCode)) {
      return false;
    }

    // The remaining part should consist of 7 digits
    var remainingDigits = phoneNumber.substring(closingParenthesisIndex + 1);
    return isValidNumber(remainingDigits) && remainingDigits.length === 7;
  }

  // If the phone number doesn't start with a plus sign, it should have 10 digits
  return isValidNumber(phoneNumber) && phoneNumber.length === 10;
}

// Helper function to check if a string consists of digits only
