def validate_font_size(font_size):
    try:
        font_size = int(font_size)
        if font_size < 10 or font_size > 40:
            return False
    except ValueError:
        return False
    return True

def validate_font_color(font_color):
    if not font_color.startswith('#') or len(font_color) != 7:
        return False
    try:
        int(font_color[1:], 16)
    except ValueError:
        return False
    return True

if __name__ == '__main__':
