```java
import android.content.Intent;
import android.graphics.Color;
import android.media.MediaPlayer;
import android.net.Uri;
import android.os.Bundle;
import android.os.Handler;
import android.provider.MediaStore;
import android.view.View;
import android.widget.Button;
import android.widget.TextView;

import androidx.appcompat.app.AppCompatActivity;

import java.util.Random;

public class MainActivity extends AppCompatActivity {

    private Button button;
    private TextView textView;
    private Button resetButton;

    private int clickCount = 0;
    private boolean buttonEnabled = true;
    private int timer = 0;
    private Handler handler = new Handler();
    private MediaPlayer mediaPlayer;
    private int textColor;
    private Uri imageUri;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        button = findViewById(R.id.button);
        textView = findViewById(R.id.textView);
        resetButton = findViewById(R.id.resetButton);

        button.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                if (buttonEnabled) {
                    // Update the TextView with the "Hello, World!" text
                    textView.setText("Hello, World!");

                    // Increase the click count and update the TextView
                    clickCount++;
                    textView.setText("Click Count: " + clickCount);
                    textView.setTextSize(16);

                    // Change the button background color to a random color
                    Random rnd = new Random();
                    int color = Color.argb(255, rnd.nextInt(256), rnd.nextInt(256), rnd.nextInt(256));
                    button.setBackgroundColor(color);

                    // Start the timer
                    startTimer();

                    // Change the font color of the TextView
                    int textColor = Color.argb(255, rnd.nextInt(256), rnd.nextInt(256), rnd.nextInt(256));
                    textView.setTextColor(textColor);

                    // Play a sound effect
                    playSoundEffect();

                    // Disable the button after 10 clicks
                    if (clickCount >= 10) {
                        buttonEnabled = false;
                        button.setText("Disabled");
                    }

                    // Enable the reset button after 3 clicks
                    if (clickCount >= 3) {
                        resetButton.setEnabled(true);
                    }
                }
            }
        });

        resetButton.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                // Reset the click count and update the TextView
                clickCount = 0;
                textView.setText("Click Count: " + clickCount);
                textView.setTextSize(20);

                // Restore the button's original background color
                button.setBackgroundResource(android.R.drawable.btn_default);

                // Disable the reset button
                resetButton.setEnabled(false);
            }
        });

        // Add logic to select a custom background image for the button
        button.setOnLongClickListener(new View.OnLongClickListener() {
            @Override
            public boolean onLongClick(View v) {
                Intent intent = new Intent(Intent.ACTION_PICK, MediaStore.Images.Media.EXTERNAL_CONTENT_URI);
                startActivityForResult(intent, 0);
                return true;
            }
        });
    }

    private void startTimer() {
        handler.postDelayed(new Runnable() {
            @Override
            public void run() {
                timer++;
                textView.setText("Elapsed Time: " + timer + " seconds");
                startTimer();
            }
        }, 1000);
    }

    private void playSoundEffect() {
        if (mediaPlayer != null) {
            mediaPlayer.release();
        }
        mediaPlayer = MediaPlayer.create(this, R.raw.sound_effect);
        mediaPlayer.start();
    }

    @Override
    protected void onActivityResult(int requestCode, int resultCode, Intent data) {
        super.onActivityResult(requestCode, resultCode, data);
        if (resultCode == RESULT_OK) {
            if (requestCode == 0) {
                imageUri = data.getData();
                button.setBackground(getDrawable(imageUri));
            }
        }
    }
}
