        // Count the number of vowels in the sentence
        int vowelCount = 0;
        for (int i = 0; i < sentence.length(); i++) {
            char c = Character.toLowerCase(sentence.charAt(i));
            if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') {
                vowelCount++;
            }
        }

        // Display the count of vowels in the sentence
        System.out.println("The sentence contains " + vowelCount + " vowels.");

        // Prompt user to enter a sentence
        System.out.print("Enter a sentence: ");
        sentence = scanner.nextLine();

        // Reverse the sentence
        String reversedSentence = "";
        for (int i = sentence.length() - 1; i >= 0; i--) {
            reversedSentence += sentence.charAt(i);
        }

        // Display the reversed sentence
        System.out.println("The reversed sentence is: " + reversedSentence);

        // Close the scanner
        scanner.close();
    }
}

