import React, { useState, useEffect } from "react";
import "./AlertMessage.css";

const AlertMessage = ({ alerts, dismissCallback }) => {
  const [dismissedAlerts, setDismissedAlerts] = useState([]);
  const [draggingAlert, setDraggingAlert] = useState(null);

  useEffect(() => {
    const handleDismiss = (event) => {
      const alertId = event.currentTarget.dataset.alertId;
      dismissAlert(alertId);
    };

    const handleDragStart = (event) => {
      const alertId = event.currentTarget.dataset.alertId;
      setDraggingAlert(alertId);
    };

    const handleDragEnd = () => {
      setDraggingAlert(null);
    };

    const handleKeyDown = (event) => {
      if (event.key === "Enter") {
        const alertId = event.currentTarget.dataset.alertId;
        dismissAlert(alertId);
      } else if (event.key === "ArrowUp" || event.key === "ArrowDown") {
        const currentIndex = alerts.findIndex(
          (alert) => alert.id === draggingAlert
        );
        let nextIndex;
        if (event.key === "ArrowUp") {
          nextIndex = currentIndex - 1;
        } else {
          nextIndex = currentIndex + 1;
        }
        if (nextIndex >= 0 && nextIndex < alerts.length) {
          setDraggingAlert(alerts[nextIndex].id);
        }
      }
    };

    const dismissAlert = (alertId) => {
      const dismissedAlert = alerts.find((alert) => alert.id === alertId);
      setDismissedAlerts((prevDismissedAlerts) => [
        ...prevDismissedAlerts,
        dismissedAlert,
      ]);
      if (dismissCallback) {
        dismissCallback(dismissedAlert);
      }
    };

    document.addEventListener("keydown", handleKeyDown);

    return () => {
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, [alerts, dismissCallback, draggingAlert]);

  const renderAlert = (alert) => {
    const isDismissed = dismissedAlerts.includes(alert);

    if (isDismissed) {
      return null;
    }

    const alertStyle = {
      backgroundColor: alert.type === "success" ? "green" : alert.type === "warning" ? "yellow" : "red",
    };

    const alertClassName = `alert ${draggingAlert === alert.id ? "dragging" : ""}`;

    return (
      <div
        key={alert.id}
        className={alertClassName}
        style={alertStyle}
        data-alert-id={alert.id}
        draggable
        onDragStart={handleDragStart}
        onDragEnd={handleDragEnd}
      >
        {alert.message}
        <button className="close-button" onClick={handleDismiss} data-alert-id={alert.id}>
          &times;
        </button>
      </div>
    );
  };

  return <div className="alert-container">{alerts.map(renderAlert)}</div>;
};

export default AlertMessage;
```

