```javascript
// Retrieve tasks from local storage if available
const tasks = JSON.parse(localStorage.getItem('tasks')) || [];

// Display tasks on page load
window.onload = function() {
  displayTasks();
}

// Function to add a new task
function addTask() {
  const taskInput = document.getElementById('taskInput');
  const taskValue = taskInput.value.trim();

  if (taskValue !== '') {
    // Create a new task object
    const task = {
      id: new Date().getTime(),
      value: taskValue,
      completed: false
    };

    // Add the task to the tasks array
    tasks.push(task);

    // Save the tasks to local storage
    localStorage.setItem('tasks', JSON.stringify(tasks));

    // Reset the input field
    taskInput.value = '';

    // Display the updated tasks
    displayTasks();
  }
}

// Function to display the tasks on the page
function displayTasks() {
  const taskContainer = document.getElementById('taskContainer');
  taskContainer.innerHTML = '';

  for (let i = 0; i < tasks.length; i++) {
    const task = tasks[i];

    // Create a new task element
    const taskElement = document.createElement('div');
    taskElement.classList.add('task');
    if (task.completed) {
      taskElement.classList.add('completed');
    }

    // Create a checkbox element
    const checkboxElement = document.createElement('input');
    checkboxElement.type = 'checkbox';
    checkboxElement.checked = task.completed;
    checkboxElement.addEventListener('change', function() {
      toggleCompleteTask(task.id);
    });

    // Create a span element for the task value
    const taskValueElement = document.createElement('span');
    taskValueElement.textContent = task.value;

    // Create a button element to delete the task
    const deleteButtonElement = document.createElement('button');
    deleteButtonElement.textContent = 'Delete';
    deleteButtonElement.addEventListener('click', function() {
      deleteTask(task.id);
    });

    // Append elements to the task element
    taskElement.appendChild(checkboxElement);
    taskElement.appendChild(taskValueElement);
    taskElement.appendChild(deleteButtonElement);

    // Append the task element to the container
    taskContainer.appendChild(taskElement);
  }
}

// Function to toggle the completion status of a task
function toggleCompleteTask(id) {
  const task = tasks.find(task => task.id === id);
  task.completed = !task.completed;
  localStorage.setItem('tasks', JSON.stringify(tasks));
  displayTasks();
}

