def caesar_cipher_encrypt(string, shift):
    result = ""
    for char in string:
        if char.isalpha():
            if char.isupper():
                result += chr((ord(char) - 65 + shift) % 26 + 65)
            else:
                result += chr((ord(char) - 97 + shift) % 26 + 97)
        else:
            result += char
    return result


def caesar_cipher_decrypt(encrypted_string):
    decrypted_list = []
    for shift in range(1, 26):
        decrypted = ""
        for char in encrypted_string:
            if char.isalpha():
                if char.isupper():
                    decrypted += chr((ord(char) - 65 - shift) % 26 + 65)
                else:
                    decrypted += chr((ord(char) - 97 - shift) % 26 + 97)
            else:
                decrypted += char
        decrypted_list.append(decrypted)
    return sorted(decrypted_list)

