import sys
import os

def calculate_average_length(lines):
    total_length = 0
    for line in lines:
        total_length += len(line.strip())
    return total_length / len(lines)

def read_lines_from_file(file_name, max_lines):
    lines = []
    try:
        with open(file_name, 'rb') as file:
            for line_number, line in enumerate(file, 1):
                if line.startswith(b'#'):
                    continue
                line = line.strip().decode('utf-8')
                lines.append(line)
                if line_number >= max_lines:
                    break
    except FileNotFoundError:
        print(f"Error: File '{file_name}' not found.")
        sys.exit(1)
    except IOError:
        print(f"Error: Unable to open file '{file_name}'.")
        sys.exit(1)
    return lines

def main():
    file_name = "data.txt"
    max_lines = 100
    if len(sys.argv) > 1:
        file_name = sys.argv[1]
    if len(sys.argv) > 2:
        max_lines = int(sys.argv[2])

    lines = read_lines_from_file(file_name, max_lines)
    average_length = calculate_average_length(lines)

    for line_number, line in enumerate(lines, 1):
        print(f"Line {line_number}: {line}")

    print(f"Average line length: {average_length:.2f}")

