double calculateSumAndAverage(int* arr, int size, double& average) {
    int sum = 0;
    int count = 0;

    for (int i = 0; i < size; i++) {
        if (arr[i] % 2 == 0 || arr[i] % 3 == 0 || arr[i] % 5 == 0) {
            continue;
        }
        sum += arr[i];
        count++;
    }

    if (count > 0) {
        average = static_cast<double>(sum) / count;
    } else {
        average = 0;
    }

    return sum;
}

