```cpp
#include <iostream>
#include <complex>
#include <cmath>

using namespace std;

void findRoots(complex<double> a, complex<double> b, complex<double> c, complex<double> d) {
    complex<double> discriminant, s, t, u;
    complex<double> i(0, 1);  // Imaginary unit

    // Calculate the discriminant
    discriminant = pow(b, 2) - 3.0 * a * c;

    // Calculate the complex roots
    s = (9.0 * a * b * c - 27.0 * pow(a, 2) * d - 2.0 * pow(b, 3)) / (2.0 * sqrt(pow(abs(discriminant), 3)));
    t = sqrt(pow(s, 2) + pow(discriminant, 3));
    u = pow(t, 1.0 / 3.0);

    // Calculate the roots
    complex<double> root1 = (-1.0 / (3.0 * a)) * (b + u + discriminant / u);
    complex<double> root2 = (-1.0 / (3.0 * a)) * (b + i * u + discriminant / (i * u));
    complex<double> root3 = (-1.0 / (3.0 * a)) * (b - u - discriminant / u);

    // Output the roots
    cout << "Root 1: " << root1 << endl;
    cout << "Root 2: " << root2 << endl;
    cout << "Root 3: " << root3 << endl;
}

