  const trimmedParams = params.map(param => param.trim());

  // Filter out parameter names that start with a number, contain special characters, or are longer than 10 characters
  const filteredParams = trimmedParams.filter(param => /^[^0-9\s][A-Za-z0-9_]{0,9}$/.test(param));

  // Check for duplicate parameter names
  const duplicateParams = filteredParams.filter((param, index) => filteredParams.indexOf(param) !== index);
  if (duplicateParams.length > 0) {
    return 'Error: Duplicate parameter names found';
  }

  // Sort the parameter names in reverse alphabetical order
  const sortedParams = filteredParams.sort((a, b) => b.localeCompare(a));

  return sortedParams;
}

