```python
class CountryCapitalData:
    def __init__(self):
        self.data = {}

    def add_capital(self, country, capital):
        if country in self.data:
            capitals = self.data[country]
            if capital in capitals:
                return False
            capitals.add(capital)
        else:
            self.data[country] = {capital}
        return True

    def remove_capital(self, country, capital):
        if country in self.data:
            capitals = self.data[country]
            if capital in capitals:
                capitals.remove(capital)
                if len(capitals) == 0:
                    del self.data[country]
                return True
        return False

    def find_country_with_capital(self, capital):
        countries = []
        for country, capitals in self.data.items():
            if capital in capitals:
                countries.append(country)
        return sorted(countries)

    def find_capitals_of_country(self, country):
        if country in self.data:
            capitals = self.data[country]
            return sorted(capitals)
        return []

    def check_capital_exists(self, capital):
        for capitals in self.data.values():
            if capital in capitals:
                return True
        return False
```

