        name = request.form['name']
        age = request.form['age']
        phone = request.form['phone']
        new_email = request.form['email']
        password = request.form['password']
        pin = request.form['pin']

        if validate_email(new_email) and is_unique_email(new_email):
            if check_password_hash(user['password'], password) and user['pin'] == pin:
                contact_info = {
                    'name': name,
                    'age': age,
                    'phone': phone,
                    'email': new_email
                }
                contacts[email] = contact_info
                user['email'] = new_email
                return redirect(url_for('dashboard'))
            else:
                return render_template('update.html', user=user, error_message='Invalid password or pin.')
        else:
            return render_template('update.html', user=user, error_message='Invalid email or email already exists.')

    return render_template('update.html', user=user)


@app.route('/logout')
def logout():
    email = session.pop('email', None)
    if email:
        pin = request.args.get('pin')
        user = find_user(email)
        if user and user['pin'] == pin:
            return redirect(url_for('home'))
    return redirect(url_for('login'))


# Helper Functions
def validate_email(email):
    return '@' in email  # Add more validation if needed


def validate_pin(pin):
    return pin.isdigit() and len(pin) == 6


def is_unique_email(email):
    for user in users:
        if user['email'] == email:
            return False
    return True


def is_unique_pin(pin):
    for user in users:
        if user['pin'] == pin:
            return False
    return True


def find_user(email):
    for user in users:
        if user['email'] == email:
            return user
    return None


if __name__ == '__main__':
