Here's an example Java program that calculates the sum of two linked lists representing integers without using any built-in classes or methods for linked lists:

```java
class LinkedList {
    Node head;

    static class Node {
        int data;
        Node next;

        Node(int d) {
            data = d;
            next = null;
        }
    }

    LinkedList addTwoLists(LinkedList list1, LinkedList list2) {
        LinkedList res = new LinkedList();
        Node curr1 = list1.head;
        Node curr2 = list2.head;
        int carry = 0, sum;

        while (curr1 != null || curr2 != null) {
            int num1 = (curr1 != null) ? curr1.data : 0;
            int num2 = (curr2 != null) ? curr2.data : 0;

            sum = carry + num1 + num2;

            carry = (sum >= 10) ? 1 : 0;

            sum = sum % 10;

            res.insert(sum);

            if (curr1 != null)
                curr1 = curr1.next;
            if (curr2 != null)
                curr2 = curr2.next;
        }

        if (carry > 0)
            res.insert(carry);

        return res;
    }

    void insert(int data) {
        Node newNode = new Node(data);
        newNode.next = null;

        if (head == null) {
            head = newNode;
        } else {
            Node last = head;
            while (last.next != null) {
                last = last.next;
            }
            last.next = newNode;
        }
    }

    void printList() {
        Node currNode = head;
        while (currNode != null) {
            System.out.print(currNode.data + " ");
            currNode = currNode.next;
        }
        System.out.println();
    }

    public static void main(String[] args) {
        LinkedList list1 = new LinkedList();
        LinkedList list2 = new LinkedList();

        // Example inputs
        list1.insert(7);
        list1.insert(5);
        list1.insert(9);
        list1.insert(4);
        list1.insert(6);
        System.out.println("First list: ");
        list1.printList();

        list2.insert(8);
        list2.insert(4);
        System.out.println("Second list: ");
        list2.printList();

        LinkedList sumList = new LinkedList();

        sumList = sumList.addTwoLists(list1, list2);

        System.out.println("Sum of two lists: ");
        sumList.printList();
    }
}
```

