import math

class Area:
    @staticmethod
    def calculate_area_circle(radius):
        try:
            area = math.pi * (radius ** 2)
            return area
        except TypeError:
            return "Invalid input. Please provide a valid radius."

    @staticmethod
    def calculate_area_rectangle(length, width):
        try:
            area = length * width
            return area
        except TypeError:
            return "Invalid input. Please provide valid length and width."

    @staticmethod
    def calculate_area_triangle(base, height):
        try:
            area = 0.5 * base * height
            return area
        except TypeError:
            return "Invalid input. Please provide valid base and height."

    @staticmethod
    def calculate_area_trapezoid(base1, base2, height):
        try:
            area = 0.5 * (base1 + base2) * height
            return area
        except TypeError:
            return "Invalid input. Please provide valid base1, base2, and height."

    @staticmethod
    def calculate_area_polygon(side_length, num_sides):
        try:
            area = (num_sides * (side_length ** 2)) / (4 * math.tan(math.pi / num_sides))
            return area
        except TypeError:
            return "Invalid input. Please provide valid side length and number of sides."
```

