function changeBackgroundColor(color, elements, animate) {
  // Check if the color is valid
  if (!/^#[0-9A-F]{6}$/i.test(color)) {
    throw new Error('Invalid color format');
  }

  // Get the current time
  const startTime = Date.now();

  // Helper function to change the background color of an element
  function changeColor(element) {
    // Calculate the time taken to change the color
    const timeTaken = Date.now() - startTime;

    // Change the background color of the element
    element.style.backgroundColor = color;

    // Log the time taken
    console.log(`Changed color in ${timeTaken}ms`);
  }

  // Iterate over each element in the array
  elements.forEach(function(element) {
    if (animate) {
      // Animate the color change over 1 second
      element.style.transition = 'background-color 1s';
      setTimeout(function() {
        changeColor(element);
      }, 0);
    } else {
      // Change the color instantly
      changeColor(element);
    }
  });
}
