Here is an implementation of finding the lowest common ancestor in a binary search tree in C++:

```cpp
#include<iostream>

// Definition for a binary tree node.
struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;

    TreeNode(int value) : val(value), left(nullptr), right(nullptr) {}
};

TreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {
    if (root == nullptr || root == p || root == q) {
        return root;
    }

    TreeNode* left = lowestCommonAncestor(root->left, p, q);
    TreeNode* right = lowestCommonAncestor(root->right, p, q);

    if (left != nullptr && right != nullptr) {
        return root;
    } else if (left != nullptr) {
        return left;
    } else {
        return right;
    }
}

int main() {
    /*
                6
              /   \
             2     8
           /  \   / \
          0    4 7   9
              / \
             3   5
    */
    TreeNode* root = new TreeNode(6);
    root->left = new TreeNode(2);
    root->left->left = new TreeNode(0);
    root->left->right = new TreeNode(4);
    root->left->right->left = new TreeNode(3);
    root->left->right->right = new TreeNode(5);
    root->right = new TreeNode(8);
    root->right->left = new TreeNode(7);
    root->right->right = new TreeNode(9);

    TreeNode* p = root->left;
    TreeNode* q = root->left->right->left;

    TreeNode* lca = lowestCommonAncestor(root, p, q);

    std::cout << "Lowest Common Ancestor: " << lca->val << std::endl;

    // Deallocate memory
    delete root->right->right;
    delete root->right->left;
    delete root->right;
    delete root->left->right->right;
    delete root->left->right->left;
    delete root->left->right;
    delete root->left->left;
    delete root->left;
    delete root;

    return 0;
}
```

Output:
```
Lowest Common Ancestor: 2
```

In this example, we have a binary search tree where the lowest common ancestor of nodes with values 3 and 5 is the node with value 2. The `lowestCommonAncestor` function is a recursive function that traverses the binary search tree to find the lowest common ancestor. It returns the lowest common ancestor node or nullptr if either of the input nodes are not found in the tree.

