```java
public class Fibonacci {

    public static void printFibonacci(int n) {
        int[] fib = new int[n+2];
        fib[0] = 0;
        fib[1] = 1;

        for (int i = 2; i <= n; i++) {
            fib[i] = fib[i-1] + fib[i-2];
        }

        for (int i = 0; i <= n; i++) {
            System.out.print(fib[i] + " ");
        }
    }

    public static void main(String[] args) {
        int n = 10;
        printFibonacci(n);
    }
}
```

In this solution, we use an array `fib` to store the Fibonacci numbers. We initialize the first two elements of the array as 0 and 1. Then, we iterate from index 2 to `n` and calculate the Fibonacci number at each index using the formula `fib[i] = fib[i-1] + fib[i-2]`. Finally, we print the Fibonacci sequence up to index `n`.

```cpp
#include <iostream>
#include <cmath>

class Complex {
private:
    double real;
    double imaginary;

public:
    Complex(double real = 0.0, double imaginary = 0.0) : real(real), imaginary(imaginary) {}

    // Copy constructor
    Complex(const Complex& other) {
        real = other.real;
        imaginary = other.imaginary;
    }

    // Assignment operator
    Complex& operator=(const Complex& other) {
        if (this != &other) {
            real = other.real;
            imaginary = other.imaginary;
        }
        return *this;
    }

    // Addition
    Complex operator+(const Complex& other) const {
        return Complex(real + other.real, imaginary + other.imaginary);
    }

    // Subtraction
    Complex operator-(const Complex& other) const {
        return Complex(real - other.real, imaginary - other.imaginary);
    }

    // Multiplication
    Complex operator*(const Complex& other) const {
        double newReal = real * other.real - imaginary * other.imaginary;
        double newImaginary = real * other.imaginary + imaginary * other.real;
        return Complex(newReal, newImaginary);
    }

    // Division
    Complex operator/(const Complex& other) const {
        double denominator = other.real * other.real + other.imaginary * other.imaginary;
        if (denominator == 0.0) {
            throw std::runtime_error("Division by zero");
        }
        double newReal = (real * other.real + imaginary * other.imaginary) / denominator;
        double newImaginary = (imaginary * other.real - real * other.imaginary) / denominator;
        return Complex(newReal, newImaginary);
    }

    // Equality
    bool operator==(const Complex& other) const {
        return (real == other.real && imaginary == other.imaginary);
    }

    // Inequality
    bool operator!=(const Complex& other) const {
        return !(*this == other);
    }

    // Conjugate
    Complex conjugate() const {
        return Complex(real, -imaginary);
    }

    // Magnitude
    double magnitude() const {
        return std::sqrt(real * real + imaginary * imaginary);
    }

    // Phase
    double phase() const {
        return std::atan2(imaginary, real);
    }

    // Square root
    Complex sqrt() const {
        double r = magnitude();
        double theta = phase();
        double newReal = std::sqrt(r) * std::cos(theta / 2);
        double newImaginary = std::sqrt(r) * std::sin(theta / 2);
        return Complex(newReal, newImaginary);
    }

    // Exponential function
    Complex exp() const {
        double newReal = std::exp(real) * std::cos(imaginary);
        double newImaginary = std::exp(real) * std::sin(imaginary);
        return Complex(newReal, newImaginary);
    }

    // Power function
    Complex pow(const Complex& other) const {
        double r = magnitude();
        double theta = phase();
        double newReal = std::pow(r, other.real) * std::exp(-other.imaginary * theta);
        double newImaginary = other.real * theta + other.imaginary * std::log(r);
        return Complex(newReal, newImaginary);
    }

    // Input operator
    friend std::istream& operator>>(std::istream& is, Complex& c) {
        char dummy;
        is >> c.real >> dummy >> c.imaginary >> dummy;
        return is;
    }

    // Output operator
    friend std::ostream& operator<<(std::ostream& os, const Complex& c) {
        os << c.real << (c.imaginary < 0 ? " - " : " + ") << std::abs(c.imaginary) << "i";
        return os;
    }
};

int main() {
    Complex c1(3.0, 4.0);
    Complex c2(2.0, -1.0);

    Complex c3 = c1 + c2;
    std::cout << "c1 + c2 = " << c3 << std::endl;

    Complex c4 = c1 - c2;
    std::cout << "c1 - c2 = " << c4 << std::endl;

    Complex c5 = c1 * c2;
    std::cout << "c1 * c2 = " << c5 << std::endl;

    Complex c6 = c1 / c2;
    std::cout << "c1 / c2 = " << c6 << std::endl;

    std::cout << "Magnitude of c1: " << c1.magnitude() << std::endl;
    std::cout << "Phase of c1: " << c1.phase() << std::endl;

    Complex c7 = c1.conjugate();
    std::cout << "Conjugate of c1: " << c7 << std::endl;

    Complex c8 = c1.sqrt();
    std::cout << "Square root of c1: " << c8 << std::endl;

    Complex c9 = c1.exp();
    std::cout << "Exponential function of c1: " << c9 << std::endl;

    Complex c10 = c1.pow(c2);
    std::cout << "c1 raised to the power of c2: " << c10 << std::endl;

    std::cout << "Enter a complex number: ";
    Complex c11;
    std::cin >> c11;
    std::cout << "You entered: " << c11 << std::endl;

    return 0;
}
