        if not self.root:
            self.root = Node(value)
            return

        curr = self.root
        while curr:
            if value < curr.value:
                if not curr.left:
                    curr.left = Node(value)
                    return
                curr = curr.left
            elif value > curr.value:
                if not curr.right:
                    curr.right = Node(value)
                    return
                curr = curr.right
            else:
                return

    def remove_node(self, value: int) -> bool:
        if not self.root:
            return False

        curr = self.root
        parent = None
        while curr:
            if value < curr.value:
                parent = curr
                curr = curr.left
            elif value > curr.value:
                parent = curr
                curr = curr.right
            else:
                if not curr.left and not curr.right:
                    if not parent:
                        self.root = None
                    elif parent.left == curr:
                        parent.left = None
                    else:
                        parent.right = None
                elif curr.left and not curr.right:
                    if not parent:
                        self.root = curr.left
                    elif parent.left == curr:
                        parent.left = curr.left
                    else:
                        parent.right = curr.left
                elif not curr.left and curr.right:
                    if not parent:
                        self.root = curr.right
                    elif parent.left == curr:
                        parent.left = curr.right
                    else:
                        parent.right = curr.right
                else:
                    successor = self._get_min_node(curr.right)
                    curr.value = successor.value
                    curr.right = self._remove_node(curr.right, successor.value)
                return True

        return False

    def search(self, value: int) -> bool:
        curr = self.root
        while curr:
            if value < curr.value:
                curr = curr.left
            elif value > curr.value:
                curr = curr.right
            else:
                return True
        return False

    def get_in_order_traversal(self) -> List[int]:
        result = []
        self._in_order_traversal(self.root, result)
        return result

    def _in_order_traversal(self, node: Node, result: List[int]) -> None:
        if not node:
            return
        self._in_order_traversal(node.left, result)
        result.append(node.value)
        self._in_order_traversal(node.right, result)

    def get_pre_order_traversal(self) -> List[int]:
        result = []
        self._pre_order_traversal(self.root, result)
        return result

    def _pre_order_traversal(self, node: Node, result: List[int]) -> None:
        if not node:
            return
        result.append(node.value)
        self._pre_order_traversal(node.left, result)
        self._pre_order_traversal(node.right, result)

    def get_post_order_traversal(self) -> List[int]:
        result = []
        self._post_order_traversal(self.root, result)
        return result

    def _post_order_traversal(self, node: Node, result: List[int]) -> None:
        if not node:
            return
        self._post_order_traversal(node.left, result)
        self._post_order_traversal(node.right, result)
        result.append(node.value)

    def get_level_order_traversal(self) -> List[int]:
        result = []
        if not self.root:
            return result
        queue = [self.root]
        while queue:
            node = queue.pop(0)
            result.append(node.value)
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        return result

    def get_min_value(self) -> int:
        if not self.root:
            raise ValueError("The binary search tree is empty")
        curr = self.root
        while curr.left:
            curr = curr.left
        return curr.value

    def get_max_value(self) -> int:
        if not self.root:
            raise ValueError("The binary search tree is empty")
        curr = self.root
        while curr.right:
            curr = curr.right
        return curr.value

    def get_height(self) -> int:
        return self._get_height(self.root)

    def _get_height(self, node: Node) -> int:
        if not node:
            return 0
        return max(self._get_height(node.left), self._get_height(node.right)) + 1

    def _get_min_node(self, node: Node) -> Node:
        curr = node
        while curr.left:
            curr = curr.left
        return curr

    def _remove_node(self, node: Node, value: int) -> Node:
        if not node:
            return None
        if value < node.value:
            node.left = self._remove_node(node.left, value)
        elif value > node.value:
            node.right = self._remove_node(node.right, value)
        else:
            if not node.left and not node.right:
                return None
            elif node.left and not node.right:
                return node.left
            elif not node.left and node.right:
                return node.right
            else:
                successor = self._get_min_node(node.right)
                node.value = successor.value
                node.right = self._remove_node(node.right, successor.value)
        return node
```

