Here is a Python implementation of the scientific calculator with the requested functionalities:

```python
import math

class ScientificCalculator:
    def __init__(self):
        self.memory = None

    def validate_input(self, num):
        try:
            float(num)
            return True
        except ValueError:
            return False

    def sum(self, num1, num2):
        if self.validate_input(num1) and self.validate_input(num2):
            return float(num1) + float(num2)
        else:
            raise ValueError("Invalid input")

    def difference(self, num1, num2):
        if self.validate_input(num1) and self.validate_input(num2):
            return float(num1) - float(num2)
        else:
            raise ValueError("Invalid input")

    def product(self, num1, num2):
        if self.validate_input(num1) and self.validate_input(num2):
            return float(num1) * float(num2)
        else:
            raise ValueError("Invalid input")

    def quotient(self, num1, num2):
        if self.validate_input(num1) and self.validate_input(num2):
            if float(num2) != 0:
                return float(num1) / float(num2)
            else:
                raise ZeroDivisionError("Division by zero")
        else:
            raise ValueError("Invalid input")

    def remainder(self, num1, num2):
        if self.validate_input(num1) and self.validate_input(num2):
            if float(num2) != 0:
                return float(num1) % float(num2)
            else:
                raise ZeroDivisionError("Division by zero")
        else:
            raise ValueError("Invalid input")

    def sine(self, num):
        if self.validate_input(num):
            return math.sin(float(num))
        else:
            raise ValueError("Invalid input")

    def cosine(self, num):
        if self.validate_input(num):
            return math.cos(float(num))
        else:
            raise ValueError("Invalid input")

    def tangent(self, num):
        if self.validate_input(num):
            return math.tan(float(num))
        else:
            raise ValueError("Invalid input")

    def logarithm(self, num, base):
        if self.validate_input(num) and self.validate_input(base):
            return math.log(float(num), float(base))
        else:
            raise ValueError("Invalid input")

    def natural_logarithm(self, num):
        if self.validate_input(num):
            return math.log(float(num))
        else:
            raise ValueError("Invalid input")

    def exponent(self, num, power):
        if self.validate_input(num) and self.validate_input(power):
            return math.pow(float(num), float(power))
        else:
            raise ValueError("Invalid input")

    def factorial(self, num):
        if self.validate_input(num):
            return math.factorial(int(num))
        else:
            raise ValueError("Invalid input")

    def square_root(self, num):
        if self.validate_input(num):
            return math.sqrt(float(num))
        else:
            raise ValueError("Invalid input")

    def round_result(self, num, decimal_places):
        if self.validate_input(num) and self.validate_input(decimal_places):
            return round(float(num), int(decimal_places))
        else:
            raise ValueError("Invalid input")

    def store_memory(self, num):
        if self.validate_input(num):
            self.memory = float(num)
        else:
            raise ValueError("Invalid input")

    def recall_memory(self):
        if self.memory is not None:
            return self.memory
        else:
            raise ValueError("Memory is empty")
```

