sequence <- "AAATACTAGCTGAGTTTGTACGTATGGGCC"

find_motifs <- function(sequence) {
  motifs <- c()

  for (i in 1:(nchar(sequence)-3)) {
    subseq <- substring(sequence, i, i+3)
    if (grepl(".*A.*C.*G.*T.*", subseq)) {
      motifs <- c(motifs, subseq)
