public class ReverseArray {

  private static int ignoredCount = 0;

  public static void main(String[] args) {
    // Checking if the specific character is provided as a command-line argument
    if (args.length < 1) {
      System.out.println("Please provide a specific character to ignore as a command-line argument.");
      return;
    }

    String specificCharacter = args[0];

    String[] array = {"String4", "String3", "String2", "String1", "Hello_World"};

    System.out.println("Number of elements in the array before ignoring: " + array.length);
    System.out.println("Array elements in reverse order:");

    reversePrint(array, specificCharacter);

    System.out.println("Number of elements in the array after ignoring: " + (array.length - ignoredCount));
    System.out.println("Number of elements ignored: " + ignoredCount);
  }

  public static void reversePrint(String[] array, String specificCharacter) {
    if (array.length == 0) {
      System.out.println("Error: The array is empty.");
      return;
    }

    reversePrintHelper(array, specificCharacter, array.length - 1);
  }

  public static void reversePrintHelper(String[] array, String specificCharacter, int index) {
    if (index >= 0) {
      String element = array[index];

      if (element.contains(specificCharacter)) {
        ignoredCount++;
      } else {
        System.out.println(element);
      }

      reversePrintHelper(array, specificCharacter, index - 1);
    }
  }
}
