import java.util.HashMap;
import java.util.Map;

public class PriorityQueue<T> {
    private Map<T, Integer> priorityMap;
    private Heap<T> heap;

    public PriorityQueue() {
        priorityMap = new HashMap<>();
        heap = new Heap<>();
    }

    public void insert(T element, int priority) {
        priorityMap.put(element, priority);
        heap.insert(element);
    }

    public void increasePriority(T element, int newPriority) {
        if (!priorityMap.containsKey(element)) {
            throw new IllegalArgumentException("Element not found in priority queue");
        }
        int currentPriority = priorityMap.get(element);
        if (newPriority < currentPriority) {
            throw new IllegalArgumentException("New priority should be higher than current priority");
        }
        priorityMap.put(element, newPriority);
        heap.heapifyUp(element);
    }

    public void decreasePriority(T element, int newPriority) {
        if (!priorityMap.containsKey(element)) {
            throw new IllegalArgumentException("Element not found in priority queue");
        }
        int currentPriority = priorityMap.get(element);
        if (newPriority > currentPriority) {
            throw new IllegalArgumentException("New priority should be lower than current priority");
        }
        priorityMap.put(element, newPriority);
        heap.heapifyDown(element);
    }

    public T peek() {
        if (heap.isEmpty()) {
            throw new IllegalStateException("Priority queue is empty");
        }
        return heap.peek();
    }

    public int size() {
        return heap.size();
    }

    private class Heap<E> {
        private final List<E> elements;
        private final Comparator<E> comparator;

        public Heap() {
            elements = new ArrayList<>();
            comparator = (o1, o2) -> priorityMap.get(o1) - priorityMap.get(o2);
        }

        public void insert(E element) {
            elements.add(element);
            heapifyUp(element);
        }

        public void heapifyUp(E element) {
            int index = elements.indexOf(element);
            while (index > 0) {
                int parentIndex = (index - 1) / 2;
                E parent = elements.get(parentIndex);
                if (comparator.compare(element, parent) >= 0) {
                    break;
                }
                swap(index, parentIndex);
                index = parentIndex;
            }
        }

        public void heapifyDown(E element) {
            int index = elements.indexOf(element);
            int size = elements.size();
            while (true) {
                int leftChildIndex = 2 * index + 1;
                int rightChildIndex = 2 * index + 2;
                int smallestChildIndex = index;
                if (leftChildIndex < size && comparator.compare(elements.get(leftChildIndex), elements.get(smallestChildIndex)) < 0) {
                    smallestChildIndex = leftChildIndex;
                }
                if (rightChildIndex < size && comparator.compare(elements.get(rightChildIndex), elements.get(smallestChildIndex)) < 0) {
                    smallestChildIndex = rightChildIndex;
                }
                if (smallestChildIndex == index) {
                    break;
                }
                swap(index, smallestChildIndex);
                index = smallestChildIndex;
            }
        }

        public E peek() {
            if (isEmpty()) {
                throw new IllegalStateException("Heap is empty");
            }
            return elements.get(0);
        }

        public int size() {
            return elements.size();
        }

        public boolean isEmpty() {
            return elements.isEmpty();
        }

        private void swap(int i, int j) {
            E temp = elements.get(i);
            elements.set(i, elements.get(j));
            elements.set(j, temp);
        }
    }
}

