public class Point {
    private int x;
    private int y;
    private int z;

    public Point(int x, int y, int z) {
        setX(x);
        setY(y);
        setZ(z);
    }

    public int getX() {
        return x;
    }

    public void setX(int x) {
        if (x < -1000 || x > 1000) {
            throw new IllegalArgumentException("Invalid x-coordinate. It should be between -1000 and 1000.");
        }
        this.x = x;
    }

    public int getY() {
        return y;
    }

    public void setY(int y) {
        if (y < -1000 || y > 1000) {
            throw new IllegalArgumentException("Invalid y-coordinate. It should be between -1000 and 1000.");
        }
        this.y = y;
    }

    public int getZ() {
        return z;
    }

    public void setZ(int z) {
        if (z < -1000 || z > 1000) {
            throw new IllegalArgumentException("Invalid z-coordinate. It should be between -1000 and 1000.");
        }
        this.z = z;
    }

    public double distance(Point other) {
        int dx = other.getX() - getX();
        int dy = other.getY() - getY();
        int dz = other.getZ() - getZ();
        return Math.sqrt(dx * dx + dy * dy + dz * dz);
    }

    public void translate(int dx, int dy, int dz) {
        setX(getX() + dx);
        setY(getY() + dy);
        setZ(getZ() + dz);
    }

    public String toString() {
        return "(" + getX() + ", " + getY() + ", " + getZ() + ")";
    }

    public double calculateAngle(Point other) {
        double dx = other.getX() - getX();
        double dy = other.getY() - getY();
        double dz = other.getZ() - getZ();
        double distance = Math.sqrt(dx * dx + dy * dy + dz * dz);
        return Math.toDegrees(Math.acos(dx / distance));
    }

    public void rotateX(double angle) {
        if (angle < 0 || angle > 360) {
            throw new IllegalArgumentException("Invalid angle. It should be between 0 and 360 degrees.");
        }
        double radians = Math.toRadians(angle);
        double newY = getY() * Math.cos(radians) - getZ() * Math.sin(radians);
        double newZ = getY() * Math.sin(radians) + getZ() * Math.cos(radians);
        setY((int) Math.round(newY));
        setZ((int) Math.round(newZ));
    }

    public void rotateY(double angle) {
        if (angle < 0 || angle > 360) {
            throw new IllegalArgumentException("Invalid angle. It should be between 0 and 360 degrees.");
        }
        double radians = Math.toRadians(angle);
        double newX = getX() * Math.cos(radians) + getZ() * Math.sin(radians);
        double newZ = -getX() * Math.sin(radians) + getZ() * Math.cos(radians);
        setX((int) Math.round(newX));
        setZ((int) Math.round(newZ));
    }

    public void rotateZ(double angle) {
        if (angle < 0 || angle > 360) {
            throw new IllegalArgumentException("Invalid angle. It should be between 0 and 360 degrees.");
        }
        double radians = Math.toRadians(angle);
        double newX = getX() * Math.cos(radians) - getY() * Math.sin(radians);
        double newY = getX() * Math.sin(radians) + getY() * Math.cos(radians);
        setX((int) Math.round(newX));
        setY((int) Math.round(newY));
    }

    public void scale(double scaleFactor) {
        if (scaleFactor <= 0) {
            throw new IllegalArgumentException("Invalid scale factor. It should be a positive value.");
        }
        setX((int) Math.round(getX() * scaleFactor));
        setY((int) Math.round(getY() * scaleFactor));
        setZ((int) Math.round(getZ() * scaleFactor));
    }

    public void reflectX() {
        setX(-getX());
    }

    public void reflectY() {
        setY(-getY());
    }

    public void reflectZ() {
        setZ(-getZ());
    }
}
