```javascript
function findMaxAndIndex(nums) {
  let currentMax = nums[0];
  let currentIndex = 0;

  for (let i = 1; i < nums.length; i++) {
    if (nums[i] > currentMax) {
      currentMax = nums[i];
      currentIndex = i;
    } else if (nums[i] === currentMax && currentIndex === 0) {
      currentIndex = i;
    } else if (nums[i] === currentMax && currentIndex !== 0) {
      currentIndex = Math.min(currentIndex, i);
    }
  }

  return { max: currentMax, index: currentIndex };
}
```

