```cpp
#include <iostream>

int main() {
    int limit;
    std::cout << "Enter the limit: ";
    std::cin >> limit;

    int fib[limit + 1];
    fib[0] = 0;
    fib[1] = 1;

    for (int i = 2; i <= limit; i++) {
        fib[i] = fib[i - 1] + fib[i - 2];
    }

    std::cout << "Fibonacci sequence up to " << limit << ": ";
    for (int i = 0; i <= limit; i++) {
        std::cout << fib[i] << " ";
    }
    std::cout << std::endl;

    return 0;
}
