#include <iostream>

void merge(int arr[], int left[], int leftSize, int right[], int rightSize) {
    int i = 0, j = 0, k = 0;
    while (i < leftSize && j < rightSize) {
        if (left[i] < right[j]) {
            arr[k++] = left[i++];
        } else if (left[i] > right[j]) {
            arr[k++] = right[j++];
        } else {
            arr[k++] = left[i++];
            j++;
        }
    }
    while (i < leftSize) {
        arr[k++] = left[i++];
    }
    while (j < rightSize) {
        arr[k++] = right[j++];
    }
}

void mergeSort(int arr[], int size) {
    if (size <= 1) {
        return;
    }
    int mid = size / 2;
    int* left = new int[mid];
    int* right = new int[size - mid];
    for (int i = 0; i < mid; i++) {
        left[i] = arr[i];
    }
    for (int i = mid; i < size; i++) {
        right[i - mid] = arr[i];
    }
    mergeSort(left, mid);
    mergeSort(right, size - mid);
    merge(arr, left, mid, right, size - mid);
    delete[] left;
    delete[] right;
}

int countUniqueElements(int arr[], int size) {
    if (size == 0) {
        return 0;
    }
    mergeSort(arr, size);
    int uniqueCount = 1;
    for (int i = 1; i < size; i++) {
        if (arr[i] != arr[i - 1]) {
            uniqueCount++;
        }
    }
    return uniqueCount;
}

void printUniqueElements(int arr[], int size) {
    if (size == 0) {
        std::cout << "The array is empty." << std::endl;
        return;
    }
    mergeSort(arr, size);
    std::cout << "Unique elements in ascending order: ";
    std::cout << arr[0] << " ";
    for (int i = 1; i < size; i++) {
        if (arr[i] != arr[i - 1]) {
            std::cout << arr[i] << " ";
        }
    }
    std::cout << std::endl;
}

int main() {
    int arr[] = {1, -2, 5, 3, -2, 6, 2, 3, 5};
    int size = sizeof(arr) / sizeof(arr[0]);
    int uniqueCount = countUniqueElements(arr, size);
    std::cout << "Number of unique elements: " << uniqueCount << std::endl;
    printUniqueElements(arr, size);
    return 0;
}
