import math

class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

class Polygon:
    def __init__(self, points):
        self.points = points
        self.num_points = len(points)

    def calculate_distance(self, p1, p2):
        return math.sqrt((p2.x - p1.x)**2 + (p2.y - p1.y)**2)

    def calculate_perimeter(self):
        perimeter = 0
        for i in range(self.num_points):
            perimeter += self.calculate_distance(self.points[i], self.points[(i+1) % self.num_points])
        return perimeter

    def calculate_area(self):
        area = 0
        for i in range(self.num_points):
            area += (self.points[i].x * self.points[(i+1) % self.num_points].y) - (self.points[(i+1) % self.num_points].x * self.points[i].y)
        return abs(area) / 2

    def check_inside(self, point):
        if self.num_points < 3:
            return False

        left = 0
        right = self.num_points - 1

        while left < right:
            middle = (left + right) // 2
            triangle_area = (self.points[left].x * (self.points[middle].y - point.y) + 
                            self.points[middle].x * (point.y - self.points[left].y) + 
                            point.x * (self.points[left].y - self.points[middle].y)) / 2

            if triangle_area == 0:
                return True

            if triangle_area < 0:
                left = middle + 1
            else:
                right = middle

        return False

    def check_on_boundary(self, point):
        for i in range(self.num_points):
            if point.x == self.points[i].x and point.y == self.points[i].y:
                return True
            next_point_index = (i + 1) % self.num_points
            if (point.x >= min(self.points[i].x, self.points[next_point_index].x) and
                    point.x <= max(self.points[i].x, self.points[next_point_index].x) and
                    point.y >= min(self.points[i].y, self.points[next_point_index].y) and
                    point.y <= max(self.points[i].y, self.points[next_point_index].y) and
                    ((point.y - self.points[i].y) / (point.x - self.points[i].x) ==
                    (self.points[next_point_index].y - self.points[i].y) / (self.points[next_point_index].x - self.points[i].x))):
                return True
        return False

    def check_intersection(self, other_polygon):
        for i in range(self.num_points):
            if self.check_inside(other_polygon.points[i]) or other_polygon.check_inside(self.points[i]):
                return True
            if self.check_on_boundary(other_polygon.points[i]) or other_polygon.check_on_boundary(self.points[i]):
                return True
        return False

    def calculate_centroid(self):
        centroid_x = 0
        centroid_y = 0
        for i in range(self.num_points):
            centroid_x += (self.points[i].x + self.points[(i+1) % self.num_points].x) * \
                          (self.points[i].x * self.points[(i+1) % self.num_points].y - \
                          self.points[(i+1) % self.num_points].x * self.points[i].y)
            centroid_y += (self.points[i].y + self.points[(i+1) % self.num_points].y) * \
                          (self.points[i].x * self.points[(i+1) % self.num_points].y - \
                          self.points[(i+1) % self.num_points].x * self.points[i].y)
        area = self.calculate_area()
        centroid_x /= 6 * area
        centroid_y /= 6 * area
        return Point(centroid_x, centroid_y)
```

Explanation:

1. `calculate_distance()` method calculates the Euclidean distance between two points.
2. `calculate_perimeter()` method calculates the perimeter by summing up the distances between each pair of consecutive points.
3. `calculate_area()` method calculates the signed area of the polygon using the Shoelace formula.
4. `check_inside()` method checks if a given point lies inside the polygon by performing a binary search. It checks the orientation of each triangle formed by the point and two consecutive vertices of the polygon. If the orientation is consistent for all triangles, then the point lies inside the polygon.
5. `check_on_boundary()` method checks if a given point lies on the boundary of the polygon by comparing its coordinates with each pair of consecutive vertices of the polygon.
6. `check_intersection()` method checks if two polygons intersect with each other by checking if any vertex of one polygon lies inside the other polygon or vice versa.
7. `calculate_centroid()` method calculates the centroid of the polygon using the formula for the centroid of a polygon. It sums up the products of each pair of consecutive vertices and the sum of each pair of consecutive x and y coordinates. Finally, it divides the sums by 6 times the area of the polygon to get the centroid coordinates.

