function countWordsAndAverageLength($str) {
  // Remove any special characters and numbers from the string
  $cleanedStr = preg_replace('/[^A-Za-z\s]/', '', $str);

  // Split the cleaned string into an array of words
  $words = explode(' ', $cleanedStr);

  $wordCount = 0;
  $totalLength = 0;

  foreach ($words as $word) {
    // Check if the word contains any numbers or special characters
    if (!preg_match('/[0-9\W]/', $word)) {
      $wordCount++;
      $totalLength += strlen($word);
    }
  }

  $averageLength = $wordCount > 0 ? $totalLength / $wordCount : 0;

  return [
    'wordCount' => $wordCount,
    'averageLength' => $averageLength
  ];
}

