class SortedList:
    def __init__(self):
        self.data = []

    def insert(self, value):
        left = 0
        right = len(self.data) - 1
        while left <= right:
            mid = (left + right) // 2
            if self.data[mid] == value:
                self.data.insert(mid, value)
                return
            elif self.data[mid] < value:
                left = mid + 1
            else:
                right = mid - 1
        self.data.insert(left, value)

    def remove(self, value):
        left = 0
        right = len(self.data) - 1
        while left <= right:
            mid = (left + right) // 2
            if self.data[mid] == value:
                self.data.pop(mid)
                return
            elif self.data[mid] < value:
                left = mid + 1
            else:
                right = mid - 1

    def count(self, value):
        left = 0
        right = len(self.data) - 1
        count = 0
        while left <= right:
            mid = (left + right) // 2
            if self.data[mid] == value:
                count += 1
                i = mid - 1
                while i >= 0 and self.data[i] == value:
                    count += 1
                    i -= 1
                i = mid + 1
                while i < len(self.data) and self.data[i] == value:
                    count += 1
                    i += 1
                return count
            elif self.data[mid] < value:
                left = mid + 1
            else:
                right = mid - 1
        return count

    def index(self, value):
        left = 0
        right = len(self.data) - 1
        while left <= right:
            mid = (left + right) // 2
            if self.data[mid] == value:
                return mid
            elif self.data[mid] < value:
                left = mid + 1
            else:
                right = mid - 1
        return -1

    def clear(self):
        self.data = []

