```javascript
function convertString(inputString, desiredFormat) {
  if (desiredFormat === "camelCase") {
    return convertToCamelCase(inputString);
  } else if (desiredFormat === "PascalCase") {
    return convertToPascalCase(inputString);
  } else if (desiredFormat === "kebab-case") {
    return convertToKebabCase(inputString);
  } else if (desiredFormat === "snake_case") {
    return convertToSnakeCase(inputString);
  } else if (desiredFormat === "lowercase with spaces") {
    return convertToLowercaseWithSpaces(inputString);
  } else {
    return "Invalid desired format";
  }
}

function convertToCamelCase(inputString) {
  return inputString.replace(/([-_ ])([a-z])/g, function(match, separator, char) {
    return char.toUpperCase();
  });
}

function convertToPascalCase(inputString) {
  var camelCase = convertToCamelCase(inputString);
  return camelCase.charAt(0).toUpperCase() + camelCase.slice(1);
}

function convertToKebabCase(inputString) {
  return inputString.replace(/([-_ ])/g, "-").toLowerCase();
}

function convertToSnakeCase(inputString) {
  return inputString.replace(/([-_ ])/g, "_").toLowerCase();
}

function convertToLowercaseWithSpaces(inputString) {
  return inputString.replace(/([-_])/g, " ").toLowerCase();
}
```

