Here is an algorithm in JavaScript that finds the k most frequent elements in an array:

```javascript
function findKFrequentElements(array, k) {
  // Create a frequency map to count the occurrence of each element
  const frequencyMap = {};
  for (let i = 0; i < array.length; i++) {
    if (frequencyMap[array[i]]) {
      frequencyMap[array[i]]++;
    } else {
      frequencyMap[array[i]] = 1;
    }
  }

  // Convert the frequency map into an array of [element, frequency] pairs
  const frequencyArray = Object.entries(frequencyMap);

  // Sort the frequency array in descending order based on frequency
  frequencyArray.sort((a, b) => b[1] - a[1]);

  // Extract the k most frequent elements
  const result = [];
  for (let i = 0; i < k; i++) {
    result.push(Number(frequencyArray[i][0]));
  }

  return result;
}
```

