        char_frequency = {}
        for char in self.input_string:
            char_frequency[char] = char_frequency.get(char, 0) + 1
        return char_frequency

    def longest_continuous_substring(self):
        longest_substring = ""
        current_substring = ""
        for i in range(len(self.input_string)):
            if i > 0 and self.input_string[i] != self.input_string[i-1]:
                current_substring = ""
            current_substring += self.input_string[i]
            if len(current_substring) > len(longest_substring):
                longest_substring = current_substring
        return longest_substring

    def replace_vowels(self):
        vowels = ['A', 'E', 'I', 'O', 'U']
        new_string = ""
        for char in self.input_string:
            if char.upper() in vowels:
                new_string += char.lower()
            else:
                new_string += char
        return new_string

    def remove_non_alphabetic(self):
        new_string = ""
        for char in self.input_string:
            if char.isalpha():
                new_string += char
        return new_string

    def capitalize_words(self):
        words = self.input_string.split()
        capitalized_words = [word.capitalize() for word in words]
        return " ".join(capitalized_words)

    def reverse_words(self):
        words = self.input_string.split()
        reversed_words = [word[::-1] for word in words]
        return " ".join(reversed_words)

    def longest_palindrome_substring(self):
        n = len(self.input_string)
        if n < 2:
            return n
        max_len = 1
        start = 0
        for i in range(n):
            if i - max_len >= 1 and self.input_string[i-max_len-1:i+1] == self.input_string[i-max_len-1:i+1][::-1]:
                start = i - max_len - 1
                max_len += 2
                continue
            if i - max_len >= 0 and self.input_string[i-max_len:i+1] == self.input_string[i-max_len:i+1][::-1]:
                start = i - max_len
                max_len += 1
        return max_len

def main():
    input_string = "Hello, World!"
    processor = TextProcessor(input_string)
    print("Original String:", input_string)
    print("Reversed String:", processor.reverse_string())
    print("Character Frequency:", processor.count_characters())
    print("Longest Continuous Substring:", processor.longest_continuous_substring())
    print("Vowels Replaced:", processor.replace_vowels())
    print("Non-alphabetic Characters Removed:", processor.remove_non_alphabetic())
    print("Words Capitalized:", processor.capitalize_words())
    print("Words Reversed:", processor.reverse_words())
    print("Longest Palindrome Substring Length:", processor.longest_palindrome_substring())

if __name__ == "__main__":
    main()

