int findFirstOccurrence(int arr[], int size, int value) {
    // Check if the first element is equal to the value
    if (arr[0] == value) {
        return 0;
    }

    // Check if the last element is equal to the value
    if (arr[size - 1] == value) {
        return size - 1;
    }

    // If the value is not at the beginning or the end,
