        return n
    else:
        return fibonacci_recursive(n-1) + fibonacci_recursive(n-2)

def fibonacci_sequence(n):
    if n <= 0:
        return 0
    else:
        nth_number = fibonacci_recursive(n)
        sequence_sum = sum(fibonacci_recursive(i) for i in range(n+1))
        return nth_number, sequence_sum
```

2. Recursive function using tail recursion:

```python
def fibonacci_tail_recursive(n, a=0, b=1):
    if n == 0:
        return a
    elif n == 1:
        return b
    else:
        return fibonacci_tail_recursive(n-1, b, a+b)

def fibonacci_sequence(n):
    if n <= 0:
        return 0
    else:
        nth_number = fibonacci_tail_recursive(n)
        sequence_sum = sum(fibonacci_tail_recursive(i) for i in range(n+1))
        return nth_number, sequence_sum
```

3. Recursive function using memoization without using a global variable or any data structures:

```python
def fibonacci_recursive(n, memo={}):
    if n <= 1:
        return n
    elif n in memo:
        return memo[n]
    else:
        memo[n] = fibonacci_recursive(n-1, memo) + fibonacci_recursive(n-2, memo)
        return memo[n]

def fibonacci_sequence(n):
    if n <= 0:
        return 0
    else:
        nth_number = fibonacci_recursive(n)
        sequence_sum = sum(fibonacci_recursive(i) for i in range(n+1))
        return nth_number, sequence_sum
```

4. Iterative approach without using recursion or memoization:

```python
def fibonacci_sequence(n):
    if n <= 0:
        return 0, 0
    else:
        a, b = 0, 1
        sequence_sum = 1

        for _ in range(n-1):
            a, b = b, a + b
            sequence_sum += b

        return b, sequence_sum
```

