#include <stdio.h>

void reverseString(char* str) {
    if (str == NULL) {
        return;
    }

    int length = 0;
    while (str[length] != '\0') {
        length++;
    }

    int start = 0;
    int end = length - 1;

    while (start < end) {
        char temp = str[start];
        str[start] = str[end];
        str[end] = temp;

        start++;
        end--;
    }
}

int main() {
    char str[] = "Hello, World!";

    printf("Before: %s\n", str);
    reverseString(str);
    printf("After: %s\n", str);

    return 0;
}
