function createForm() {
  // Generate a unique ID for the form
  const formId = "form-" + Math.random().toString(36).substr(2, 9);

  // Create the form element
  const form = document.createElement("form");
  form.id = formId;
  form.classList.add("custom-form");

  // Create the input field
  const input = document.createElement("input");
  input.type = "text";
  input.placeholder = "Enter your name";
  form.appendChild(input);

  // Create the select dropdown
  const select = document.createElement("select");
  const options = ["Option 1", "Option 2", "Option 3"];
  options.forEach(optionText => {
    const option = document.createElement("option");
    option.text = optionText;
    select.add(option);
  });
  form.appendChild(select);

  // Create the textarea
  const textarea = document.createElement("textarea");
  textarea.placeholder = "Enter your message";
  form.appendChild(textarea);

  // Create the submit button
  const button = document.createElement("button");
  button.classList.add("submit-button");
  button.textContent = "Submit";
  button.addEventListener("click", function(e) {
    e.preventDefault();
    const name = input.value.trim();
    const option = select.value.trim();
    const message = textarea.value.trim();

    // Reset any previous error messages
    const errorMessages = form.querySelectorAll(".error-message");
    errorMessages.forEach(errorMessage => errorMessage.remove());

    // Validate form fields
    if (name === "") {
      showError(input, "Name is required");
      return;
    }
    if (option === "") {
      showError(select, "Option must be selected");
      return;
    }
    if (message === "") {
      showError(textarea, "Message is required");
      return;
    }

    // Display success message and disable the form
    alert("Form submitted!");
    disableForm();

    // Clear form fields and reset error messages
    input.value = "";
    select.value = "";
    textarea.value = "";
    errorMessages.forEach(errorMessage => errorMessage.remove());

    // Enable the form after a random amount of time
    const disableTime = getRandomInt(1000, 5000);
    setTimeout(enableForm, disableTime);
  });
  form.appendChild(button);

  // Append the form to the document body
  document.body.appendChild(form);

  // Function to show error message below an input field
  function showError(inputField, errorMessage) {
    const error = document.createElement("span");
    error.classList.add("error-message");
    error.textContent = errorMessage;
    inputField.insertAdjacentElement("afterend", error);
  }

  // Function to disable the form and change submit button text
  function disableForm() {
    form.querySelectorAll("input, select, textarea, button").forEach(element => {
      element.disabled = true;
    });
    button.textContent = "Please wait...";
  }

  // Function to enable the form and change submit button text back to "Submit"
  function enableForm() {
    form.querySelectorAll("input, select, textarea, button").forEach(element => {
      element.disabled = false;
    });
    button.textContent = "Submit";
  }

  // Function to generate a random integer between min (inclusive) and max (exclusive)
  function getRandomInt(min, max) {
    return Math.floor(Math.random() * (max - min) + min);
  }
}

// Call the createForm function to create the form
createForm();
```

