function findLongestSubstringLength(str) {
  let longestLength = 0;
  let seenChars = {};
  let start = 0;

  for (let i = 0; i < str.length; i++) {
    const char = str[i];

    // Check if the current character is already seen
    if (seenChars[char]) {
      // Update the starting index of the substring
      start = Math.max(start, seenChars[char]);
    }

    // Update the length of the longest substring
    longestLength = Math.max(longestLength, i - start + 1);

    // Store the index of the next character as the starting index
    seenChars[char] = i + 1;
  }

  return longestLength;
}

const inputString = "abcabcbb123@#!";
const longestSubstringLength = findLongestSubstringLength(inputString);
console.log(longestSubstringLength); // Output: 7
```

Explanation:
1. We start by initializing the `longestLength` variable to 0, which will store the length of the longest substring found.
2. We also initialize an empty object `seenChars` to keep track of the last seen index of each character in the string.
3. We use a sliding window approach to iterate through the input string. The `start` variable keeps track of the starting index of the current substring.
4. For each character in the string, we check if it has already been seen by checking `seenChars[char]`. If it has been seen, we update the starting index of the substring to the maximum of its current value and the index of the previously seen character.
5. We then update the `longestLength` variable by taking the maximum of its current value and the length of the current substring (i - start + 1).
6. Finally, we store the index of the next character as the starting index in the `seenChars` object.
7. After iterating through the entire string, we return the `longestLength` variable, which contains the length of the longest substring without repeating characters.

