public static boolean isSubsequence(String s1, String s2) {
    int index = 0;
    for (int i = 0; i < s2.length(); i++) {
        if (index < s1.length() && s1.charAt(index) == s2.charAt(i)) {
            index++;
        }
    }
    return index == s1.length();
}
