import re

class Account:
    def __init__(self, username, password):
        self.username = username
        self.password = password
        self.balance = 0

    def deposit(self, amount):
        if amount > 0:
            self.balance += amount
            print("Deposit successful.")
        else:
            print("Invalid amount.")

    def withdraw(self, amount):
        if amount > 0:
            if self.balance >= amount:
                self.balance -= amount
                print("Withdrawal successful.")
            else:
                print("Insufficient funds.")
        else:
            print("Invalid amount.")

    def transfer(self, amount, recipient):
        if amount > 0:
            if self.balance >= amount:
                if recipient in accounts:
                    self.balance -= amount
                    accounts[recipient].balance += amount
                    print("Transfer successful.")
                else:
                    print("Recipient account does not exist.")
            else:
                print("Insufficient funds.")
        else:
            print("Invalid amount.")

    def check_balance(self):
        print(f"Your current balance is: {self.balance}")

    def change_password(self, new_password):
        if (
            len(new_password) >= 8 and
            re.search('[A-Z]', new_password) and
            re.search('[a-z]', new_password) and
            re.search('[0-9]', new_password) and
            re.search('[^A-Za-z0-9]', new_password)
        ):
            self.password = new_password
            print("Password changed successfully.")
        else:
            print("Invalid password. Please make sure it is at least 8 characters long and contains at least one uppercase letter, one lowercase letter, one digit, and one special character.")


def create_account():
    username = input("Enter a username: ")
    password = input("Enter a password: ")
    if username in accounts:
        print("Username already exists.")
    else:
        accounts[username] = Account(username, password)
        print("Account created successfully.")


def login():
    username = input("Enter your username: ")
    password = input("Enter your password: ")
    if username in accounts and accounts[username].password == password:
        return accounts[username]
    else:
        print("Invalid username or password.")
        return None


def print_menu():
    print("1. Deposit")
    print("2. Withdraw")
    print("3. Transfer")
    print("4. Check Balance")
    print("5. Change Password")
    print("6. Logout")


accounts = {}

def main():
    logged_in_account = None

    while True:
        if logged_in_account is None:
            print("\n--- Welcome to Simple Bank ---")
            print("1. Create Account")
            print("2. Login")
            print("3. Quit")
            choice = input("Enter your choice: ")

            if choice == "1":
                create_account()
            elif choice == "2":
                logged_in_account = login()
            elif choice == "3":
                break
            else:
                print("Invalid choice.")

        else:
            print("\n--- Main Menu ---")
            print_menu()
            choice = input("Enter your choice: ")

            if choice == "1":
                amount = int(input("Enter the amount to deposit: "))
                logged_in_account.deposit(amount)
            elif choice == "2":
                amount = int(input("Enter the amount to withdraw: "))
                logged_in_account.withdraw(amount)
            elif choice == "3":
                amount = int(input("Enter the amount to transfer: "))
                recipient = input("Enter the username of the recipient: ")
                logged_in_account.transfer(amount, recipient)
            elif choice == "4":
                logged_in_account.check_balance()
            elif choice == "5":
                new_password = input("Enter your new password: ")
                logged_in_account.change_password(new_password)
            elif choice == "6":
                logged_in_account = None
                print("Logged out successfully.")
            else:
                print("Invalid choice.")

    print("Thank you for using Simple Bank!")


if __name__ == "__main__":
    main()
```

In this program, the `Account` class represents a user's account. The `create_account` function allows users to create an account with a unique username and password. The `login` function verifies the username and password provided by the user and returns the corresponding `Account` object if the login is successful.

The main program loop allows users to perform different actions based on their logged-in status. When logged in, users can deposit, withdraw, transfer funds, check their balance, change their password, or log out. When not logged in, users can create a new account, log in, or quit the program.

The account information is stored in the `accounts` dictionary, with the username as the key and the `Account` object as the value. The dictionary maintains the usernames in a sorted order based on the account balances using the default sorting behavior of dictionaries.

