function convertToIntegerArray(arr) {
  var intArray = [];

  for (var i = 0; i < arr.length; i++) {
    var intValue = 0;
    var isNegative = false;

    // Handle negative numbers
    if (arr[i][0] === '-') {
      isNegative = true;
      arr[i] = arr[i].substring(1);
    }

    // Convert each digit to integer
    for (var j = 0; j < arr[i].length; j++) {
      var digitValue = arr[i].charCodeAt(j) - '0'.charCodeAt(0);
      intValue = (intValue * 10) + digitValue;
    }

    // Add negative sign if necessary
    if (isNegative) {
      intValue = -intValue;
    }

    // Add integer value to the array
    if (intValue > 0) {
      intArray.push(intValue);
    }
  }

  return intArray;
}

