import random

def validate_secret_key(key):
    if len(set(key)) != len(key):
        return False
    if not key.isupper():
        return False
    return True

def substitution_cipher(message, key):
    encrypted_message = ""
    for char in message:
        if char.isalpha():
            index = ord(char) - ord('A')
            encrypted_message += key[index]
        else:
            encrypted_message += char
    return encrypted_message

def transposition_cipher(message, key, block_size):
    blocks = [message[i:i+block_size] for i in range(0, len(message), block_size)]
    reordered_blocks = [blocks[int(i)-1] for i in key]
    encrypted_message = "".join(reordered_blocks)
    return encrypted_message

def encrypt_message(message, key, block_size):
    encrypted_message = substitution_cipher(message, key)
    encrypted_message = transposition_cipher(encrypted_message, key, block_size)
    return encrypted_message

def decrypt_message(encrypted_message, key, block_size):
    decrypted_message = transposition_cipher(encrypted_message, key, block_size)
    decrypted_message = substitution_cipher(decrypted_message, key)
    return decrypted_message

def generate_secret_key():
    letters = list("ABCDEFGHIJKLMNOPQRSTUVWXYZ")
    random.shuffle(letters)
    return "".join(letters)

def choose_substitution_cipher_algorithm():
    algorithms = ["QWERTYUIOPASDFGHJKLZXCVBNM", "ABCDEFGHIJKLMNOPQRSTUVWXYZ", "ZYXWVUTSRQPONMLKJIHGFEDCBA"]
    print("Available substitution cipher algorithms:")
    for i, algorithm in enumerate(algorithms):
        print(f"{i+1}. {algorithm}")
    choice = int(input("Choose an algorithm (1-3): "))
    return algorithms[choice-1]

def main():
    print("Welcome to the Text Encryption Program!")
    while True:
        print("\nMenu:")
        print("1. Encrypt a message")
        print("2. Decrypt a message")
        print("3. Exit")
        choice = int(input("Enter your choice (1-3): "))

        if choice == 1:
            message = input("Enter the plaintext message: ").upper().replace(" ", "")
            key = input("Enter the secret key (or press enter to generate a random key): ")
            if key == "":
                key = generate_secret_key()
                print(f"Generated secret key: {key}")
            while not validate_secret_key(key):
                print("Invalid secret key! The key must consist of unique uppercase letters only.")
                key = input("Enter the secret key (or press enter to generate a random key): ")
                if key == "":
                    key = generate_secret_key()
                    print(f"Generated secret key: {key}")
            block_size = int(input("Enter the block size for the transposition cipher: "))
            encrypted_message = encrypt_message(message, key, block_size)
            print(f"Encrypted message: {encrypted_message}")

        elif choice == 2:
            encrypted_message = input("Enter the encrypted message: ")
            key = input("Enter the secret key used for encryption: ")
            block_size = int(input("Enter the block size used for the transposition cipher: "))
            decrypted_message = decrypt_message(encrypted_message, key, block_size)
            print(f"Decrypted message: {decrypted_message}")

        elif choice == 3:
            print("Thank you for using the Text Encryption Program!")
            break

        else:
            print("Invalid choice! Please enter a valid choice (1-3).")

if __name__ == "__main__":
    main()
```

This program provides a menu-based interface for the user to encrypt or decrypt messages. The program validates the secret key and allows the user to enter a different key or generate a random one if needed. The program also prompts the user to choose the block size for the transposition cipher and the substitution cipher algorithm. The encryption and decryption processes are performed using the provided secret key and options.

