func convertPythonDictToSwiftDict(_ pythonDict: [String: Any]) -> [String: Any] {
    var swiftDict: [String: Any] = [:]

    for (key, value) in pythonDict {
        if key.hasPrefix("a") || key.hasPrefix("e") || key.hasPrefix("i") || key.hasPrefix("o") || key.hasPrefix("u") {
            if let intValue = value as? Int {
                swiftDict[key] = intValue
            } else if let intList = value as? [Int] {
                swiftDict[key] = intList.sorted()
            } else if let nestedDict = value as? [String: Any] {
                swiftDict[key] = convertPythonDictToSwiftDict(nestedDict)
            } else if let nestedDictList = value as? [[String: Any]] {
                let convertedDictList = nestedDictList.map { convertPythonDictToSwiftDict($0) }
                swiftDict[key] = convertedDictList.sorted { dict1, dict2 in
                    guard let dict1FirstKey = dict1.keys.first, let dict2FirstKey = dict2.keys.first else {
                        return false
                    }
                    return dict1FirstKey < dict2FirstKey
                }
            }
        }
    }

    return swiftDict
}

