public class BinaryCombinations {

    public static void main(String[] args) {
        List<String> combinations = generateBinaryCombinations(4);
        for (String combination : combinations) {
            System.out.println(combination);
        }
    }

    public static List<String> generateBinaryCombinations(int length) {
        List<String> combinations = new ArrayList<>();
        generateCombinations("", length, length, 0, 0, combinations);
        return combinations;
    }

    private static void generateCombinations(String combination, int length, int remainingOnes, int consecutiveZeroes, int consecutiveOnes, List<String> combinations) {
        if (length == 0 && remainingOnes == 0) {
            combinations.add(combination);
            return;
        }

        if (consecutiveZeroes == 2 || consecutiveOnes == 2) {
            return;
        }

        if (remainingOnes > 0) {
            generateCombinations(combination + "1", length - 1, remainingOnes - 1, 0, consecutiveOnes + 1, combinations);
        }

        if (length - remainingOnes > 0) {
            generateCombinations(combination + "0", length - 1, remainingOnes, consecutiveZeroes + 1, 0, combinations);
        }
    }
}
