#include <functional>
#include <queue>
#include <mutex>

int n = 100;
int numThreads = 4;
int maxTasks = 10;
std::mutex mtx;

void worker(std::queue<int>& tasks)
{
    while (!tasks.empty())
    {
        std::unique_lock<std::mutex> lock(mtx);
        if (tasks.size() > maxTasks)
        {
            lock.unlock();
            std::this_thread::yield();
            lock.lock();
        }

        int task = tasks.front();
        tasks.pop();

        std::cout << task << "\n";
    }
}

void foo(int n)
{
    std::vector<std::thread> threads;
    std::queue<int> tasks;

    for (int i = 0; i < n; i++)
    {
        tasks.push(i);
    }

    for (int i = 0; i < numThreads; i++)
    {
        threads.push_back(std::thread(worker, std::ref(tasks)));
    }

    for (int i = 0; i < numThreads; i++)
    {
        threads[i].join();
    }
}

