def word_count(sentence):
    # Initialize an empty dictionary to store the word counts
    word_counts = {}

    # Initialize an empty string to store the current word
    current_word = ""

    # Iterate through each character in the sentence
    for char in sentence:
        # Convert the character to lowercase
        char = char.lower()

        # Check if the character is a letter
        if char.isalpha():
            # Append the character to the current word
            current_word += char
        # Check if the character is a space or punctuation mark
        elif char.isspace() or char in ["!", ",", ".", "?", "'", '"', ":", ";"]:
            # Check if the current word is not empty
            if current_word:
                # Add the current word to the word counts dictionary
                if current_word in word_counts:
                    word_counts[current_word] += 1
                else:
                    word_counts[current_word] = 1

                # Reset the current word
                current_word = ""

    # Check if the current word is not empty (for the last word in the sentence)
    if current_word:
        # Add the current word to the word counts dictionary
        if current_word in word_counts:
            word_counts[current_word] += 1
        else:
            word_counts[current_word] = 1

    return word_counts

