function findCombinations(array, target) {
  let count = 0;
  let combinations = [];

  function findCombinationsHelper(currentCombination, remainingTarget, currentIndex) {
    if (remainingTarget === 0) {
      count++;
      combinations.push(currentCombination);
      return;
    }

    if (remainingTarget < 0 || currentIndex >= array.length) {
      return;
    }

    findCombinationsHelper([...currentCombination, array[currentIndex]], remainingTarget - array[currentIndex], currentIndex + 1);
    findCombinationsHelper(currentCombination, remainingTarget, currentIndex + 1);
  }

  findCombinationsHelper([], target, 0);

  return {
    count: count,
    combinations: combinations
  };
}

