    // Base case: if start and end are equal or cross each other, return
    if (start >= end) {
        return;
    }

    // Swap characters at start and end indices
    swap(str[start], str[end]);

    // Recur for the rest of the string
    reverseStringRecursion(str, start + 1, end - 1);
