```java
import java.util.Scanner;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class RemoveComments {
    public static void main(String[] args) {
        // Read the input Java program
        Scanner scanner = new Scanner(System.in);
        StringBuilder input = new StringBuilder();
        while (scanner.hasNextLine()) {
            input.append(scanner.nextLine()).append("\n");
        }
        scanner.close();

        // Remove comments from the input Java program
        String output = removeComments(input.toString());

        // Print the modified Java program without comments
        System.out.println(output);
    }

    private static String removeComments(String input) {
        // Regular expression pattern to match single-line and multi-line comments
        Pattern pattern = Pattern.compile("/\\*(.|[\\r\\n])*?\\*/|//.*");

        // Remove single-line and multi-line comments from the input Java program
        Matcher matcher = pattern.matcher(input);
        StringBuffer output = new StringBuffer();
        while (matcher.find()) {
            // Handle nested comments properly
            if (matcher.group().startsWith("/*") && matcher.group().endsWith("*/")) {
                matcher.appendReplacement(output, "");
            } else {
                matcher.appendReplacement(output, Matcher.quoteReplacement(matcher.group()));
            }
        }
        matcher.appendTail(output);

        return output.toString();
    }
}
```

