public class RectangleUtils {

    public static boolean isPointInsideRectangle(double pointX, double pointY, double rectAngle, double rectRadius, double rectWidth, double rectHeight, double rotationAngle) throws Exception {
        // Check if rectangle is invalid
        if (rectWidth < 0 || rectHeight < 0) {
            throw new Exception("Invalid rectangle: width or height is negative");
        }

        // Check if rectangle is degenerate
        if (rectWidth == 0 || rectHeight == 0) {
            throw new Exception("Degenerate rectangle: width or height is zero");
        }

        // Check if rotation angle is invalid
        if (rotationAngle > 2 * Math.PI || rotationAngle < 0) {
            throw new Exception("Invalid rotation angle: must be between 0 and 2π");
        }

        // Calculate the position of the point relative to the rectangle's top-left corner
        double relativePointX = pointX - rectRadius * Math.cos(rectAngle);
        double relativePointY = pointY - rectRadius * Math.sin(rectAngle);

        // Rotate the point based on the rectangle's rotation angle
        double rotatedPointX = relativePointX * Math.cos(rotationAngle) - relativePointY * Math.sin(rotationAngle);
        double rotatedPointY = relativePointX * Math.sin(rotationAngle) + relativePointY * Math.cos(rotationAngle);

        // Calculate the range of error for the point
        double errorRange = 0.001;

        // Check if the rotated point is inside the rectangle
        if (rotatedPointX >= -rectWidth/2 - errorRange && rotatedPointX <= rectWidth/2 + errorRange &&
            rotatedPointY >= -rectHeight/2 - errorRange && rotatedPointY <= rectHeight/2 + errorRange) {
            return true;
        } else {
            return false;
        }
    }
}
