import java.util.*;

public class TwoSum {
    public static int[] twoSum(int[] arr, int target) {
        // Create a HashMap to store the complement value and its index
        HashMap<Integer, Integer> map = new HashMap<>();

        // Iterate through the array
        for (int i = 0; i < arr.length; i++) {
            // Check if the complement value exists in the HashMap
            if (map.containsKey(target - arr[i])) {
                // Return the indices of the two elements
                return new int[] {map.get(target - arr[i]), i};
            }

            // Add the current element and its index to the HashMap
            map.put(arr[i], i);
        }

        // Return [-1, -1] if no such pair exists
        return new int[] {-1, -1};
    }

