    } else if (sortingOrder == 2) {
        sortPtr = &selectionSort;
    } else {
        printf("Invalid sorting order.\n");
        return 0;
    }

    // Sort the array using the function pointer
    (*sortPtr)(arr, n);

    printf("Sorted array: ");
    printArray(arr, n);

    return 0;
}
```

