```java
public class DayOfMonth {
    public static void main(String[] args) {
        // Create a Date object with the desired date
        Date date = new Date(2022, 2, 15);

        // Get the day of the month
        int dayOfMonth = getDayOfMonth(date);

        // Print the result
        System.out.println("Day of the month: " + dayOfMonth);
    }

    public static int getDayOfMonth(Date date) {
        // Calculate the number of days since January 1st of the given year
        int days = 0;
        for (int i = 1; i < date.getMonth(); i++) {
            days += getDaysInMonth(i, date.getYear());
        }

        // Add the number of days in the current month
        days += date.getDay();

        // Return the result
        return days;
    }

    public static int getDaysInMonth(int month, int year) {
        // Handle leap years
        if (month == 2 && isLeapYear(year)) {
            return 29;
        }

        // Return the number of days in the given month
        switch (month) {
            case 1:
            case 3:
            case 5:
            case 7:
            case 8:
            case 10:
            case 12:
                return 31;
            case 4:
            case 6:
            case 9:
            case 11:
                return 30;
            default:
                return -1; // Invalid month
        }
    }

    public static boolean isLeapYear(int year) {
        // Leap years are divisible by 4, but not by 100 (unless divisible by 400)
        return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
    }
}
