Here is the implementation of a DoublyLinkedList class in Java with the additional functionalities:

```java
class DoublyLinkedList {
    Node head;

    static class Node {
        int data;
        Node prev;
        Node next;

        Node(int data) {
            this.data = data;
            prev = null;
            next = null;
        }
    }

    // 1. Insert a new node at the beginning of the list
    void insertAtBeginning(int data) {
        Node newNode = new Node(data);
        newNode.next = head;

        if (head != null) {
            head.prev = newNode;
        }

        head = newNode;
    }

    // 2. Insert a new node at the end of the list
    void insertAtEnd(int data) {
        Node newNode = new Node(data);

        if (head == null) {
            head = newNode;
            return;
        }

        Node lastNode = head;
        while (lastNode.next != null) {
            lastNode = lastNode.next;
        }

        lastNode.next = newNode;
        newNode.prev = lastNode;
    }

    // 3. Insert a new node after a specific node in the list
    void insertAfterNode(Node prevNode, int data) {
        if (prevNode == null) {
            System.out.println("Previous node cannot be null.");
            return;
        }

        Node newNode = new Node(data);
        newNode.next = prevNode.next;
        prevNode.next = newNode;
        newNode.prev = prevNode;

        if (newNode.next != null) {
            newNode.next.prev = newNode;
        }
    }

    // 4. Delete a node from the list
    void deleteNode(Node node) {
        if (head == null || node == null) {
            return;
        }

        if (head == node) {
            head = node.next;
        }

        if (node.next != null) {
            node.next.prev = node.prev;
        }

        if (node.prev != null) {
            node.prev.next = node.next;
        }
    }

    // 5. Reverse the order of the nodes in the list
    void reverse() {
        Node temp = null;
        Node current = head;

        while (current != null) {
            temp = current.prev;
            current.prev = current.next;
            current.next = temp;
            current = current.prev;
        }

        if (temp != null) {
            head = temp.prev;
        }
    }

    // 6. Check if the list contains a certain value
    boolean contains(int value) {
        Node current = head;

        while (current != null) {
            if (current.data == value) {
                return true;
            }

            current = current.next;
        }

        return false;
    }

    // 7. Find the length of the list
    int length() {
        int count = 0;
        Node current = head;

        while (current != null) {
            count++;
            current = current.next;
        }

        return count;
    }

    // 8. Remove all duplicate values from the list
    void removeDuplicates() {
        Node current = head;

        while (current != null) {
            Node temp = current.next;

            while (temp != null) {
                if (current.data == temp.data) {
                    Node next = temp.next;
                    deleteNode(temp);
                    temp = next;
                } else {
                    temp = temp.next;
                }
            }

            current = current.next;
        }
    }

    // 9. Sort the list in ascending order
    void sort() {
        Node current = head, index = null;
        int temp;

        if (head == null) {
            return;
        } else {
            while (current != null) {
                index = current.next;

                while (index != null) {
                    if (current.data > index.data) {
                        temp = current.data;
                        current.data = index.data;
                        index.data = temp;
                    }

                    index = index.next;
                }

                current = current.next;
            }
        }
    }

    // 10. Check if the list is palindrome
    boolean isPalindrome() {
        Node start = head;
        Node end = head;

        while (end.next != null) {
            end = end.next;
        }

        while (start != end && start != null && end != null) {
            if (start.data != end.data) {
                return false;
            }

            start = start.next;
            end = end.prev;
        }

        return true;
    }

    // 11. Merge two sorted lists into one sorted list
    static DoublyLinkedList mergeSortedLists(DoublyLinkedList list1, DoublyLinkedList list2) {
        DoublyLinkedList mergedList = new DoublyLinkedList();
        Node node1 = list1.head, node2 = list2.head;

        while (node1 != null && node2 != null) {
            if (node1.data <= node2.data) {
                mergedList.insertAtEnd(node1.data);
                node1 = node1.next;
            } else {
                mergedList.insertAtEnd(node2.data);
                node2 = node2.next;
            }
        }

        while (node1 != null) {
            mergedList.insertAtEnd(node1.data);
            node1 = node1.next;
        }

        while (node2 != null) {
            mergedList.insertAtEnd(node2.data);
            node2 = node2.next;
        }

        return mergedList;
    }

    // 12. Split the list into two halves
    DoublyLinkedList[] splitList() {
        DoublyLinkedList[] splitLists = new DoublyLinkedList[2];
        splitLists[0] = new DoublyLinkedList();
        splitLists[1] = new DoublyLinkedList();

        Node slowPtr = head, fastPtr = head;

        while (fastPtr != null && fastPtr.next != null) {
            slowPtr = slowPtr.next;
            fastPtr = fastPtr.next.next;
        }

        splitLists[0].head = head;
        splitLists[1].head = slowPtr.next;

        splitLists[0].head.prev = null;
        splitLists[1].head.prev = null;

        slowPtr.next = null;

        return splitLists;
    }

    // Helper method to print the list
    void printList() {
