  // Case 3: If N is negative, return null
  if (N < 0) {
    return null;
  }

  // Case 4: If N is zero, return the last element of the array
  if (N === 0) {
    return arr[arr.length - 1];
  }

  // Case 5: If N is a positive number, return the Nth element from the end of the array
  if (N > 0) {
    return arr[arr.length - N];
  }

  // Case 6: If N is equal to the length of the array, return the first element of the array
  if (N === arr.length) {
    return arr[0];
  }
}
