#include <iostream>
#include <ctime>
#include <string>

class HelloPrinter {
private:
    std::string name;
    int count;

public:
    HelloPrinter(const std::string& newName) : name(newName), count(0) {}

    void printHello(int numTimes) {
        if (numTimes <= 0) {
            return;
        }

        std::time_t currentTime = std::time(nullptr);
        std::cout << "Hello World! - Current Date and Time: " << std::ctime(&currentTime);

        for (int i = 0; i < numTimes; i++) {
            std::cout << "Hello World! - Name: " << name << std::endl;
        }

        count += numTimes;
    }

    void setName(const std::string& newName) {
        if (newName.empty() || newName.find_first_not_of(' ') == std::string::npos) {
            throw std::invalid_argument("Invalid name");
        }

        name = newName;
    }

    int getCount() const {
        return count;
    }

    // Copy constructor
    HelloPrinter(const HelloPrinter& other) : name(other.name), count(other.count) {}

    // Assignment operator
    HelloPrinter& operator=(const HelloPrinter& other) {
        if (this != &other) {
            name = other.name;
            count = other.count;
        }
        return *this;
    }
};
