Here's a function in C that takes a string as input and corrects all occurrences of two or more consecutive spaces with a single space:

```c
#include <stdio.h>
#include <string.h>

void editString(char* str) {
    int i, j;
    int len = strlen(str);
    int space_count = 0;

    for (i = 0, j = 0; i < len; i++) {
        // If the character is a space or a tab
        if (str[i] == ' ' || str[i] == '\t') {
            // Increment the space_count
            space_count++;

            // If it's a space and there are more than 1 consecutive spaces, skip it
            if (str[i] == ' ' && space_count > 1) {
                continue;
            }

            // If it's a tab and there are more than 1 consecutive tabs, skip it
            if (str[i] == '\t' && space_count > 1) {
                continue;
            }

            // Otherwise, add the character to the new string
            str[j++] = str[i];
        } 
        else {
            // If the character is not a space or a tab, reset the space_count
            space_count = 0;

            // Add the character to the new string
            str[j++] = str[i];
        }
    }

    // Null terminate the new string
    str[j] = '\0';
}

int main() {
    char str[100] = "Hi   everyone   ";

    printf("Before: %s\n", str);
    editString(str);
    printf("After: %s\n", str);

    return 0;
}
