Here's a JavaScript program that checks if a number is within a given range, where the lower bound and upper bound values are dynamic and can only be prime numbers. It also validates if the given range is a consecutive prime number range:

```javascript
// Function to check if a number is prime
function isPrime(num) {
  if (num <= 1) return false;
  if (num <= 3) return true;

  if (num % 2 === 0 || num % 3 === 0) return false;

  let i = 5;
  while (i * i <= num) {
    if (num % i === 0 || num % (i + 2) === 0) return false;
    i += 6;
  }

  return true;
}

// Function to check if the range is consecutive prime numbers
function isConsecutivePrimeRange(lowerBound, upperBound) {
  let isConsecutive = true;

  for (let i = lowerBound + 1; i < upperBound; i++) {
    if (!isPrime(i)) {
      isConsecutive = false;
      break;
    }
  }

  return isConsecutive;
}

// Function to check if a number is within the given range
function isInRange(number, lowerBound, upperBound) {
  if (isPrime(lowerBound) && isPrime(upperBound) && isConsecutivePrimeRange(lowerBound, upperBound)) {
    return number >= lowerBound && number <= upperBound;
  }

  return false;
}

// Example usage
const lowerBound = 5;  // Dynamic lower bound prime number
const upperBound = 11; // Dynamic upper bound prime number
const numberToCheck = 7;

console.log(isInRange(numberToCheck, lowerBound, upperBound)); // Output: true
```

In this program, the `isPrime` function checks if a number is prime using the optimized algorithm called the "Sieve of Eratosthenes". The `isConsecutivePrimeRange` function checks if the numbers between the lower and upper bounds are consecutive prime numbers. The `isInRange` function combines both functions and checks if a given number is within the range while ensuring the lower and upper bounds are prime and the range is consecutive prime numbers.

