function extractAlphabeticalSubstring($string, $start, $length) {
    // Remove any non-alphabetical characters from the string
    $string = preg_replace('/[^a-zA-Z]/', '', $string);

    // If start index is greater than the length of the string, return an empty string
    if ($start >= strlen($string)) {
        return "";
    }

    // If length is negative, adjust it to the length of the remaining substring
    if ($length < 0) {
        $length = strlen($string) - $start;
    }

    // Extract the substring based on start and length, and reverse it
    $substring = strrev(substr($string, $start, $length));

