// Function to encrypt a sentence using Vigenère cipher
void encrypt(char *sentence, char *key) {
    int sentence_len = strlen(sentence);
    int key_len = strlen(key);

    for (int i = 0; i < sentence_len; i++) {
        if (isalpha(sentence[i])) {
            int shift = tolower(key[i % key_len]) - 'a';
            char base = isupper(sentence[i]) ? 'A' : 'a';
            sentence[i] = (sentence[i] - base + shift) % 26 + base;
        }
    }
}

// Function to decrypt an encrypted sentence using Vigenère cipher
void decrypt(char *encrypted, char *key) {
    int encrypted_len = strlen(encrypted);
    int key_len = strlen(key);

    for (int i = 0; i < encrypted_len; i++) {
        if (isalpha(encrypted[i])) {
            int shift = tolower(key[i % key_len]) - 'a';
            char base = isupper(encrypted[i]) ? 'A' : 'a';
            encrypted[i] = (encrypted[i] - base - shift + 26) % 26 + base;
        }
    }
}

// Function to calculate the frequency of each letter in a sentence
void calculateFrequency(char *sentence, int *frequency) {
    int len = strlen(sentence);

    for (int i = 0; i < len; i++) {
        if (isalpha(sentence[i])) {
            int index = tolower(sentence[i]) - 'a';
            frequency[index]++;
        }
    }
}

// Function to display frequency distribution in descending order
void displayFrequency(int *frequency) {
    printf("Frequency Distribution:\n");

    for (int i = 25; i >= 0; i--) {
        printf("%c: %d\n", 'a' + i, frequency[i]);
    }
}

