```python
import numpy as np

class NeuralNetwork:
    def __init__(self, input_size, hidden_sizes, output_size, activation='sigmoid'):
        self.input_size = input_size
        self.hidden_sizes = hidden_sizes
        self.output_size = output_size

        self.weights = []
        self.biases = []
        self.activations = []

        # Initialize weights and biases randomly
        sizes = [input_size] + hidden_sizes + [output_size]
        for i in range(len(sizes) - 1):
            self.weights.append(np.random.randn(sizes[i], sizes[i+1]))
            self.biases.append(np.random.randn(sizes[i+1]))

        # Set activation function
        if activation == 'sigmoid':
            self.activation_func = self.sigmoid
            self.activation_derivative = self.sigmoid_derivative
        elif activation == 'relu':
            self.activation_func = self.relu
            self.activation_derivative = self.relu_derivative
        elif activation == 'tanh':
            self.activation_func = self.tanh
            self.activation_derivative = self.tanh_derivative

    def forward(self, X):
        self.layer_outputs = []
        self.layer_outputs.append(X)

        for i in range(len(self.weights)):
            X = self.activation_func(np.dot(X, self.weights[i]) + self.biases[i])
            self.layer_outputs.append(X)

        return X

    def backward(self, X, y, learning_rate):
        d_weights = []
        d_biases = []

        # Compute gradients
        error = self.loss_derivative(y, self.layer_outputs[-1]) * self.activation_derivative(self.layer_outputs[-1])
        d_weights.append(np.dot(self.layer_outputs[-2].T, error))
        d_biases.append(np.sum(error, axis=0))

        for i in range(len(self.weights) - 1, 0, -1):
            error = np.dot(error, self.weights[i].T) * self.activation_derivative(self.layer_outputs[i])
            d_weights.append(np.dot(self.layer_outputs[i-1].T, error))
            d_biases.append(np.sum(error, axis=0))

        # Update weights and biases
        for i in range(len(self.weights)):
            self.weights[i] -= learning_rate * d_weights[-(i+1)]
            self.biases[i] -= learning_rate * d_biases[-(i+1)]

    def train(self, X, y, learning_rate, epochs):
        for epoch in range(epochs):
            output = self.forward(X)
            self.backward(X, y, learning_rate)

            if epoch % 100 == 0:
                loss = self.loss(y, output)
                print(f"Epoch {epoch}: Loss = {loss}")

    def predict(self, X):
        return self.forward(X)

    def sigmoid(self, x):
        return 1 / (1 + np.exp(-x))

    def sigmoid_derivative(self, x):
        return x * (1 - x)

    def relu(self, x):
        return np.maximum(0, x)

    def relu_derivative(self, x):
        return np.where(x <= 0, 0, 1)

    def tanh(self, x):
        return np.tanh(x)

    def tanh_derivative(self, x):
        return 1 - np.tanh(x) ** 2

    def loss(self, y_true, y_pred):
        return np.mean((y_true - y_pred) ** 2)

    def loss_derivative(self, y_true, y_pred):
        return 2 * (y_pred - y_true)
```

