Here is a C# method that finds the longest common subsequence of two strings:

```csharp
public static string FindLongestCommonSubsequence(string s1, string s2)
{
    if (string.IsNullOrEmpty(s1) || string.IsNullOrEmpty(s2))
    {
        return string.Empty;
    }

    int m = s1.Length;
    int n = s2.Length;

    int[,] dp = new int[m + 1, n + 1];

    for (int i = 1; i <= m; i++)
    {
        for (int j = 1; j <= n; j++)
        {
            if (s1[i - 1] == s2[j - 1])
            {
                dp[i, j] = dp[i - 1, j - 1] + 1;
            }
            else
            {
                dp[i, j] = Math.Max(dp[i - 1, j], dp[i, j - 1]);
            }
        }
    }

    StringBuilder sb = new StringBuilder();

    int x = m, y = n;

    while (x > 0 && y > 0)
    {
        if (s1[x - 1] == s2[y - 1])
        {
            sb.Insert(0, s1[x - 1]);
            x--;
            y--;
        }
        else if (dp[x - 1, y] > dp[x, y - 1])
        {
            x--;
        }
        else
        {
            y--;
        }
    }

    return sb.ToString();
}
```

