1. The email address must not contain any special characters such as !, #, $, %, etc.
2. The email address must not start with a number.
3. The email address must be at least 6 characters long.
4. The error message should specify the reason for the invalid email address (e.g., "Invalid format", "Contains special characters", "Starts with a number", "Too short").

<form>
    <input type="text" name="email" required>
    <span id="error-msg" style="display: none; color: red;"></span>
    <input type="submit" value="Submit" onclick="validateEmail(event)">
</form>

<script>
    function validateEmail(event) {
        event.preventDefault();
        var emailInput = document.getElementsByName('email')[0];
        var errorSpan = document.getElementById('error-msg');
        var email = emailInput.value;

        if (!validateFormat(email)) {
            errorSpan.style.display = 'inline';
            errorSpan.innerText = 'Invalid format';
            return;
        }
        if (containsSpecialCharacters(email)) {
            errorSpan.style.display = 'inline';
            errorSpan.innerText = 'Contains special characters';
            return;
        }
        if (startsWithNumber(email)) {
            errorSpan.style.display = 'inline';
            errorSpan.innerText = 'Starts with a number';
            return;
        }
        if (isTooShort(email)) {
            errorSpan.style.display = 'inline';
            errorSpan.innerText = 'Too short';
            return;
        }
        errorSpan.style.display = 'none';
        // Other validation logic or submission code here
    }

    function validateFormat(email) {
        var pattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        return pattern.test(email);
    }

    function containsSpecialCharacters(email) {
        var pattern = /^[a-zA-Z0-9]+$/;
        return !pattern.test(email);
    }

    function startsWithNumber(email) {
        var pattern = /^[0-9]/;
        return pattern.test(email);
    }

    function isTooShort(email) {
        return email.length < 6;
    }
</script>

