```javascript
function removeVowelsAndConvertToRoman(str) {
  const vowels = ['a', 'e', 'i', 'o', 'u'];
  const romanNumerals = {
    1: 'I',
    4: 'IV',
    5: 'V',
    9: 'IX',
    10: 'X',
    40: 'XL',
    50: 'L',
    90: 'XC',
    100: 'C',
    400: 'CD',
    500: 'D',
    900: 'CM',
    1000: 'M'
  };

  let result = '';

  for (let i = 0; i < str.length; i++) {
    const char = str[i];

    if (!isNaN(char)) {
      // If the character is a number, convert it to Roman numeral
      let num = Number(char);
      let romanNumeral = '';

      // Find the largest Roman numeral that is less than or equal to the number
      const romanNumeralKeys = Object.keys(romanNumerals).sort((a, b) => b - a);
      for (let j = 0; j < romanNumeralKeys.length; j++) {
        const key = romanNumeralKeys[j];
        if (num >= key) {
          romanNumeral = romanNumerals[key];
          num -= key;
          break;
        }
      }

      result += romanNumeral;
    } else if (!vowels.includes(char.toLowerCase())) {
      // If the character is not a vowel, add it to the result
      result += char;
    }
  }

  return result;
}
```

