void countCharacterFrequency(string str) {
    vector<pair<char, int>> frequency;
    for (char c : str) {
        if (isalpha(c)) {
            bool found = false;
            for (auto &pair : frequency) {
                if (tolower(pair.first) == tolower(c)) {
                    pair.second++;
                    found = true;
                    break;
                }
            }
            if (!found) {
                frequency.push_back(make_pair(tolower(c), 1));
            }
        }
    }
    sort(frequency.begin(), frequency.end(), [](const pair<char, int>& a, const pair<char, int>& b) {
        if (a.second == b.second) {
            return a.first < b.first;
        }
        return a.second > b.second;
    });
