}

// Function to check if a given string is a valid email address
bool isValidEmail(string email) {
    size_t atIndex = email.find('@');
    size_t dotIndex = email.find('.');
    if (atIndex == string::npos || dotIndex == string::npos || atIndex >= dotIndex) {
        return false;
    }
    string username = email.substr(0, atIndex);
    string domain = email.substr(atIndex + 1, dotIndex - atIndex - 1);
    string extension = email.substr(dotIndex + 1);
    for (char c : username) {
        if (!isalnum(c) && c != '.' && c != '_' && c != '-') {
            return false;
        }
    }
    for (char c : domain) {
        if (!isalnum(c) && c != '.') {
            return false;
        }
    }
    return true;
}

// Function to convert a given binary number to its decimal equivalent
int binaryToDecimal(string binary) {
    int decimal = 0;
    int power = 0;
    for (int i = binary.length() - 1; i >= 0; i--) {
        if (binary[i] == '1') {
            decimal += pow(2, power);
        }
        power++;
    }
    return decimal;
}

// Function to check if a number is prime
bool isPrime(int number) {
    if (number <= 1) {
        return false;
    }
    for (int i = 2; i <= sqrt(number); i++) {
        if (number % i == 0) {
            return false;
        }
    }
    return true;
}

// Function to find the largest prime number within a given range of numbers
int findLargestPrime(int start, int end) {
    int largestPrime = -1;
    for (int i = start; i <= end; i++) {
        if (isPrime(i)) {
            largestPrime = i;
        }
    }
    return largestPrime;
}

