function mergeArrays(A, B) {
  let merged = [];
  let indexA = 0;
  let indexB = 0;

  while (indexA < A.length || indexB < B.length) {
    if (indexA < A.length) {
      merged.push(A[indexA]);
      indexA++;
    }

    if (indexB < B.length) {
