function findMinMaxAvgMedianMode(numbers) {
  let uniqueNumbers = [...new Set(numbers)];
  let min = uniqueNumbers[0];
  let max = uniqueNumbers[0];
  let sum = uniqueNumbers[0];
  let mode = {};
  let maxFrequency = 0;

  // Find min, max, and sum
  for (let i = 1; i < uniqueNumbers.length; i++) {
    let currentNumber = uniqueNumbers[i];
    min = Math.min(min, currentNumber);
    max = Math.max(max, currentNumber);
    sum += currentNumber;
  }

  let average = sum / uniqueNumbers.length;

  // Find mode
  for (let i = 0; i < numbers.length; i++) {
    let currentNumber = numbers[i];
    mode[currentNumber] = (mode[currentNumber] || 0) + 1;
    maxFrequency = Math.max(maxFrequency, mode[currentNumber]);
  }

  let modes = Object.keys(mode).filter(key => mode[key] === maxFrequency);

  // Find median
  uniqueNumbers.sort((a, b) => a - b);
  let median;
  if (uniqueNumbers.length % 2 === 0) {
    let midIndex = uniqueNumbers.length / 2;
    median = (uniqueNumbers[midIndex - 1] + uniqueNumbers[midIndex]) / 2;
  } else {
    median = uniqueNumbers[Math.floor(uniqueNumbers.length / 2)];
  }

  console.log("Minimum:", min);
  console.log("Maximum:", max);
  console.log("Average:", average);
  console.log("Median:", median);
  console.log("Mode:", modes);
}

