function getAsciiSum(str) {
  let sum = 0;
  for (let i = 0; i < str.length; i++) {
    sum += str.charCodeAt(i);
  }
  return sum;
}

function compareStrings(str1, str2) {
  const sum1 = getAsciiSum(str1);
  const sum2 = getAsciiSum(str2);

  if (sum1 !== sum2) {
    return sum2 - sum1; // sort by descending ASCII sum
  } else {
    return str1.localeCompare(str2); // sort lexicographically
  }
}

function sortStringsByAsciiSum(arr) {
  return arr.sort(compareStrings);
}

