        raise ZeroDivisionError("Division by zero is not allowed")
    return a / b

# Function to perform square root
def sqrt(a):
    return math.sqrt(a)

# Function to perform exponentiation
def power(a, b):
    return a ** b

# Function to perform logarithm
def log(a, b):
    return math.log(a, b)

# Function to perform trigonometric functions
def sin(a):
    return math.sin(a)

def cos(a):
    return math.cos(a)

def tan(a):
    return math.tan(a)

# Function to store the result in memory
def store_result(result):
    global memory
    memory = result

# Function to retrieve the result from memory
def retrieve_result():
    return memory

# Function to evaluate an expression
def evaluate_expression(expression):
    try:
        # Split the expression into operands and operator
        parts = expression.split()
        if len(parts) != 3:
            raise ValueError("Invalid expression")

        operand1 = None
        operand2 = None

        # Check if the first operand is a number or a keyword
        if parts[0].lower() == "previous_result":
            operand1 = retrieve_result()
        else:
            operand1 = float(parts[0])

        # Check if the second operand is a number or a keyword
        if parts[2].lower() == "previous_result":
            operand2 = retrieve_result()
        else:
            operand2 = float(parts[2])

        operator = parts[1]

        # Perform the appropriate operation
        if operator == "+":
            result = add(operand1, operand2)
        elif operator == "-":
            result = subtract(operand1, operand2)
        elif operator == "*":
            result = multiply(operand1, operand2)
        elif operator == "/":
            result = divide(operand1, operand2)
        elif operator == "sqrt":
            result = sqrt(operand1)
        elif operator == "^":
            result = power(operand1, operand2)
        elif operator == "log":
            result = log(operand1, operand2)
        elif operator == "sin":
            result = sin(operand1)
        elif operator == "cos":
            result = cos(operand1)
        elif operator == "tan":
            result = tan(operand1)
        else:
            raise ValueError("Invalid operator")

        # Store the result in memory
        store_result(result)

        # Add the expression and result to history
        history.append(f"{expression} = {result}")

        # Return the result
        return result

    except ValueError as e:
        print("Error:", e)
    except ZeroDivisionError as e:
        print("Error:", e)

# Main loop
while True:
