            return;
        }

        // Calculate and display the sum of all the numbers in the series
        long sum = fibonacciSum(size);
        System.out.println("\nSum of the Fibonacci series: " + sum);

        // Calculate and display the average of the numbers in the series
        double average = (double) sum / size;
        System.out.println("Average of the Fibonacci series: " + average);

        scanner.close();
    }

    // Generate the Fibonacci series using recursion
    public static long fibonacciRecursion(int n) {
        if (n <= 1) {
            return n;
        }
        return fibonacciRecursion(n - 1) + fibonacciRecursion(n - 2);
    }

    // Generate the Fibonacci series using iteration
    public static long fibonacciIteration(int n) {
        if (n <= 1) {
            return n;
        }
        long fib = 1;
        long prevFib = 1;
        for (int i = 2; i < n; i++) {
            long temp = fib;
            fib += prevFib;
            prevFib = temp;
        }
        return fib;
    }

    // Calculate the sum of all the numbers in the series
    public static long fibonacciSum(int size) {
        long sum = 0;
        for (int i = 0; i < size; i++) {
            sum += fibonacciIteration(i);
        }
        return sum;
    }
}
```

This program allows the user to enter the desired size of the Fibonacci series and choose whether to generate it using recursion or iteration. It also validates the user input, calculates and displays the sum and average of the numbers in the series. The program is implemented in a way that minimizes memory usage by calculating each Fibonacci number only once.

