public static int removeDuplicates(int[] nums) {
    int length = nums.length;

    if (length == 0 || length == 1) {
        return length;
    }

    int index = 1;
    for (int i = 1; i < length; i++) {
        int j;
        for (j = 0; j < i; j++) {
            if (nums[i] == nums[j]) {
