```perl
#!/usr/bin/perl

use strict;
use warnings;

# Function to calculate the nth Fibonacci number
sub fibonacci {
    my $n = shift;

    # Base cases
    if ($n == 0) {
        return 0;
    } elsif ($n == 1) {
        return 1;
    }

    # Recursive case
    return fibonacci($n-1) + fibonacci($n-2);
}

# Function to generate the Fibonacci series in reverse order
sub reverse_fibonacci {
    my $n = shift;

    # Print the Fibonacci series in reverse order
    for (my $i = $n; $i >= 0; $i--) {
        print fibonacci($i), " ";
    }
    print "\n";
}

# Get the input from the user
print "Enter the number of terms in the Fibonacci series: ";
my $num_terms = <STDIN>;

# Call the reverse_fibonacci function
reverse_fibonacci($num_terms-1);
```

