import java.util.Arrays;

public class PrimePower {

    public static void main(String[] args) {
        int[] input = {5, 2}; // Example input array
        try {
            int result = calculatePower(input);
            System.out.println("Result: " + result);
        } catch (IllegalArgumentException e) {
            System.out.println(e.getMessage());
        }
    }

    public static int calculatePower(int[] input) {
        if (input == null || input.length != 2) {
            throw new IllegalArgumentException("Input array must contain exactly two numbers");
        }

        int base = input[0];
        int exponent = input[1];

        if (!isPrime(base) || !isPrime(exponent)) {
            throw new IllegalArgumentException("Input array must contain two positive prime numbers");
        }

        if (!isInRange(base, exponent)) {
            throw new IllegalArgumentException("Input numbers are not within the specified range");
        }

        return (int) Math.pow(base, exponent);
    }

    public static boolean isPrime(int number) {
        if (number <= 1) {
            return false;
        }
        for (int i = 2; i <= Math.sqrt(number); i++) {
            if (number % i == 0) {
                return false;
            }
        }
        return true;
    }

    public static boolean isInRange(int base, int exponent) {
        int largestSmallerPrime = base - 1;
        while (!isPrime(largestSmallerPrime)) {
            largestSmallerPrime--;
        }

        int smallestLargerPrime = exponent + 1;
        while (!isPrime(smallestLargerPrime)) {
            smallestLargerPrime++;
        }

        return base > largestSmallerPrime && exponent < smallestLargerPrime;
    }
}
```

Explanation:

- The `calculatePower` method takes an array as input, performs all the necessary checks, and returns the result of raising the first number to the power of the second number.
