Here is an example implementation of a C++ object representing a 2D point with the mentioned features:

```cpp
#include <iostream>
#include <cmath>

class Point {
private:
    int x;
    int y;

public:
    Point(int xCoordinate, int yCoordinate) {
        if (xCoordinate < -1000 || xCoordinate > 1000 || yCoordinate < -1000 || yCoordinate > 1000) {
            std::cout << "Invalid coordinates!" << std::endl;
            exit(1);
        }

        x = xCoordinate;
        y = yCoordinate;
    }

    int getX() const {
        return x;
    }

    int getY() const {
        return y;
    }

    double distanceTo(const Point& otherPoint) const {
        int dx = x - otherPoint.x;
        int dy = y - otherPoint.y;
        return std::sqrt(dx * dx + dy * dy);
    }

    double angleTo(const Point& otherPoint) const {
        int dx = otherPoint.x - x;
        int dy = otherPoint.y - y;
        double radians = std::atan2(dy, dx);
        double degrees = radians * 180 / M_PI;
        if (degrees < 0) {
            degrees += 360;
        }
        return degrees;
    }

    void rotate(double angle) {
        double radians = angle * M_PI / 180;
        double cosAngle = std::cos(radians);
        double sinAngle = std::sin(radians);

        int newX = std::round(x * cosAngle - y * sinAngle);
        int newY = std::round(x * sinAngle + y * cosAngle);

        x = newX;
        y = newY;
    }

    void translate(const Point& vector) {
        x += vector.x;
        y += vector.y;
    }

    void scale(float factor) {
        x = std::round(x * factor);
        y = std::round(y * factor);
    }
};

int main() {
    Point p1(3, 4);
    Point p2(-2, 1);

    std::cout << "Distance between p1 and p2: " << p1.distanceTo(p2) << std::endl;
    std::cout << "Angle between p1 and p2: " << p1.angleTo(p2) << std::endl;

    p1.rotate(45);
    std::cout << "Rotated p1: (" << p1.getX() << ", " << p1.getY() << ")" << std::endl;

    Point translationVector(2, 3);
    p1.translate(translationVector);
    std::cout << "Translated p1: (" << p1.getX() << ", " << p1.getY() << ")" << std::endl;

    p1.scale(2.5);
    std::cout << "Scaled p1: (" << p1.getX() << ", " << p1.getY() << ")" << std::endl;

    return 0;
}
```

