Here is an implementation of the function that checks if the brackets in the string are properly nested without using any built-in stack data structure:

```java
public class BracketValidator {

    public static boolean isProperlyNested(String input) {
        int countRoundBrackets = 0;
        int countSquareBrackets = 0;
        int countCurlyBrackets = 0;

        for (char c : input.toCharArray()) {
            if (c == '(') {
                countRoundBrackets++;
            } else if (c == ')') {
                countRoundBrackets--;
            } else if (c == '[') {
                countSquareBrackets++;
            } else if (c == ']') {
                countSquareBrackets--;
            } else if (c == '{') {
                countCurlyBrackets++;
            } else if (c == '}') {
                countCurlyBrackets--;
            }

            if (countRoundBrackets < 0 || countSquareBrackets < 0 || countCurlyBrackets < 0) {
                return false; // More closing brackets than opening brackets
            }
        }

        return countRoundBrackets == 0 && countSquareBrackets == 0 && countCurlyBrackets == 0;
    }

    public static void main(String[] args) {
        String input1 = "(({}))";
        String input2 = "[[{()}]]";
        String input3 = "{(})";

        System.out.println(isProperlyNested(input1)); // Output: true
        System.out.println(isProperlyNested(input2)); // Output: true
        System.out.println(isProperlyNested(input3)); // Output: false
    }
}
```

The `isProperlyNested` function iterates through each character in the input string. Whenever it encounters an opening bracket, it increments the corresponding counter. Similarly, when it encounters a closing bracket, it decrements the corresponding counter.

If at any point, the counter for any type of bracket becomes negative, it means there are more closing brackets than opening brackets. In such a case, the function returns false immediately.

At the end, the function checks if all three counters are zero, indicating that all opening brackets have been closed properly. If this condition is true, the function returns true, otherwise false.

In the `main` method, we test the function with three different input strings and print the corresponding outputs.

Here is a C++ program that implements a binary tree and includes the functionalities you have mentioned:

```cpp
#include <iostream>
using namespace std;

class Node {
public:
    int data;
    Node* left;
    Node* right;

    Node(int value) {
        data = value;
        left = nullptr;
        right = nullptr;
    }
};

class BinaryTree {
private:
    Node* root;

    Node* insertRecursive(Node* current, int value) {
        if (current == nullptr) {
            return new Node(value);
        }

        if (value < current->data) {
            current->left = insertRecursive(current->left, value);
        }
        else if (value > current->data) {
            current->right = insertRecursive(current->right, value);
        }

        return current;
    }

    Node* deleteRecursive(Node* current, int value) {
        if (current == nullptr) {
            return nullptr;
        }

        if (value == current->data) {
            if (current->left == nullptr && current->right == nullptr) {
                delete current;
                return nullptr;
            }
            else if (current->left == nullptr) {
                Node* temp = current->right;
                delete current;
                return temp;
            }
            else if (current->right == nullptr) {
                Node* temp = current->left;
                delete current;
                return temp;
            }
            else {
                Node* smallestNode = findSmallestNode(current->right);
                current->data = smallestNode->data;
                current->right = deleteRecursive(current->right, smallestNode->data);
            }
        }
        else if (value < current->data) {
            current->left = deleteRecursive(current->left, value);
        }
        else if (value > current->data) {
            current->right = deleteRecursive(current->right, value);
        }

        return current;
    }

    Node* findSmallestNode(Node* current) {
        while (current->left != nullptr) {
            current = current->left;
        }
        return current;
    }

    Node* searchRecursive(Node* current, int value) {
        if (current == nullptr || current->data == value) {
            return current;
        }

        if (value < current->data) {
            return searchRecursive(current->left, value);
        }
        else {
            return searchRecursive(current->right, value);
        }
    }

    int findHeightRecursive(Node* current) {
        if (current == nullptr) {
            return -1;
        }

        int leftHeight = findHeightRecursive(current->left);
        int rightHeight = findHeightRecursive(current->right);

        return max(leftHeight, rightHeight) + 1;
    }

    void inorderTraversalRecursive(Node* current) {
        if (current != nullptr) {
            inorderTraversalRecursive(current->left);
            cout << current->data << " ";
            inorderTraversalRecursive(current->right);
        }
    }

public:
    BinaryTree() {
        root = nullptr;
    }

    void insert(int value) {
        root = insertRecursive(root, value);
    }

    void remove(int value) {
        root = deleteRecursive(root, value);
    }

    bool search(int value) {
        Node* node = searchRecursive(root, value);
        return (node != nullptr);
    }

    int getHeight() {
        return findHeightRecursive(root);
    }

    void displayInorderTraversal() {
        inorderTraversalRecursive(root);
        cout << endl;
    }
};

int main() {
    BinaryTree tree;

    tree.insert(50);
    tree.insert(30);
    tree.insert(20);
    tree.insert(40);
    tree.insert(70);
    tree.insert(60);
    tree.insert(80);

    cout << "Inorder Traversal: ";
    tree.displayInorderTraversal();

    cout << "Height of the tree: " << tree.getHeight() << endl;

    int element = 40;
    if (tree.search(element)) {
        cout << element << " is found in the tree." << endl;
    }
    else {
        cout << element << " is not found in the tree." << endl;
    }

    tree.remove(40);

    cout << "Inorder Traversal after deleting 40: ";
    tree.displayInorderTraversal();

    return 0;
}
```

