        return words.containsKey(word);
    }

    public int getWordCount() {
        return words.size();
    }

    public List<String> getWordsStartingWith(String prefix) {
        List<String> result = new ArrayList<>();
        for (String word : words.keySet()) {
            if (word.startsWith(prefix)) {
                result.add(word);
            }
        }
        return result;
    }

