    setIsLoggedIn(false);
  };

  const handleMenuExpand = () => {
    setIsMenuExpanded(!isMenuExpanded);
  };

  const handleKeyDown = (event) => {
    if (!isMenuExpanded) return;

    if (event.key === 'ArrowUp') {
      event.preventDefault();
      setSelectedMenuItem((prev) => (prev === null ? menuItems.length - 1 : prev - 1));
    } else if (event.key === 'ArrowDown') {
      event.preventDefault();
      setSelectedMenuItem((prev) => (prev === null ? 0 : (prev + 1) % menuItems.length));
    } else if (event.key === 'Enter') {
      event.preventDefault();
      handleMenuClick(selectedMenuItem);
    }
  };

  const handleMenuClick = (index) => {
    setSelectedMenuItem(null);
    setIsMenuExpanded(false);
    // Handle menu item click logic here
  };

  return (
    <nav className={`navbar ${isSticky ? 'sticky' : ''}`}>
      <div className="navbar-logo" style={{ color: logoColor }} onClick={handleLogoClick}>
        Logo
      </div>
      <ul className={`navbar-menu ${isMenuExpanded ? 'expanded' : ''}`}>
        {menuItems.map((item, index) => (
          <li
            key={index}
            className={`navbar-menu-item ${selectedMenuItem === index ? 'highlighted' : ''}`}
            onMouseEnter={() => handleMenuItemHover(index)}
            onClick={() => handleMenuClick(index)}
          >
            <Link to={item.link}>{item.name}</Link>
          </li>
        ))}
        <li className="navbar-menu-dropdown" onClick={handleDropdownToggle}>
          Dropdown
          {showDropdown && (
            <ul className="dropdown-menu" ref={dropdownRef}>
              {dropdownItems.map((item, index) => (
                <li key={index} onClick={() => handleMenuClick(index)}>
                  <Link to={item.link}>{item.name}</Link>
                </li>
              ))}
              {isLoggedIn ? (
                <li onClick={handleLogout}>
                  <span>Logout</span>
                </li>
              ) : (
                <li>
                  <Link to="/login">Login</Link>
                </li>
              )}
            </ul>
          )}
        </li>
      </ul>
      {notificationCount > 0 && (
        <div className="notification-badge">{notificationCount}</div>
      )}
      <button className="menu-button" onClick={handleMenuExpand}>
        <div className={`menu-icon ${isMenuExpanded ? 'expanded' : ''}`} />
      </button>
    </nav>
  );
};

