```cpp
#include <iostream>
#include <vector>
#include <cmath>
#include <stdexcept>

template<typename T>
std::vector<T> normalizeVector(const std::vector<T>& vector) {
    std::vector<T> result;
    T magnitude = 0;

    // Calculate the magnitude of the vector
    for (const T& value : vector) {
        magnitude += value * value;
    }
    magnitude = std::sqrt(magnitude);

    // Check if the magnitude is zero
    if (magnitude == 0) {
        throw std::runtime_error("Cannot normalize a vector with zero magnitude");
    }

    // Normalize the vector
    for (const T& value : vector) {
        result.push_back(value / magnitude);
    }

    return result;
}

int main() {
    std::vector<int> intVector = {3, 4};  // Example integer vector
    std::vector<float> floatVector = {1.5, 2.0, 2.5};  // Example floating-point vector

    try {
        std::vector<int> normalizedIntVector = normalizeVector(intVector);
        std::cout << "Normalized integer vector: ";
        for (const int& value : normalizedIntVector) {
            std::cout << value << " ";
        }
        std::cout << std::endl;
    } catch (const std::exception& e) {
        std::cout << "Error: " << e.what() << std::endl;
    }

    try {
        std::vector<float> normalizedFloatVector = normalizeVector(floatVector);
        std::cout << "Normalized floating-point vector: ";
        for (const float& value : normalizedFloatVector) {
            std::cout << value << " ";
        }
        std::cout << std::endl;
    } catch (const std::exception& e) {
        std::cout << "Error: " << e.what() << std::endl;
    }

    return 0;
}
```

This implementation uses a template function to handle both integer and floating-point vectors. It first calculates the magnitude of the vector using the Euclidean norm (square root of the sum of the squares of the vector components). If the magnitude is zero, it throws a std::runtime_error exception. Otherwise, it normalizes the vector by dividing each component by the magnitude and returns the normalized vector.

In the main function, we test the normalizeVector function with an example integer vector and an example floating-point vector. The normalized vectors are then printed. If an exception occurs during the normalization process, the error message is printed instead.

