function fibonacciSeries(n) {
  let fibonacci = [0, 1]; // Initialize the Fibonacci series array with the first two numbers
  let sum = 1; // Initialize the sum variable with the sum of the first two numbers

  while (fibonacci[fibonacci.length - 1] + fibonacci[fibonacci.length - 2] <= n) {
    let nextNumber = fibonacci[fibonacci.length - 1] + fibonacci[fibonacci.length - 2];
    fibonacci.push(nextNumber);
    sum += nextNumber;
  }

  console.log("Fibonacci series up to", n + ":");
