Process findProcessWithHighestExecutionTime(const std::vector<Process>& processes) {
    if (processes.empty()) {
        // Return a default process or handle the error appropriately
        return Process();
    }

    Process highestExecutionTimeProcess = processes[0];

    for (int i = 1; i < processes.size(); i++) {
        if (processes[i].executionTime > highestExecutionTimeProcess.executionTime) {
            highestExecutionTimeProcess = processes[i];
        }
    }

    return highestExecutionTimeProcess;
