bool isPrime(int num) {
    if (num <= 1) {
        return false;
    }
    for (int i = 2; i <= sqrt(num); i++) {
        if (num % i == 0) {
            return false;
        }
    }
    return true;
}

int largestPrime(int arr[], int size) {
    int maxPrime = 0;
    int maxPrimeIndex = -1;
    for (int i = 0; i < size; i++) {
        if (isPrime(arr[i])) {
            if (arr[i] > maxPrime) {
                maxPrime = arr[i];
                maxPrimeIndex = i;
            }
        }
    }
    return maxPrimeIndex;
}

int main() {
    int size;
    std::cout << "Enter the size of the array: ";
    std::cin >> size;

    int* arr = new int[size];
    std::cout << "Enter the elements of the array: ";
    for (int i = 0; i < size; i++) {
        std::cin >> arr[i];
    }

    int largestPrimeIndex = largestPrime(arr, size);
    if (largestPrimeIndex == -1) {
        std::cout << "No prime numbers found in the array." << std::endl;
    } else {
        std::cout << "The largest prime number in the array is: " << arr[largestPrimeIndex] << std::endl;
        std::cout << "Its index position is: " << largestPrimeIndex << std::endl;
    }

    delete[] arr;
    return 0;
}
