double calculateArea(double radius) {
    return M_PI * pow(radius, 2);
}

double calculateCircumference(double radius) {
    return 2 * M_PI * radius;
}

bool isPositiveNumber(double number) {
    return number >= 0;
}

bool isValidInput() {
    if (cin.fail()) {
        cin.clear();
        cin.ignore(numeric_limits<streamsize>::max(), '\n');
        return false;
    }
    return true;
}

double getRadiusFromUser() {
    double radius;
    while (true) {
        cout << "Enter the radius of the circle: ";
        cin >> radius;
        if (isValidInput() && isPositiveNumber(radius)) {
            break;
        }
        cout << "Invalid input. Please enter a positive number for the radius." << endl;
    }
    return radius;
}

int main() {
    int choice;
    double radius;

    while (true) {
        cout << "Menu:" << endl;
        cout << "1. Calculate the area of the circle" << endl;
        cout << "2. Calculate the circumference of the circle" << endl;
        cout << "0. Exit" << endl;
        cout << "Enter your choice: ";
        cin >> choice;

        if (isValidInput()) {
            switch (choice) {
                case 1:
                    radius = getRadiusFromUser();
                    cout.precision(2);
                    cout << "The area of the circle is: " << fixed << calculateArea(radius) << endl;
                    break;
                case 2:
                    radius = getRadiusFromUser();
                    cout.precision(2);
                    cout << "The circumference of the circle is: " << fixed << calculateCircumference(radius) << endl;
                    break;
                case 0:
                    cout << "Exiting the program." << endl;
                    return 0;
                default:
                    cout << "Invalid choice. Please enter a valid menu option." << endl;
                    break;
            }
        }
        else {
            cout << "Invalid input. Please enter a valid menu option." << endl;
        }
        cin.ignore(numeric_limits<streamsize>::max(), '\n');
    }
}
