import matplotlib.animation as animation
from multiprocessing import Pool

class GameOfLife:
    def __init__(self, size, iterations):
        self.size = size
        self.iterations = iterations
        self.grid = np.zeros((size, size), dtype=int)
        self.fig, self.ax = plt.subplots()
        self.im = self.ax.imshow(self.grid, cmap='binary')

    def initialize_grid(self, pattern):
        if pattern == "random":
            self.random_pattern()
        elif pattern == "glider":
            self.glider_pattern()
        # Add more patterns here

    def random_pattern(self):
        for i in range(self.size):
            for j in range(self.size):
                self.grid[i][j] = random.randint(0, 1)

    def glider_pattern(self):
        self.grid[0][1] = 1
        self.grid[1][2] = 1
        self.grid[2][0] = 1
        self.grid[2][1] = 1
        self.grid[2][2] = 1

    def count_live_cells(self):
        return np.sum(self.grid)

    def update_grid(self, frame):
        new_grid = np.copy(self.grid)
        pool = Pool()
        indices = [(i, j) for i in range(self.size) for j in range(self.size)]
        new_grid = pool.map(self.update_cell, indices)
        pool.close()
        pool.join()
        self.grid = np.reshape(new_grid, (self.size, self.size))
        self.im.set_array(self.grid)
        return self.im,

    def update_cell(self, index):
        i, j = index
        current_state = self.grid[i][j]
        live_neighbors = self.count_live_neighbors(i, j)

        if current_state == 0 and live_neighbors == 3:
            return 1
        elif current_state == 1 and (live_neighbors < 2 or live_neighbors > 3):
            return 0
        else:
            return current_state

    def count_live_neighbors(self, i, j):
        count = 0
        for x in range(-1, 2):
            for y in range(-1, 2):
                if x == 0 and y == 0:
                    continue
                if (i + x >= 0 and i + x < self.size) and (j + y >= 0 and j + y < self.size):
                    count += self.grid[i + x][j + y]
        return count

    def run_simulation(self):
        ani = animation.FuncAnimation(self.fig, self.update_grid, frames=self.iterations, interval=200, blit=True)
        plt.show()

