public class LongestString {
    public static void main(String[] args) {
        String string1 = "helloo";
        String string2 = "worldddd";

        int longestLength = getLongestStringLength(string1, string2);
        System.out.println("Length of the longest string: " + longestLength);

        int commonSubstringLength = getCommonSubstringLength(string1, string2);
        System.out.println("Length of the common substring: " + commonSubstringLength);
    }

    public static int getLongestStringLength(String string1, String string2) {
        int length1 = 0;
        int length2 = 0;

        for (char c : string1.toCharArray()) {
            length1++;
        }

        for (char c : string2.toCharArray()) {
            length2++;
        }

        return Math.max(length1, length2);
    }

    public static int getCommonSubstringLength(String string1, String string2) {
        int maxLength = 0;
        int[][] lengths = new int[string1.length()][string2.length()];

        for (int i = 0; i < string1.length(); i++) {
            for (int j = 0; j < string2.length(); j++) {
                if (string1.charAt(i) == string2.charAt(j)) {
                    if (i == 0 || j == 0) {
                        lengths[i][j] = 1;
                    } else {
                        lengths[i][j] = lengths[i - 1][j - 1] + 1;
                    }
                    maxLength = Math.max(maxLength, lengths[i][j]);
                }
            }
        }

        return maxLength;
    }
}
