public class HashMapExample {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int numOfElements = getNumOfElements(scanner);
        int capacity = 1000;

        HashMap<String, Integer> hashMap = new HashMap<>();

        for (int i = 0; i < numOfElements; i++) {
            System.out.print("Enter key (max length 20 characters): ");
            String key = scanner.next();

            if (key.length() > 20) {
                System.out.println("Invalid key length. Please enter a key with maximum length of 20 characters.");
                i--;
                continue;
            }

            System.out.print("Enter value (between -1000 and 1000): ");
            int value = scanner.nextInt();

            if (value < -1000 || value > 1000) {
                System.out.println("Invalid value. Please enter a value between -1000 and 1000 (inclusive).");
                i--;
                continue;
            }

            hashMap.put(key, value);

            System.out.println("Current size of the HashMap: " + hashMap.size());
            System.out.println("Current capacity of the HashMap: " + capacity);
        }

        System.out.println("HashMap elements: ");
        for (Map.Entry<String, Integer> entry : hashMap.entrySet()) {
            System.out.println("Key: " + entry.getKey() + ", Value: " + entry.getValue());
        }

        System.out.print("Enter a key to remove an element from the HashMap (press 'N' to skip): ");
        String keyToRemove = scanner.next();

        if (!keyToRemove.equalsIgnoreCase("N")) {
            Integer removedValue = hashMap.remove(keyToRemove);
            if (removedValue != null) {
                System.out.println("Element with key '" + keyToRemove + "' has been removed from the HashMap.");
            } else {
                System.out.println("No element with key '" + keyToRemove + "' found in the HashMap.");
            }
        }

        System.out.println("HashMap elements in ascending order of keys: ");
        Map<String, Integer> sortedHashMap = new TreeMap<>(hashMap);
        for (Map.Entry<String, Integer> entry : sortedHashMap.entrySet()) {
            System.out.println("Key: " + entry.getKey() + ", Value: " + entry.getValue());
        }
    }

    private static int getNumOfElements(Scanner scanner) {
        int numOfElements = 0;
        boolean validInput = false;

        while (!validInput) {
            try {
                System.out.print("Enter the number of elements to add to the HashMap: ");
                numOfElements = Integer.parseInt(scanner.next());
                if (numOfElements > 0) {
                    validInput = true;
                } else {
                    System.out.println("Invalid input. Please enter a positive number.");
                }
            } catch (NumberFormatException e) {
                System.out.println("Invalid input. Please enter a valid number.");
            }
        }

        return numOfElements;
    }
}

