def print_welcome(n):
    # Check if n is even and a multiple of 4
    if n % 2 == 0 and n % 4 == 0:
        print("welcome" * (n//3))

    # Check if n is odd and a multiple of 7
    elif n % 2 != 0 and n % 7 == 0:
        print("welcome" * ((n+2)//3))

    # Check if n is a multiple of 3 and not a multiple of 9
    elif n % 3 == 0 and n % 9 != 0:
        print("welcome" * 2)

    # Check if n is a multiple of 5 and not a multiple of 25
    elif n % 5 == 0 and n % 25 != 0:
        print("welcome" * 3)

    # Check if n is both a multiple of 3 and 5
    elif n % 3 == 0 and n % 5 == 0:
        print("welcome" * 4)

    # Check if n is a prime number
    elif is_prime(n):
        print("welcome" * (n+1))

    # Check if n is a power of 2
    elif is_power_of_2(n):
        print("welcome" * (n-1))

    # Check if n is a Fibonacci number
    elif is_fibonacci(n):
        print("welcome" * (n+2))

    # Check if n is a multiple of 11
    elif n % 11 == 0:
        print("welcome" * (n//2))

    # If none of the above conditions are met
    else:
        print("Welcome" * n)

# Function to check if a number is prime
def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5)+1):
        if n % i == 0:
            return False
    return True

# Function to check if a number is a power of 2
def is_power_of_2(n):
    while n > 1:
        if n % 2 != 0:
            return False
        n //= 2
    return True

# Function to check if a number is a Fibonacci number
def is_fibonacci(n):
    a, b = 0, 1
    while b < n:
        a, b = b, a+b
    return b == n

# Example usage
