public class RecursiveMultiplication {
    private static int recursiveCalls = 0;

    public static int recursiveMultiply(int a, int b) {
        if (a < -1000 || a > 1000 || b < -1000 || b > 1000) {
            throw new IllegalArgumentException("Input integers are outside the specified range.");
        }

        recursiveCalls++;
        if (a == 0 || b == 0) {
            return 0;
        } else if (b > 0) {
            return a + recursiveMultiply(a, b - 1);
        } else {
            return -recursiveMultiply(a, -b);
        }
    }

    public static double recursiveMultiply(double a, double b) {
        if (a < -1000.0 || a > 1000.0 || b < -1000.0 || b > 1000.0) {
            throw new IllegalArgumentException("Input numbers are outside the specified range.");
        }

        recursiveCalls++;
        if (a == 0 || b == 0) {
            return 0.0;
        } else if (b > 0) {
            return a + recursiveMultiply(a, b - 1.0);
        } else {
            return -recursiveMultiply(a, -b);
        }
    }

    public static int recursiveMultiply(int... numbers) {
        if (numbers.length == 0) {
            throw new IllegalArgumentException("No numbers provided for multiplication.");
        }

        int result = 1;
        for (int num : numbers) {
            if (num < -1000 || num > 1000) {
                throw new IllegalArgumentException("Input integers are outside the specified range.");
            }
            result = recursiveMultiply(result, num);
        }
        return result;
    }

    public static void main(String[] args) {
        System.out.println(recursiveMultiply(2, 3)); // Output: 6
        System.out.println(recursiveMultiply(-2, 3)); // Output: -6
        System.out.println(recursiveMultiply(-2, -3)); // Output: 6

        System.out.println(recursiveMultiply(2.5, 3.5)); // Output: 8.75
        System.out.println(recursiveMultiply(-2.5, 3.5)); // Output: -8.75
        System.out.println(recursiveMultiply(-2.5, -3.5)); // Output: 8.75

