        System.out.println(recursiveMultiply(-2, 3, 4)); // Output: -24
        System.out.println(recursiveMultiply(-2, -3, -4)); // Output: -24

        System.out.println("Number of recursive calls: " + recursiveCalls);
    }
}
```

