        self.first_name = first_name
        self.last_name = last_name
        self.age = age
        self.grade = 0
        self.subjects = []

    def calculate_average_grade(self):
        total_grades = 0
        for subject in self.subjects:
            total_grades += subject[1]
        return total_grades / len(self.subjects)

    def add_subject(self, subject_name, grade):
        self.subjects.append((subject_name, grade))

    def remove_subject(self, subject_name):
        for subject in self.subjects:
            if subject[0] == subject_name:
                self.subjects.remove(subject)
                break

    def update_grade(self, subject_name, new_grade):
        for i, subject in enumerate(self.subjects):
            if subject[0] == subject_name:
                self.subjects[i] = (subject_name, new_grade)
                break

