            ]
        };

        // Function to generate the table from JSON object
        function generateTable() {
            var table = document.getElementById("jsonTable");
            var data = jsonData.data;

            // Clear existing table rows
            while (table.rows.length > 1) {
                table.deleteRow(1);
            }

            // Generate table rows
            for (var i = 0; i < data.length; i++) {
                var row = table.insertRow(i + 1);

                var nameCell = row.insertCell(0);
                nameCell.innerHTML = data[i].name;

                var ageCell = row.insertCell(1);
                ageCell.innerHTML = data[i].age;

                var activeCell = row.insertCell(2);
                activeCell.innerHTML = data[i].active;
            }
        }

        // Function to sort table by column
        function sortTable(column) {
            var table, rows, switching, i, x, y, shouldSwitch;
            table = document.getElementById("jsonTable");
            switching = true;

            while (switching) {
                switching = false;
                rows = table.rows;

                for (i = 1; i < (rows.length - 1); i++) {
                    shouldSwitch = false;
                    x = rows[i].getElementsByTagName("td")[column].innerHTML;
                    y = rows[i + 1].getElementsByTagName("td")[column].innerHTML;

                    // Compare values based on data type
                    if (column === 1) {  // Number
                        if (Number(x) > Number(y)) {
                            shouldSwitch = true;
                            break;
                        }
                    } else if (column === 2) {  // Boolean
                        if (x === "true" && y === "false") {
                            shouldSwitch = true;
                            break;
                        }
                    } else {  // String
                        if (x.toLowerCase() > y.toLowerCase()) {
                            shouldSwitch = true;
                            break;
                        }
                    }
                }

                if (shouldSwitch) {
                    rows[i].parentNode.insertBefore(rows[i + 1], rows[i]);
                    switching = true;
                }
            }
        }
