public class EvenNumbersSum {

    public static void main(String[] args) {
        int[] nums = {2, 4, 6, 10, 11, 14, 20};

        List<Integer> evenNumbers = new ArrayList<>();

        for (int num : nums) {
            if (num % 2 == 0) {
                evenNumbers.add(num);
            }
        }

