```matlab
function bubbleSort(arr)
    n = length(arr);
    swapped = true;

    while swapped
        swapped = false;

        for i = 1:n-1
            if arr(i) > arr(i+1)
                temp = arr(i);
                arr(i) = arr(i+1);
                arr(i+1) = temp;
                swapped = true;
            end
        end

        n = n - 1;
    end

    disp(arr);
end
