Here's the JavaScript code that implements this:

```javascript
function isPrime(num) {
  if (num < 2) {
    return false;
  }
  for (let i = 2; i <= Math.sqrt(num); i++) {
    if (num % i === 0) {
      return false;
    }
  }
  return true;
}

function findProductOfPrimes(list) {
  let largest = Math.max(...list);
  let product = 1;
  let foundPrime = false;

  for (let num = 2; num <= largest; num++) {
    if (isPrime(num)) {
      product *= num;
      foundPrime = true;
    }
  }

  return foundPrime ? product : 0;
}

// Example usage
const list = [8, 3, 6, 7, 12, 5, 15, 11];
const productOfPrimes = findProductOfPrimes(list);
console.log(productOfPrimes); // Output: 3 * 5 * 7 * 11 = 1155
```

