```python
class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

class CircularLinkedList:
    def __init__(self):
        self.head = None

    def append(self, data):
        new_node = Node(data)
        if not self.head:
            self.head = new_node
            self.head.next = self.head
        else:
            curr_node = self.head
            while curr_node.next != self.head:
                curr_node = curr_node.next
            curr_node.next = new_node
            new_node.next = self.head

    def prepend(self, data):
        new_node = Node(data)
        new_node.next = self.head

        if not self.head:
            new_node.next = new_node
        else:
            curr_node = self.head
            while curr_node.next != self.head:
                curr_node = curr_node.next
            curr_node.next = new_node

        self.head = new_node

    def delete(self, data):
        if not self.head:
            return

        curr_node = self.head
        prev_node = None
        while curr_node.next != self.head:
            if curr_node.data == data:
                if prev_node:
                    prev_node.next = curr_node.next
                else:
                    while curr_node.next != self.head:
                        curr_node = curr_node.next
                    curr_node.next = self.head.next
                    self.head = self.head.next
                return
            prev_node = curr_node
            curr_node = curr_node.next

        if curr_node.data == data:
            if prev_node:
                prev_node.next = self.head
            else:
                self.head = None

    def print_list(self):
        if not self.head:
            return

        curr_node = self.head
        while True:
            print(curr_node.data, end=' ')
            curr_node = curr_node.next
            if curr_node == self.head:
                break
        print()

# Example usage:
cll = CircularLinkedList()
cll.append(1)
cll.append(2)
cll.append(3)
cll.prepend(4)
cll.print_list()  # Output: 4 1 2 3
cll.delete(2)
cll.print_list()  # Output: 4 1 3
```

This implementation defines two classes: `Node` and `CircularLinkedList`. The `Node` class represents a single node in the linked list, while the `CircularLinkedList` class implements the circular linked list data structure. The `append` method adds a new node to the end of the list, the `prepend` method adds a new node to the beginning of the list, and the `delete` method removes a node with the given data from the list. The `print_list` method prints all the elements in the list.

