import React, { useState, useEffect } from 'react';

const GridList = () => {
  const [items, setItems] = useState([]);
  const [search, setSearch] = useState('');
  const [sorted, setSorted] = useState(false);

  // Generate a random background color
  const getRandomColor = () => {
    const letters = '0123456789ABCDEF';
    let color = '#';
    for (let i = 0; i < 6; i++) {
      color += letters[Math.floor(Math.random() * 16)];
    }
    return color;
  };

  // Generate a new item with a random background color
  const generateItem = () => {
    const newItem = {
      id: Math.random().toString(36).substring(7),
      color: getRandomColor(),
      name: 'Item ' + (items.length + 1)
    };
    return newItem;
  };

  // Insert the new item at a random position in the grid
  const addItem = () => {
    const newItem = generateItem();
    const randomIndex = Math.floor(Math.random() * (items.length + 1));
    const newItems = [...items];
    newItems.splice(randomIndex, 0, newItem);
    setItems(newItems);
  };

  // Remove a random item from the grid
  const removeItem = () => {
    const randomIndex = Math.floor(Math.random() * items.length);
    const newItems = [...items];
    newItems.splice(randomIndex, 1);
    setItems(newItems);
  };

  // Sort the items in alphabetical order
  const sortItems = () => {
    const newItems = [...items];
    newItems.sort((a, b) => a.name.localeCompare(b.name));
    setItems(newItems);
    setSorted(true);
  };

  // Reset the grid to its original state
  const resetGrid = () => {
    setItems([]);
    setSearch('');
    setSorted(false);
  };

  // Filter the items by their name
  const filteredItems = items.filter(item =>
    item.name.toLowerCase().includes(search.toLowerCase())
  );

  useEffect(() => {
    // Change the background color of each item every second
    const interval = setInterval(() => {
      setItems(prevItems =>
        prevItems.map(item => ({ ...item, color: getRandomColor() }))
      );
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  return (
    <div>
      <div>
        <button onClick={addItem}>Add Item</button>
        <button onClick={removeItem}>Remove Item</button>
        <button onClick={sortItems}>Sort Items</button>
        <button onClick={resetGrid}>Reset Grid</button>
      </div>
      <input
        type="text"
        value={search}
        onChange={e => setSearch(e.target.value)}
        placeholder="Search by name"
      />
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, 200px)',
          gridGap: '10px',
          justifyContent: 'center'
        }}
      >
        {filteredItems.map(item => (
          <div
            key={item.id}
            style={{
              backgroundColor: item.color,
              padding: '10px',
              borderRadius: '5px'
            }}
          >
            {item.name}
          </div>
        ))}
      </div>
    </div>
  );
};

export default GridList;
