public static int Fibonacci(int n)
{
    if (n == 0)
    {
        return 0;
    }
    else if (n == 1)
    {
        return 1;
    }
    else
    {
        return FibonacciHelper(0, 1, n - 2);
    }
}

private static int FibonacciHelper(int a, int b, int n)
{
    if (n == 0)
    {
        return a + b;
    }
    else
    {
        return FibonacciHelper(b, a + b, n - 1);
    }
}
