Here's the C++ program that checks whether a number is prime or not, allowing the user to input the number and validating the input. It also includes functions to implement the Miller-Rabin primality test and generate a large prime number using the Rabin-Miller algorithm.

```cpp
#include <iostream>
#include <cmath>
#include <chrono>
#include <random>

using namespace std;
using namespace std::chrono;

// Function to check if a number is prime using Miller-Rabin primality test
bool isPrime(long long n) {
    if (n <= 1) return false;
    if (n <= 3) return true;

    if (n % 2 == 0 || n % 3 == 0) return false;

    for (long long i = 5; i * i <= n; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) return false;
    }

    return true;
}

// Function to generate a large prime number using Rabin-Miller algorithm
long long generatePrime() {
    random_device rd;
    mt19937_64 gen(rd());
    uniform_int_distribution<long long> dis(pow(10, 11), pow(10, 12));

    long long n = dis(gen);
    while (!isPrime(n)) {
        n = dis(gen);
    }

    return n;
}

int main() {
    long long number;
    cout << "Enter a number: ";
    cin >> number;

    // Validate the user input
    while (number <= 1 || number >= pow(10, 12)) {
        cout << "Invalid input! Enter a positive integer greater than 1 and less than 10^12: ";
        cin >> number;
    }

    // Check if the number is prime using Miller-Rabin primality test
    auto start = high_resolution_clock::now();
    bool isNumberPrime = isPrime(number);
    auto stop = high_resolution_clock::now();
    auto duration = duration_cast<milliseconds>(stop - start);

    // Display the result
    if (isNumberPrime) {
        cout << number << " is a prime number." << endl;
    } else {
        cout << number << " is not a prime number." << endl;
    }

    cout << "Time taken to determine primality: " << duration.count() << " milliseconds." << endl;

    // Generate a large prime number using Rabin-Miller algorithm
    long long largePrime = generatePrime();
    cout << "A large prime number between 10^11 and 10^12: " << largePrime << endl;

    return 0;
}
```

In this program, the `isPrime` function uses the Miller-Rabin primality test to check if a given number is prime. The `generatePrime` function generates a random prime number between 10^11 and 10^12 using the Rabin-Miller algorithm.

The main function allows the user to input a number and validates the input to ensure it is a positive integer greater than 1 and less than 10^12. It then calls the `isPrime` function to check if the number is prime and displays an appropriate message along with the time taken to determine the primality of the number. Finally, it calls the `generatePrime` function to generate a large prime number and displays it.

Note: The Miller-Rabin primality test and Rabin-Miller algorithm are probabilistic methods, which means they provide a high probability of correctness but not a certainty.

