Improve the efficiency of the given Java program by implementing a binary search algorithm to search for a specific element in the list.

public class Debug {
    public static void main(String[] args) {
        List<String> list = new ArrayList<String>();
        list.add("Hello");
        list.add("World");
        list.add("Programming");
        list.add("Test");
        list.add("Question");
        System.out.println(list);

        String target = "Programming";
        int index = binarySearch(list, target);
        if (index != -1) {
            System.out.println("Found at index: " + index);
        } else {
            System.out.println("Not found in the list.");
        }
    }

    public static int binarySearch(List<String> list, String target) {
        int low = 0;
        int high = list.size() - 1;

        while (low <= high) {
            int mid = (low + high) / 2;
            int comparison = target.compareTo(list.get(mid));

            if (comparison == 0) {
                return mid;
            } else if (comparison < 0) {
                high = mid - 1;
