  // Add 5 random uppercase letters
  for (let i = 0; i < 5; i++) {
    randomString += uppercaseLetters.charAt(Math.floor(Math.random() * uppercaseLetters.length));
  }

  // Add 5 random lowercase letters
  for (let i = 0; i < 5; i++) {
    randomString += lowercaseLetters.charAt(Math.floor(Math.random() * lowercaseLetters.length));
  }

  // Add 5 random digits
  for (let i = 0; i < 5; i++) {
    randomString += digits.charAt(Math.floor(Math.random() * digits.length));
  }

  // Add 5 random special characters
  for (let i = 0; i < 5; i++) {
    randomString += specialCharacters.charAt(Math.floor(Math.random() * specialCharacters.length));
  }

  // Fill the remaining length with random characters from all categories
  const remainingLength = 20 - randomString.length;
  const allCharacters = uppercaseLetters + lowercaseLetters + digits + specialCharacters;
  for (let i = 0; i < remainingLength; i++) {
