Here's a script that sorts the elements of an array in ascending order, placing all negative integers before all positive integers while maintaining the original order within their respective groups. It has a time complexity of O(n) and a space complexity of O(1).

```javascript
function sortArray(arr) {
  let i = 0; // Pointer for negative numbers
  let j = arr.length - 1; // Pointer for positive numbers

  while (i <= j) {
    if (arr[i] >= 0 && arr[j] < 0) {
      // Swap positive number with negative number
      let temp = arr[i];
      arr[i] = arr[j];
      arr[j] = temp;
      i++;
      j--;
    } else {
      if (arr[i] < 0) {
        i++; // Increment pointer for negative numbers
      }
      if (arr[j] >= 0) {
        j--; // Decrement pointer for positive numbers
      }
    }
  }

  return arr;
}

// Test the script
