struct Node {
    int value;
    Node* left;
    Node* right;
};

int max_depth(Node* root) {
    if (root == nullptr) {
        return 0;
    }

    int left_depth = max_depth(root->left);
    int right_depth = max_depth(root->right);

    return std::max(left_depth, right_depth) + 1;
}

int main() {
    // Create a binary tree
    Node* root = new Node();
    root->value = 1;

    Node* leftChild = new Node();
    leftChild->value = 2;
    root->left = leftChild;

    Node* rightChild = new Node();
    rightChild->value = 3;
    root->right = rightChild;

    Node* grandChild = new Node();
    grandChild->value = 4;
    leftChild->left = grandChild;

    // Compute the maximum depth
    int depth = max_depth(root);
    std::cout << "Maximum depth: " << depth << std::endl;

    // Clean up the memory
    delete grandChild;
    delete leftChild;
    delete rightChild;
    delete root;

    return 0;
}
