public class Point {
    private int x;
    private int y;
    private int z;

    public Point(int x, int y, int z) {
        setX(x);
        setY(y);
        setZ(z);
    }

    public int getX() {
        return x;
    }

    public void setX(int x) {
        if (x < -1000 || x > 1000) {
            throw new IllegalArgumentException("x-coordinate out of range");
        }
        this.x = x;
    }

    public int getY() {
        return y;
    }

    public void setY(int y) {
        if (y < -1000 || y > 1000) {
            throw new IllegalArgumentException("y-coordinate out of range");
        }
        this.y = y;
    }

    public int getZ() {
        return z;
    }

    public void setZ(int z) {
        if (z < -1000 || z > 1000) {
            throw new IllegalArgumentException("z-coordinate out of range");
        }
        this.z = z;
    }

    public double distance(Point other) {
        int dx = x - other.getX();
        int dy = y - other.getY();
        int dz = z - other.getZ();
        return Math.sqrt(dx*dx + dy*dy + dz*dz);
    }

    public void translate(int dx, int dy, int dz) {
        setX(x + dx);
        setY(y + dy);
        setZ(z + dz);
    }

    @Override
    public String toString() {
        return "(" + x + ", " + y + ", " + z + ")";
    }

    public double calculateAngle(Point other) {
        double dx = other.getX() - x;
        double dy = other.getY() - y;
        double dz = other.getZ() - z;
        double angle = Math.atan2(dy, dx) + Math.atan2(dz, Math.sqrt(dx*dx + dy*dy));
        return Math.toDegrees(angle);
    }

    public void rotateX(double angle) {
        if (angle < 0 || angle > 360) {
            throw new IllegalArgumentException("Rotation angle out of range");
        }
        double radianAngle = Math.toRadians(angle);
        double cosAngle = Math.cos(radianAngle);
        double sinAngle = Math.sin(radianAngle);
        int newY = (int) (y * cosAngle - z * sinAngle);
        int newZ = (int) (y * sinAngle + z * cosAngle);
        setY(newY);
        setZ(newZ);
    }

    public void rotateY(double angle) {
        if (angle < 0 || angle > 360) {
            throw new IllegalArgumentException("Rotation angle out of range");
        }
        double radianAngle = Math.toRadians(angle);
        double cosAngle = Math.cos(radianAngle);
        double sinAngle = Math.sin(radianAngle);
        int newX = (int) (x * cosAngle + z * sinAngle);
        int newZ = (int) (-x * sinAngle + z * cosAngle);
        setX(newX);
        setZ(newZ);
    }

    public void rotateZ(double angle) {
        if (angle < 0 || angle > 360) {
            throw new IllegalArgumentException("Rotation angle out of range");
        }
        double radianAngle = Math.toRadians(angle);
        double cosAngle = Math.cos(radianAngle);
        double sinAngle = Math.sin(radianAngle);
        int newX = (int) (x * cosAngle - y * sinAngle);
        int newY = (int) (x * sinAngle + y * cosAngle);
        setX(newX);
        setY(newY);
    }
}
