  var relativeLuminance = (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255;

  // Set the text color to white if the background color is dark, otherwise set it to black
  return (relativeLuminance > 0.5) ? '#000000' : '#FFFFFF';
}

