```csharp
using System;

class Program
{
    static bool ContainsConsecutiveSubstring(string mainString, string substring)
    {
        // Convert both strings to lowercase for case-insensitive comparison
        string lowerMainString = mainString.ToLower();
        string lowerSubstring = substring.ToLower();

        // Check if the substring appears at least twice consecutively in the main string
        return lowerMainString.Contains(lowerSubstring + lowerSubstring);
    }

    static void Main()
    {
        string x = "Hello, World!";
        string y = "worlD";

        bool result = ContainsConsecutiveSubstring(x, y);
        Console.WriteLine(result);
    }
}
