function bitwiseModulo(a, b) {
  if (!Number.isInteger(a) || !Number.isInteger(b)) {
    return NaN;
  }

  if (b === 0) {
    return NaN;
  }

  // Handle negative numbers
  let isNegative = false;
  if (a < 0) {
    isNegative = true;
    a = -a;
  }
  if (b < 0) {
    b = -b;
  }

  // Perform bitwise division and remainder calculation
  let quotient = 0;
  let remainder = 0;
  for (let i = 31; i >= 0; i--) {
    quotient <<= 1;
    remainder <<= 1;

    if (a & (1 << i)) {
      remainder |= 1;
    }

    if (remainder >= b) {
      remainder -= b;
      quotient |= 1;
    }
  }

  if (isNegative) {
    quotient = -quotient;
    remainder = -remainder;
  }

  return remainder;
}
```

This function first checks if either of the parameters is not an integer using the `Number.isInteger()` function. If any of the parameters is not an integer, it returns `NaN`.

Next, it checks if the second parameter (`b`) is zero. If it is, it also returns `NaN` to avoid division by zero.

To handle negative numbers, the function first checks if the first parameter (`a`) is negative. If it is, it sets a flag `isNegative` to `true` and converts `a` to its absolute value using the unary minus operator. Similarly, if the second parameter (`b`) is negative, it converts `b` to its absolute value.

The function then performs the bitwise division and remainder calculation. It initializes the quotient and remainder variables to zero. It then iterates through the bits of `a` from the most significant bit (31) to the least significant bit (0). For each bit, it shifts the quotient and remainder variables to the left by one bit.

If the current bit of `a` is set (1), it sets the corresponding bit in the remainder variable. After that, it checks if the remainder is greater than or equal to `b`. If it is, it subtracts `b` from the remainder and sets the least significant bit of the quotient variable.

After the iteration is complete, the function checks if the `isNegative` flag is set. If it is, it negates the quotient and remainder variables.

Finally, the function returns the remainder variable as the result.

Note: This implementation assumes that the input parameters are within the range of signed 32-bit integers. If the input parameters can be larger, the number of iterations in the for loop should be increased accordingly.

