      // Convert to hexadecimal
      std::ostringstream hexOss;
      hexOss << std::hex << roundedInt;
      str = hexOss.str();
    }
  }

  // Add minus sign for negative numbers
  if (isNegative) {
    str = "-" + str;
  }

  return str;
}

