```csharp
using System;

class Program
{
    static bool IsPrime(int number)
    {
        if (number < 2)
        {
            return false;
        }

        for (int i = 2; i <= Math.Sqrt(number); i++)
        {
            if (number % i == 0)
            {
                return false;
            }
        }

        return true;
    }

    static void Main(string[] args)
    {
        int[,] matrix = { { 11, 21, 31, 41 }, { 12, 22, 32, 42 }, { 13, 23, 33, 43 } };
        int rows = matrix.GetLength(0);
        int columns = matrix.GetLength(1);

        int smallestPrime = int.MaxValue;
        int largestPrime = int.MinValue;
        int smallestPrimeRow = 0;
        int smallestPrimeColumn = 0;
        int largestPrimeRow = 0;
        int largestPrimeColumn = 0;

        for (int i = 0; i < rows; i++)
        {
            for (int j = 0; j < columns; j++)
            {
                int currentNumber = matrix[i, j];
                if (IsPrime(currentNumber))
                {
                    if (currentNumber < smallestPrime)
                    {
                        smallestPrime = currentNumber;
                        smallestPrimeRow = i;
                        smallestPrimeColumn = j;
                    }

                    if (currentNumber > largestPrime)
                    {
                        largestPrime = currentNumber;
                        largestPrimeRow = i;
                        largestPrimeColumn = j;
                    }
                }
            }
        }

        Console.WriteLine("Largest Prime Number: {0} (Row: {1}, Column: {2})", largestPrime, largestPrimeRow, largestPrimeColumn);
        Console.WriteLine("Smallest Prime Number: {0} (Row: {1}, Column: {2})", smallestPrime, smallestPrimeRow, smallestPrimeColumn);
    }
}
