```java
import java.util.ArrayList;

public class RemoveValues {

    // Function to check if a number is prime
    public static boolean isPrime(int number) {
        if (number <= 1) {
            return false;
        }
        for (int i = 2; i <= Math.sqrt(number); i++) {
            if (number % i == 0) {
                return false;
            }
        }
        return true;
    }

    // Function to calculate the sum of digits of a number
    public static int sumOfDigits(int number) {
        int sum = 0;
        while (number != 0) {
            sum += number % 10;
            number /= 10;
        }
        return sum;
    }

    // Function to remove values from an array based on the given conditions
    public static int[] removeValuesGreaterThanNumber(int[] arr, int number) {
        ArrayList<Integer> result = new ArrayList<>();
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] <= number && isPrime(sumOfDigits(arr[i]))) {
                result.add(arr[i]);
            }
        }

        // Convert ArrayList to int[]
        int[] output = new int[result.size()];
        for (int i = 0; i < result.size(); i++) {
            output[i] = result.get(i);
        }
        return output;
    }

    // Main function to test the removeValuesGreaterThanNumber function
    public static void main(String[] args) {
        int[] arr = { 123, 45, 6789, 876, 543, 21 };
        int number = 100;

        int[] result = removeValuesGreaterThanNumber(arr, number);

        System.out.println("Original array: ");
        for (int num : arr) {
            System.out.print(num + " ");
        }

        System.out.println("\nNew array: ");
        for (int num : result) {
            System.out.print(num + " ");
        }
    }
}
