Here's an example implementation of a function in C that swaps values of different data types, including pointers:

```c
#include <stdio.h>

void swap(void* a, void* b, size_t size) {
    char temp[size];

    // Copy value from a to temp
    memcpy(temp, a, size);

    // Copy value from b to a
    memcpy(a, b, size);

    // Copy value from temp to b
    memcpy(b, temp, size);
}

int main() {
    int intA = 5, intB = 10;
    float floatA = 3.14, floatB = 2.71;
    char charA = 'A', charB = 'B';

    int* intPtrA = &intA;
    int* intPtrB = &intB;
    float* floatPtrA = &floatA;
    float* floatPtrB = &floatB;
    char* charPtrA = &charA;
    char* charPtrB = &charB;

    // Swapping integers
    swap(&intA, &intB, sizeof(int));
    printf("After swapping: intA = %d, intB = %d\n", intA, intB);

    // Swapping floating-point numbers
    swap(&floatA, &floatB, sizeof(float));
    printf("After swapping: floatA = %.2f, floatB = %.2f\n", floatA, floatB);

    // Swapping characters
    swap(&charA, &charB, sizeof(char));
    printf("After swapping: charA = %c, charB = %c\n", charA, charB);

    // Swapping pointers to integers
    swap(&intPtrA, &intPtrB, sizeof(int*));
    printf("After swapping: *intPtrA = %d, *intPtrB = %d\n", *intPtrA, *intPtrB);

    // Swapping pointers to floating-point numbers
    swap(&floatPtrA, &floatPtrB, sizeof(float*));
    printf("After swapping: *floatPtrA = %.2f, *floatPtrB = %.2f\n", *floatPtrA, *floatPtrB);

    // Swapping pointers to characters
    swap(&charPtrA, &charPtrB, sizeof(char*));
    printf("After swapping: *charPtrA = %c, *charPtrB = %c\n", *charPtrA, *charPtrB);

    return 0;
}
```

In this implementation, the `swap` function uses `memcpy` to swap the values of the input parameters. The `size` parameter is used to determine the size of each data type, which is necessary for `memcpy`. The `sizeof` operator is used to calculate the size of each data type.

Note that when swapping pointers, the `sizeof` operator is used to determine the size of a pointer. In this case, the function swaps the addresses, not the values pointed to by the pointers.

