import java.util.regex.Pattern;

public class EmailValidator {

    private static final Pattern EMAIL_REGEX = Pattern.compile("^[a-zA-Z0-9_+&*-]+(?:\\.[a-zA-Z0-9_+&*-]+)*@(?:[a-zA-Z0-9-]+\\.)+[a-zA-Z]{2,7}$");

    public static boolean isValidEmail(String email) {
        return EMAIL_REGEX.matcher(email).matches();
    }

    public static boolean isEmailInDomain(String email, String domain) {
        String emailDomain = email.substring(email.lastIndexOf("@") + 1);
        return emailDomain.equalsIgnoreCase(domain);
    }

    public static void main(String[] args) {
        String email = "example@gmail.com";
        String domain = "gmail.com";

        if (isValidEmail(email)) {
            System.out.println("Valid email address");
            if (isEmailInDomain(email, domain)) {
                System.out.println("Email belongs to the specified domain");
            } else {
                System.out.println("Email does not belong to the specified domain");
            }
        } else {
            System.out.println("Invalid email address");
        }
    }
}
