Here is an example of a hash table in C with 5 elements using separate chaining as the collision resolution strategy:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Structure for the hash table entry
struct Entry {
    char* key;
    int value;
    struct Entry* next;
};

// Structure for the hash table
struct HashTable {
    int size;
    int count;
    struct Entry** array;
};

// Function to create a new entry
struct Entry* newEntry(const char* key, int value) {
    struct Entry* entry = malloc(sizeof(struct Entry));
    entry->key = malloc(strlen(key) + 1);
    strcpy(entry->key, key);
    entry->value = value;
    entry->next = NULL;
    return entry;
}

// Function to create a new hash table
struct HashTable* newHashTable(int size) {
    struct HashTable* table = malloc(sizeof(struct HashTable));
    table->size = size;
    table->count = 0;
    table->array = malloc(sizeof(struct Entry*) * size);
    for (int i = 0; i < size; i++) {
        table->array[i] = NULL;
    }
    return table;
}

// Hash function
int hash(const char* key, int size) {
    int hash = 0;
    for (int i = 0; i < strlen(key); i++) {
        hash += key[i];
    }
    return hash % size;
}

// Function to insert a key-value pair into the hash table
void insert(struct HashTable* table, const char* key, int value) {
    // Check load factor and resize if necessary
    if ((float)table->count / table->size > 0.75) {
        resize(table, table->size * 2);
    }

    int index = hash(key, table->size);
    struct Entry* entry = table->array[index];

    // If the key already exists, update the value
    while (entry != NULL) {
        if (strcmp(entry->key, key) == 0) {
            entry->value = value;
            return;
        }
        entry = entry->next;
    }

    // Create a new entry and insert it at the beginning of the linked list
    struct Entry* newEntry = newEntry(key, value);
    newEntry->next = table->array[index];
    table->array[index] = newEntry;
    table->count++;
}

// Function to retrieve the value associated with a key
int get(struct HashTable* table, const char* key) {
    int index = hash(key, table->size);
    struct Entry* entry = table->array[index];

    // Traverse the linked list to find the key
    while (entry != NULL) {
        if (strcmp(entry->key, key) == 0) {
            return entry->value;
        }
        entry = entry->next;
    }

    // Return -1 if the key is not found
    return -1;
}

// Function to resize the hash table
void resize(struct HashTable* table, int newSize) {
    struct Entry** newArray = malloc(sizeof(struct Entry*) * newSize);

    // Initialize the new array with NULL values
    for (int i = 0; i < newSize; i++) {
        newArray[i] = NULL;
    }

    // Rehash all existing entries into the new array
    for (int i = 0; i < table->size; i++) {
        struct Entry* entry = table->array[i];
        while (entry != NULL) {
            struct Entry* nextEntry = entry->next;
            int newIndex = hash(entry->key, newSize);
            entry->next = newArray[newIndex];
            newArray[newIndex] = entry;
            entry = nextEntry;
        }
    }

    // Free the old array and update the hash table properties
    free(table->array);
    table->array = newArray;
    table->size = newSize;
}

// Function to print the hash table
void printHashTable(struct HashTable* table) {
    for (int i = 0; i < table->size; i++) {
        struct Entry* entry = table->array[i];
        printf("%d: ", i);
        while (entry != NULL) {
            printf("(%s, %d) ", entry->key, entry->value);
            entry = entry->next;
        }
        printf("\n");
    }
}

int main() {
    struct HashTable* table = newHashTable(5);

    insert(table, "key1", 10);
    insert(table, "key2", 20);
    insert(table, "key3", 30);
    insert(table, "key4", 40);
    insert(table, "key5", 50);

    printHashTable(table);

    printf("Value for key 'key3': %d\n", get(table, "key3"));

    return 0;
}
```

In this implementation, the `HashTabel` structure holds the size, count, and an array of pointers to the entries. The `Entry` structure represents a key-value pair and includes a pointer to the next entry in case of collisions. The `newEntry` function is used to create a new entry with a given key and value. The `newHashTable` function initializes a new hash table with a given size.

The `hash` function calculates the hash value for a given key using a simple sum of the ASCII values of the characters. The `insert` function inserts a key-value pair into the hash table, first checking the load factor and resizing if necessary. It then calculates the index for the key using the hash function and handles collisions by adding the new entry at the beginning of a linked list. The `get` function retrieves the value associated with a key by traversing the linked list at the corresponding index. The `resize` function doubles the size of the hash table and rehashes all existing entries into the new array.

Finally, the `printHashTable` function is provided to print the contents of the hash table, and the main function demonstrates the usage of the hash table by inserting some key-value pairs, printing the hash table, and retrieving a value by key.

