class ComplexNumber:
    def __init__(self, real, imaginary):
        self.real = real
        self.imaginary = imaginary

    def add(self, other):
        return ComplexNumber(self.real + other.real, self.imaginary + other.imaginary)

    def subtract(self, other):
        return ComplexNumber(self.real - other.real, self.imaginary - other.imaginary)

    def multiply(self, other):
        real = self.real * other.real - self.imaginary * other.imaginary
        imaginary = self.real * other.imaginary + self.imaginary * other.real
        return ComplexNumber(real, imaginary)

    def divide(self, other):
        denominator = other.real ** 2 + other.imaginary ** 2
        if denominator == 0:
            raise ZeroDivisionError("Division by zero is not allowed.")
        real = (self.real * other.real + self.imaginary * other.imaginary) / denominator
        imaginary = (self.imaginary * other.real - self.real * other.imaginary) / denominator
        return ComplexNumber(real, imaginary)

    def absolute(self):
        return (self.real ** 2 + self.imaginary ** 2) ** 0.5

    def conjugate(self):
        return ComplexNumber(self.real, -self.imaginary)

    def is_equal(self, other):
        return self.real == other.real and self.imaginary == other.imaginary

    def __str__(self):
        return f"{self.real} + {self.imaginary}i"

    @staticmethod
    def square_root(number):
        real = (number.real ** 2 - number.imaginary ** 2) ** 0.5
        imaginary = (2 * number.real * number.imaginary) ** 0.5
        return ComplexNumber(real, imaginary)

    def __eq__(self, other):
        return self.is_equal(other)

    def exponential(self):
        import cmath
        result = cmath.exp(complex(self.real, self.imaginary))
        return ComplexNumber(result.real, result.imag)

    @classmethod
    def complex_conjugate(cls, number):
        return ComplexNumber(number.real, -number.imaginary)

    @staticmethod
    def magnitude(number):
        return (number.real ** 2 + number.imaginary ** 2) ** 0.5

    def __ne__(self, other):
        return not self.is_equal(other)

    def __add__(self, scalar):
        return ComplexNumber(self.real + scalar, self.imaginary)

    def __sub__(self, scalar):
        return ComplexNumber(self.real - scalar, self.imaginary)

    def __mul__(self, scalar):
        return ComplexNumber(self.real * scalar, self.imaginary * scalar)

