import csv
import sys

def read_csv_file(file_name):
    try:
        with open(file_name, 'r') as file:
            reader = csv.reader(file)
            data = list(reader)
            return data
    except FileNotFoundError:
        print("Error: The specified CSV file does not exist or cannot be accessed.")
        sys.exit()

def get_column_index(header, column_name):
    try:
        return header.index(column_name)
    except ValueError:
        print("Error: The specified column does not exist in the CSV file.")
        sys.exit()

def calculate_sum(column_data):
    try:
        return sum(column_data)
    except TypeError:
        print("Error: The specified column contains non-numeric values.")
        sys.exit()

def find_min_max(column_data):
    try:
        return min(column_data), max(column_data)
    except TypeError:
        print("Error: The specified column contains non-numeric values.")
        sys.exit()

def sort_csv_data(data, column_index):
    try:
        sorted_data = sorted(data[1:], key=lambda x: x[column_index])
        sorted_data.insert(0, data[0])
        return sorted_data
    except MemoryError:
        print("Error: The program ran out of memory while processing the CSV file.")
        sys.exit()

def save_to_csv_file(file_name, data):
    try:
        with open(file_name, 'w', newline='') as file:
            writer = csv.writer(file)
            writer.writerows(data)
            print("The sorted data has been saved to a new CSV file.")
    except IOError:
        print("Error: Failed to save the sorted data to a new CSV file.")
        sys.exit()

def main():
    file_name = input("Enter the name of the CSV file: ")
    data = read_csv_file(file_name)

    header = data[0]
    column_name = input("Enter the name of the column to perform calculations: ")
    column_index = get_column_index(header, column_name)

    column_data = []
    for row in data[1:]:
        try:
            value = float(row[column_index])
            column_data.append(value)
        except ValueError:
            column_data.append(None)

    sum_result = calculate_sum(column_data)
    print("Sum of the column:", sum_result)

    min_value, max_value = find_min_max(column_data)
    print("Minimum value in the column:", min_value)
    print("Maximum value in the column:", max_value)

    sorted_data = sort_csv_data(data, column_index)
    new_file_name = input("Enter the name of the new CSV file to save the sorted data: ")
    save_to_csv_file(new_file_name, sorted_data)

if __name__ == '__main__':
    main()
```

