  // Remove duplicates from the input array
  $uniqueArray = array_unique($inputArray);

  // Initialize an empty array to store the prime numbers
  $primeNumbers = [];

  // Loop through each number in the unique array
  foreach ($uniqueArray as $number) {
    // Check if the number is greater than 1
    if ($number > 1) {
      $isPrime = true;

      // Loop through each number from 2 to half of the number
      for ($i = 2; $i <= $number / 2; $i++) {
        // If the number is divisible by any number, it is not prime
        if ($number % $i == 0) {
          $isPrime = false;
          break;
        }
      }

      // If the number is prime, add it to the primeNumbers array
      if ($isPrime) {
        $primeNumbers[] = $number;
      }
    }
  }

  // Return the array of prime numbers
  return $primeNumbers;
}

