import React, { useState, useEffect } from 'react';

const Table = () => {
  const [filteredRecords, setFilteredRecords] = useState([]);
  const [sortedRecords, setSortedRecords] = useState([]);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(0);
  const [searchTerm, setSearchTerm] = useState('');
  const [ageFilter, setAgeFilter] = useState(25);

  const records = [
    { id: 1, name: 'Adam', age: 25 },
    { id: 2, name: 'James', age: 30 },
    { id: 3, name: 'Nick', age: 28 },
    { id: 4, name: 'John', age: 29 }
  ];

  const itemsPerPage = 5;

  // Calculate average age dynamically based on filtered records
  const calculateAverageAge = () => {
    const filteredAges = filteredRecords.map(record => record.age);
    const sum = filteredAges.reduce((a, b) => a + b, 0);
    return sum / filteredAges.length;
  };

  // Filter records based on name and age filters
  const filterRecords = () => {
    let filtered = records.filter(record => record.name.toLowerCase().includes(searchTerm.toLowerCase()));
    filtered = filtered.filter(record => record.age >= ageFilter);
    setFilteredRecords(filtered);
  };

  // Sort records by name in ascending order
  const sortRecords = () => {
    const sorted = filteredRecords.sort((a, b) => (a.name > b.name) ? 1 : -1);
    setSortedRecords(sorted);
  };

  // Update filtered and sorted records whenever filters change
  useEffect(() => {
    filterRecords();
    sortRecords();
  }, [searchTerm, ageFilter]);

  // Update total number of pages whenever filtered records change
  useEffect(() => {
    setTotalPages(Math.ceil(sortedRecords.length / itemsPerPage));
  }, [sortedRecords]);

  // Update current page whenever the filtered records or total pages change
  useEffect(() => {
    setCurrentPage(1);
  }, [filteredRecords, totalPages]);

  // Handle page change
  const handlePageChange = (newPage) => {
    setCurrentPage(newPage);
  };

  // Handle search input change
  const handleSearchInputChange = (event) => {
    setSearchTerm(event.target.value);
  };

  // Handle age filter change
  const handleAgeFilterChange = (event) => {
    setAgeFilter(parseInt(event.target.value));
  };

  // Reset filter and pagination settings to default values
  const resetSettings = () => {
    setSearchTerm('');
    setAgeFilter(25);
    setCurrentPage(1);
  };

  // Get the records for the current page
  const getCurrentPageRecords = () => {
    const startIndex = (currentPage - 1) * itemsPerPage;
    const endIndex = startIndex + itemsPerPage;
    return sortedRecords.slice(startIndex, endIndex);
  };

  // Render table rows
  const renderTableRows = () => {
    const currentRecords = getCurrentPageRecords();

    return currentRecords.map(record => (
      <tr key={record.id}>
        <td>{record.name}</td>
        <td>{record.age}</td>
        <td>{record.age - calculateAverageAge()}</td>
      </tr>
    ));
  };

  // Render pagination buttons
  const renderPaginationButtons = () => {
    const buttons = [];

    for (let i = 1; i <= totalPages; i++) {
      buttons.push(
        <button
          key={i}
          onClick={() => handlePageChange(i)}
          className={currentPage === i ? 'active' : ''}
        >
          {i}
        </button>
      );
    }

    return buttons;
  };

  return (
    <div>
      <div>
        <input type="text" value={searchTerm} onChange={handleSearchInputChange} placeholder="Search by name" />
        <select value={ageFilter} onChange={handleAgeFilterChange}>
          <option value={25}>25+</option>
          <option value={30}>30+</option>
        </select>
        <button onClick={resetSettings}>Reset</button>
      </div>
      <table>
        <thead>
          <tr>
            <th>Name</th>
            <th>Age</th>
            <th>Age Difference</th>
          </tr>
        </thead>
        <tbody>
          {renderTableRows()}
        </tbody>
      </table>
      <div>
        <p>Total records: {sortedRecords.length}</p>
        <p>Current page: {currentPage}</p>
        <p>Total pages: {totalPages}</p>
        <div>
          {renderPaginationButtons()}
        </div>
      </div>
    </div>
  );
};

export default Table;

