```java
public class DynamicArrayStack {
    private int[] array;
    private int top;
    private int size;

    public DynamicArrayStack() {
        array = new int[10];
        top = -1;
        size = 0;
    }

    public void push(int element) {
        if (top == array.length - 1) {
            resize();
        }
        array[++top] = element;
        size++;
    }

    public int pop() {
        if (isEmpty()) {
            throw new IllegalStateException("Stack is empty");
        }
        size--;
        return array[top--];
    }

    public int peek() {
        if (isEmpty()) {
            throw new IllegalStateException("Stack is empty");
        }
        return array[top];
    }

    public boolean isEmpty() {
        return size == 0;
    }

    public int size() {
        return size;
    }

    private void resize() {
        int[] newArray = new int[array.length * 2];
        System.arraycopy(array, 0, newArray, 0, array.length);
        array = newArray;
    }
}
