```javascript
function countUniqueElements(arr) {
  // Create an empty object to store unique elements
  var uniqueElements = {};

  // Iterate through the array
  for (var i = 0; i < arr.length; i++) {
    // Add each element as a key in the object
    uniqueElements[arr[i]] = true;
  }

  // Count the number of keys in the object
  var count = 0;
  for (var key in uniqueElements) {
    if (uniqueElements.hasOwnProperty(key)) {
      count++;
    }
  }

  return count;
}

