#define BUFFER_SIZE 10

int buffer[BUFFER_SIZE];
int count = 0;
int in = 0;
int out = 0;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t full = PTHREAD_COND_INITIALIZER;
pthread_cond_t empty = PTHREAD_COND_INITIALIZER;

void* producer_func(void* arg) {
    int data = 0;
    while (1) {
        pthread_mutex_lock(&mutex);
        while (count == BUFFER_SIZE) {
            pthread_cond_wait(&full, &mutex);
        }

        buffer[in] = data;
        in = (in + 1) % BUFFER_SIZE;
        count++;

        pthread_cond_signal(&empty);
        pthread_mutex_unlock(&mutex);

        data++;
    }
    return NULL;
}

void* consumer_func(void* arg) {
    while (1) {
        pthread_mutex_lock(&mutex);
        while (count == 0) {
            pthread_cond_wait(&empty, &mutex);
        }

        int data = buffer[out];
        out = (out + 1) % BUFFER_SIZE;
        count--;

        pthread_cond_signal(&full);
        pthread_mutex_unlock(&mutex);

        // Process the data

        printf("Consumed: %d\n", data);
    }
    return NULL;
}

int main() {
    pthread_t producer_thread, consumer_thread;

    pthread_create(&producer_thread, NULL, producer_func, NULL);
    pthread_create(&consumer_thread, NULL, consumer_func, NULL);

    pthread_join(producer_thread, NULL);
    pthread_join(consumer_thread, NULL);

    return 0;
}
```

In this rewritten test, the code now implements a producer-consumer scenario using a shared buffer of fixed size. The `producer_func` generates data and adds it to the buffer, while the `consumer_func` consumes the data from the buffer. Both functions are executed concurrently in separate threads. 

To ensure thread-safety, mutex locks and condition variables are used. The mutex lock is acquired before accessing the shared resources (buffer, count, in, out) and released after the operation is completed. Condition variables are used to allow threads to wait and signal each other based on the state of the shared resources. The `pthread_cond_wait` function suspends the thread until a signal is received, and the `pthread_cond_signal` function wakes up a waiting thread.

Overall, this modified test requires a more advanced understanding of synchronization mechanisms and demonstrates the ability to handle more complex concurrency scenarios.

