#include <iostream>

void swapVariables(int& a, int& b) {
    if (&a == &b) // check if the variables are the same
        return;

    a = a ^ b; // XOR operation to store the XOR of a and b in a
    b = a ^ b; // XOR operation to get the original value of a and store it in b
    a = a ^ b; // XOR operation to get the original value of b and store it in a
}

