```php
function getHTMLTitle($url) {
    // Initialize cURL session
    $ch = curl_init();

    // Set cURL options
    curl_setopt($ch, CURLOPT_URL, $url);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_HEADER, false);

    // Execute the cURL request
    $response = curl_exec($ch);

    // Close cURL session
    curl_close($ch);

    // Check if request was successful
    if ($response === false) {
        return "Error: Unable to retrieve the URL.";
    }

    // Extract the title tag from the response
    preg_match("/<title>(.*?)<\/title>/i", $response, $matches);

    // Check if title tag was found
    if (isset($matches[1])) {
        $title = $matches[1];
    } else {
        $title = "Title tag not found.";
    }

    return $title;
}

// Example usage
