Here's a possible implementation of the generic vector class:

```python
import math

class Vector:
    def __init__(self, vector):
        self.vector = vector

    def __len__(self):
        return len(self.vector)

    def __add__(self, other):
        if len(self) != len(other):
            raise ValueError("Vectors must have the same length")
        return Vector([a + b for a, b in zip(self.vector, other.vector)])

    def __sub__(self, other):
        if len(self) != len(other):
            raise ValueError("Vectors must have the same length")
        return Vector([a - b for a, b in zip(self.vector, other.vector)])

    def __mul__(self, other):
        if isinstance(other, (int, float)):
            return Vector([a * other for a in self.vector])
        elif isinstance(other, Vector):
            if len(self) != len(other):
                raise ValueError("Vectors must have the same length")
            return sum(a * b for a, b in zip(self.vector, other.vector))
        else:
            raise TypeError("Multiplication is only supported by a scalar or another vector")

    def cross_product(self, other):
        if len(self) != 3 or len(other) != 3:
            raise ValueError("Cross product is only supported by 3-dimensional vectors")
        x = self.vector[1] * other.vector[2] - self.vector[2] * other.vector[1]
        y = self.vector[2] * other.vector[0] - self.vector[0] * other.vector[2]
        z = self.vector[0] * other.vector[1] - self.vector[1] * other.vector[0]
        return Vector([x, y, z])

    def magnitude(self):
        return math.sqrt(sum(a * a for a in self.vector))

    def normalize(self):
        mag = self.magnitude()
        return Vector([a / mag for a in self.vector])

    def angle(self, other):
        if len(self) != len(other):
            raise ValueError("Vectors must have the same length")
        dot = self * other
        mag_self = self.magnitude()
        mag_other = other.magnitude()
        cos_theta = dot / (mag_self * mag_other)
        return math.acos(cos_theta)

    def projection(self, other):
        if len(self) != len(other):
            raise ValueError("Vectors must have the same length")
        dot = self * other
        mag_other = other.magnitude()
        return (dot / (mag_other * mag_other)) * other
```

