public class Node {
    int data;
    Node next;

    public Node(int data) {
        this.data = data;
        this.next = null;
    }
}

public Node deleteNode(Node head, int position) {
    // If the position is 1, delete the head node
    if (position == 1) {
        return head.next;
    }

    Node current = head;
    Node previous = null;

    // Traverse the linked list until the position-1 node is found
    for (int i = 1; i < position; i++) {
        previous = current;
        current = current.next;
    }

    // Update the next pointer of the previous node to skip the current node
    previous.next = current.next;

    // Delete the current node by setting its value to null
    current = null;

    return head;
}
```

