import React, { useState, useEffect } from 'react';

const CityTable = () => {
  const [cities, setCities] = useState([]);
  const [filteredCities, setFilteredCities] = useState([]);
  const [sortConfig, setSortConfig] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [viewMode, setViewMode] = useState('list');
  const [currentPage, setCurrentPage] = useState(1);
  const [citiesPerPage] = useState(10);
  const [selectedCities, setSelectedCities] = useState([]);
  const [filters, setFilters] = useState({
    attractions: null,
    rainfall: null,
  });

  // Fetch cities data from API or local storage on component mount
  useEffect(() => {
    const fetchCities = async () => {
      // Fetch cities data from API or local storage
      const citiesData = await fetchData();

      setCities(citiesData);
      setFilteredCities(citiesData);
    };

    fetchCities();
  }, []);

  // Handle sorting by column
  const handleSort = (columnName) => {
    let direction = 'ascending';

    if (sortConfig && sortConfig.column === columnName && sortConfig.direction === 'ascending') {
      direction = 'descending';
    }

    const sortedCities = [...filteredCities].sort((a, b) => {
      if (a[columnName] < b[columnName]) {
        return direction === 'ascending' ? -1 : 1;
      }
      if (a[columnName] > b[columnName]) {
        return direction === 'ascending' ? 1 : -1;
      }
      return 0;
    });

    setFilteredCities(sortedCities);
    setSortConfig({ column: columnName, direction });
  };

  // Handle search query change
  const handleSearch = (event) => {
    const query = event.target.value.toLowerCase();
    const filteredCities = cities.filter((city) => {
      return (
        city.name.toLowerCase().includes(query) ||
        city.population.toString().includes(query) ||
        city.temperature.toString().includes(query)
      );
    });

    setSearchQuery(query);
    setFilteredCities(filteredCities);
  };

  // Handle view mode change
  const handleViewModeChange = (mode) => {
    setViewMode(mode);
  };

  // Handle page change
  const handlePageChange = (pageNumber) => {
    setCurrentPage(pageNumber);
  };

  // Handle city selection
  const handleCitySelection = (city) => {
    if (selectedCities.includes(city)) {
      setSelectedCities(selectedCities.filter((selectedCity) => selectedCity !== city));
    } else {
      setSelectedCities([...selectedCities, city]);
    }
  };

  // Handle filter change
  const handleFilterChange = (filterType, filterValue) => {
    setFilters({
      ...filters,
      [filterType]: filterValue,
    });
  };

  // Handle city deletion
  const handleCityDeletion = () => {
    const updatedCities = cities.filter((city) => !selectedCities.includes(city));

    setCities(updatedCities);
    setFilteredCities(updatedCities);
    setSelectedCities([]);
  };

  // Handle city addition
  const handleCityAddition = (newCity) => {
    const updatedCities = [...cities, newCity];

    setCities(updatedCities);
    setFilteredCities(updatedCities);
  };

  // Handle city update
  const handleCityUpdate = (updatedCity) => {
    const updatedCities = cities.map((city) => {
      if (city === updatedCity) {
        return updatedCity;
      }
      return city;
    });

    setCities(updatedCities);
    setFilteredCities(updatedCities);
  };

  // Save changes to local storage on cities update
  useEffect(() => {
    localStorage.setItem('cities', JSON.stringify(cities));
  }, [cities]);

  // Paginate cities
  const indexOfLastCity = currentPage * citiesPerPage;
  const indexOfFirstCity = indexOfLastCity - citiesPerPage;
  const currentCities = filteredCities.slice(indexOfFirstCity, indexOfLastCity);
  const totalPages = Math.ceil(filteredCities.length / citiesPerPage);

  return (
    <div>
      <input type="text" value={searchQuery} onChange={handleSearch} placeholder="Search..." />

      <button onClick={() => handleViewModeChange('list')}>List View</button>
      <button onClick={() => handleViewModeChange('grid')}>Grid View</button>

      <table>
        <thead>
          <tr>
            <th onClick={() => handleSort('name')}>City Name</th>
            <th onClick={() => handleSort('population')}>Population</th>
            <th onClick={() => handleSort('temperature')}>Average Temperature</th>
            <th onClick={() => handleSort('attractions')}>Number of Tourist Attractions</th>
            <th onClick={() => handleSort('rainfall')}>Percentage of Annual Rainfall</th>
          </tr>
        </thead>
        <tbody>
          {currentCities.map((city) => (
            <tr key={city.id} onClick={() => handleCitySelection(city)}>
              <td>{city.name}</td>
              <td>{city.population}</td>
              <td>{city.temperature}</td>
              <td>{city.attractions}</td>
              <td>{city.rainfall}</td>
            </tr>
          ))}
        </tbody>
      </table>

      <Pagination
        totalPages={totalPages}
        currentPage={currentPage}
        onPageChange={handlePageChange}
      />

      <Dropdown
        options={[
          { label: 'Number of Tourist Attractions', value: 'attractions' },
          { label: 'Percentage of Annual Rainfall', value: 'rainfall' },
        ]}
        onFilterChange={handleFilterChange}
      />

      {viewMode === 'grid' ? (
        <GridView cities={currentCities} />
      ) : (
        <ListView cities={currentCities} />
      )}

      <MapView
        cities={currentCities}
        selectedCities={selectedCities}
        onCitySelection={handleCitySelection}
      />

      <button onClick={handleCityDeletion}>Delete Selected Cities</button>

      <CityForm onSubmit={handleCityAddition} />
    </div>
  );
};

export default CityTable;
