```dart
import 'dart:math';

void main() {
  int start = -100;
  int end = 100;

  List<int> randomNumbers = generateRandomNumbers(start, end);

  int countDivisibleBy3 = getCountDivisibleBy3(randomNumbers);
  int sumOfNumbers = getSumOfNumbers(randomNumbers);

  print('Count of numbers divisible by 3: $countDivisibleBy3');
  print('Sum of all generated numbers: $sumOfNumbers');
}

List<int> generateRandomNumbers(int start, int end) {
  Random random = Random();
  List<int> numbers = [];

  for (int i = start; i <= end; i++) {
    numbers.add(random.nextInt(end - start + 1) + start);
  }

  return numbers;
}

int getCountDivisibleBy3(List<int> numbers) {
  int count = 0;

  for (int number in numbers) {
    if (number % 3 == 0) {
      count++;
    }
  }

  return count;
}

int getSumOfNumbers(List<int> numbers) {
  int sum = 0;

  for (int number in numbers) {
    sum += number;
  }

  return sum;
}
```

