function findShortestWord(str) {
  // Remove non-alphabetic characters and convert the string to lowercase
  str = str.replace(/[^a-zA-Z ]/g, "").toLowerCase();

  // Split the string into an array of words
  const words = str.split(" ");

  // Initialize the shortestWord variable to store the result
  let shortestWord = "";

  // Iterate over each word in the array
  for (let i = 0; i < words.length; i++) {
    const word = words[i];

    // Check if the word meets the requirements
    if (
      word.length > 3 &&
      word.match(/^[a-z]*$/g) &&
      /[aeiou]/i.test(word) &&
      /[b-df-hj-np-tv-z]{1}[aeiou]{1}[b-df-hj-np-tv-z]{1}/i.test(word)
    ) {
      // If shortestWord is empty or the current word is shorter than shortestWord, update shortestWord
      if (shortestWord === "" || word.length < shortestWord.length) {
        shortestWord = word;
      }
    }
  }

  // Return the shortestWord
  return shortestWord;
}
