Here is an example of a hangman game using object-oriented programming in Python:

```python
import random
import time

class HangmanGame:
    def __init__(self):
        self.words = {
            'easy': ['cat', 'dog', 'bird'],
            'medium': ['elephant', 'giraffe', 'rhinoceros'],
            'hard': ['hippopotamus', 'crocodile', 'orangutan']
        }
        self.difficulty = None
        self.word = None
        self.guessed_letters = []
        self.lives = 6
        self.score = 0
        self.hint_penalty = 5
        self.start_time = None

    def select_difficulty(self):
        difficulties = ['easy', 'medium', 'hard']
        print('Select difficulty level:')
        for i, difficulty in enumerate(difficulties):
            print(f'{i + 1}. {difficulty}')
        choice = int(input('Enter your choice (1-3): '))
        self.difficulty = difficulties[choice - 1]

    def select_word(self):
        self.word = random.choice(self.words[self.difficulty])

    def play(self):
        self.select_difficulty()
        self.select_word()
        self.start_time = time.time()

        while self.lives > 0:
            self.display_word()
            self.display_stats()
            guess = self.get_guess()
            if guess == 'hint':
                self.give_hint()
                continue
            if self.is_letter_guessed(guess):
                print('Letter already guessed. Try again.')
                continue
            self.guessed_letters.append(guess)
            if self.is_word_guessed():
                self.calculate_score()
                print(f'Congratulations! You guessed the word "{self.word}" correctly.')
                break
            elif guess not in self.word:
                self.lives -= 1
                print('Wrong guess. You lost a life.')
                if self.lives == 0:
                    print(f'Game over. The word was "{self.word}".')

    def display_word(self):
        for letter in self.word:
            if letter in self.guessed_letters:
                print(letter, end=' ')
            else:
                print('_', end=' ')
        print()

    def display_stats(self):
        print(f'Lives: {self.lives}')
        print(f'Score: {self.score}')
        elapsed_time = int(time.time() - self.start_time)
        print(f'Time elapsed: {elapsed_time} seconds')

    def get_guess(self):
        guess = input('Enter a letter or type "hint" for a clue: ').lower()
        if guess == 'hint':
            return guess
        if len(guess) != 1 or not guess.isalpha():
            print('Invalid guess. Try again.')
            return self.get_guess()
        return guess

    def is_letter_guessed(self, guess):
        return guess in self.guessed_letters

    def is_word_guessed(self):
        return set(self.word) <= set(self.guessed_letters)

    def calculate_score(self):
        if self.difficulty == 'easy':
            self.score += 10
        elif self.difficulty == 'medium':
            self.score += 20
        elif self.difficulty == 'hard':
            self.score += 30

    def give_hint(self):
        if self.score >= self.hint_penalty:
            self.score -= self.hint_penalty
            hint_letter = random.choice([letter for letter in self.word if letter not in self.guessed_letters])
            print(f'Hint: The word contains the letter "{hint_letter}".')
        else:
            print('Insufficient score for hint.')

hangman = HangmanGame()
hangman.play()
```

