def binary_search_closest(arr, val):
    low = 0
    high = len(arr) - 1

    while low <= high:
        mid = (low + high) // 2

        if arr[mid] == val:
            return arr[mid]

        if arr[mid] < val:
            low = mid + 1
        else:
            high = mid - 1

    if low >= len(arr):
        return arr[high]
    elif high < 0:
        return arr[low]
    elif abs(arr[low] - val) <= abs(arr[high] - val):
        return arr[low]
    else:
