```java
public class DayOfWeekCalculator {
    public static void main(String[] args) {
        int day = 1; // Day of the month (1-31)
        int month = 1; // Month (1-12)
        int year = 1900; // Year

        // Prompt the user to enter a date
        // You can modify this part to get the date from the user
        System.out.println("Enter a date (YYYY-MM-DD): " + year + "-" + month + "-" + day);

        int dayOfWeek = calculateDayOfWeek(day, month, year);

        // Print the day of the week
        System.out.println("The day of the week is: " + getDayOfWeekString(dayOfWeek));
    }

    // Calculate the day of the week using Zeller's Congruence algorithm
    public static int calculateDayOfWeek(int day, int month, int year) {
        if (month < 3) {
            month += 12;
            year--;
        }

        int h = (day + 2 * month + 3 * (month + 1) / 5 + year + year / 4 - year / 100 + year / 400) % 7;

        // Convert the result to ISO standard (1 = Monday, 7 = Sunday)
        return (h + 5) % 7 + 1;
    }

    // Get the day of the week as a string
    public static String getDayOfWeekString(int dayOfWeek) {
        String[] daysOfWeek = {"Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"};
        return daysOfWeek[dayOfWeek - 1];
    }
}
```

