Here is an implementation of a doubly linked list class in Python with the required functionalities:

```python
class Node:
    def __init__(self, data):
        self.data = data
        self.prev = None
        self.next = None

class DoublyLinkedList:
    def __init__(self):
        self.head = None
        self.tail = None
        self.size = 0

    def insert_at_beginning(self, data):
        new_node = Node(data)
        if self.head is None:
            self.head = new_node
            self.tail = new_node
        else:
            new_node.next = self.head
            self.head.prev = new_node
            self.head = new_node
        self.size += 1

    def insert_at_end(self, data):
        new_node = Node(data)
        if self.tail is None:
            self.head = new_node
            self.tail = new_node
        else:
            new_node.prev = self.tail
            self.tail.next = new_node
            self.tail = new_node
        self.size += 1

    def insert_after(self, node, data):
        if node is None:
            raise ValueError("Node is None.")
        new_node = Node(data)
        new_node.prev = node
        new_node.next = node.next
        if node.next is not None:
            node.next.prev = new_node
        node.next = new_node
        if node == self.tail:
            self.tail = new_node
        self.size += 1

    def delete(self, node):
        if node is None:
            raise ValueError("Node is None.")
        if node.prev is not None:
            node.prev.next = node.next
        else:
            self.head = node.next
        if node.next is not None:
            node.next.prev = node.prev
        else:
            self.tail = node.prev
        self.size -= 1

    def delete_all(self, value):
        current = self.head
        while current is not None:
            if current.data == value:
                if current.prev is not None:
                    current.prev.next = current.next
                else:
                    self.head = current.next
                if current.next is not None:
                    current.next.prev = current.prev
                else:
                    self.tail = current.prev
                self.size -= 1
            current = current.next

    def get_size(self):
        return self.size

    def contains(self, value):
        current = self.head
        while current is not None:
            if current.data == value:
                return True
            current = current.next
        return False

    def reverse(self):
        current = self.head
        while current is not None:
            temp = current.next
            current.next = current.prev
            current.prev = temp
            if temp is None:
                self.tail = self.head
                self.head = current
            current = temp

    def print_list(self):
        current = self.head
        while current is not None:
            print(current.data, end=" ")
            current = current.next
        print()
```

Time complexity analysis:
- Insert a node at the beginning of the list: O(1)
- Insert a node at the end of the list: O(1)
- Insert a node after a specific node in the list: O(1)
- Delete a node from the list: O(1)
- Delete all nodes with the same value in the list: O(n), where n is the size of the list
- Get the size of the list: O(1)
- Check if a value exists in the list: O(n), where n is the size of the list
- Reverse the order of the list: O(n), where n is the size of the list

Space complexity analysis:
- The space complexity of the doubly linked list class is O(n), where n is the size of the list, as we need to store the nodes and their connections.

Here's a Java program that finds all pairs of integers from an array whose sum equals a given number, with the constraint that each integer can only be used once in a pair:

```java
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class PairSumWithConstraint {

    public static List<List<Integer>> findPairs(int[] nums, int target) {
        List<List<Integer>> result = new ArrayList<>();
        Map<Integer, Integer> map = new HashMap<>();

        for (int num : nums) {
            int complement = target - num;
            if (map.containsKey(complement) && map.get(complement) > 0) {
                List<Integer> pair = new ArrayList<>();
                pair.add(num);
                pair.add(complement);
                result.add(pair);
                map.put(num, map.get(num) - 1);
                map.put(complement, map.get(complement) - 1);
            } else {
                map.put(num, map.getOrDefault(num, 0) + 1);
            }
        }

        return result;
    }

    public static void main(String[] args) {
        int[] nums = {2, 4, 3, 5, 6, -2, 4, 7, 8, 9};
        int target = 7;

        List<List<Integer>> pairs = findPairs(nums, target);

        if (pairs.isEmpty()) {
            System.out.println("No pairs found.");
        } else {
            System.out.println("Pairs with sum " + target + ":");
            for (List<Integer> pair : pairs) {
                System.out.println(pair.get(0) + " + " + pair.get(1) + " = " + target);
            }
        }
    }
}
```

This program uses a HashMap to keep track of the count of each number encountered in the array. For each number, it calculates its complement (the difference between the target and the number). If the complement is present in the HashMap and has a count greater than 0, a pair is found. The pair is added to the result list, and the count of both the number and its complement is decreased by 1. If the complement is not present in the HashMap, the count of the number is incremented by 1. Finally, the program prints the pairs found with the given target sum.

