```javascript
function calculateSum(jsonArray) {
  let sum = 0;

  // Iterate over each object in the array
  jsonArray.forEach(obj => {
    // Check if "num_sessions" and "duration" properties exist and are positive
    if (obj.num_sessions && obj.duration && obj.num_sessions >= 0 && obj.duration >= 0) {
      // Calculate the product and add it to the sum
      sum += obj.num_sessions * obj.duration;
    }

    // Recursively check for nested objects
