function validateString(str) {
  // Track the counts of digits, special characters, and capital letters
  let digitCount = 0;
  let specialCharCount = 0;
  let capitalLetterCount = 0;

  // Track the previous character to check for consecutive repeating characters
  let previousChar = '';

  // Iterate through each character in the string
  for (let i = 0; i < str.length; i++) {
    const char = str[i];

    // Check if the character is a digit
    if (/\d/.test(char)) {
      digitCount++;
    }
    // Check if the character is a special character
    else if (/[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(char)) {
      specialCharCount++;
    }
    // Check if the character is a capital letter
    else if (/[A-Z]/.test(char)) {
      capitalLetterCount++;
    }

    // Check for consecutive repeating characters
    if (char === previousChar) {
      return false;
    }

    // Update the previous character
    previousChar = char;
  }

  // Check if the string meets all the criteria
  return digitCount >= 2 && specialCharCount >= 2 && capitalLetterCount >= 2;
}
```

This implementation uses regular expressions to check for digits, special characters, and capital letters in the string. It also keeps track of the counts of each type of character and checks for consecutive repeating characters.

