function countAndSort(arr) {
  // Create an empty object to store the occurrence count of each element
  const occurrenceCount = {};

  // Iterate over the array
  for (let i = 0; i < arr.length; i++) {
    const element = arr[i];

    // Ignore any duplicate elements
    if (occurrenceCount[element] !== undefined) {
      continue;
    }

    // Ignore elements that are less than 0 or greater than 100
    if (element < 0 || element > 100) {
      continue;
    }

    // Count the occurrence of the element
    let count = 0;
    for (let j = i; j < arr.length; j++) {
      if (arr[j] === element) {
        count++;
      }
    }

    // Store the occurrence count of the element in the object
    occurrenceCount[element] = count;
  }

  // Convert the object to an array of objects
  const occurrenceArray = [];
  for (const element in occurrenceCount) {
    occurrenceArray.push({
      element: parseInt(element),
      count: occurrenceCount[element]
    });
  }

  // Sort the array of objects in descending order based on the occurrence count
  occurrenceArray.sort((a, b) => b.count - a.count);

  // Filter the array to only include elements with an occurrence count greater than or equal to 2
  const filteredArray = occurrenceArray.filter(obj => obj.count >= 2);

  // Return the first 10 objects in the filtered array
  return filteredArray.slice(0, 10);
}
