bool isPrime(int num) {
    if (num <= 1) return false;
    if (num <= 3) return true;

    if (num % 2 == 0 || num % 3 == 0) return false;

    for (int i = 5; i * i <= num; i += 6) {
        if (num % i == 0 || num % (i + 2) == 0) return false;
    }

    return true;
}

int main() {
    int arr[] = {-4, 3, 2, -2, 6, -7, 3, 2, 1, 9};
    int size = sizeof(arr) / sizeof(arr[0]);

    // Create a new array with non-negative numbers
    std::vector<int> newArray;
    for (int i = 0; i < size; i++) {
        if (arr[i] >= 0) {
            // Add only unique elements
            if (std::find(newArray.begin(), newArray.end(), arr[i]) == newArray.end()) {
                newArray.push_back(arr[i]);
            }
        }
    }

    // Sort the new array in ascending order
    std::sort(newArray.begin(), newArray.end());

    // Calculate the median of the new array
    int median;
    int midIndex = newArray.size() / 2;
    if (newArray.size() % 2 == 0) {
        median = (newArray[midIndex - 1] + newArray[midIndex]) / 2;
    } else {
        median = newArray[midIndex];
    }

    // Count the number of unique prime numbers in the new array
    int countPrimes = 0;
    for (int i = 0; i < newArray.size(); i++) {
