ll calculateProduct(ll *numbers, int count, ll modulo) {
    ll product = 1;

    for (int i = 0; i < count; i++) {
        // Check for overflow condition
        if (numbers[i] == 0 || product == 0) {
            return 0;
        }

        // Check for potential overflow/underflow
        if (numbers[i] > 0 && product > LLONG_MAX / numbers[i]) {
            printf("Product exceeds maximum value\n");
            exit(EXIT_FAILURE);
        } else if (numbers[i] < 0 && product < LLONG_MIN / numbers[i]) {
            printf("Product exceeds minimum value\n");
            exit(EXIT_FAILURE);
        }

        product *= numbers[i];
        product %= modulo;  // Calculate product modulo a given number
    }

    return product;
}

