```R
# Function to sort a list of numbers in descending order using Bubble Sort
bubbleSortDescending <- function(numbers) {
  n <- length(numbers)

  for (i in 1:(n - 1)) {
    for (j in 1:(n - i)) {
      if (numbers[j] < numbers[j + 1]) {
        temp <- numbers[j]
        numbers[j] <- numbers[j + 1]
        numbers[j + 1] <- temp
      }
    }
  }

  return(numbers)
}

# Test the function
numbers <- c(10, 5, 8, 2, 7)
sortedNumbers <- bubbleSortDescending(numbers)
print(sortedNumbers)
```

