def date_to_timestamp(date_string):
    year = int(date_string[:4])
    month = int(date_string[5:7])
    day = int(date_string[8:10])
    hour = int(date_string[11:13])
    minute = int(date_string[14:16])
    second = int(date_string[17:19])

    days_since_epoch = 0
    for y in range(1970, year):
        days_since_epoch += 365
        if is_leap_year(y):
            days_since_epoch += 1

    for m in range(1, month):
        days_since_epoch += days_in_month(year, m)

    days_since_epoch += day - 1

    timestamp = days_since_epoch * 24 * 60 * 60 + hour * 60 * 60 + minute * 60 + second

    return timestamp


def is_leap_year(year):
    if year % 4 != 0:
        return False
    elif year % 100 != 0:
        return True
    elif year % 400 != 0:
        return False
    else:
        return True


def days_in_month(year, month):
    if month in [1, 3, 5, 7, 8, 10, 12]:
        return 31
    elif month in [4, 6, 9, 11]:
        return 30
    elif month == 2:
        if is_leap_year(year):
            return 29
        else:
            return 28
    else:
