To calculate the square root of the product of the first 150 prime numbers and output only the integer part using C++, you can follow these steps:

1. Create a function to check if a number is prime. This function will be used to generate the prime numbers.
2. Create a function to calculate the product of the first 150 prime numbers.
3. Calculate the square root of the product using the `sqrt` function from the `cmath` library.
4. Output the integer part of the square root using the `floor` function from the `cmath` library.

Here's the C++ code:

```cpp
#include <iostream>
#include <cmath>

// Function to check if a number is prime
bool isPrime(int n) {
    if (n <= 1) return false;
    if (n == 2 || n == 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;

    for (int i = 5; i * i <= n; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) {
            return false;
        }
    }

    return true;
}

// Function to calculate the product of the first 150 prime numbers
long long calculateProduct() {
    int count = 0;
    long long product = 1;
    int number = 2;

    while (count < 150) {
        if (isPrime(number)) {
            product *= number;
            count++;
        }
        number++;
    }

    return product;
}

int main() {
    // Calculate the product
    long long product = calculateProduct();

    // Calculate the square root and output the integer part
    int integerPart = floor(sqrt(product));
    std::cout << "The square root of the product of the first 150 prime numbers is: " << integerPart << std::endl;

    return 0;
}
```

This code will calculate the product of the first 150 prime numbers and output the integer part of the square root.

