Here is an implementation of a stack using a linked list structure in Python:

```python
class Node:
    def __init__(self, data):
        self.data = data
        self.next = None


class Stack:
    def __init__(self):
        self.head = None
        self.size = 0
        self.min_stack = []

    def push(self, data):
        new_node = Node(data)

        if self.isEmpty():
            self.head = new_node
            self.min_stack.append(data)
        else:
            new_node.next = self.head
            self.head = new_node
            if data <= self.min_stack[-1]:
                self.min_stack.append(data)

        self.size += 1

    def pop(self):
        if self.isEmpty():
            raise Exception("Stack is empty")

        data = self.head.data
        self.head = self.head.next
        self.size -= 1

        if data == self.getMin():
            self.min_stack.pop()

        return data

    def peek(self):
        if self.isEmpty():
            raise Exception("Stack is empty")

        return self.head.data

    def getSize(self):
        return self.size

    def isEmpty(self):
        return self.size == 0

    def clear(self):
        self.head = None
        self.size = 0
        self.min_stack = []

    def getMin(self):
        if self.isEmpty():
            raise Exception("Stack is empty")

        return self.min_stack[-1]

    def popMin(self):
        if self.isEmpty():
            raise Exception("Stack is empty")

        min_value = self.getMin()
        temp_stack = Stack()

        while self.peek() != min_value:
            temp_stack.push(self.pop())

        self.pop()

        while not temp_stack.isEmpty():
            self.push(temp_stack.pop())

        return min_value

    def popAllGreaterThan(self, value):
        temp_stack = Stack()

        while not self.isEmpty():
            if self.peek() > value:
                self.pop()
            else:
                temp_stack.push(self.pop())

        while not temp_stack.isEmpty():
            self.push(temp_stack.pop())
```

This implementation uses a linked list to store the elements of the stack. The `push` operation adds a new node at the head of the linked list, and updates the `min_stack` to keep track of the minimum element in the stack. The `pop` operation removes the node at the head of the linked list and updates the `min_stack` if necessary. The `peek` operation returns the data of the node at the head of the linked list. The `getSize` operation returns the size of the stack. The `isEmpty` operation checks if the stack is empty. The `clear` operation removes all elements from the stack. The `getMin` operation returns the minimum element in the stack. The `popMin` operation removes and returns the minimum element in the stack. The `popAllGreaterThan` operation removes all elements from the stack that are greater than the given value.

