```java
public class PalindromeChecker {
    public static void main(String[] args) {
        String input = "A man, a plan, a canal, Panama";
        System.out.println(isPalindrome(input));
    }

    public static boolean isPalindrome(String input) {
        // Remove special characters, numbers, and whitespace
        String strippedInput = input.replaceAll("[^a-zA-Z]", "").toLowerCase();

        // Check if the stripped string is a palindrome
        int left = 0;
        int right = strippedInput.length() - 1;

        while (left < right) {
            if (strippedInput.charAt(left) != strippedInput.charAt(right)) {
                return false;
            }
            left++;
            right--;
        }

        return true;
    }
}
```

