function partitionArray(arr) {
  let left = 0;
  let right = arr.length - 1;

  while (left < right) {
    // Find the first odd number from the left side
    while (arr[left] % 2 === 0 && left < right) {
      left++;
    }

    // Find the first even number from the right side
    while (arr[right] % 2 !== 0 && left < right) {
      right--;
    }

    // Swap the odd and even numbers
    if (left < right) {
      let temp = arr[left];
      arr[left] = arr[right];
      arr[right] = temp;
    }
  }
}
```

