```python
class Node:
    def __init__(self, data):
        self.data = data
        self.prev = None
        self.next = None


class DoublyLinkedList:
    def __init__(self):
        self.head = None
        self.tail = None
        self.size = 0

    def insert_at_beginning(self, data):
        new_node = Node(data)
        if self.head is None:
            self.head = new_node
            self.tail = new_node
        else:
            new_node.next = self.head
            self.head.prev = new_node
            self.head = new_node
        self.size += 1

    def insert_at_end(self, data):
        new_node = Node(data)
        if self.head is None:
            self.head = new_node
            self.tail = new_node
        else:
            new_node.prev = self.tail
            self.tail.next = new_node
            self.tail = new_node
        self.size += 1

    def insert_after_node(self, prev_node, data):
        if prev_node is None:
            raise ValueError("Previous node cannot be None")
        new_node = Node(data)
        new_node.next = prev_node.next
        if prev_node.next is not None:
            prev_node.next.prev = new_node
        prev_node.next = new_node
        new_node.prev = prev_node
        if prev_node == self.tail:
            self.tail = new_node
        self.size += 1

    def delete_node(self, node):
        if self.head is None:
            raise ValueError("List is empty")
        if node == self.head:
            self.head = node.next
            if self.head is not None:
                self.head.prev = None
        elif node == self.tail:
            self.tail = node.prev
            if self.tail is not None:
                self.tail.next = None
        else:
            node.prev.next = node.next
            node.next.prev = node.prev
        node.prev = None
        node.next = None
        self.size -= 1

    def delete_nodes_with_value(self, value):
        if self.head is None:
            raise ValueError("List is empty")
        current_node = self.head
        while current_node is not None:
            if current_node.data == value:
                self.delete_node(current_node)
            current_node = current_node.next

    def get_size(self):
        return self.size

    def contains(self, value):
        current_node = self.head
        while current_node is not None:
            if current_node.data == value:
                return True
            current_node = current_node.next
        return False

    def reverse(self):
        if self.head is None:
            raise ValueError("List is empty")
        current_node = self.head
        while current_node is not None:
            temp = current_node.prev
            current_node.prev = current_node.next
            current_node.next = temp
            current_node = current_node.prev
        self.head, self.tail = self.tail, self.head

    def __str__(self):
        if self.head is None:
            return "Empty List"
        result = ""
        current_node = self.head
        while current_node is not None:
            result += str(current_node.data) + " "
            current_node = current_node.next
        return result


# Example Usage:
dll = DoublyLinkedList()
dll.insert_at_beginning(1)
dll.insert_at_beginning(2)
dll.insert_at_end(3)
dll.insert_after_node(dll.head, 4)
print(dll)  # Output: 2 1 4 3
print(dll.get_size())  # Output: 4
print(dll.contains(2))  # Output: True
dll.delete_node(dll.head)
print(dll)  # Output: 1 4 3
dll.delete_nodes_with_value(3)
print(dll)  # Output: 1 4
dll.reverse()
print(dll)  # Output: 4 1
