public static String toUpperCase(String input) {
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c >= 'a' && c <= 'z') {
            // Convert lowercase letters to uppercase using bitwise manipulation
