```javascript
function generateRandomArray(m, n) {
  let array = [];
  let sum = 0;

  // Generate random 2D array
  for (let i = 0; i < m; i++) {
    array[i] = [];
    for (let j = 0; j < n; j++) {
      array[i][j] = Math.floor(Math.random() * 6);
      sum += array[i][j];
    }
  }

  // Check if sum is less than 50 and generate new values if necessary
  while (sum < 50) {
    for (let i = 0; i < m; i++) {
      for (let j = 0; j < n; j++) {
        let diff = 50 - sum;
        let addValue = Math.floor(Math.random() * (6 - array[i][j])) + 1;
        if (diff >= addValue) {
          array[i][j] += addValue;
          sum += addValue;
        }
      }
    }
  }

  return array;
}

