```csharp
using System;
using System.Collections.Generic;
using System.Linq;

class Program
{
    static void Main()
    {
        Console.Write("Enter the number of strings (N): ");
        if (!int.TryParse(Console.ReadLine(), out int n) || n <= 0)
        {
            Console.WriteLine("Invalid input. Please enter a positive integer for N.");
            return;
        }

        List<string> stringsList = new List<string>();

        for (int i = 0; i < n; i++)
        {
            Console.Write($"Enter string #{i + 1}: ");
            string inputString = Console.ReadLine();
            if (!IsValidString(inputString))
            {
                Console.WriteLine("Invalid string. Each string must contain at least one uppercase letter, one lowercase letter, and one special character.");
                return;
            }
            stringsList.Add(inputString);
        }

        Console.WriteLine("\nOriginal Strings:");
        foreach (string str in stringsList)
        {
            Console.WriteLine(str);
        }

        stringsList.Sort((a, b) => GetSpecialCharacterCount(b) - GetSpecialCharacterCount(a));

        Console.WriteLine("\nSorted Strings (Descending order based on special character count):");
        foreach (string str in stringsList)
        {
            Console.WriteLine(ReverseCase(str));
        }
    }

    static bool IsValidString(string str)
    {
        return str.Any(c => char.IsUpper(c)) &&
               str.Any(c => char.IsLower(c)) &&
               str.Any(c => char.IsSymbol(c) || char.IsPunctuation(c));
    }

    static int GetSpecialCharacterCount(string str)
    {
        return str.Count(c => char.IsSymbol(c) || char.IsPunctuation(c));
    }

    static string ReverseCase(string str)
    {
        char[] charArray = str.ToCharArray();
        for (int i = 0; i < charArray.Length; i++)
        {
            if (char.IsUpper(charArray[i]))
            {
                charArray[i] = char.ToLower(charArray[i]);
            }
            else if (char.IsLower(charArray[i]))
            {
                charArray[i] = char.ToUpper(charArray[i]);
            }
        }
        return new string(charArray);
    }
}
```

