    count = 2
    i = 4
    while count < N:
        if is_prime(i):
            prime_numbers.append(i)
            count += 1
        i += 1
    fib_numbers = [0, 1]
    for i in range(2, N + 1):
        fib_numbers.append(fib_numbers[i - 1] + fib_numbers[i - 2])
    for i in range(N):
