Here is a Python script that takes in a positive integer as input, determines whether it is a prime number, and prints the sum of all the prime digits in the input number. It also finds and prints the largest prime factor of the input number:

```python
import math

def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        if n % i == 0:
            return False
    return True

def get_prime_digits_sum(n):
    prime_digits = [2, 3, 5, 7]
    digit_sum = 0
    while n > 0:
        digit = n % 10
        if digit in prime_digits:
            digit_sum += digit
        n //= 10
    return digit_sum

def get_largest_prime_factor(n):
    largest_prime = 1
    i = 2
    while i <= n / i:
        if n % i == 0:
            n //= i
            largest_prime = i
        else:
            i += 1
    if n > largest_prime:
        largest_prime = n
    return largest_prime

# Take input from the user
num = int(input("Enter a positive integer greater than or equal to 100 and less than or equal to 10^9: "))

# Check if the number is prime
if is_prime(num):
    print(num, "is a prime number.")
else:
    print(num, "is not a prime number.")

# Calculate and print the sum of prime digits
prime_digits_sum = get_prime_digits_sum(num)
print("The sum of prime digits in", num, "is", prime_digits_sum)

# Calculate and print the largest prime factor
largest_prime_factor = get_largest_prime_factor(num)
print("The largest prime factor of", num, "is", largest_prime_factor)
```

Note: The script uses the `math.sqrt()` function to optimize the prime number checking algorithm. The function `is_prime()` checks if a number is prime by iterating from 3 to the square root of the number, skipping all even numbers except 2. The function `get_largest_prime_factor()` calculates the largest prime factor of a number by continuously dividing the number by its smallest prime factors.

