function randomizeArray(array) {
  // Helper function to check if two consecutive elements have the same starting letter
  function hasSameStartingLetter(a, b) {
    return a[0].toLowerCase() === b[0].toLowerCase();
  }

  // Randomly shuffle the array
  function shuffleArray(array) {
    for (let i = array.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [array[i], array[j]] = [array[j], array[i]];
    }
    return array;
  }

  // Randomly swap elements with same starting letter
  function swapElementsWithSameStartingLetter(array) {
    for (let i = 0; i < array.length - 1; i++) {
      if (hasSameStartingLetter(array[i], array[i + 1])) {
        const randomIndex = Math.floor(Math.random() * (array.length - 1));
        [array[i], array[randomIndex]] = [array[randomIndex], array[i]];
      }
    }
    return array;
  }

  // Randomize the array while checking for consecutive elements with the same starting letter
  let randomizedArray = shuffleArray(array);
  while (swapElementsWithSameStartingLetter(randomizedArray).length > 0) {
    randomizedArray = swapElementsWithSameStartingLetter(randomizedArray);
  }

  return randomizedArray;
}

