def bubble_sort_recursive(arr):
    n = len(arr)

    # Base case
    if n <= 1:
        return arr

    # One pass of bubble sort
    has_swapped = False
    for i in range(n - 1):
        if arr[i] > arr[i + 1]:
            arr[i], arr[i + 1] = arr[i + 1], arr[i]
            has_swapped = True

    # Recursive call if any swaps were made
    if has_swapped:
        return bubble_sort_recursive(arr[:-1]) + [arr[-1]]
    else:
        return arr


