Here's a script that sorts the elements of an array in ascending order, placing floating-point numbers before integers and maintaining the original order within their respective groups:

```javascript
function sortArray(arr) {
  // Divide the array into two parts: floating-point numbers and integers
  let floatingPoint = [];
  let integers = [];

  for (let i = 0; i < arr.length; i++) {
    if (Number.isInteger(arr[i])) {
      integers.push(arr[i]);
    } else {
      floatingPoint.push(arr[i]);
    }
  }

  // Sort the floating-point numbers in ascending order
  floatingPoint.sort((a, b) => a - b);

  // Merge the sorted floating-point numbers and integers back into one array
  let sortedArr = [...floatingPoint, ...integers];

  return sortedArr;
}

