```python
class SmallestElement:
    def __init__(self, numbers):
        self.numbers = numbers

    def find_using_linear_search(self):
        smallest = self.numbers[0]
        for num in self.numbers:
            if num < smallest:
                smallest = num
        return smallest

    def find_using_selection_sort(self):
        sorted_numbers = self.numbers[:]
        for i in range(len(sorted_numbers)):
            min_idx = i
            for j in range(i+1, len(sorted_numbers)):
                if sorted_numbers[j] < sorted_numbers[min_idx]:
                    min_idx = j
            sorted_numbers[i], sorted_numbers[min_idx] = sorted_numbers[min_idx], sorted_numbers[i]
        return sorted_numbers

    def is_sorted(self):
        for i in range(1, len(self.numbers)):
            if self.numbers[i] < self.numbers[i-1]:
                return False
        return True

    def find_kth_smallest_linear_search(self, k):
        sorted_numbers = self.numbers[:]
        for i in range(k):
            smallest = sorted_numbers[i]
            smallest_idx = i
            for j in range(i, len(sorted_numbers)):
                if sorted_numbers[j] < smallest:
                    smallest = sorted_numbers[j]
                    smallest_idx = j
            sorted_numbers[i], sorted_numbers[smallest_idx] = sorted_numbers[smallest_idx], sorted_numbers[i]
        return sorted_numbers[k-1]

    def find_kth_smallest_selection_sort(self, k):
        sorted_numbers = self.numbers[:]
        for i in range(k):
            min_idx = i
            for j in range(i+1, len(sorted_numbers)):
                if sorted_numbers[j] < sorted_numbers[min_idx]:
                    min_idx = j
            sorted_numbers[i], sorted_numbers[min_idx] = sorted_numbers[min_idx], sorted_numbers[i]
        return sorted_numbers[k-1]

    def find_kth_smallest_quickselect(self, k):
        sorted_numbers = self.numbers[:]
        return self.quickselect(sorted_numbers, 0, len(sorted_numbers)-1, k)

    def quickselect(self, numbers, left, right, k):
        if left == right:
            return numbers[left]
        pivot_idx = self.partition(numbers, left, right)
        if k == pivot_idx:
            return numbers[k]
        elif k < pivot_idx:
            return self.quickselect(numbers, left, pivot_idx-1, k)
        else:
            return self.quickselect(numbers, pivot_idx+1, right, k)

    def partition(self, numbers, left, right):
        pivot = numbers[right]
        i = left
        for j in range(left, right):
            if numbers[j] <= pivot:
                numbers[i], numbers[j] = numbers[j], numbers[i]
                i += 1
        numbers[i], numbers[right] = numbers[right], numbers[i]
        return i

    def is_sorted_non_increasing(self):
        for i in range(1, len(self.numbers)):
            if self.numbers[i] > self.numbers[i-1]:
                return False
        return True


