        allowedSpecialChars.add(',');
        allowedSpecialChars.add('.');
        allowedSpecialChars.add('?');
        allowedSpecialChars.add('/');
        allowedSpecialChars.add('`');

        for (int i = 0; i < password.length(); i++) {
            if (!allowedSpecialChars.contains(password.charAt(i))) {
                return true;
            }
        }

        return false;
    }

    public static void main(String[] args) {
