```javascript
const numbers = [12, 15, 9, 17, 24, 6, 3, 11];
const sum = numbers.reduce((accumulator, currentNumber) => {
  if (currentNumber % 3 === 0 && currentNumber > 10) {
    return accumulator + currentNumber;
  }
  return accumulator;
}, 0);

