    }
    return removed;
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        std::cout << "Usage: " << argv[0] << " <input_file_name>" << std::endl;
        return 1;
    }

    std::string inputFileName = argv[1];
    std::ifstream inputFile(inputFileName);

    if (!inputFile.is_open()) {
        std::cout << "Error opening file: " << inputFileName << std::endl;
        return 1;
    }

    char searchChar;
    std::cout << "Enter the specific character to search for: ";
    std::cin >> searchChar;
    searchChar = std::tolower(searchChar); // Convert to lowercase for case-insensitive search

    std::string line;
    size_t lineCount = 0;
    size_t wordCount = 0;

    // Process each line in the input file
    while (std::getline(inputFile, line)) {
        lineCount++;

        // Trim leading and trailing whitespace characters
        line = trim(line);

        // Check if the first character matches the specific character
        if (!line.empty() && std::tolower(line[0]) == searchChar) {
            wordCount++;

            // Tokenize the line into individual words
            std::string word;
            std::istringstream iss(line);
            while (iss >> word) {
                // Remove leading and trailing whitespace characters from each word
                word = trim(word);

                // Remove punctuation marks from each word
                word = removePunctuation(word);

                // Check if the first character matches the specific character
                if (!word.empty() && std::tolower(word[0]) == searchChar) {
                    wordCount++;
                }
            }
        }

        // Display progress indicator
        if (lineCount % 1000 == 0) {
            std::cout << "Processed " << lineCount << " lines" << std::endl;
        }
    }

    inputFile.close();

    std::cout << "Total lines starting with '" << searchChar << "': " << lineCount << std::endl;
    std::cout << "Total words starting with '" << searchChar << "': " << wordCount << std::endl;

    return 0;
}
```

