Here's a JavaScript function that takes a string and returns the longest word in it, excluding any words that contain the letter "z":

```javascript
function findLongestWordWithoutZ(string) {
  // Split the string into an array of words
  const words = string.split(" ");

  // Initialize variables for the longest word and its length
  let longestWord = "";
  let longestWordLength = 0;

  // Loop through each word in the array
  for (let i = 0; i < words.length; i++) {
    const currentWord = words[i];

    // Check if the current word contains the letter "z"
    if (!currentWord.includes("z")) {
      const currentWordLength = currentWord.length;

      // Check if the current word is longer than the longest word found so far
      if (currentWordLength > longestWordLength) {
        longestWord = currentWord;
        longestWordLength = currentWordLength;
      }
    }
  }

  return longestWord;
}

// Example usage
const string = "This is an example string";
console.log(findLongestWordWithoutZ(string)); // Output: example
```

This function splits the input string into an array of words using the `split()` method and then iterates over each word. It checks if the current word contains the letter "z" using the `includes()` method. If the word does not contain "z", it compares the length of the current word with the length of the longest word found so far. If the current word is longer, it updates the longest word and its length. Finally, the function returns the longest word found.

Here's an example function in JavaScript that checks if a given positive integer is a prime number using the Miller-Rabin primality test:

```javascript
function isPrime(num) {
  // Check if the input is a positive integer
  if (!Number.isInteger(num) || num <= 1) {
    throw new Error("Input must be a positive integer");
  }

  // Special cases for small prime numbers
  if (num === 2 || num === 3) {
    return true;
  }

  // Check if the number is even
  if (num % 2 === 0) {
    return false;
  }

  // Miller-Rabin primality test
  const iterations = Math.ceil(Math.log2(num));
  for (let i = 0; i < iterations; i++) {
    const a = Math.floor(Math.random() * (num - 3)) + 2; // Random number between 2 and num-2
    if (modularExponentiation(a, num - 1, num) !== 1) {
      return false;
    }
  }

  return true;
}

function modularExponentiation(base, exponent, modulus) {
  if (modulus === 1) {
    return 0;
  }
  let result = 1;
  base = base % modulus;
  while (exponent > 0) {
    if (exponent % 2 === 1) {
      result = (result * base) % modulus;
    }
    exponent = exponent >> 1;
    base = (base * base) % modulus;
  }
  return result;
}
```

