// Check if timezone data is already cached
if (!$redis->exists($timezone)) {
    // Fetch and cache timezone data
    $redis->watch($timezone); // Start watching the key
    $redis->multi(); // Begin transaction
    $redis->set($timezone, date_default_timezone_get()); // Store timezone data
    $redis->expire($timezone, 3600); // Set expiry time to 1 hour
    $redis->exec(); // Execute transaction
}

// Get timezone data from cache
$current_timezone = $redis->get($timezone);

// Set timezone
date_default_timezone_set($current_timezone);

// Get current date and time
$current_date = date("Y-m-d");
$current_time = date("H:i:s");

// Display the current date, day, and time
echo "Current date and day in $timezone: $current_date (".date('l').")<br>";
echo "Current time in 24-hour format: $current_time";

// Disconnect from Redis
$redis->close();
?>
