            throw std::invalid_argument("Maximum quantity reached");
        }
        quantity += amount;
    }

    void decreaseQuantity(int amount) {
        if (quantity - amount < MIN_QUANTITY) {
            throw std::invalid_argument("Minimum quantity reached");
        }
        quantity -= amount;
    }

    bool isAvailable() {
        return quantity > 0;
    }

    static int getTotalQuantity(Fruit fruits[], int size) {
        int totalQuantity = 0;
        for (int i = 0; i < size; i++) {
            totalQuantity += fruits[i].quantity;
        }
        return totalQuantity;
    }

    std::string getName() {
        return name;
    }

    std::string getColor() {
        return color;
    }

    int getQuantity() {
