    var request = new XMLHttpRequest();
    request.open('GET', 'validate-email.php?email=' + email, true);
    request.onload = function() {
      if (request.status >= 200 && request.status < 400) {
        var response = JSON.parse(request.responseText);
        if (response.isValid) {
          saveEmail(email);
        } else {
          displayError('Email address does not exist');
        }
      } else {
        displayError('Error occurred while validating email');
      }
    };
    request.onerror = function() {
      displayError('Error occurred while validating email');
