void printSpiralPattern(int size) {
    int matrix[size][size];
    int num = 1;
    int row = size / 2;
    int col = size / 2;

    matrix[row][col] = num++;

    // Move right, up, left, down in the spiral pattern
    for (int i = 1; i < size; i++) {
        for (int j = 0; j < i; j++) {
            matrix[row][++col] = num++;
        }
        for (int j = 0; j < i; j++) {
            matrix[--row][col] = num++;
        }
        for (int j = 0; j < i + 1; j++) {
            matrix[row][--col] = num++;
        }
        for (int j = 0; j < i + 1; j++) {
            matrix[++row][col] = num++;
        }
    }

    // Print the matrix
    for (int i = 0; i < size; i++) {
        for (int j = 0; j < size; j++) {
            std::cout << matrix[i][j] << "\t";
