def modified_insertion_sort(arr):
    if len(arr) <= 1:
        return arr

    def binary_search(arr, low, high, target):
        if low == high:
            return low if arr[low] <= target else low + 1
        if low > high:
            return low

        mid = (low + high) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            return binary_search(arr, mid + 1, high, target)
        else:
            return binary_search(arr, low, mid - 1, target)

    def insert(arr, i):
        if i == 0:
            return
        index = binary_search(arr, 0, i - 1, arr[i])
        temp = arr[i]
        for j in range(i, index, -1):
            arr[j] = arr[j - 1]
        arr[index] = temp
        insert(arr, i - 1)

    insert(arr, len(arr) - 1)
    return arr

