import React, { Component } from 'react';

class Greeting extends Component {
  constructor(props) {
    super(props);
    this.state = {
      name: props.name,
      location: null,
      weather: null,
      temperatureUnit: 'Fahrenheit',
      error: null,
    };
  }

  componentDidMount() {
    this.fetchLocation();
    this.fetchWeather();
  }

  fetchLocation() {
    // Use browser geolocation API to get user's location
    navigator.geolocation.getCurrentPosition(
      position => {
        const { latitude, longitude } = position.coords;
        this.setState({ location: { latitude, longitude } });
      },
      error => {
        this.setState({ error: 'Failed to fetch location. Please try again.' });
      }
    );
  }

  fetchWeather() {
    const { location } = this.state;

    if (location) {
      // Use weather API to get current weather based on user's location
      const apiKey = 'your_weather_api_key';
      const url = `https://api.weather.com/...?lat=${location.latitude}&lon=${location.longitude}&apiKey=${apiKey}`;

      fetch(url)
        .then(response => response.json())
        .then(data => {
          const { temperature, description } = data;
          this.setState({ weather: { temperature, description } });
        })
        .catch(error => {
          this.setState({ error: 'Failed to fetch weather. Please try again.' });
        });
    }
  }

  changeName = () => {
    const newName = prompt('Enter your name:');
    if (newName) {
      this.setState({ name: newName });
    }
  };

  toggleTemperatureUnit = () => {
    const { temperatureUnit } = this.state;
    const newUnit = temperatureUnit === 'Fahrenheit' ? 'Celsius' : 'Fahrenheit';
    this.setState({ temperatureUnit: newUnit });
  };

  changeLocation = () => {
    this.setState({ location: null, weather: null, error: null }, () => {
      this.fetchLocation();
      this.fetchWeather();
    });
  };

  renderGreeting() {
    const { name, location, weather, temperatureUnit } = this.state;

    if (location && weather) {
      const { temperature, description } = weather;

      // Determine the time of day
      const now = new Date();
      const hour = now.getHours();
      let timeOfDay;
      let backgroundColor;

      if (hour >= 6 && hour < 12) {
        timeOfDay = 'morning';
        backgroundColor = '#f8e7d8';
      } else if (hour >= 12 && hour < 18) {
        timeOfDay = 'afternoon';
        backgroundColor = '#f6f6b4';
      } else {
        timeOfDay = 'evening';
        backgroundColor = '#c9d2d8';
      }

      // Generate personalized message
      let message = `Good ${timeOfDay}, ${name}!`;
      message += ` It's ${description.toLowerCase()} and ${this.convertTemperature(temperature, temperatureUnit)} in ${location}.`;
      message += ` You might enjoy visiting the local park for a picnic.`;

      return (
        <div style={{ backgroundColor }}>
          <h1>{message}</h1>
          <button onClick={this.changeName}>Change Name</button>
          <button onClick={this.toggleTemperatureUnit}>Toggle Temperature Unit</button>
          <button onClick={this.changeLocation}>Change Location</button>
        </div>
      );
    } else if (location === null || weather === null) {
      return <h1>Loading...</h1>;
    } else {
      return (
        <div>
          <h1>Error: {error}</h1>
          <button onClick={this.fetchLocation}>Retry</button>
        </div>
      );
    }
  }

  convertTemperature(temperature, unit) {
    if (unit === 'Fahrenheit') {
      return `${temperature}°F`;
    } else {
      const celsius = Math.round((temperature - 32) * 5 / 9);
      return `${celsius}°C`;
    }
  }

  render() {
    return this.renderGreeting();
  }
}

export default Greeting;
