CREATE TRIGGER generate_username
BEFORE INSERT ON users
FOR EACH ROW
BEGIN
    DECLARE counter INT DEFAULT 1;
    DECLARE new_username VARCHAR(255);

    SET new_username = CONCAT(LOWER(SUBSTRING(NEW.first_name, 1, 1)), NEW.last_name);

    WHILE (SELECT COUNT(*) FROM users WHERE username = new_username) > 0 DO
        SET new_username = CONCAT(LOWER(SUBSTRING(NEW.first_name, 1, 1)), NEW.last_name, counter);
