import java.util.Arrays;
import java.util.Scanner;

public class ArrayDeletion {
    public static void main(String[] args) {
        int[] array = {1, 2, 3, 4, 5};

        System.out.println("Array before deletion: " + Arrays.toString(array));
        int index = getIndexToDelete(array.length);

        int[] updatedArray = deleteAtIndex(array, index);
        System.out.println("Array after deletion: " + Arrays.toString(updatedArray));
    }

    public static int getIndexToDelete(int arrayLength) {
        Scanner scanner = new Scanner(System.in);
        int index;

        do {
            System.out.print("Enter the index of the item you want to delete: ");
            while (!scanner.hasNextInt()) {
                System.out.println("Invalid input. Please enter a valid integer index.");
                scanner.next();
            }
            index = scanner.nextInt();

            if (index < 0 || index >= arrayLength) {
                System.out.println("Invalid index. Please enter a valid index within the range of the array.");
            }
        } while (index < 0 || index >= arrayLength);

        return index;
    }

    public static int[] deleteAtIndex(int[] array, int index) {
        int[] updatedArray = new int[array.length - 1];

        for (int i = 0, j = 0; i < array.length; i++) {
            if (i != index) {
                updatedArray[j] = array[i];
                j++;
            }
        }

        return updatedArray;
    }
}
```

This implementation uses a `Scanner` to read user input and validates the input to ensure it is a valid integer within the range of the array's indices. The `getIndexToDelete` method handles this validation logic.

The `deleteAtIndex` method creates a new array with a length one less than the original array and copies all elements from the original array except the one at the specified index. This ensures that the subsequent elements are shifted to fill the gap left by the deleted item.

