```java
import java.sql.*;

public class DatabaseConnector {
    private static final String DB_HOST = "localhost";
    private static final int DB_PORT = 3306;
    private static final String DB_NAME = "mydatabase";
    private static final String DB_USERNAME = "myusername";
    private static final String DB_PASSWORD = "mypassword";

    public static void main(String[] args) {
        Connection connection = null;
        try {
            // Establish a connection to the remote database
            connection = DriverManager.getConnection(
                    "jdbc:mysql://" + DB_HOST + ":" + DB_PORT + "/" + DB_NAME,
                    DB_USERNAME, DB_PASSWORD
            );

            // Create a SQL statement to retrieve data from a specific table
            String sql = "SELECT * FROM mytable WHERE condition = ?";

            // Prepare the statement with the SQL query
            PreparedStatement statement = connection.prepareStatement(sql);

            // Set the parameter value for the condition
            statement.setString(1, "some condition");

            // Execute the SQL query and get the result set
            ResultSet resultSet = statement.executeQuery();

            // Process the result set and display the retrieved data on the console
            while (resultSet.next()) {
                String column1Value = resultSet.getString("column1");
                int column2Value = resultSet.getInt("column2");

                System.out.println("Column 1: " + column1Value);
                System.out.println("Column 2: " + column2Value);
                System.out.println("----------");
            }
        } catch (SQLException e) {
            e.printStackTrace();
        } finally {
            // Close the database connection
            try {
                if (connection != null && !connection.isClosed()) {
                    connection.close();
                }
            } catch (SQLException e) {
                e.printStackTrace();
            }
        }
    }
}
```

