import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { HttpClient } from '@angular/common/http';

@Component({
  selector: 'app-registration',
  templateUrl: './registration.component.html',
  styleUrls: ['./registration.component.css']
})
export class RegistrationComponent implements OnInit {
  registrationForm: FormGroup;

  constructor(private formBuilder: FormBuilder, private http: HttpClient) { }

  ngOnInit() {
    this.registrationForm = this.formBuilder.group({
      username: ['', [Validators.required]],
      password: ['', [Validators.required, Validators.pattern(/^(?=.*\d)(?=.*[a-z])(?=.*[A-Z])(?=.*[^a-zA-Z0-9]).{8,}$/)]],
      email: ['', [Validators.required, Validators.email]]
    });
  }

  onSubmit() {
    if (this.registrationForm.invalid) {
      return;
    }

    // Check if username is taken
    this.http.get('/api/check-username/' + this.registrationForm.get('username').value).subscribe((response: any) => {
      if (response.usernameTaken) {
        this.registrationForm.get('username').setErrors({ usernameTaken: true });
      } else {
        // Check if email is taken
        this.http.get('/api/check-email/' + this.registrationForm.get('email').value).subscribe((response: any) => {
          if (response.emailTaken) {
            this.registrationForm.get('email').setErrors({ emailTaken: true });
          } else {
            // Save registration data to the database
            this.http.post('/api/register', this.registrationForm.value).subscribe(() => {
              // Registration successful, redirect to login page
              window.location.href = '/login';
            });
          }
        });
      }
    });
  }
}
