public class PrimeNumberValidator {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.println("Enter a string of prime numbers (separated by commas):");
        String input = scanner.nextLine();

        if (isValid(input)) {
            System.out.println("Input string is valid");
        } else {
            System.out.println("Input string is invalid");
        }
    }

    public static boolean isValid(String input) {
        // Check if input string is empty
        if (input.isEmpty()) {
            System.out.println("Input string cannot be empty");
            return false;
        }

        // Check if input string exceeds maximum length of 10 characters
        if (input.length() > 10) {
            System.out.println("Input string length exceeds maximum limit of 10 characters");
            return false;
        }

        // Split the input string by commas
        String[] numbers = input.split(",");

        // Convert the string numbers to integers
        int[] primes = new int[numbers.length];
        for (int i = 0; i < numbers.length; i++) {
            try {
                primes[i] = Integer.parseInt(numbers[i]);
            } catch (NumberFormatException e) {
                System.out.println("Input string contains non-numeric characters");
                return false;
            }
        }

        // Check if prime numbers are in ascending order
        for (int i = 0; i < primes.length - 1; i++) {
            if (primes[i] >= primes[i + 1]) {
                System.out.println("Prime numbers in input string are not in ascending order");
                return false;
            }
        }

        // Check if numbers are prime
        for (int num : primes) {
            if (!isPrime(num)) {
                System.out.println("Input string contains non-prime numbers");
                return false;
            }
        }

        return true;
    }

    public static boolean isPrime(int num) {
        if (num <= 1) {
            return false;
        }

        for (int i = 2; i <= Math.sqrt(num); i++) {
            if (num % i == 0) {
                return false;
            }
        }

        return true;
    }
}
