One possible data structure that can efficiently support the mentioned operations is a hash table. In the hash table, the course names can be used as keys, and the course details can be stored as values.

Here is an example implementation in Python:

```python
class Course:
    def __init__(self, name, details):
        self.name = name
        self.details = details

class CourseDatabase:
    def __init__(self):
        self.courses = {}

    def add_course(self, name, details):
        course = Course(name, details)
        self.courses[name] = course

    def remove_course(self, name):
        if name in self.courses:
            del self.courses[name]

    def update_course_details(self, name, new_details):
        if name in self.courses:
            self.courses[name].details = new_details

    def get_course_details(self, name):
        if name in self.courses:
            return self.courses[name].details
        return None

    def get_all_courses(self):
        return list(self.courses.values())

    def get_courses_with_keyword(self, keyword):
        matching_courses = []
        for course in self.courses.values():
            if keyword in course.details:
                matching_courses.append(course)
        return matching_courses
