func splitStringByDelimiter(_ string: String, delimiter: String) -> Result<[String], String> {
    if let range = string.range(of: delimiter) {
        let parts = string.components(separatedBy: delimiter)
        return .success(parts)
    } else {
        return .failure("Delimiter not found in the string.")
