int containsThreeConsecutivePunctuations(char* str) {
    int count = 0;

    while (*str != '\0') {
        if (*str == '!' || *str == '?' || *str == '.') {
            count++;
            if (count == 3) {
                return 1;
            }
        } else {
            count = 0;
        }
        str++;
    }

