To implement a recursive function to find the logarithm (base 10) of a number without using any built-in logarithm functions or libraries, you can use the concept of binary search to iteratively divide the number and reduce the search space.

Here's an example implementation in Python:

```python
def log_base_10(num, low, high):
    if num == 0:
        return float('-inf')  # log(0) is undefined
    elif num == 1:
        return 0  # log(1) is 0
    elif num < 0:
        return float('nan')  # log of negative number is undefined

    mid = (low + high) // 2

    if mid == low:
        return mid

    if 10**mid == num:
        return mid
    elif 10**mid < num:
        return log_base_10(num, mid, high)
    else:
        return log_base_10(num, low, mid)

def log10(num):
    if num <= 0:
        return float('nan')  # log of non-positive number is undefined
    elif num == 1:
        return 0  # log(1) is 0
    elif num < 1:
        return -log_base_10(1/num, 0, 1)
    else:
        return log_base_10(num, 0, num)

# Testing the log10 function
print(log10(100))  # Output: 2.0
print(log10(1000))  # Output: 3.0
print(log10(10))  # Output: 1.0
print(log10(1))  # Output: 0.0
