public class HighestValueFinder {

  public static void main(String[] args) {
    int[] array = {10, -5, 20, 10, 5, -10, 20};
    int highestValue = findHighestValue(array);
    System.out.println("Highest value: " + highestValue);
  }

  public static int findHighestValue(int[] array) {
    if (array.length == 0) {
      throw new IllegalArgumentException("Array is empty");
    }

    int highestValue = Integer.MIN_VALUE;
    int highestOccurrence = 0;

    for (int i = 0; i < array.length; i++) {
      if (array[i] > highestValue) {
        highestValue = array[i];
        highestOccurrence = 1;
      } else if (array[i] == highestValue) {
        highestOccurrence++;
      }
    }

    if (highestValue == Integer.MIN_VALUE) {
      throw new IllegalArgumentException("Array contains only negative values");
    }

    return highestValue;
  }
}
```

Explanation:
