def evaluate_expression_tree(root):
    if root.val == '+':
        return evaluate_expression_tree(root.left) + evaluate_expression_tree(root.right)
    elif root.val == '-':
        return evaluate_expression_tree(root.left) - evaluate_expression_tree(root.right)
    elif root.val == '*':
        return evaluate_expression_tree(root.left) * evaluate_expression_tree(root.right)
    elif root.val == '/':
        right_value = evaluate_expression_tree(root.right)
        if right_value == 0:
            raise ValueError("Division by zero")
        return evaluate_expression_tree(root.left) / right_value
    else:
        return root.val


