import xml.etree.ElementTree as ET

def convert_to_xml(data):
    root = ET.Element("root")
    convert_to_xml_recursive(data, root)
    return ET.tostring(root, encoding="unicode", method="xml")

def convert_to_xml_recursive(data, parent):
    if isinstance(data, dict):
        for key, value in data.items():
            if isinstance(value, (dict, list)):
                element = ET.SubElement(parent, key)
                convert_to_xml_recursive(value, element)
            else:
                ET.SubElement(parent, key).text = str(value)
    elif isinstance(data, list):
        for item in data:
            if isinstance(item, (dict, list)):
                element = ET.SubElement(parent, "item")
                convert_to_xml_recursive(item, element)
            else:
                ET.SubElement(parent, "item").text = str(item)
    else:
        raise ValueError("Invalid input data structure")

