import java.util.HashSet;

public class ReverseAndCombineStrings {
    public static void main(String[] args) {
        String string1 = "hello";
        String string2 = "world";
        String string3 = "!";

        String combinedString = reverseAndCombineStrings(string1, string2, string3);
        System.out.println(combinedString);
    }

    public static String reverseAndCombineStrings(String string1, String string2, String string3) {
        String reversedString1 = reverseString(string1);
        String reversedString2 = reverseString(string2);
        String reversedString3 = reverseString(string3);

        String combinedString = reversedString1 + reversedString2 + reversedString3;

        return removeDuplicates(combinedString);
    }

    public static String reverseString(String string) {
        StringBuilder reversedString = new StringBuilder();
        for (int i = string.length() - 1; i >= 0; i--) {
            reversedString.append(string.charAt(i));
        }
        return reversedString.toString();
    }

    public static String removeDuplicates(String string) {
        StringBuilder uniqueString = new StringBuilder();
        HashSet<Character> seenCharacters = new HashSet<>();
        for (char c : string.toCharArray()) {
            if (!seenCharacters.contains(c)) {
                uniqueString.append(c);
                seenCharacters.add(c);
            }
        }
        return uniqueString.toString();
    }
}
