```java
import java.util.Scanner;

public class InputReader {
    private static final Scanner scanner = new Scanner(System.in);

    public static void main(String[] args) {
        int integer = readInteger("Enter an integer: ");
        System.out.println("You entered: " + integer);

        double floatingPointNumber = readFloatingPointNumber("Enter a floating-point number: ");
        System.out.println("You entered: " + floatingPointNumber);

        String string = readString("Enter a string: ");
        System.out.println("You entered: " + string);
    }

    public static int readInteger(String message) {
        while (true) {
            try {
                System.out.print(message);
                String input = scanner.nextLine();
                int value = Integer.parseInt(input);
                return value;
            } catch (NumberFormatException e) {
                System.out.println("Invalid input. Please enter an integer.");
            }
        }
    }

    public static double readFloatingPointNumber(String message) {
        while (true) {
            try {
                System.out.print(message);
                String input = scanner.nextLine();
                double value = Double.parseDouble(input);
                return value;
            } catch (NumberFormatException e) {
                System.out.println("Invalid input. Please enter a floating-point number.");
            }
        }
    }

    public static String readString(String message) {
        while (true) {
            System.out.print(message);
            String input = scanner.nextLine();
            if (input.matches("[a-zA-Z]+")) {
                return input;
            }
            System.out.println("Invalid input. Please enter a string containing only alphabetic characters.");
        }
    }
}
```

