import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;
import java.util.concurrent.*;

public class PrimeNumberGenerator {
    private static final int THREAD_COUNT = 4;
    private static volatile boolean isPaused = false;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a number: ");
        int number = scanner.nextInt();

        ExecutorService executorService = Executors.newFixedThreadPool(THREAD_COUNT);
        List<Future<List<Integer>>> futures = new ArrayList<>();

        int chunkSize = number / THREAD_COUNT;
        int start = 2;
        int end = start + chunkSize;

        // Submit tasks to the executor service
        for (int i = 0; i < THREAD_COUNT; i++) {
            Callable<List<Integer>> callable = new PrimeNumberCallable(start, end);
            futures.add(executorService.submit(callable));
            start = end + 1;
            end = start + chunkSize;
            if (end >= number) {
                end = number;
            }
        }

        // Create a separate thread to update the progress bar
        Thread progressBarThread = new Thread(() -> {
            int totalPrimesFound = 0;
            int lastPercentage = 0;
            while (totalPrimesFound < number) {
                if (!isPaused) {
                    totalPrimesFound = futures.stream()
                            .mapToInt(future -> {
                                try {
                                    return future.get().size();
                                } catch (InterruptedException | ExecutionException e) {
                                    e.printStackTrace();
                                }
                                return 0;
                            })
                            .sum();

                    int percentage = (int) ((totalPrimesFound / (double) number) * 100);
                    if (percentage != lastPercentage) {
                        lastPercentage = percentage;
                        updateProgressBar(percentage);
                    }
                }
            }
            executorService.shutdown();
        });
        progressBarThread.start();

        // Display prime numbers in real-time
        for (Future<List<Integer>> future : futures) {
            try {
                List<Integer> primes = future.get();
                System.out.println(primes);
            } catch (InterruptedException | ExecutionException e) {
                e.printStackTrace();
            }
        }

        // Wait for the progress bar thread to finish
        try {
            progressBarThread.join();
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }

    private static class PrimeNumberCallable implements Callable<List<Integer>> {
        private final int start;
        private final int end;

        PrimeNumberCallable(int start, int end) {
            this.start = start;
            this.end = end;
        }

        @Override
        public List<Integer> call() {
            List<Integer> primes = new ArrayList<>();
            for (int number = start; number <= end; number++) {
                if (isPrime(number)) {
                    primes.add(number);
                }
            }
            return primes;
        }

        private boolean isPrime(int number) {
            if (number <= 1) {
                return false;
            }
            for (int i = 2; i <= Math.sqrt(number); i++) {
                if (number % i == 0) {
                    return false;
                }
            }
            return true;
        }
    }

    private static void updateProgressBar(int percentage) {
        int width = 50;
        int progress = (int) (percentage / 100.0 * width);

        StringBuilder progressBar = new StringBuilder("[");
        for (int i = 0; i < progress; i++) {
            progressBar.append("=");
        }
        for (int i = progress; i < width; i++) {
            progressBar.append(" ");
        }
        progressBar.append("] ").append(percentage).append("%");
        System.out.print("\r" + progressBar.toString());
    }
}

