function utf8Bytes(string) {
  if (string.length === 0) {
    return 0;
  }

  const codePoint = string.codePointAt(0);

  if (codePoint <= 127) {
    return 1;
  }

  if (codePoint < 2048) {
    return 2;
  }

  if (codePoint < 65536) {
    return 3;
  }

  return 4;
}
