import math

class Shape:
    def __init__(self, length, width):
        if self.is_prime(length) and self.is_prime(width):
            self.length = length
            self.width = width
        else:
            raise ValueError("Length and width must be prime numbers")

    def calculate_area(self, length, width):
        return round(length * width)

    def calculate_perimeter(self, length, width):
        return round(2 * (length + width))

    def calculate_diagonal(self):
        return round(math.sqrt(self.length ** 2 + self.width ** 2))

    def isSquare(self):
        return self.length == self.width

    def __str__(self):
        return "Length: {}, Width: {}".format(self.length, self.width)

    def is_prime(self, n):
        if n <= 1:
            return False
        for i in range(2, int(math.sqrt(n)) + 1):
            if n % i == 0:
                return False
        return True

# Example usage:
