void draw() {
  background(255);

  while (circlesGenerated < 1000) {
    float x = random(width);
    float y = random(height);
    float radius = random(10, 50);
    Circle newCircle = new Circle(x, y, radius);

    boolean overlapping = false;
    for (Circle c : circles) {
      if (newCircle.intersects(c)) {
        overlapping = true;
        break;
      }
    }

    if (!overlapping && newCircle.withinCanvas()) {
      circles.add(newCircle);
      circlesGenerated++;
    }
  }

  for (Circle c : circles) {
    c.display();
  }

  fill(0);
  text("Circles Generated: " + circlesGenerated, 10, 20);
}

class Circle {
  float x, y;
  float radius;

  Circle(float x, float y, float radius) {
    this.x = x;
    this.y = y;
    this.radius = radius;
  }

  void display() {
    ellipse(x, y, radius * 2, radius * 2);
  }

  boolean intersects(Circle other) {
    float distance = dist(x, y, other.x, other.y);
    return distance < (radius + other.radius);
  }

  boolean withinCanvas() {
    return (x - radius) > 0 && (x + radius) < width && (y - radius) > 0 && (y + radius) < height;
  }
}
