Here's a JavaScript function that takes a date as input and returns the corresponding day of the week along with the current time in the format DD/MM/YYYY hh:mm:ss. The function also handles leap years correctly:

```javascript
function getDayAndTime(dateString) {
  // Split the date string into year, month, and day components
  const [year, month, day] = dateString.split("-");

  // Create a Date object from the input year, month, and day
  const date = new Date(year, month - 1, day);

  // Check if the input date is valid
  if (isNaN(date.getTime())) {
    return "Invalid date";
  }

  // Get the day of the week (0 = Sunday, 1 = Monday, ..., 6 = Saturday)
  const dayOfWeek = date.getDay();

  // Get the current time in hh:mm:ss format
  const time = new Date().toLocaleTimeString([], {
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  });

  // Format the date as DD/MM/YYYY
  const formattedDate = `${day.padStart(2, "0")}/${month.padStart(
    2,
    "0"
  )}/${year}`;

  // Define an array of weekdays
  const weekdays = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];

  // Return the day of the week and the current time
  return `${weekdays[dayOfWeek]} ${formattedDate} ${time}`;
}
