```python
from bs4 import BeautifulSoup

def parse_html(html_code):
    # Create a BeautifulSoup object
    soup = BeautifulSoup(html_code, 'html.parser')

    # Helper function to recursively parse elements
    def parse_element(element):
        # Initialize dictionary for storing element data
        data = {}

        # Extract tag name
        data['tag'] = element.name

        # Extract attributes
        if element.attrs:
            data['attributes'] = element.attrs

        # Extract text content
        if element.string:
            data['text'] = element.string.strip()

        # Recursively parse nested elements
        if element.contents:
            data['children'] = [parse_element(child) for child in element.contents if child.name is not None]

        return data

    # Start parsing from the root element
    root = soup.find('html')
    return parse_element(root)

