```java
import java.util.Scanner;

public class HexToInteger {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a hexadecimal character: ");
        String hexChar = scanner.next();

        int decimalValue = hexToDecimal(hexChar.charAt(0));
        System.out.println("The decimal value of " + hexChar + " is " + decimalValue);
    }

    public static int hexToDecimal(char hexChar) {
        int decimalValue = 0;

        if (hexChar >= '0' && hexChar <= '9') {
            decimalValue = hexChar - '0';
        } else if (hexChar >= 'A' && hexChar <= 'F') {
            decimalValue = hexChar - 'A' + 10;
        } else if (hexChar >= 'a' && hexChar <= 'f') {
            decimalValue = hexChar - 'a' + 10;
        } else {
            System.out.println("Invalid hexadecimal character");
            System.exit(1);
        }

        return decimalValue;
    }
}
