```cpp
#include <iostream>
#include <vector>

using namespace std;

typedef long long ll;

vector<pair<ll, ll>> prime_factorize(ll n) {
    vector<pair<ll, ll>> factors;
    for (ll i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            ll cnt = 0;
            while (n % i == 0) {
                n /= i;
                cnt++;
            }
            factors.push_back({i, cnt});
        }
    }
    if (n > 1) {
        factors.push_back({n, 1});
    }
    return factors;
}

ll gcd(ll a, ll b) {
    if (a == 0)
        return b;
    if (b == 0)
        return a;

    if (a < 0)
        a = -a;
    if (b < 0)
        b = -b;

    if (a == b)
        return a;

    if (a == 1 || b == 1)
        return 1;

    if ((a & 1) == 0 && (b & 1) == 0)
        return 2 * gcd(a >> 1, b >> 1);

    if ((a & 1) == 0)
        return gcd(a >> 1, b);

    if ((b & 1) == 0)
        return gcd(a, b >> 1);

    if (a > b)
        return gcd(a - b, b);

    return gcd(a, b - a);
}

bool areCoPrime(ll a, ll b) {
    return gcd(a, b) == 1;
}

int main() {
    // Example usage
    ll a = 14;
    ll b = 21;
    cout << "GCD: " << gcd(a, b) << endl;
    cout << "Co-Prime: " << (areCoPrime(a, b) ? "Yes" : "No") << endl;
    cout << "Prime Factors of GCD: ";
    vector<pair<ll, ll>> factors = prime_factorize(gcd(a, b));
    for (const auto& factor : factors) {
        cout << factor.first << "^" << factor.second << " ";
    }
    cout << endl;

    return 0;
}
```

Explanation:

- The `prime_factorize` function takes an integer `n` as input and returns a vector of pairs, where each pair represents a prime factor and its corresponding power in the factorization of `n`. This function is implemented using a basic trial division algorithm.
- The `gcd` function calculates the greatest common divisor of two integers `a` and `b` using a recursive approach. It first handles the base cases of `a` or `b` being zero, then handles the case of either `a` or `b` being equal to 1. It also handles the case of `a` and `b` being equal. The function utilizes bitwise operations to optimize the calculation when one or both of the numbers are even. It also uses recursion to reduce the problem size for odd numbers.
- The `areCoPrime` function simply checks if the GCD of `a` and `b` is equal to 1, indicating that the two numbers are co-prime.
- In the `main` function, we demonstrate the usage of the above functions. We calculate the GCD of two numbers (`a` and `b`), check if they are co-prime, and print the prime factorization of the GCD.

