import React, { useState } from 'react';

const Table = () => {
  const [data, setData] = useState([
    { id: 1, name: 'John Doe', age: 25 },
    { id: 2, name: 'Jane Smith', age: 30 },
    { id: 3, name: 'Bob Johnson', age: 35 },
  ]);
  const [selectedRows, setSelectedRows] = useState([]);
  const [editingRow, setEditingRow] = useState(null);
  const [newRow, setNewRow] = useState({ name: '', age: '' });

  const handleCheckboxChange = (id) => {
    if (selectedRows.includes(id)) {
      setSelectedRows(selectedRows.filter((rowId) => rowId !== id));
    } else {
      setSelectedRows([...selectedRows, id]);
    }
  };

  const handleDeleteSelected = () => {
    setData(data.filter((row) => !selectedRows.includes(row.id)));
    setSelectedRows([]);
  };

  const handleAddRow = () => {
    setData([...data, { id: data.length + 1, ...newRow }]);
    setNewRow({ name: '', age: '' });
  };

  const handleEditRow = (id) => {
    setEditingRow(id);
  };

  const handleSaveRow = (id, updatedRow) => {
    setData(data.map((row) => (row.id === id ? updatedRow : row)));
    setEditingRow(null);
  };

  const handleSort = (key) => {
    const sortedData = [...data].sort((a, b) => {
      if (a[key] < b[key]) return -1;
      if (a[key] > b[key]) return 1;
      return 0;
    });
    setData(sortedData);
  };

  return (
    <div>
      <button onClick={handleDeleteSelected}>Delete Selected</button>
      <table>
        <thead>
          <tr>
            <th>
              <input
                type="checkbox"
                checked={selectedRows.length === data.length}
                onChange={() =>
                  setSelectedRows(
                    selectedRows.length === data.length ? [] : data.map((row) => row.id)
                  )
                }
              />
            </th>
            <th>
              <button onClick={() => handleSort('name')}>Name</button>
            </th>
            <th>
              <button onClick={() => handleSort('age')}>Age</button>
            </th>
            <th>Edit</th>
          </tr>
        </thead>
        <tbody>
          {data.map((row) => (
            <tr key={row.id}>
              <td>
                <input
                  type="checkbox"
                  checked={selectedRows.includes(row.id)}
                  onChange={() => handleCheckboxChange(row.id)}
                />
              </td>
              <td>{editingRow === row.id ? <input value={row.name} /> : row.name}</td>
              <td>{editingRow === row.id ? <input value={row.age} /> : row.age}</td>
              <td>
