          <tr>
            <td>
              <input
                type="checkbox"
                checked={false}
                onChange={() => {}}
                disabled
              />
            </td>
            <td>
              <input
                value={newRow.name}
                onChange={(e) => setNewRow({ ...newRow, name: e.target.value })}
              />
            </td>
            <td>
              <input
