```javascript
function parseUrl(url) {
  // Check if the URL is valid
  const regex = /^(http|https):\/\/([^:/?]+)(?::(\d+))?(\/[^?]+)?(?:\?(.*))?$/;
  const match = url.match(regex);

  // Return null if the URL is invalid
  if (!match) {
    return null;
  }

  const [, protocol, domain, port, path, queryString] = match;

  // Set default port values
  if (!port) {
    port = protocol === 'http' ? '80' : '443';
  }

  // Parse query parameters
  const queryParams = {};
  if (queryString) {
    const params = queryString.split('&');
    for (const param of params) {
      const [key, value] = param.split('=');
      queryParams[key] = decodeURIComponent(value);
    }
  }

  return {
    protocol,
    domain,
    port,
    path: path || '/',
    queryParams,
  };
}

// Example usage
const url = 'https://www.example.com:8080/path/to/page?param1=value1&param2=value2';
const result = parseUrl(url);
console.log(result);
```

This implementation uses a regular expression to match and capture the different components of the URL. It then sets default values for the port and path, and parses the query parameters into an object. Finally, it returns an object containing the parsed components.

