#include<stdio.h>

#define SIZE 26

void countFrequency(char *str, int *frequency) {
    while (*str) {
        if (*str >= 'a' && *str <= 'z') {
            frequency[*str - 'a']++;
        } else if (*str >= 'A' && *str <= 'Z') {
            frequency[*str - 'A']++;
        }
        str++;
    }
}

int main() {
    char str[] = "aAbBcCabcABC";
    int frequency[SIZE] = {0};

    countFrequency(str, frequency);

    for (int i = 0; i < SIZE; i++) {
        if (frequency[i] > 0) {
