import json

def convert_json_to_string(json_object, current_depth=0, visited_objects=None):
    if visited_objects is None:
        visited_objects = set()

    if current_depth > 10:
        return "Max depth of 10 exceeded"

    try:
        json_string = json.dumps(json_object)
    except (TypeError, OverflowError):
        return "Invalid JSON object"

    if json_object in visited_objects:
        return "Circular reference detected"

    visited_objects.add(json_object)

    if isinstance(json_object, dict):
        if len(json_object) > 100:
            return "Max key-value pair limit of 100 exceeded"

        for key, value in json_object.items():
            if current_depth < 10:
                result = convert_json_to_string(value, current_depth + 1, visited_objects)
                if isinstance(result, str):
                    return result
            else:
                return "Max depth of 10 exceeded"

    elif isinstance(json_object, list):
        for item in json_object:
            if current_depth < 10:
                result = convert_json_to_string(item, current_depth + 1, visited_objects)
                if isinstance(result, str):
                    return result
            else:
                return "Max depth of 10 exceeded"

    visited_objects.remove(json_object)
    return json_string
```

