        this.taskId = taskId;
        this.priority = priority;
    }

    @Override
    public void run() {
        try {
            lock.lock();
            while (currentThread != priority) {
                Thread.sleep(100);
            }
            currentThread++;
        } catch (InterruptedException ex) {
            Logger.getLogger(Task.class.getName()).log(Level.SEVERE, null, ex);
            Thread.currentThread().interrupt();
        } finally {
            lock.unlock();
        }

        try {
            switch (taskId) {
                case 1:
                    multiplyMatrices();
                    break;
                case 2:
                    performComplexComputation();
                    break;
                // Add more cases for other tasks
            }
