```swift
func capitalizeFirstLetterOfEachWord(_ sentence: String) -> String {
    // Remove leading and trailing spaces
    let trimmedSentence = sentence.trimmingCharacters(in: .whitespacesAndNewlines)

    // Split the sentence into an array of words
    let words = trimmedSentence.components(separatedBy: .whitespaces)

    // Create an empty array to store the capitalized words
    var capitalizedWords: [String] = []

    // Iterate over each word and capitalize the first letter
    for word in words {
        // Get the first character of the word
        let firstCharacter = String(word.prefix(1))

        // Check if the first character is a vowel
        let vowels: Set<Character> = ["a", "e", "i", "o", "u"]
        if vowels.contains(firstCharacter.lowercased().first!) {
            // If the first character is a vowel, capitalize the whole word
            capitalizedWords.append(word.capitalized)
        } else {
            // If the first character is a consonant, capitalize only the first letter
            let restOfWord = word.dropFirst()
            capitalizedWords.append(firstCharacter.uppercased() + restOfWord.lowercased())
        }
    }

    // Join the capitalized words back into a sentence
    let capitalizedSentence = capitalizedWords.joined(separator: " ")

    // Capitalize the first letter of the sentence and preserve punctuation marks
    let firstCharacter = capitalizedSentence.prefix(1)
    let restOfSentence = capitalizedSentence.dropFirst()
    let finalSentence = firstCharacter.uppercased() + restOfSentence

    return finalSentence
}
```

