class Queue<QueueElement> {
    private var elements = [QueueElement]()
    private let maxCapacity = 100

    func enqueue(_ element: QueueElement) throws {
        if elements.count >= maxCapacity {
            throw QueueFullException()
        }
        elements.append(element)
    }

    func dequeue() throws -> QueueElement {
        if elements.isEmpty {
            throw QueueEmptyException()
        }
        return elements.removeFirst()
    }

    func isEmpty() -> Bool {
        return elements.isEmpty
    }

    func size() -> Int {
        var count = 0
        for _ in elements {
            count += 1
