To implement an in-place Merge Sort algorithm in C++ without modifying the input array and without using any additional data structures, we can make use of a technique called "bottom-up merge sort". This technique works by merging adjacent subarrays of size 1, then merging adjacent subarrays of size 2, then merging adjacent subarrays of size 4, and so on until the entire array is sorted.

Here's the implementation:

```cpp
#include <iostream>
#include <algorithm>
using namespace std;

// Function to merge two sorted subarrays into one sorted subarray
void merge(int arr[], int left, int mid, int right) {
    int n1 = mid - left + 1;
    int n2 = right - mid;

    int* leftArr = new int[n1];
    int* rightArr = new int[n2];

    for (int i = 0; i < n1; i++)
        leftArr[i] = arr[left + i];
    for (int j = 0; j < n2; j++)
        rightArr[j] = arr[mid + 1 + j];

    int i = 0, j = 0, k = left;
    while (i < n1 && j < n2) {
        if (leftArr[i] <= rightArr[j]) {
            arr[k] = leftArr[i];
            i++;
        }
        else {
            arr[k] = rightArr[j];
            j++;
        }
        k++;
    }

    while (i < n1) {
        arr[k] = leftArr[i];
        i++;
        k++;
    }

    while (j < n2) {
        arr[k] = rightArr[j];
        j++;
        k++;
    }

    delete[] leftArr;
    delete[] rightArr;
}

// Function to perform bottom-up merge sort
void mergeSort(int arr[], int n) {
    for (int currSize = 1; currSize <= n - 1; currSize = 2 * currSize) {
        for (int leftStart = 0; leftStart < n - 1; leftStart += 2 * currSize) {
            int mid = min(leftStart + currSize - 1, n - 1);
            int rightEnd = min(leftStart + 2 * currSize - 1, n - 1);
            merge(arr, leftStart, mid, rightEnd);
        }
    }
}

// Function to print the array
void printArray(int arr[], int n) {
    for (int i = 0; i < n; i++)
        cout << arr[i] << " ";
    cout << endl;
}

// Main function
int main() {
    int arr[] = { 6, 5, 12, 10, 9, 1 };
    int n = sizeof(arr) / sizeof(arr[0]);

    cout << "Original array: ";
    printArray(arr, n);

    mergeSort(arr, n);

    cout << "Sorted array: ";
    printArray(arr, n);

    return 0;
}
```

In this implementation, the `merge` function is used to merge two sorted subarrays into one sorted subarray. The `mergeSort` function performs the bottom-up merge sort by repeatedly merging adjacent subarrays of increasing size. Finally, the `printArray` function is used to print the sorted array.

Note that this implementation does not modify the original array and does not use any additional data structures.

