Here is an example of a C++ program that calculates the Yield to Maturity (YTM) of a bond based on the given requirements:

```cpp
#include <iostream>
#include <cmath>

// Function to calculate the present value of the bond's cash flows
double presentValue(double couponRate, double faceValue, double discountRate, int numPeriods) {
    double presentValue = 0;
    for (int i = 1; i <= numPeriods; i++) {
        double couponPayment = couponRate * faceValue;
        double discountFactor = 1 / pow(1 + discountRate, i);
        presentValue += couponPayment * discountFactor;
    }
    presentValue += faceValue * pow(1 + discountRate, -numPeriods);
    return presentValue;
}

// Function to calculate the YTM using the bisection method
double calculateYTM(double couponRate, double faceValue, double marketPrice, int numPeriods) {
    double left = 0;
    double right = 1;
    double tolerance = 0.00001;

    while (right - left > tolerance) {
        double mid = (left + right) / 2;
        double presentValueMid = presentValue(couponRate, faceValue, mid, numPeriods);

        if (presentValueMid > marketPrice) {
            left = mid;
        } else {
            right = mid;
        }
    }

    return (left + right) / 2;
}

int main() {
    double couponRate, faceValue, marketPrice;
    int numPeriods;

    // Prompt the user to enter necessary inputs
    std::cout << "Enter the coupon rate: ";
    std::cin >> couponRate;
    std::cout << "Enter the face value: ";
    std::cin >> faceValue;
    std::cout << "Enter the market price: ";
    std::cin >> marketPrice;
    std::cout << "Enter the number of periods: ";
    std::cin >> numPeriods;

    // Calculate the YTM
    double ytm = calculateYTM(couponRate, faceValue, marketPrice, numPeriods);

    // Display the calculated YTM
    std::cout << "The Yield to Maturity (YTM) is: " << ytm << std::endl;

    return 0;
}
```

