Below is an example implementation of the program that meets the given requirements. The program is written in Python and uses the `sympy` library for prime number generation and checking.

```python
import sympy
import threading
from multiprocessing import Pool, cpu_count
from tqdm import tqdm

class PrimeNumberGenerator:
    def __init__(self):
        self.prime_cache = {}

    def generate_primes(self, n):
        if n < 2:
            raise ValueError("n must be greater than or equal to 2")

        self.prime_cache = {}
        self.calculate_primes(n)

    def calculate_primes(self, n):
        primes = []
        progress_bar = tqdm(total=n, desc="Calculating primes", unit="number")

        def worker(start, end):
            for num in range(start, end + 1):
                if self.is_prime(num):
                    primes.append(num)
                progress_bar.update(1)

        threads = []
        num_threads = min(cpu_count(), n)
        chunk_size = n // num_threads

        for i in range(num_threads):
            start = i * chunk_size
            end = start + chunk_size - 1 if i != num_threads - 1 else n - 1
            thread = threading.Thread(target=worker, args=(start, end))
            thread.start()
            threads.append(thread)

        for thread in threads:
            thread.join()

        progress_bar.close()
        self.print_primes(primes)
        self.print_sum(primes)

    def is_prime(self, num):
        if num in self.prime_cache:
            return self.prime_cache[num]

        if sympy.isprime(num):
            self.prime_cache[num] = True
            return True

        self.prime_cache[num] = False
        return False

    def print_primes(self, primes):
        print("Prime numbers:")
        for prime in primes:
            print(prime)

    def print_sum(self, primes):
        print("Sum of prime numbers:")
        print(sum(primes))


def main():
    try:
        n = int(input("Enter the value of n: "))
        prime_generator = PrimeNumberGenerator()
        prime_generator.generate_primes(n)
    except ValueError as e:
        print("Invalid input:", e)


if __name__ == "__main__":
    main()
```

