Here's a Node.js code snippet that uses the `http` module to achieve the desired functionality:

```javascript
const http = require('http');
const https = require('https');
const url = require('url');

const targetURL = 'http://example.com';

function getStatusCode(urlString) {
  return new Promise((resolve, reject) => {
    const { protocol, hostname, path } = url.parse(urlString);

    const client = protocol === 'https:' ? https : http;

    const options = {
      hostname,
      path,
      method: 'GET',
    };

    const req = client.request(options, (res) => {
      resolve(res.statusCode);
    });

    req.on('error', (err) => {
      reject(err);
    });

    req.end();
  });
}

function extractHyperlinks(html) {
  const regex = /<a[^>]+href=["'](.*?)["']/g;
  const hyperlinks = [];

  let match;
  while ((match = regex.exec(html)) !== null) {
    hyperlinks.push(match[1]);
  }

  return hyperlinks;
}

function calculateAverageResponseTime(urls) {
  const promises = urls.map((url) => {
    return new Promise((resolve, reject) => {
      const startTime = Date.now();

      getStatusCode(url)
        .then(() => {
          const endTime = Date.now();
          const responseTime = endTime - startTime;
          resolve(responseTime);
        })
        .catch(reject);
    });
  });

  return Promise.all(promises).then((responseTimes) => {
    const sum = responseTimes.reduce((acc, time) => acc + time, 0);
    return sum / responseTimes.length;
  });
}

// Main function
getStatusCode(targetURL)
  .then((statusCode) => {
    console.log('Response status code:', statusCode);

    if (statusCode === 200) {
      return new Promise((resolve, reject) => {
        const req = http.get(targetURL, (res) => {
          let html = '';
          res.on('data', (chunk) => {
            html += chunk;
          });

          res.on('end', () => {
            const hyperlinks = extractHyperlinks(html);
            resolve(hyperlinks);
          });
        });

        req.on('error', reject);
      });
    } else {
      throw new Error('Invalid response status code');
    }
  })
  .then((hyperlinks) => {
    console.log('Hyperlinks:', hyperlinks);

    return calculateAverageResponseTime(hyperlinks);
  })
  .then((averageResponseTime) => {
    console.log('Average response time:', averageResponseTime, 'ms');
  })
  .catch((error) => {
    console.error('Error:', error.message);
  });
```

