import java.util.Scanner;

public class PyramidPattern {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Step 1: Prompt the user to enter a positive odd integer N
        System.out.print("Enter the number of rows (N): ");
        int N = scanner.nextInt();

        // Step 2: Validate the input to ensure that N is a positive odd integer
        while (N <= 0 || N % 2 == 0) {
            System.out.println("Invalid input. Please enter a positive odd integer.");
            System.out.print("Enter the number of rows (N): ");
            N = scanner.nextInt();
        }

        // Step 3: Initialize the variable to keep track of the number of spaces
        int spaces = (N - 1) / 2;

        // Step 4: Iterate over the rows of the pattern
        for (int row = 1; row <= N; row++) {

            // Step 5: Iterate over the columns of each row
            for (int col = 1; col <= (2 * N - 1); col++) {

                // Step 6: Check the condition to print asterisk or space
                if (col >= (spaces + 1) && col <= (2 * row - 1 - spaces)) {
                    System.out.print("*");
                } else {
                    System.out.print(" ");
                }
            }

            // Step 7: Move to the next line
            System.out.println();

            // Step 8: Update the number of spaces for the next row
            spaces--;
        }

        scanner.close();
    }
}
