    return;
  }

  // Check for Firefox version 3 or lower
  var firefoxMatch = userAgent.match(/Firefox\/(\d+)/);
  if (firefoxMatch && parseInt(firefoxMatch[1]) <= 3) {
    displayErrorMessage("Your version of Firefox is outdated. Please update to the latest version.");
    return;
  }

  // Check for Safari version 5 or lower
  var safariMatch = userAgent.match(/Version\/(\d+)/);
  if (safariMatch && parseInt(safariMatch[1]) <= 5) {
    displayErrorMessage("Your version of Safari is outdated. Please update to the latest version.");
    return;
  }

  // Check for Chrome version 30 or lower
