function findObjectWithMostProperties(obj) {
  let maxProperties = 0;
  let maxObject = null;

  const visited = new WeakSet();

  function countProperties(object) {
    if (visited.has(object)) {
      return 0;
    }
    visited.add(object);

    let count = 0;

    for (let key in object) {
      if (object.hasOwnProperty(key) && !isIgnoredValue(object[key])) {
        count++;
        if (isObjectOrArray(object[key])) {
          count += countProperties(object[key]);
        }
      }
    }

    return count;
  }

  function isIgnoredValue(value) {
    return value === null || value === undefined || value === "";
  }

  function isObjectOrArray(value) {
    return typeof value === "object" && !Array.isArray(value);
  }

  function findLargestObject(object) {
    const keys = Object.keys(object);
    for (let i = 0; i < keys.length; i++) {
      const key = keys[i];
      const value = object[key];
      if (isObjectOrArray(value)) {
        const propertyCount = countProperties(value);
        if (propertyCount > maxProperties) {
          maxProperties = propertyCount;
          maxObject = value;
        }
        findLargestObject(value);
      }
    }
  }

  findLargestObject(obj);

  return maxObject;
}

