```javascript
const http = require('http');
const url = require('url');
const fs = require('fs');
const { v4: uuidv4 } = require('uuid');

// Rate Limiting
const MAX_REQUESTS_PER_MINUTE = 100;
const requests = {};
setInterval(() => {
  for (const key in requests) {
    if (requests[key].timestamp < Date.now() - 60000) {
      delete requests[key];
    }
  }
}, 60000);

// Authentication
const users = {};

// Logging
const logStream = fs.createWriteStream('access.log', { flags: 'a' });

const server = http.createServer((req, res) => {
  // Log request
  const timestamp = new Date().toISOString();
  logStream.write(`[${timestamp}] ${req.method} ${req.url}\n`);

  // Rate Limiting
  const ip = req.connection.remoteAddress;
  if (requests[ip] && requests[ip].count >= MAX_REQUESTS_PER_MINUTE) {
    res.statusCode = 429; // Too Many Requests
    return res.end('Rate limit exceeded');
  }
  if (!requests[ip]) {
    requests[ip] = {
      count: 0,
      timestamp: Date.now()
    };
  }
  requests[ip].count++;

  // Authentication
  const authHeader = req.headers['authorization'];
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.statusCode = 401; // Unauthorized
    return res.end('Invalid or missing token');
  }
  const token = authHeader.substring(7);
  const user = Object.values(users).find(u => u.token === token);
  if (!user || user.expiry < Date.now()) {
    res.statusCode = 401; // Unauthorized
    return res.end('Invalid or expired token');
  }

  const reqUrl = url.parse(req.url, true);
  if (req.method !== 'GET') {
    res.statusCode = 405; // Method Not Allowed
    return res.end('Only GET requests are allowed');
  }

  if (reqUrl.pathname !== '/') {
    res.statusCode = 404; // Not Found
    return res.end('Invalid URL');
  }

  res.setHeader('Content-Type', 'text/plain');
  res.statusCode = 200;
  res.end('Hello, World!');
});

// Start the server
const PORT = 3000;
server.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});

