Here's a recursive method in Java to print all the prime numbers up to n:

```java
public class PrimeNumbersRecursive {

    public static void printPrimes(int n) {
        printPrimesHelper(n, 2);
    }

    private static void printPrimesHelper(int n, int num) {
        if (num <= n) {
            if (isPrime(num)) {
                System.out.println(num);
            }
            printPrimesHelper(n, num + 1);
        }
    }

    private static boolean isPrime(int num) {
        if (num <= 1) {
            return false;
        }
        return isPrimeHelper(num, 2);
    }

    private static boolean isPrimeHelper(int num, int divisor) {
        if (divisor > Math.sqrt(num)) {
            return true;
        }
        if (num % divisor == 0) {
            return false;
        }
        return isPrimeHelper(num, divisor + 1);
    }

    public static void main(String[] args) {
        int n = 20;
        System.out.println("Prime numbers up to " + n + ":");
        printPrimes(n);
    }
}
