# Recursive function to compute the sum
recursive_sum <- function(lst, index = 1, total = 0) {
  # Base case: if index exceeds the length of the list, return the total
  if (index > length(lst)) {
    return(total)
  }

  # Recursive case: add the element to the total if it's non-negative, and call the function with the next index
  if (lst[index] >= 0) {
    total <- total + lst[index]
  }
  total <- recursive_sum(lst, index + 1, total)

  # Return the updated total
  return(total)
}

