    public static int findElementIndex(int[] array, int searchElement) {
        int low = 0;
        int high = array.length - 1;

        while (low <= high) {
            int mid = (low + high) / 2;

            if (array[mid] == searchElement) {
                return mid;
            } else if (array[mid] < searchElement) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        return -1;
    }
