        return math.sqrt(dx**2 + dy**2)

    def midpoint(self, other):
        mx = (self.x + other.x) / 2
        my = (self.y + other.y) / 2
        return Point(mx, my)

    def is_inside_rectangle(self, top_left, bottom_right):
        if top_left.x <= self.x <= bottom_right.x and bottom_right.y <= self.y <= top_left.y:
            return True
        return False

    def is_inside_circle(self, center, radius):
        dx = self.x - center.x
        dy = self.y - center.y
        distance_squared = dx**2 + dy**2
        if distance_squared <= radius**2:
            return True
        return False

    def rotate(self, angle):
        rad_angle = math.radians(angle)
        new_x = self.x * math.cos(rad_angle) - self.y * math.sin(rad_angle)
        new_y = self.x * math.sin(rad_angle) + self.y * math.cos(rad_angle)
        return Point(new_x, new_y)

    def reflection(self, line_point1, line_point2):
        dx = line_point2.x - line_point1.x
        dy = line_point2.y - line_point1.y
        distance_squared = dx**2 + dy**2
        u = ((self.x - line_point1.x) * dx + (self.y - line_point1.y) * dy) / distance_squared
        ref_x = line_point1.x + u * dx
        ref_y = line_point1.y + u * dy
        return Point(2 * ref_x - self.x, 2 * ref_y - self.y)

    def is_on_line(self, line_point1, line_point2):
        dx = line_point2.x - line_point1.x
        dy = line_point2.y - line_point1.y
        distance_squared = dx**2 + dy**2
        u = ((self.x - line_point1.x) * dx + (self.y - line_point1.y) * dy) / distance_squared
        if 0 <= u <= 1:
            return True
        return False

    def is_collinear(self, point1, point2):
        return (point2.y - point1.y) * (self.x - point1.x) == (self.y - point1.y) * (point2.x - point1.x)

    def slope_to_point(self, other):
        if self.x == other.x:
            return float('inf')
        return (other.y - self.y) / (other.x - self.x)

    def closest_point_on_line(self, line_point1, line_point2):
        dx = line_point2.x - line_point1.x
        dy = line_point2.y - line_point1.y
        distance_squared = dx**2 + dy**2
        u = ((self.x - line_point1.x) * dx + (self.y - line_point1.y) * dy) / distance_squared
        closest_x = line_point1.x + u * dx
        closest_y = line_point1.y + u * dy
        return Point(closest_x, closest_y)
```

This implementation provides the required functionality and handles edge cases appropriately. Note that for certain methods (e.g., `is_inside_rectangle`, `is_inside_circle`, `reflection`), it is assumed that the rectangle and circle are axis-aligned, meaning they are not rotated. If rotation is required, additional calculations would need to be implemented.

Additionally, for some methods (e.g., `is_on_line`, `is_collinear`, `closest_point_on_line`), it is assumed that the line is defined by two distinct points. If the line is defined differently, additional checks or modifications may be needed.

