import math

def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        if n % i == 0:
            return False
    return True

def generate_fibonacci(n):
    sequence = [0, 1]
    while len(sequence) < n:
        next_num = sequence[-1] + sequence[-2]
        sequence.append(next_num)
    return sequence

def sum_primes(start, end):
    primes = []
    current_number = start
    while len(primes) < 5:
        if is_prime(current_number):
            primes.append(current_number)
        current_number += 1
    return sum(primes)

start_num = 10
end_num = 100
prime_sum = sum_primes(start_num, end_num)
fibonacci_sequence = generate_fibonacci(prime_sum)

print(f"The Fibonacci sequence up to the sum of the first 5 prime numbers between {start_num} and {end_num} is:")
print(fibonacci_sequence)
```

When you run the script, it will output the Fibonacci sequence up to the sum of the first 5 prime numbers between 10 and 100.

