Here is an implementation of a generic Binary Search Tree in Swift:

```swift
class Node<T: Comparable> {
    var value: T
    var left: Node?
    var right: Node?

    init(value: T) {
        self.value = value
        self.left = nil
        self.right = nil
    }
}

class BinarySearchTree<T: Comparable> {
    var root: Node<T>?

    // Insert a value into the tree
    func insert(value: T) {
        let newNode = Node(value: value)

        if let root = root {
            insertHelper(node: root, newNode: newNode)
        } else {
            root = newNode
        }
    }

    private func insertHelper(node: Node<T>, newNode: Node<T>) {
        if newNode.value < node.value {
            if let left = node.left {
                insertHelper(node: left, newNode: newNode)
            } else {
                node.left = newNode
            }
        } else {
            if let right = node.right {
                insertHelper(node: right, newNode: newNode)
            } else {
                node.right = newNode
            }
        }
    }

    // Delete a value from the tree
    func delete(value: T) {
        root = deleteHelper(node: root, value: value)
    }

    private func deleteHelper(node: Node<T>?, value: T) -> Node<T>? {
        guard let node = node else { return nil }

        if value < node.value {
            node.left = deleteHelper(node: node.left, value: value)
        } else if value > node.value {
            node.right = deleteHelper(node: node.right, value: value)
        } else {
            // Case 1: No child or one child
            if node.left == nil {
                return node.right
            } else if node.right == nil {
                return node.left
            }

            // Case 2: Two children
            let minValue = findMinValue(node: node.right!)
            node.value = minValue
            node.right = deleteHelper(node: node.right, value: minValue)
        }

        return node
    }

    private func findMinValue(node: Node<T>) -> T {
        var current = node
        while let left = current.left {
            current = left
        }
        return current.value
    }

    // Search for a value in the tree
    func search(value: T) -> Bool {
        return searchHelper(node: root, value: value)
    }

    private func searchHelper(node: Node<T>?, value: T) -> Bool {
        guard let node = node else { return false }

        if value == node.value {
            return true
        } else if value < node.value {
            return searchHelper(node: node.left, value: value)
        } else {
            return searchHelper(node: node.right, value: value)
        }
    }

    // Traverse the tree in-order and print the values
    func printInOrder() {
        printInOrderHelper(node: root)
    }

    private func printInOrderHelper(node: Node<T>?) {
        guard let node = node else { return }

        printInOrderHelper(node: node.left)
        print(node.value)
        printInOrderHelper(node: node.right)
    }
}
```

