```python
def is_valid_email(email):
    if len(email) < 6:
        return False
    if email[0] == '.' or email[0] == '@':
        return False
    if email[-1] == '.' or email[-1] == '@':
        return False
    if '@@' in email or '..' in email:
        return False
    if email.count('@') != 1 or email.count('.') < 1:
        return False

    atIndex = email.find('@')
    dotIndex = email.find('.')

    if atIndex < 1 or dotIndex < atIndex + 2:
        return False

    for char in email:
        if not (char.isalpha() or char == '.' or char == '@'):
            return False

    return True

