```javascript
const axios = require('axios');

async function fetchData(type, startDate, endDate, token) {
  const endpoint = 'www.example.com/api/v1/data';

  const params = {
    type: type
  };

  const headers = {
    Authorization: token
  };

  const data = {
    filters: {
      startDate: startDate,
      endDate: endDate
    }
  };

  try {
    let retryCount = 0;
    let maxRetries = 3;

    while (retryCount < maxRetries) {
      try {
        let response = await axios.get(endpoint, {
          params: params,
          headers: headers,
          data: data
        });

        // Print the response data in a structured format
        console.table(response.data);
        break; // Exit the loop if successful
      } catch (error) {
        if (error.response && error.response.status === 429) {
          // Rate limit exceeded, wait for 1 second and retry
          await sleep(1000);
          retryCount++;
        } else {
          if (error.response) {
            // The request was made and the server responded with an error status code
            console.error('Error:', error.response.data);
          } else if (error.request) {
            // The request was made but no response was received
            console.error('Error:', error.request);
          } else {
            // Something happened in setting up the request that triggered an Error
            console.error('Error:', error.message);
          }
          break; // Exit the loop if an error occurred
        }
      }
    }

    if (retryCount >= maxRetries) {
      console.error('Rate limit exceeded. Retry limit reached.');
    }
  } catch (error) {
    console.error('Error:', error);
  }
}

