import sqlite3

def execute_sql_query(query):
    try:
        connection = sqlite3.connect(":memory:")
        cursor = connection.cursor()

        cursor.execute(query)

        if query.lower().startswith("select"):
            columns = [description[0] for description in cursor.description]
            rows = cursor.fetchall()
            print_tabular_data(columns, rows)
        elif query.lower().startswith("insert") or query.lower().startswith("update") or query.lower().startswith("delete"):
            print("Operation executed successfully.")
        elif query.lower().startswith("create table"):
            print("Table created successfully.")
        elif query.lower().startswith("drop table"):
            confirmation = input("Are you sure you want to drop the table(s)? (yes/no): ")
            if confirmation.lower() == "yes":
                print("Table(s) dropped successfully.")
            else:
                print("Operation canceled.")
        else:
            print("Invalid SQL query.")

    except sqlite3.Error as error:
        print("Error executing SQL query:", error)

    finally:
        if cursor:
            cursor.close()
        if connection:
            connection.close()

def print_tabular_data(columns, rows):
    max_column_widths = [len(column) for column in columns]
    for row in rows:
        for i, value in enumerate(row):
            max_column_widths[i] = max(max_column_widths[i], len(str(value)))

    print_row_separator(max_column_widths)
    print_row(columns, max_column_widths)
    print_row_separator(max_column_widths)

    for row in rows:
        print_row(row, max_column_widths)

    print_row_separator(max_column_widths)

def print_row_separator(column_widths):
    for width in column_widths:
        print("+" + "-" * (width + 2), end="")
    print("+")

def print_row(values, column_widths):
    for value, width in zip(values, column_widths):
        print("|", str(value).ljust(width), end=" ")
    print("|")

# Example usage
query = "SELECT columnA, columnB FROM tableA JOIN (SELECT columnC FROM tableC WHERE columnD > 10) AS subquery ON tableA.id = subquery.id"
execute_sql_query(query)
```

