import java.util.Arrays;

public class SecondMaxMinInArray {
    public static void main(String[] args) {
        int[] array = {5, 2, 7, 2, 9, 1, 5, 9, 8};

        int secondMax = findSecondMax(array);
        int secondMin = findSecondMin(array);

        if (secondMax != Integer.MIN_VALUE && secondMin != Integer.MAX_VALUE) {
            System.out.println("Second Maximum: " + secondMax);
            System.out.println("Second Minimum: " + secondMin);
        } else {
            System.out.println("Error: Not enough elements in the array.");
        }
    }

    public static int findSecondMax(int[] array) {
        int max = Integer.MIN_VALUE;
        int secondMax = Integer.MIN_VALUE;

        for (int num : array) {
            if (num > max) {
                secondMax = max;
                max = num;
            } else if (num > secondMax && num != max) {
                secondMax = num;
            }
        }

        return secondMax;
    }

    public static int findSecondMin(int[] array) {
        int min = Integer.MAX_VALUE;
        int secondMin = Integer.MAX_VALUE;

        for (int num : array) {
            if (num < min) {
                secondMin = min;
                min = num;
            } else if (num < secondMin && num != min) {
                secondMin = num;
            }
        }

        return secondMin;
    }
}
