Create a file named `server.js` and add the following code:

```javascript
const express = require('express');
const moment = require('moment-timezone');
const mongoose = require('mongoose');

const app = express();
const port = 3000;

// Connect to MongoDB
mongoose.connect('mongodb://localhost:27017/tasks', {
  useNewUrlParser: true,
  useUnifiedTopology: true
}).then(() => {
  console.log('Connected to MongoDB');
}).catch((error) => {
  console.log('Error connecting to MongoDB:', error);
});

// Create a task schema
const taskSchema = new mongoose.Schema({
  name: String,
  description: String,
  dueDate: Date,
  priority: String
});

// Create a task model
const Task = mongoose.model('Task', taskSchema);

// Serve static HTML page
app.use(express.static('public'));

// Display current time in a specific timezone
app.get('/time/:timezone', (req, res) => {
  const timezone = req.params.timezone;
  const time = moment().tz(timezone).format('YYYY-MM-DD HH:mm:ss');

  res.send(`Current time in ${timezone}: ${time}`);
});

// Create a new task
app.post('/tasks', (req, res) => {
  const task = new Task({
    name: req.body.name,
    description: req.body.description,
    dueDate: req.body.dueDate,
    priority: req.body.priority
  });

  task.save().then(() => {
    res.status(201).send('Task created successfully');
  }).catch((error) => {
    res.status(500).send('Error creating task:', error);
  });
});

// Retrieve all tasks
app.get('/tasks', (req, res) => {
  Task.find().then((tasks) => {
    res.send(tasks);
  }).catch((error) => {
    res.status(500).send('Error retrieving tasks:', error);
  });
});

app.listen(port, () => {
  console.log(`Server listening on port ${port}`);
});
```

