def flatten_dictionary(d):
    def flatten_helper(item, prefix=''):
        if isinstance(item, dict):
            flattened_dict = {}
            for key, value in item.items():
                new_key = prefix + key if prefix else key
                flattened_dict.update(flatten_helper(value, new_key + '_'))
