```java
import java.math.BigDecimal;
import java.math.MathContext;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.List;

public class ScientificCalculator {
    private List<String> history;

    public ScientificCalculator() {
        history = new ArrayList<>();
    }

    public void add(double num1, double num2) {
        BigDecimal result = BigDecimal.valueOf(num1).add(BigDecimal.valueOf(num2));
        addToHistory(num1 + " + " + num2 + " = " + result);
    }

    public void subtract(double num1, double num2) {
        BigDecimal result = BigDecimal.valueOf(num1).subtract(BigDecimal.valueOf(num2));
        addToHistory(num1 + " - " + num2 + " = " + result);
    }

    public void multiply(double num1, double num2) {
        BigDecimal result = BigDecimal.valueOf(num1).multiply(BigDecimal.valueOf(num2));
        addToHistory(num1 + " * " + num2 + " = " + result);
    }

    public void divide(double num1, double num2) {
        if (num2 == 0) {
            System.out.println("Error: Division by zero");
            return;
        }

        BigDecimal result = BigDecimal.valueOf(num1).divide(BigDecimal.valueOf(num2), MathContext.DECIMAL50);
        addToHistory(num1 + " / " + num2 + " = " + result);
    }

    public void squareRoot(double num) {
        if (num < 0) {
            System.out.println("Error: Square root of a negative number");
            return;
        }

        BigDecimal result = BigDecimal.valueOf(Math.sqrt(num)).setScale(50, RoundingMode.HALF_UP);
        addToHistory("√" + num + " = " + result);
    }

    public void logarithm(double num) {
        if (num <= 0) {
            System.out.println("Error: Logarithm of a non-positive number");
            return;
        }

        BigDecimal result = BigDecimal.valueOf(Math.log(num)).setScale(50, RoundingMode.HALF_UP);
        addToHistory("log(" + num + ") = " + result);
    }

    public void exponentiation(double base, double exponent) {
        BigDecimal result = BigDecimal.valueOf(Math.pow(base, exponent)).setScale(50, RoundingMode.HALF_UP);
        addToHistory(base + "^" + exponent + " = " + result);
    }

    public void factorial(int num) {
        if (num < 0) {
            System.out.println("Error: Factorial of a negative number");
            return;
        }

        BigDecimal result = BigDecimal.ONE;
        for (int i = 1; i <= num; i++) {
            result = result.multiply(BigDecimal.valueOf(i));
        }

        addToHistory(num + "! = " + result);
    }

    public void addToHistory(String calculation) {
        history.add(calculation);
    }

    public List<String> getHistory() {
        return history;
    }

    public static void main(String[] args) {
        ScientificCalculator calculator = new ScientificCalculator();
        calculator.add(2, 3);
        calculator.subtract(5, 2);
        calculator.multiply(4, 5);
        calculator.divide(10, 3);
        calculator.squareRoot(25);
        calculator.logarithm(10);
        calculator.exponentiation(2, 4);
        calculator.factorial(5);

        List<String> history = calculator.getHistory();
        for (String calculation : history) {
            System.out.println(calculation);
        }
    }
}
```

In this implementation, the `ScientificCalculator` class contains methods for each mathematical operation, such as `add`, `subtract`, `multiply`, `divide`, `squareRoot`, `logarithm`, `exponentiation`, and `factorial`. These methods use `BigDecimal` to handle arbitrary precision arithmetic and ensure accurate results.

The `addToHistory` method adds a calculation to the history list, and the `getHistory` method returns the entire history.

The `main` method demonstrates how to use the `ScientificCalculator` class by performing several calculations and printing the history.

