```swift
func removeDuplicates(_ nums: inout [Int]) -> [Int] {
    var index = 0
    while index < nums.count {
        var currentIndex = index + 1
        while currentIndex < nums.count {
            if nums[currentIndex] == nums[index] {
                nums.remove(at: currentIndex)
            } else {
                currentIndex += 1
            }
        }
        index += 1
    }
    return nums
}

