function findTwoLargestPrimes(numbers) {
  // Filter out negative numbers, decimal numbers, and duplicates
  const primes = numbers.filter(number => number > 1 && Number.isInteger(number) && Number.isSafeInteger(number))
                        .filter((number, index, array) => array.indexOf(number) === index);

  // Sort the prime numbers in descending order
  primes.sort((a, b) => b - a);

  // Return the two largest prime numbers or an empty array if there are less than two prime numbers
  return primes.slice(0, 2);
}
