using namespace std;

// Function to generate a random array of integers within a specified range
vector<int> generateRandomArray(int size, int minRange, int maxRange) {
    vector<int> arr(size);

    // Seed the random number generator
    srand(time(NULL));

    // Generate random integers within the specified range
    for (int i = 0; i < size; i++) {
        arr[i] = rand() % (maxRange - minRange + 1) + minRange;
    }

    return arr;
}

// Function to calculate the average of the elements in the sorted array
double calculateAverage(vector<int>& arr) {
    int sum = 0;
    int size = arr.size();

    // Calculate the sum of the elements
    for (int i = 0; i < size; i++) {
        sum += arr[i];
    }

    // Calculate the average
    double average = static_cast<double>(sum) / size;

    return average;
}

// Function to swap two elements in the array
void swap(int& a, int& b) {
    int temp = a;
    a = b;
    b = temp;
}

// Function to perform selection sort in descending order
void selectionSort(vector<int>& arr) {
    int size = arr.size();

    for (int i = 0; i < size - 1; i++) {
        int maxIndex = i;

        // Find the index of the maximum element in the remaining unsorted array
        for (int j = i + 1; j < size; j++) {
            if (arr[j] > arr[maxIndex]) {
                maxIndex = j;
            }
        }

        // Swap the maximum element with the current element
        swap(arr[i], arr[maxIndex]);
    }
}

