import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class CombinationFinder {
    public static void main(String[] args) {
        int[] array = {2, 7, 3, 5, 4, 1, 2, 7, 3, 5, 4, 1};
        int sum = 12;

        List<List<Integer>> combinations = findCombinations(array, sum);
        int uniqueCombinations = combinations.size();

        System.out.println("Unique Combinations: " + uniqueCombinations);
        System.out.println("Combinations: " + combinations);
    }

    public static List<List<Integer>> findCombinations(int[] array, int sum) {
        List<List<Integer>> combinations = new ArrayList<>();
        Set<List<Integer>> uniqueCombinations = new HashSet<>();

        Arrays.sort(array); // Sort the array to handle duplicate numbers

        for (int i = 0; i < array.length - 2; i++) {
            int left = i + 1;
            int right = array.length - 1;

            while (left < right) {
                int currentSum = array[i] + array[left] + array[right];

                if (currentSum == sum) {
                    List<Integer> combination = Arrays.asList(array[i], array[left], array[right]);

                    if (uniqueCombinations.add(combination)) {
                        combinations.add(combination);
                    }

                    left++;
                    right--;
                } else if (currentSum < sum) {
                    left++;
                } else {
                    right--;
                }
            }
        }

        return combinations;
    }
}

def max_sum_path(matrix):
