        Scanner input = new Scanner(System.in);

        System.out.print("Enter conversion type (1 for miles to kilometers, 2 for kilometers to miles): ");
        int conversionType = input.nextInt();

        if (conversionType == 1) {
            System.out.print("Enter distance value: ");
            double distance = input.nextDouble();
            double kilometers = milesToKilometers(distance);

            if (kilometers != -1) {
                System.out.printf("%.2f miles is equal to %.2f kilometers.", distance, kilometers);
            } else {
                System.out.println("Invalid distance value entered.");
            }
        } else if (conversionType == 2) {
            System.out.print("Enter distance value: ");
            double distance = input.nextDouble();
            double miles = kilometersToMiles(distance);

            if (miles != -1) {
                System.out.printf("%.2f kilometers is equal to %.2f miles.", distance, miles);
            } else {
                System.out.println("Invalid distance value entered.");
            }
        } else {
            System.out.println("Invalid conversion type entered.");
        }

        input.close();
    }

