        if (miles >= 0) {
            return miles * 1.60934;
        } else {
            return -1;
        }
    }

    public static double kilometersToMiles(double kilometers) {
        if (kilometers >= 0) {
            return kilometers / 1.60934;
        } else {
            return -1;
        }
    }
}

