function getMostFrequentWords(str) {
  // Remove leading and trailing punctuation, and convert to lowercase
  const words = str.toLowerCase().replace(/[^a-zA-Z0-9 ]/g, '').split(' ');

  // Stop words to exclude from the word count
  const stopWords = ['the', 'and', 'is', 'etc.'];

  // Word count object to store the frequency of each word
  const wordCount = {};

  // Count the frequency of each word
  for (let word of words) {
    // Exclude stop words and empty words
    if (word.length > 0 && !stopWords.includes(word)) {
      wordCount[word] = (wordCount[word] || 0) + 1;
    }
  }

  // Convert the word count object to an array of [word, frequency] pairs
  const wordCountArray = Object.entries(wordCount);

  // Sort the word count array based on frequency (descending) and word (ascending)
  wordCountArray.sort((a, b) => {
    if (a[1] === b[1]) {
      return a[0].localeCompare(b[0]);
    } else {
      return b[1] - a[1];
    }
  });

  // Extract only the words from the sorted word count array
  const mostFrequentWords = wordCountArray.map(([word, _]) => word);

  return mostFrequentWords;
}

// Example usage
const str = "The quick brown fox jumps over the lazy dog. The quick brown fox is a very fast animal.";
