function isPrime(num) {
  // Check if the number is less than 2
  if (num < 2) {
    return false;
  }

  // Check for divisibility from 2 to sqrt(num)
  for (let i = 2; i <= Math.sqrt(num); i++) {
    if (num % i === 0) {
      return false;
    }
  }

  return true;
}

// Function to generate a random prime number between 100 and 1000
function generateRandomPrime() {
  let randomNum;

  // Generate a random number between 100 and 1000
  do {
    randomNum = Math.floor(Math.random() * (1000 - 100 + 1)) + 100;
  } while (!isPrime(randomNum));

  return randomNum;
}

