NSArray* findPrimes(int start, int end) {
    NSMutableArray *primes = [[NSMutableArray alloc] init];
    for (int i = end; i >= start; i--) {
        if (isPrime(i)) {
            [primes addObject:@(i)];
        }
    }
    return [primes sortedArrayUsingComparator:^NSComparisonResult(id a, id b) {
        return [b compare:a];
    }];
}

int main(int argc, const char * argv[]) {
