        int start = 1;
        int end = 100;

        NSArray *primeNumbers = findPrimes(start, end);

        NSLog(@"Prime numbers between %d and %d in descending order:", start, end);
        for (NSNumber *prime in primeNumbers) {
            NSLog(@"%@", prime);
        }
    }
    return 0;
}
