To calculate the maximum depth of the binary search tree, we need to traverse the tree and keep track of the current level. We can use a recursive approach to do this.

Here is the C++ code to calculate the maximum depth:

```cpp
#include <iostream>
#include <algorithm>
using namespace std;

// Definition of a tree node
struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

int maxDepth(TreeNode* root, int level) {
    // Base case: empty tree
    if (root == nullptr) {
        return level - 1;
    }

    // Check if the current level and node value satisfy the condition
    if ((level % 2 == 0 && root->val % 2 != 0) ||
        (level % 2 != 0 && root->val % 2 == 0)) {
        return -1;  // Invalid condition, return -1
    }

    // Recursively calculate the maximum depth of the left and right subtrees
    int leftDepth = maxDepth(root->left, level + 1);
    int rightDepth = maxDepth(root->right, level + 1);

    // Return the maximum depth among the left and right subtrees
    return max(leftDepth, rightDepth);
}

int main() {
    // Create the binary search tree
    TreeNode* root = new TreeNode(3);
    root->left = new TreeNode(2);
    root->right = new TreeNode(7);
    root->left->left = new TreeNode(1);
    root->left->right = new TreeNode(5);
    root->right->left = new TreeNode(6);
    root->right->right = new TreeNode(8);

    // Calculate the maximum depth
    int maxDepth = maxDepth(root, 1);

    cout << "Maximum depth: " << maxDepth << endl;

    return 0;
}
```

