def parse_json(json_string):
    stack = []
    current_object = {}
    current_key = ''
    current_value = ''

    for char in json_string:
        if char == '{':
            stack.append(current_object)
            current_object[current_key] = {}
            current_object = current_object[current_key]
            current_key = ''
            current_value = ''
        elif char == '[':
            stack.append(current_object)
            current_object[current_key] = []
            current_object = current_object[current_key]
            current_key = ''
            current_value = ''
        elif char == '}':
            if current_key:
                current_object[current_key] = current_value
                current_key = ''
                current_value = ''
            current_object = stack.pop()
        elif char == ']':
            if current_key:
                current_object[current_key] = current_value
                current_key = ''
                current_value = ''
            current_object = stack.pop()
        elif char == ',':
            if current_key:
                current_object[current_key] = current_value
                current_key = ''
                current_value = ''
        elif char == ':':
            current_key = current_value
            current_value = ''
        else:
            current_value += char

    for key, value in current_object.items():
        print_json(key, value, 0)


def print_json(key, value, indent):
    if isinstance(value, dict):
        print(' ' * indent + key + ':')
        for inner_key, inner_value in value.items():
            print_json(inner_key, inner_value, indent + 4)
    elif isinstance(value, list):
        print(' ' * indent + key + ':')
        for item in value:
            if isinstance(item, dict):
                for inner_key, inner_value in item.items():
                    print_json(inner_key, inner_value, indent + 4)
            else:
                print(' ' * (indent + 4) + item)
    else:
        print(' ' * indent + key + ': ' + value)


