```javascript
// Define global variables
let data = []; // Array to store the fetched data
let filteredData = []; // Array to store the filtered data
let currentPage = 1; // Current page number

// Fetch data from the API endpoint
function fetchData() {
    fetch('api-endpoint-url')
        .then(response => response.json())
        .then(json => {
            data = json;
            filteredData = data;
            renderTable();
        })
        .catch(error => console.log(error));
}

// Render the table based on the current data and page number
function renderTable() {
    const tableBody = document.getElementById('table-body');
    const rowsPerPage = 10;
    const startIndex = (currentPage - 1) * rowsPerPage;
    const endIndex = startIndex + rowsPerPage;
    const paginatedData = filteredData.slice(startIndex, endIndex);

    // Clear the table body
    tableBody.innerHTML = '';

    // Render the table rows
    for (let i = 0; i < paginatedData.length; i++) {
        const row = document.createElement('tr');
        row.innerHTML = `
            <td>${paginatedData[i].id}</td>
            <td>${paginatedData[i].first_name}</td>
            <td>${paginatedData[i].last_name}</td>
        `;
        tableBody.appendChild(row);
    }

    // Update the row count and current page number
    document.getElementById('row-count').textContent = `Total rows: ${filteredData.length}`;
    document.getElementById('current-page').textContent = currentPage;
}

// Sort the data based on the selected column
function sortData(column) {
    filteredData.sort((a, b) => {
        const valueA = a[column].toLowerCase();
        const valueB = b[column].toLowerCase();

        if (valueA < valueB) {
            return -1;
        }
        if (valueA > valueB) {
            return 1;
        }
        return 0;
    });

    renderTable();
}

// Filter the data based on the input values
function filterTable() {
    const idFilter = document.getElementById('id-filter').value.toLowerCase();
    const firstNameFilter = document.getElementById('first-name-filter').value.toLowerCase();
    const lastNameFilter = document.getElementById('last-name-filter').value.toLowerCase();

    filteredData = data.filter(row => {
        return row.id.toLowerCase().includes(idFilter) &&
            row.first_name.toLowerCase().includes(firstNameFilter) &&
            row.last_name.toLowerCase().includes(lastNameFilter);
    });

    renderTable();
}

// Go to the previous page
function previousPage() {
    if (currentPage > 1) {
        currentPage--;
        renderTable();
    }
}

// Go to the next page
function nextPage() {
    const totalPages = Math.ceil(filteredData.length / 10);
    if (currentPage < totalPages) {
        currentPage++;
        renderTable();
    }
}

// Fetch data and initialize the table
fetchData();
```

4. Replace `'api-endpoint-url'` in the `fetchData` function with the actual API endpoint from which you want to fetch the data.

Make sure to update the API endpoint URL and customize the sorting and filtering logic according to your specific requirements.

That's it! You have now created a web application with an interactive table that allows users to sort, filter, and paginate the data.

