```java
public class ConcatenateStringWithInteger {

    public static String concatenate(int number, String text) {
        // Check if number is positive and less than 1000
        if (number <= 0 || number >= 1000) {
            throw new IllegalArgumentException("Number must be positive and less than 1000.");
        }

        // Check if number contains any digit more than once
        if (!hasUniqueDigits(number)) {
            throw new IllegalArgumentException("Number must not contain any digit more than once.");
        }

        // Concatenate the number and text
        return number + text;
    }

    private static boolean hasUniqueDigits(int number) {
        String numString = String.valueOf(number);
        int[] count = new int[10]; // Array to keep count of each digit

        // Iterate over each digit in the number
        for (char digit : numString.toCharArray()) {
            int num = Character.getNumericValue(digit);
            count[num]++;

            // If count of any digit is more than 1, return false
            if (count[num] > 1) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        int number = 123;
        String text = "Hello";

        try {
            String result = concatenate(number, text);
            System.out.println(result);
        } catch (IllegalArgumentException e) {
            System.out.println(e.getMessage());
        }
    }
}
```

