import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

public class ReverseString {
    private static final String[] COMMON_WORDS = {"the", "and", "is"}; // Commonly used English words

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Input string
        System.out.print("Enter a string: ");
        String inputString = scanner.nextLine();

        // Reverse the order of words
        String reversedString = reverseWords(inputString);

        // Print the reversed string
        System.out.println("Reversed string: " + reversedString);
    }

    private static String reverseWords(String inputString) {
        // Split the string into words
        String[] words = inputString.split("\\s+");

        // Validate number of words
        if (words.length < 5) {
            return "Input string must have at least 5 words.";
        }

        // Check for duplicate words
        if (hasDuplicateWords(words)) {
            return "Input string contains duplicate words.";
        }

        // Reverse the order of words
        StringBuilder reversedBuilder = new StringBuilder();
        for (int i = words.length - 1; i >= 0; i--) {
            String word = words[i];

            // Ignore numbers, special characters, and punctuation marks
            if (word.matches("[a-zA-Z]+")) {
                // Exclude common words
                if (!isCommonWord(word)) {
                    // Convert word to uppercase
                    word = word.toUpperCase();

                    // Append word to reversed string
                    reversedBuilder.append(word).append(" ");
                }
            }
        }

        String reversedString = reversedBuilder.toString().trim();

        // Ensure reversed sentence starts with a capital letter
        reversedString = capitalizeFirstLetter(reversedString);

        // Ensure reversed sentence ends with a punctuation mark
        reversedString = addPunctuation(reversedString);

        return reversedString;
    }

    private static boolean hasDuplicateWords(String[] words) {
        Set<String> wordSet = new HashSet<>();
        for (String word : words) {
            if (!wordSet.add(word.toLowerCase())) {
                return true;
            }
        }
        return false;
    }

    private static boolean isCommonWord(String word) {
        for (String commonWord : COMMON_WORDS) {
            if (commonWord.equalsIgnoreCase(word)) {
                return true;
            }
        }
        return false;
    }

    private static String capitalizeFirstLetter(String str) {
        return Character.toUpperCase(str.charAt(0)) + str.substring(1);
    }

    private static String addPunctuation(String str) {
        if (!str.endsWith(".") && !str.endsWith("?") && !str.endsWith("!")) {
            return str + ".";
        }
        return str;
    }
}

Here is a Java program that finds all prime numbers within a given range and stores them in an array, and then displays the prime numbers in descending order:

```java
import java.util.Arrays;

public class PrimeNumbers {

    public static void main(String[] args) {
        int startRange = 1;
        int endRange = 100;

        int[] primeNumbers = findPrimeNumbers(startRange, endRange);
        Arrays.sort(primeNumbers);
        reverseArray(primeNumbers);

        System.out.println("Prime numbers within the range " + startRange + " to " + endRange + ":");
        displayArray(primeNumbers);
    }

    public static int[] findPrimeNumbers(int start, int end) {
        int count = 0;
        for (int i = start; i <= end; i++) {
            if (isPrime(i)) {
                count++;
            }
        }

        int[] primeNumbers = new int[count];
        int index = 0;
        for (int i = start; i <= end; i++) {
            if (isPrime(i)) {
                primeNumbers[index] = i;
                index++;
            }
        }
        return primeNumbers;
    }

    public static boolean isPrime(int num) {
        if (num <= 1) {
            return false;
        }
        for (int i = 2; i <= Math.sqrt(num); i++) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }

    public static void reverseArray(int[] arr) {
        int start = 0;
        int end = arr.length - 1;
        while (start < end) {
            int temp = arr[start];
            arr[start] = arr[end];
            arr[end] = temp;
            start++;
            end--;
        }
    }

    public static void displayArray(int[] arr) {
        for (int i = 0; i < arr.length; i++) {
            System.out.print(arr[i] + " ");
        }
        System.out.println();
    }
}
```

