    words = sentence.split()
    pig_latin_words = []

    for word in words:
        if len(word) > 10:
            pig_latin_words.append(word)
            continue

        punctuation = ''
        if not word[-1].isalpha():
            punctuation = word[-1]
            word = word[:-1]

        capitalized = False
        if word[0].isupper():
            capitalized = True
            word = word.lower()

        if word[0] in vowels:
            pig_latin_word = word + 'way'
        else:
