Here's an example implementation in C++ to split a sentence into an array of words and sort them alphabetically without using any built-in sorting functions or libraries:

```cpp
#include <iostream>
#include <string>
#include <vector>

using namespace std;

// Function to split the sentence into words
vector<string> splitSentence(const string& sentence) {
    vector<string> words;
    string word = "";

    for (char c : sentence) {
        // Check if the character is an alphabet or a space
        if (isalpha(c) || c == ' ') {
            word += c;
        }
        // Check if the word is not empty and a delimiter is found
        else if (!word.empty()) {
            words.push_back(word);
            word = "";
        }
    }

    // Add the last word if any
    if (!word.empty()) {
        words.push_back(word);
    }

    return words;
}

// Function to sort the words in alphabetical order
void sortWords(vector<string>& words) {
    int n = words.size();

    // Bubble Sort
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            if (words[j] > words[j + 1]) {
                swap(words[j], words[j + 1]);
            }
        }
    }
}

int main() {
    string sentence = "Hello, how are you doing today? I am 25 years old.";

    // Split the sentence into words
    vector<string> words = splitSentence(sentence);

    // Sort the words
    sortWords(words);

    // Print the sorted words
    for (const string& word : words) {
        cout << word << " ";
    }
    cout << endl;

    return 0;
}
```

