import java.util.List;
import java.util.Map;

public class Student {
    private String name;
    private Map<String, List<Integer>> marks;
    private List<Integer> attendance;
    private List<String> extraCurricularActivities;

    public Student(String name, Map<String, List<Integer>> marks, List<Integer> attendance, List<String> extraCurricularActivities) {
        this.name = name;
        this.marks = marks;
        this.attendance = attendance;
        this.extraCurricularActivities = extraCurricularActivities;
    }

    public String getName() {
        return name;
    }

    public Map<String, List<Integer>> getMarks() {
        return marks;
    }

    public List<Integer> getAttendance() {
        return attendance;
    }

    public List<String> getExtraCurricularActivities() {
        return extraCurricularActivities;
    }

    public double calculateSubjectAverage(String subject) {
        if (marks.containsKey(subject)) {
            List<Integer> subjectMarks = marks.get(subject);
            int sum = 0;
            for (int mark : subjectMarks) {
                sum += mark;
            }
            return (double) sum / subjectMarks.size();
        }
        return 0.0;
    }

    public double calculateOverallAverage() {
        int totalMarks = 0;
        int totalAssessments = 0;
        for (List<Integer> subjectMarks : marks.values()) {
            for (int mark : subjectMarks) {
                totalMarks += mark;
                totalAssessments++;
            }
        }
        return (double) totalMarks / totalAssessments;
    }

    public double calculateAttendancePercentage() {
        int totalClasses = attendance.size();
        int totalPresent = 0;
        for (int present : attendance) {
            if (present == 1) {
                totalPresent++;
            }
        }
        return (double) totalPresent / totalClasses * 100;
    }

    public int calculateTotalExtraCurricularHours() {
        int totalHours = 0;
        for (String activity : extraCurricularActivities) {
            // Assuming each activity is logged with the number of hours spent
            totalHours += Integer.parseInt(activity);
        }
        return totalHours;
    }
}
```

With this Java object, you can create a new student object and perform calculations on their marks, attendance, and extracurricular activities.

