// isPrime checks if a number is prime or not using the Miller-Rabin primality test
func isPrime(n int64) bool {
	// Handle small numbers explicitly
	if n <= 1 {
		return false
	}

	// Check divisibility by small primes
	if n <= 3 {
		return true
	}
	if n%2 == 0 || n%3 == 0 {
		return false
	}

	// Convert the number to big.Int for calculations
	bigN := big.NewInt(n)

	// Find r and d such that n-1 = 2^r * d
	d := bigN.Sub(bigN, big.NewInt(1))
	r := 0
	for d.Bit(0) == 0 {
		d.Rsh(d, 1)
		r++
	}

	// Run the Miller-Rabin primality test multiple times
	k := 10 // Number of rounds for the test (higher value gives higher accuracy)
	for i := 0; i < k; i++ {
		if !millerRabinTest(bigN, d, r) {
			return false
		}
	}

	return true
}

// millerRabinTest performs a single round of the Miller-Rabin primality test
func millerRabinTest(n *big.Int, d *big.Int, r int) bool {
	a := big.NewInt(2 + rand.Int63n(n.Int64()-2)) // Pick a random number between 2 and n-2

	x := big.NewInt(0).Exp(a, d, n)

	if x.Cmp(big.NewInt(1)) == 0 || x.Cmp(big.NewInt(n.Int64()-1)) == 0 {
		return true
	}

	for i := 0; i < r-1; i++ {
		x.Exp(x, big.NewInt(2), n)
		if x.Cmp(big.NewInt(n.Int64()-1)) == 0 {
			return true
		}
	}

	return false
}
```

