Here is one possible implementation of the `matrix_multiply` function:

```python
class IncompatibleMatrixDimensionsError(Exception):
    pass

class InvalidMatrixValueError(Exception):
    pass

def matrix_multiply(A, B):
    # Check if the number of columns in matrix A is equal to the number of rows in matrix B
    if len(A[0]) != len(B):
        raise IncompatibleMatrixDimensionsError("Matrices cannot be multiplied due to incompatible dimensions")

    # Validate that all values in the matrices are positive integers
    for row in A:
        for value in row:
            if not isinstance(value, int) or value <= 0:
                raise InvalidMatrixValueError("Invalid matrix value. All values must be positive integers")
    for row in B:
        for value in row:
            if not isinstance(value, int) or value <= 0:
                raise InvalidMatrixValueError("Invalid matrix value. All values must be positive integers")

    # Multiply the matrices
    n = len(A)
    m = len(B)
    p = len(B[0])
    result = [[0] * p for _ in range(n)]
    for i in range(n):
        for j in range(p):
            for k in range(m):
                result[i][j] += A[i][k] * B[k][j]

    return result

