```python
import csv
import json

def convert_csv_to_json(csv_string):
    csv_data = csv_string.strip().split("\n")
    headers = csv_data[0].split(",")
    json_data = {}

    for line in csv_data[1:]:
        fields = line.split(",")
        city_data = {}

        for i, field in enumerate(fields):
            if i < len(headers):
                header = headers[i]
                if header == "latitude" or header == "longitude":
                    try:
                        coordinate = float(field)
                        if header == "latitude" and (coordinate < -90 or coordinate > 90):
                            raise ValueError("Invalid latitude value: {}".format(field))
                        if header == "longitude" and (coordinate < -180 or coordinate > 180):
                            raise ValueError("Invalid longitude value: {}".format(field))
                        city_data[header] = coordinate
                    except ValueError:
                        city_data[header] = None
                else:
                    city_data[header] = field

        if city_data.get("city"):
            json_data[city_data["city"]] = city_data

    return json.dumps(json_data, indent=2)
```

This implementation uses the `csv` module to parse the csv string and extract the headers and data. It then iterates through each line of the data, creating a dictionary representing each city. The function validates the latitude and longitude values and adds them to the city's dictionary if they are valid.

