const axios = require('axios');

function getMovieReleaseDate(movieTitle, callback) {
  const apiKey = 'YOUR_IMDB_API_KEY';
  const apiUrl = `http://www.omdbapi.com/?t=${encodeURIComponent(movieTitle)}&apikey=${apiKey}`;

  axios.get(apiUrl)
    .then(response => {
      if (response.data.Response === 'False') {
        throw new Error(response.data.Error);
      }
      const releaseDate = response.data.Released;
      callback(null, releaseDate);
    })
    .catch(error => {
      callback(error);
    });
}

