```python
import string

def caesar_encrypt(text, shift):
    encrypted_text = ""
    for char in text:
        if char.isalpha():
            if char.isupper():
                encrypted_text += chr((ord(char) - 65 + shift) % 26 + 65)
            else:
                encrypted_text += chr((ord(char) - 97 + shift) % 26 + 97)
        else:
            encrypted_text += char
    return encrypted_text

def caesar_decrypt(text, shift):
    decrypted_text = ""
    for char in text:
        if char.isalpha():
            if char.isupper():
                decrypted_text += chr((ord(char) - 65 - shift) % 26 + 65)
            else:
                decrypted_text += chr((ord(char) - 97 - shift) % 26 + 97)
        else:
            decrypted_text += char
    return decrypted_text

def get_valid_shift():
    while True:
        try:
            shift = int(input("Enter the shift value: "))
            if shift < 1 or shift > 25:
                print("Shift value must be between 1 and 25.")
            else:
                return shift
        except ValueError:
            print("Invalid shift value. Please enter a valid integer.")

def encode_decode_menu():
    print("Choose an option:")
    print("1. Encode a string")
    print("2. Decode an encoded string")
    print("3. Exit")

while True:
    encode_decode_menu()
    option = input("Enter your choice (1, 2, or 3): ")

    if option == "1":
        text = input("Enter the string to be encoded: ")
        shift = get_valid_shift()
        encoded_text = caesar_encrypt(text, shift)
        print("Encoded string: " + encoded_text)
    elif option == "2":
        text = input("Enter the encoded string: ")
        shift = get_valid_shift()
        decoded_text = caesar_decrypt(text, shift)
        print("Decoded string: " + decoded_text)
    elif option == "3":
        print("Exiting the program...")
        break
    else:
        print("Invalid option. Please choose a valid option (1, 2, or 3).")
