        return 'Error: Sentence must contain a verb'

    imperative_sentence = []

    # Iterate through the tokens and convert to imperative form
    for token in doc:
        if token.dep_ == 'nsubj':
            imperative_sentence.append(token.text)
        elif token.pos_ == 'VERB':
            imperative_sentence.append(token.lemma_)
        elif token.pos_ == 'PUNCT' and token.text == ',':
            imperative_sentence.append(',')
        elif token.dep_ == 'dobj':
            imperative_sentence.append(token.text)

