```javascript
function validateEmail(email) {
  // Check if email address has a valid format
  if (!email.includes('@')) {
    return false;
  }

  // Split email address into local part and domain name
  const [localPart, domainName] = email.split('@');

  // Check maximum length of email address
  if (email.length > 255 || localPart.length > 64 || domainName.length > 64) {
    return false;
  }

  // Check if email address starts or ends with a "."
  if (email.startsWith('.') || email.endsWith('.')) {
    return false;
  }

