      return false;
    }
  }

  // Check if domain name has at least one dot and a valid extension
  const domainParts = domainName.split('.');
  if (domainParts.length < 2 || !isValidExtension(domainParts[domainParts.length - 1])) {
    return false;
  }

  return true;
}

