import java.util.ArrayList;
import java.util.List;

public class LongestString {
    public static void main(String[] args) {
        List<String> strings = new ArrayList<>();
        strings.add("abc");
        strings.add("defg");
        strings.add("hi");
        strings.add("jklmno");
        strings.add("pqr");
        strings.add("stuvwx");
        strings.add("yz");
        strings.add("aaabb");
        strings.add("cc");
        strings.add("dd");
        strings.add("ee");

        String longestString = findLongestString(strings);
        System.out.println("Longest String: " + longestString);
    }

    private static String findLongestString(List<String> strings) {
        if (strings.isEmpty()) {
            return null;
        }

        sortStrings(strings);

        return strings.get(strings.size() - 1);
    }

    private static void sortStrings(List<String> strings) {
        mergeSort(strings, 0, strings.size() - 1);
    }

    private static void mergeSort(List<String> strings, int left, int right) {
        if (left < right) {
            int mid = (left + right) / 2;
            mergeSort(strings, left, mid);
            mergeSort(strings, mid + 1, right);
            merge(strings, left, mid, right);
        }
    }

    private static void merge(List<String> strings, int left, int mid, int right) {
        int n1 = mid - left + 1;
        int n2 = right - mid;

        List<String> leftStrings = new ArrayList<>();
        List<String> rightStrings = new ArrayList<>();

        for (int i = 0; i < n1; i++) {
            leftStrings.add(strings.get(left + i));
        }

        for (int j = 0; j < n2; j++) {
            rightStrings.add(strings.get(mid + 1 + j));
        }

        int i = 0, j = 0, k = left;

        while (i < n1 && j < n2) {
            if (compareStrings(leftStrings.get(i), rightStrings.get(j)) <= 0) {
                strings.set(k, leftStrings.get(i));
                i++;
            } else {
                strings.set(k, rightStrings.get(j));
                j++;
            }
            k++;
        }

        while (i < n1) {
            strings.set(k, leftStrings.get(i));
            i++;
            k++;
        }

        while (j < n2) {
            strings.set(k, rightStrings.get(j));
            j++;
            k++;
        }
    }

    private static int compareStrings(String s1, String s2) {
        int uniqueCharCount1 = countUniqueCharacters(s1);
        int uniqueCharCount2 = countUniqueCharacters(s2);

        if (uniqueCharCount1 == uniqueCharCount2) {
            return s1.length() - s2.length();
        }

        return uniqueCharCount1 - uniqueCharCount2;
    }

    private static int countUniqueCharacters(String str) {
        boolean[] visited = new boolean[26];
        int count = 0;

        for (char ch : str.toCharArray()) {
            if (Character.isAlphabetic(ch) && !visited[ch - 'a']) {
                visited[ch - 'a'] = true;
                count++;
            }
        }

        return count;
    }
}
```

