To find the inverse of a matrix using the adjugate method, we need to follow these steps:

1. Check if the matrix is square. If not, raise a ValueError.
2. Calculate the determinant of the matrix. If the determinant is 0, raise a ValueError.
3. Calculate the adjugate of the matrix.
4. Multiply each element of the adjugate matrix by 1/determinant to obtain the inverse matrix.

Here is the correct code to find the inverse of a matrix using the adjugate method:

```python
def calculate_determinant(matrix):
    if len(matrix) == 2:
        return matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0]
    else:
        determinant = 0
        for j in range(len(matrix)):
            determinant += ((-1) ** j) * matrix[0][j] * calculate_determinant(get_submatrix(matrix, 0, j))
        return determinant

def get_submatrix(matrix, i, j):
    submatrix = []
    for row in range(len(matrix)):
        if row != i:
            subrow = []
            for col in range(len(matrix[0])):
                if col != j:
                    subrow.append(matrix[row][col])
            submatrix.append(subrow)
    return submatrix

def calculate_adjugate(matrix):
    adjugate = []
    for i in range(len(matrix)):
        row = []
        for j in range(len(matrix[0])):
            cofactor = ((-1) ** (i + j)) * calculate_determinant(get_submatrix(matrix, i, j))
            row.append(cofactor)
        adjugate.append(row)
    return list(map(list, zip(*adjugate)))

def matrix_inverse(matrix):
    if len(matrix) != len(matrix[0]):
        raise ValueError("Matrix must be square.")

    determinant = calculate_determinant(matrix)
    if determinant == 0:
        raise ValueError("Matrix must have a non-zero determinant.")

    adjugate_matrix = calculate_adjugate(matrix)

    inverse_matrix = []
    for i in range(len(adjugate_matrix)):
        row = []
        for j in range(len(adjugate_matrix[0])):
            row.append(adjugate_matrix[i][j] / determinant)
        inverse_matrix.append(row)

    return inverse_matrix
```

Note: The code assumes that you have defined the `calculate_determinant` and `get_submatrix` functions. These functions are used to calculate the determinant and obtain submatrices, respectively.

