import java.util.Scanner;

public class LargestPrimeNumber {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int largestPrime = -1;
        boolean isPrimeFound = false;

        System.out.println("Enter a list of numbers (negative number to exit):");

        while (true) {
            int num = scanner.nextInt();

            if (num < 0) {
                break;
            }

            if (isPrime(num)) {
                isPrimeFound = true;

                if (num > largestPrime) {
                    largestPrime = num;
                }
            }
        }

        if (isPrimeFound) {
            System.out.println("The largest prime number is: " + largestPrime);
        } else {
            System.out.println("No prime number found in the input.");
        }

        scanner.close();
    }

    public static boolean isPrime(int num) {
        if (num <= 1) {
            return false;
        }

        if (num <= 3) {
            return true;
        }

        if (num % 2 == 0 || num % 3 == 0) {
            return false;
        }

        for (int i = 5; i * i <= num; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) {
                return false;
            }
        }

        return true;
    }
}

