        if (enrolledSubjects.size() >= MAX_SUBJECTS) {
            removeSubjectWithLowestGrade();
        }
        enrolledSubjects.add(subject);
    }

    public void sortEnrolledSubjectsByGradeDescending() {
        enrolledSubjects.sort(Comparator.comparing(Subject::getGrade).reversed());
    }

    public double findMedianGrade() {
        int size = enrolledSubjects.size();
        if (size == 0) {
            return 0.0;
        }
        sortEnrolledSubjectsByGradeDescending();
        int middleIndex = size / 2;
        if (size % 2 == 0) {
            double middleGrade1 = enrolledSubjects.get(middleIndex - 1).getGrade();
            double middleGrade2 = enrolledSubjects.get(middleIndex).getGrade();
            return (middleGrade1 + middleGrade2) / 2.0;
        } else {
            return enrolledSubjects.get(middleIndex).getGrade();
        }
    }

    private void removeSubjectWithLowestGrade() {
        Subject subjectWithLowestGrade = enrolledSubjects.stream()
                .min(Comparator.comparing(Subject::getGrade))
                .orElse(null);
        if (subjectWithLowestGrade != null) {
            enrolledSubjects.remove(subjectWithLowestGrade);
        }
    }

    public List<Subject> findNHighestGradeSubjects(int n) {
        sortEnrolledSubjectsByGradeDescending();
        return enrolledSubjects.subList(0, Math.min(n, enrolledSubjects.size()));
    }

    public double calculateWeightedAverage() {
        double totalWeightedGrade = 0.0;
        double totalWeight = 0.0;
        for (Subject subject : enrolledSubjects) {
            double weight = calculateWeight(subject.getGrade());
            totalWeightedGrade += subject.getGrade() * weight;
            totalWeight += weight;
        }
        if (totalWeight == 0.0) {
            return 0.0;
        }
        return totalWeightedGrade / totalWeight;
    }

