#include <iostream>
#include <vector>
#include <algorithm>

bool containsOnlyVowels(const std::string& str) {
    std::string vowels = "aeiou";
    for (char c : str) {
        char lower = std::tolower(c);
        if (vowels.find(lower) == std::string::npos) {
            return false;
        }
    }
    return true;
}

std::vector<std::string> removeVowelsAndReverse(std::vector<std::string>& arr) {
    arr.erase(std::remove_if(arr.begin(), arr.end(), containsOnlyVowels), arr.end());
    std::reverse(arr.begin(), arr.end());
    return arr;
}

