Here is one possible solution to flatten an array up to a given depth using JavaScript:

```javascript
function flattenArray(arr, depth) {
  // Check if depth is zero or if arr is not an array
  if (depth === 0 || !Array.isArray(arr)) {
    return arr;
  }

  // Create a new flattened array
  var flattened = [];

  // Loop through each element in arr
  for (var i = 0; i < arr.length; i++) {
    // Recursively flatten nested arrays up to depth - 1
    var nested = flattenArray(arr[i], depth - 1);

    // Add elements of nested array to flattened array
    flattened.push.apply(flattened, nested);
  }

  return flattened;
}
```

