function combineArrays(arr1, arr2) {
  let arr3 = [];
  let maxLength = Math.max(arr1.length, arr2.length);

  for (let i = 0; i < maxLength; i++) {
    if (i < arr1.length) {
      arr3.push(arr1[i]);
    }
    if (i < arr2.length) {
      arr3.push(arr2[i]);
    }
  }

  return arr3;
}
