To solve this problem, we can create a helper function `isPrime` to check if a number is prime. Then, we can create another helper function `generateFibonacci` to generate the Fibonacci sequence up to a given limit. Finally, we can iterate through the generated Fibonacci sequence and check if each number is prime. If it is, we add it to the result array until we reach the desired number of prime Fibonacci numbers.

Here's the JavaScript program that accomplishes this:

```javascript
function isPrime(num) {
  if (num <= 1) {
    return false;
  }
  if (num <= 3) {
    return true;
  }
  if (num % 2 === 0 || num % 3 === 0) {
    return false;
  }
  let i = 5;
  while (i * i <= num) {
    if (num % i === 0 || num % (i + 2) === 0) {
      return false;
    }
    i += 6;
  }
  return true;
}

function generateFibonacci(limit) {
  const fibonacci = [0, 1];
  let i = 2;
  while (fibonacci[i - 1] <= limit) {
    fibonacci[i] = fibonacci[i - 1] + fibonacci[i - 2];
    i++;
  }
  return fibonacci.slice(2); // Exclude the first two numbers (0, 1)
}

function generatePrimeFibonacciArray(limit) {
  const primeFibonacciArray = [];
  const fibonacciArray = generateFibonacci(limit);
  for (const num of fibonacciArray) {
    if (isPrime(num)) {
      primeFibonacciArray.push(num);
      if (primeFibonacciArray.length === 1000) {
        break; // Stop when we reach 1000 prime Fibonacci numbers
      }
    }
  }
  return primeFibonacciArray;
}

const result = generatePrimeFibonacciArray(Infinity);
console.log(result);
```

