function dragStart() {
  draggedItem = this;
  setTimeout(() => this.style.display = 'none', 0);
}

// Drag end event
function dragEnd() {
  draggedItem.style.display = 'block';
  draggedItem = null;
}

// Drag over event
function dragOver(event) {
  event.preventDefault();
}

// Drop event
function drop(event) {
  event.preventDefault();
  const dropZone = this;

  // Check if the dropped item is allowed in the drop zone
  const allowedItems = dropZone.dataset.allowedItems.split(',');
  if (allowedItems.includes(draggedItem.id)) {
    dropZone.appendChild(draggedItem);
    showSuccessMessage();
  }
}

// Show success message
