import java.util.ArrayList;
import java.util.List;

public class Dice {
    private int sides;
    private List<Integer> rollHistory;

    public Dice(int numSides) {
        if (numSides >= 4 && numSides <= 20) {
            sides = numSides;
        } else {
            throw new IllegalArgumentException("Number of sides must be between 4 and 20, inclusive.");
        }
        rollHistory = new ArrayList<>();
    }

    public int roll() {
        int result = (int) (Math.random() * sides) + 1;
        rollHistory.add(result);
        return result;
    }

    public int getSides() {
        return sides;
    }

    public void setSides(int numSides) {
        if (numSides >= 4 && numSides <= 20) {
            sides = numSides;
        } else {
            throw new IllegalArgumentException("Number of sides must be between 4 and 20, inclusive.");
        }
    }

    public String toString() {
        return "Dice with " + sides + " sides";
    }

    public List<Integer> rollMultipleTimes(int numRolls) {
        List<Integer> rolls = new ArrayList<>();
        for (int i = 0; i < numRolls; i++) {
            rolls.add(roll());
        }
        return rolls;
    }

    public int calculateSum() {
        int sum = 0;
        for (int roll : rollHistory) {
            sum += roll;
        }
        return sum;
    }

    public boolean isDouble() {
        if (rollHistory.size() < 2) {
            return false;
        }
        int lastRoll = rollHistory.get(rollHistory.size() - 1);
        int secondLastRoll = rollHistory.get(rollHistory.size() - 2);
        return lastRoll == secondLastRoll;
    }

    public void reset() {
        rollHistory.clear();
    }

    public List<Integer> getRollHistory() {
        return rollHistory;
    }

    public double getAverageRoll() {
        if (rollHistory.isEmpty()) {
            return 0;
        }
        int sum = calculateSum();
        return (double) sum / rollHistory.size();
    }

    public static void main(String[] args) {
        Dice dice = new Dice(20);
        System.out.println(dice);

        // Roll the dice 10 times and print the results
        List<Integer> rolls = dice.rollMultipleTimes(10);
        System.out.println("Rolls: " + rolls);

        // Calculate the sum of all rolls
