        for grade in grades:
            subject, grade_value = grade
            student.add_grade(subject, grade_value)
        self.students.append(student)

    def remove_student(self, name):
        for student in self.students:
            if student.name == name:
                self.students.remove(student)
                break

    def update_student_grade(self, name, subject, grade):
        for student in self.students:
            if student.name == name:
                student.update_grade(subject, grade)
                break

    def calculate_student_average_grade(self, name):
        for student in self.students:
            if student.name == name:
                return student.get_average_grade()

    def calculate_subject_average_grade(self, subject):
        total_grades = 0
        num_students = 0
        for student in self.students:
            if subject in student.grades:
                total_grades += student.grades[subject]
                num_students += 1
        if num_students > 0:
