function isValidDate(day, month, year) {
  const isValidDay = day > 0 && day <= 31;
  const isValidMonth = month > 0 && month <= 12;
  const isValidYear = year >= 2000 && year <= 2050;

  if (isValidMonth && day > 28) {
    if (month == 2) {
      if (day > 29 || (day == 29 && !isLeapYear(year))) {
        return false;
      }
    } else if ([4, 6, 9, 11].includes(month) && day > 30) {
      return false;
    }
  }

  return isValidDay && isValidMonth && isValidYear;
}

function isLeapYear(year) {
  return (year % 4 === 0 && year % 100 !== 0) || (year % 400 === 0);
}

function isValidTime(hours, minutes, seconds) {
  return hours >= 0 && hours < 24 && minutes >= 0 && minutes < 60 && seconds >= 0 && seconds < 60;
}

function formatTime(timePart) {
  const [hours, minutes, seconds] = timePart.split(":");
  return `${hours.padStart(2, "0")}:${minutes.padStart(2, "0")}:${seconds.padStart(2, "0")}`;
}

function formatDate(datePart, dateFormat) {
  const [month, day, year] = datePart.split("/");
  const formattedDate = dateFormat
    .replace("MM", month.padStart(2, "0"))
    .replace("DD", day.padStart(2, "0"))
    .replace("YYYY", year);
  return formattedDate;
}

function calculateDaysUntilNextLeapYear(year) {
  let currentYear = Number(year);
  while (!isLeapYear(currentYear)) {
    currentYear++;
  }

  const currentDate = new Date().getDate();
  const currentMonth = new Date().getMonth() + 1;
  let daysUntilNextLeapYear = 0;

  for (let i = currentMonth; i <= 12; i++) {
    if (i == 2) {
      daysUntilNextLeapYear += isLeapYear(currentYear) ? 29 : 28;
    } else if ([4, 6, 9, 11].includes(i)) {
      daysUntilNextLeapYear += 30;
    } else {
      daysUntilNextLeapYear += 31;
    }
  }

  daysUntilNextLeapYear -= currentDate;
  return daysUntilNextLeapYear;
}

