Here is a C++ program that lists all the prime numbers divisible by 7 from 1 to 500, excluding numbers that are multiples of both 3 and 5, and prints the product of all the prime numbers found:

```cpp
#include <iostream>

bool isPrime(int num) {
    if (num <= 1)
        return false;

    for (int i = 2; i * i <= num; i++) {
        if (num % i == 0)
            return false;
    }

    return true;
}

int main() {
    int product = 1;

    for (int i = 1; i <= 500; i++) {
        if (i % 7 == 0 && i % 3 != 0 && i % 5 != 0 && isPrime(i)) {
            std::cout << i << " ";
            product *= i;
        }
    }

    std::cout << std::endl << "Product of prime numbers: " << product << std::endl;

    return 0;
}
```

Explanation:
1. The `isPrime` function checks if a number is prime or not by iterating from 2 to the square root of the number and checking for any divisors.
