function findSmallestPrimes(arr) {
  // Helper function to check if a number is prime
  function isPrime(num) {
    if (num <= 1) return false;
    for (let i = 2; i * i <= num; i++) {
      if (num % i === 0) return false;
    }
    return true;
  }

  // Remove duplicates from the array
  arr = [...new Set(arr)];

  // Initialize variables for the first, second, and third smallest prime numbers
  let first = Infinity;
  let second = Infinity;
  let third = Infinity;

  // Iterate over each number in the array
  for (let i = 0; i < arr.length; i++) {
    // Check if the number is prime
    if (isPrime(arr[i])) {
      // Update the variables accordingly
      if (arr[i] < first) {
        third = second;
        second = first;
        first = arr[i];
      } else if (arr[i] < second) {
        third = second;
        second = arr[i];
      } else if (arr[i] < third) {
        third = arr[i];
      }
    }
  }

  // Print the first, second, and third smallest prime numbers in ascending order
  console.log(`First smallest prime: ${first}`);
  console.log(`Second smallest prime: ${second}`);
  console.log(`Third smallest prime: ${third}`);
}
```

