        Random random = new Random();
        String language = languages.get(random.nextInt(languages.size()));
        if (usedLanguages.size() == languages.size()) {
            usedLanguages.clear();
        }
        while (usedLanguages.contains(language)) {
            language = languages.get(random.nextInt(languages.size()));
        }
        usedLanguages.add(language);
        return language;
