        int leastUsedCount = Integer.MAX_VALUE;
        String leastUsedLanguage = "";
        for (int i = 0; i < languages.size(); i++) {
            if (languageCounts.get(i) < leastUsedCount) {
                leastUsedCount = languageCounts.get(i);
                leastUsedLanguage = languages.get(i);
            }
        }
