```javascript
function convertToScientificNotation(number) {
  // Check if the number is already in scientific notation
  if (number.toString().includes('e')) {
    return number.toString();
  }

  // Convert the number to a string with maximum 15 decimal places
  let strNumber = number.toFixed(15).toString();

  // Remove trailing zeros from the decimal part
  strNumber = strNumber.replace(/0+$/, '');

  // Split the number into the decimal part and the exponent part
  let [decimalPart, exponentPart] = strNumber.split('e');

  // Convert the exponent part to a number and limit it to a maximum of 10 digits
  let exponent = parseInt(exponentPart);
  if (exponent > 10) {
    exponent = 10;
  }

  // Return the number in scientific notation
  return decimalPart + 'e' + exponent;
}
```

