get_uncorrelated_columns <- function(data, significance = 0.05, method = "pearson") {
  # Impute missing values
  imputed_data <- custom_impute(data)

  # Calculate correlation matrix
  cor_matrix <- cor(imputed_data, method = custom_cor, method.args = list(method = method))

  # Find uncorrelated columns
  uncorrelated_columns <- names(cor_matrix)[apply(cor_matrix, 1, function(x) all(abs(x) < significance))]

