// Node class to represent a node in the AVL tree
class Node {
    int data;
    int height;
    Node left, right;

    Node(int value) {
        data = value;
        height = 1;
    }
}

// AVLTree class
public class AVLTree {
    Node root;

    // Method to get the height of a node
    int height(Node node) {
        if (node == null)
            return 0;
        return node.height;
    }

    // Method to get the maximum of two integers
    int max(int a, int b) {
        return Math.max(a, b);
    }

    // Method to rotate a subtree rooted with y
    Node rotateRight(Node y) {
        Node x = y.left;
        Node T2 = x.right;

        // Perform rotation
        x.right = y;
        y.left = T2;

        // Update heights
        y.height = max(height(y.left), height(y.right)) + 1;
        x.height = max(height(x.left), height(x.right)) + 1;

        // Return new root
        return x;
    }

    // Method to rotate a subtree rooted with x
    Node rotateLeft(Node x) {
        Node y = x.right;
        Node T2 = y.left;

        // Perform rotation
        y.left = x;
        x.right = T2;

        // Update heights
        x.height = max(height(x.left), height(x.right)) + 1;
        y.height = max(height(y.left), height(y.right)) + 1;

        // Return new root
        return y;
    }

    // Get the balance factor of a node
    int getBalance(Node node) {
        if (node == null)
            return 0;
        return height(node.left) - height(node.right);
    }

    // Method to insert a node into the AVL tree
    Node insert(Node node, int value) {
        // Perform the normal BST insertion
        if (node == null)
            return new Node(value);
        if (value < node.data)
            node.left = insert(node.left, value);
        else if (value > node.data)
            node.right = insert(node.right, value);
        else
            return node;

        // Update the height of the ancestor node
        node.height = 1 + max(height(node.left), height(node.right));

        // Check the balance factor and rotate the tree if needed
        int balance = getBalance(node);

        // Left Left Case
        if (balance > 1 && value < node.left.data)
            return rotateRight(node);

        // Right Right Case
        if (balance < -1 && value > node.right.data)
            return rotateLeft(node);

        // Left Right Case
        if (balance > 1 && value > node.left.data) {
            node.left = rotateLeft(node.left);
            return rotateRight(node);
        }

        // Right Left Case
        if (balance < -1 && value < node.right.data) {
            node.right = rotateRight(node.right);
            return rotateLeft(node);
        }

        return node;
    }

    // Method to delete a node from the AVL tree
    Node delete(Node root, int value) {
        // Perform the normal BST delete
        if (root == null)
            return root;
        if (value < root.data)
            root.left = delete(root.left, value);
        else if (value > root.data)
            root.right = delete(root.right, value);
        else {
            // Node to be deleted found

            // Node with only one child or no child
            if ((root.left == null) || (root.right == null)) {
                Node temp = null;
                if (temp == root.left)
                    temp = root.right;
                else
                    temp = root.left;

                // No child case
                if (temp == null) {
                    temp = root;
                    root = null;
                } else // One child case
                    root = temp; // Copy the contents of the non-empty child

                temp = null;
            } else {
                // Node with two children: Get the inorder successor (smallest in the right subtree)
                Node temp = minValueNode(root.right);

                // Copy the inorder successor's data to this node
                root.data = temp.data;

                // Delete the inorder successor
                root.right = delete(root.right, temp.data);
            }
        }

        // If the tree had only one node then return
        if (root == null)
            return root;

        // Update the height of the current node
        root.height = max(height(root.left), height(root.right)) + 1;

        // Check the balance factor and rotate the tree if needed
        int balance = getBalance(root);

        // Left Left Case
        if (balance > 1 && getBalance(root.left) >= 0)
            return rotateRight(root);

        // Left Right Case
        if (balance > 1 && getBalance(root.left) < 0) {
            root.left = rotateLeft(root.left);
            return rotateRight(root);
        }

        // Right Right Case
        if (balance < -1 && getBalance(root.right) <= 0)
            return rotateLeft(root);

        // Right Left Case
        if (balance < -1 && getBalance(root.right) > 0) {
            root.right = rotateRight(root.right);
            return rotateLeft(root);
        }

        return root;
    }

    // Method to find the inorder successor (smallest in the right subtree)
    Node minValueNode(Node node) {
        Node current = node;
        while (current.left != null)
            current = current.left;
        return current;
    }

    // Method to search for a specific value in the AVL tree
    boolean search(Node root, int value) {
        if (root == null)
            return false;
        if (root.data == value)
            return true;
        if (root.data < value)
            return search(root.right, value);
        return search(root.left, value);
    }

    // Method to perform a level order traversal of the AVL tree
    void levelOrderTraversal(Node root) {
        if (root == null)
            return;
        Queue<Node> queue = new LinkedList<>();
        queue.add(root);
        while (!queue.isEmpty()) {
            Node tempNode = queue.poll();
            System.out.print(tempNode.data + " ");
            if (tempNode.left != null)
                queue.add(tempNode.left);
            if (tempNode.right != null)
                queue.add(tempNode.right);
        }
    }

    public static void main(String[] args) {
        AVLTree avlTree = new AVLTree();
        avlTree.root = avlTree.insert(avlTree.root, 9);
        avlTree.root = avlTree.insert(avlTree.root, 5);
        avlTree.root = avlTree.insert(avlTree.root, 10);
        avlTree.root = avlTree.insert(avlTree.root, 0);
        avlTree.root = avlTree.insert(avlTree.root, 6);
        avlTree.root = avlTree.insert(avlTree.root, 11);
        avlTree.root = avlTree.insert(avlTree.root, -1);
        avlTree.root = avlTree.insert(avlTree.root, 1);
        avlTree.root = avlTree.insert(avlTree.root, 2);

        System.out.println("Level order traversal of the AVL tree:");
        avlTree.levelOrderTraversal(avlTree.root);
        System.out.println();

        avlTree.root = avlTree.delete(avlTree.root, 10);

        System.out.println("Level order traversal of the AVL tree after deleting 10:");
        avlTree.levelOrderTraversal(avlTree.root);
        System.out.println();

        boolean isFound = avlTree.search(avlTree.root, 6);
        System.out.println("Is 6 present in the AVL tree? " + isFound);
    }
}
