<!DOCTYPE html>
<html>
<head>
    <title>Solar System Simulation</title>
    <style>
        canvas {
            border: 1px solid black;
        }
    </style>
</head>
<body>
    <canvas id="canvas" width="800" height="600"></canvas>
    <script>
        // Constants
        const G = 0.05; // Gravitational constant
        const MAX_SPEED = 5;

        // Celestial Body class
        class CelestialBody {
            constructor(x, y, mass, radius, color) {
                this.x = x;
                this.y = y;
                this.mass = mass;
                this.radius = radius;
                this.color = color;
                this.vx = Math.random() * 2 - 1;
                this.vy = Math.random() * 2 - 1;
            }

            draw(ctx) {
                ctx.beginPath();
                ctx.arc(this.x, this.y, this.radius, 0, 2 * Math.PI);
                ctx.fillStyle = this.color;
                ctx.fill();
                ctx.closePath();
            }

            update() {
                this.x += this.vx;
                this.y += this.vy;
            }

            applyGravity(otherBodies) {
                for (let body of otherBodies) {
                    if (body !== this) {
                        const dx = body.x - this.x;
                        const dy = body.y - this.y;
                        const distance = Math.sqrt(dx ** 2 + dy ** 2);
                        const force = (G * this.mass * body.mass) / (distance ** 2);
                        const acceleration = force / this.mass;

                        const ax = (acceleration * dx) / distance;
                        const ay = (acceleration * dy) / distance;

                        this.vx = Math.min(Math.max(this.vx + ax, -MAX_SPEED), MAX_SPEED);
                        this.vy = Math.min(Math.max(this.vy + ay, -MAX_SPEED), MAX_SPEED);
                    }
                }
            }

            checkCollision(otherBodies) {
                for (let body of otherBodies) {
                    if (body !== this) {
                        const dx = body.x - this.x;
                        const dy = body.y - this.y;
                        const distance = Math.sqrt(dx ** 2 + dy ** 2);

                        if (distance < this.radius + body.radius) {
                            return true;
                        }
                    }
                }
                return false;
            }
        }

        // Initialize canvas
        const canvas = document.getElementById('canvas');
        const ctx = canvas.getContext('2d');

        // Initialize celestial bodies
        const bodies = [];
        const numBodies = 10;

        for (let i = 0; i < numBodies; i++) {
            const x = Math.random() * canvas.width;
            const y = Math.random() * canvas.height;
            const mass = Math.random() * 10 + 1;
            const radius = mass;
            const color = `rgb(${Math.random() * 255}, ${Math.random() * 255}, ${Math.random() * 255})`;

            const body = new CelestialBody(x, y, mass, radius, color);
            bodies.push(body);
        }

        // Simulation loop
        function loop() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            for (let body of bodies) {
                body.applyGravity(bodies);
                body.update();
                body.draw(ctx);

                if (body.x < 0 || body.x > canvas.width || body.y < 0 || body.y > canvas.height) {
                    body.vx *= -1;
                    body.vy *= -1;
                }

                if (body.checkCollision(bodies)) {
                    body.vx *= -1;
                    body.vy *= -1;
                }
            }

            requestAnimationFrame(loop);
        }

        loop();
    </script>
</body>
</html>
```

This code sets up a simple 2D canvas and creates a `CelestialBody` class that represents a celestial body with its position, mass, radius, velocity, and color. It also contains methods to draw, update, apply gravity, and check for collisions.

The `loop` function is the main simulation loop, which updates the positions of the celestial bodies, applies gravitational forces, checks for collisions, and redraws the canvas. It uses `requestAnimationFrame` to achieve a smooth animation.

