    validateUserInput();
    return;
  }

  // Check if input contains at least one uppercase letter
  if (userInput.toUpperCase() === userInput) {
    alert("Input must contain at least one uppercase letter.");
    validateUserInput();
    return;
  }

  // Check if input contains at least one lowercase letter
  if (userInput.toLowerCase() === userInput) {
    alert("Input must contain at least one lowercase letter.");
    validateUserInput();
    return;
  }

  // Check if input contains at least one numeric digit
