class Calculator {
  constructor() {
    this.number1 = 0;
    this.number2 = 0;
    this.result = 0;
  }

  add(num1, num2) {
    this.number1 = num1;
    this.number2 = num2;
    this.result = this.number1 + this.number2;
    return this.result;
  }

  subtract(num1, num2) {
    this.number1 = num1;
    this.number2 = num2;
    this.result = this.number1 - this.number2;
    return this.result;
  }

  multiply(num1, num2) {
    this.number1 = num1;
    this.number2 = num2;
    this.result = this.number1 * this.number2;
    return this.result;
  }

  divide(num1, num2) {
    this.number1 = num1;
    this.number2 = num2;

    if (this.number2 === 0) {
      throw new Error("Cannot divide by zero");
    }

    this.result = this.number1 / this.number2;
    return this.result;
  }

  power(base, exponent) {
    this.number1 = base;
    this.number2 = exponent;

    if (this.number2 <= 0 || !Number.isInteger(this.number2)) {
      throw new Error("Exponent must be a positive integer");
    }

    this.result = Math.pow(this.number1, this.number2);
    return this.result;
  }

  factorial(num) {
    this.number1 = num;

    if (this.number1 <= 0 || !Number.isInteger(this.number1)) {
      throw new Error("Number must be a positive integer");
    }

    let factorial = 1;
    for (let i = 1; i <= this.number1; i++) {
      factorial *= i;
    }

    this.result = factorial;
    return this.result;
  }

  squareRoot(num) {
    this.number1 = num;

    if (this.number1 < 0) {
      throw new Error("Number cannot be negative");
    }

    this.result = Math.sqrt(this.number1);
    return this.result;
  }

  getResult() {
    return this.result;
  }
}

