Here's a C program that encrypts a sentence using the Vigenère cipher with a user-defined key:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* vigenereEncrypt(char* sentence, char* key) {
    int len = strlen(sentence);
    char* encrypted = (char*) malloc(len + 1);
    int keyLen = strlen(key);

    for (int i = 0; i < len; i++) {
        if (sentence[i] >= 'a' && sentence[i] <= 'z') {
            encrypted[i] = ((sentence[i] - 'a') + (key[i % keyLen] - 'a')) % 26 + 'a';
        }
        else if (sentence[i] >= 'A' && sentence[i] <= 'Z') {
            encrypted[i] = ((sentence[i] - 'A') + (key[i % keyLen] - 'a')) % 26 + 'A';
        }
        else {
            encrypted[i] = sentence[i];
        }
    }
    encrypted[len] = '\0';

    return encrypted;
}

int main() {
    char sentence[100];
    char key[100];

    printf("Enter the sentence to encrypt: ");
    fgets(sentence, sizeof(sentence), stdin);
    sentence[strcspn(sentence, "\n")] = '\0'; // Remove newline character

    printf("Enter the key: ");
    fgets(key, sizeof(key), stdin);
    key[strcspn(key, "\n")] = '\0'; // Remove newline character

    char* encryptedSentence = vigenereEncrypt(sentence, key);
    printf("Encrypted sentence: %s\n", encryptedSentence);

    free(encryptedSentence);

    return 0;
}
```

