        // Read and validate the second number
        while (true) {
            try {
                System.out.print("Enter the second positive integer: ");
                number2 = scanner.nextInt();

                if (number2 <= 0) {
                    throw new IllegalArgumentException("Number must be positive.");
                }
                break;
