def count_items(nested_list, chunk_size=1000):
    count_dict = {}
    start_index = 0
    while start_index < len(nested_list):
        chunk = nested_list[start_index:start_index+chunk_size]
        count_occurrences(chunk, count_dict)
        start_index += chunk_size
    return count_dict
