import java.util.*;

public class PatternProgram {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter an integer n: ");
        int n = scanner.nextInt();

        List<Character> alphabet = new ArrayList<>();
        for (char c = 'A'; c <= 'Z'; c++) {
            alphabet.add(c);
        }

        Random random = new Random();

        for (int i = n; i >= 1; i--) {
            List<Character> line = new ArrayList<>();
            line.add('A');

            for (int j = 2; j <= i; j++) {
                int randomIndex = random.nextInt(alphabet.size() - 1) + 1;
                char randomChar = alphabet.remove(randomIndex);
                line.add(randomChar);
            }

            line.add('Z');

            for (char c : line) {
                System.out.print(c);
            }
            System.out.println();
        }
    }
}
```

