int setBit(int num, int N) {
    // Left shift 1 by N positions and perform bitwise OR operation with num
    return num | (1 << N);
}

int clearBit(int num, int N) {
    // Left shift 1 by N positions, complement it, and perform bitwise AND operation with num
    return num & ~(1 << N);
}

