class Shape:
    def getArea(self, length, width, shape_type):
        if length <= 0 or width <= 0:
            return "Invalid input: length and width must be positive integers."

        if shape_type == 'rectangle':
            return length * width
        elif shape_type == 'square':
            return length * length
        elif shape_type == 'triangle':
            return (length * width) / 2
        else:
            return "Invalid shape type."

    def getPerimeter(self, length, width, shape_type):
        if length <= 0 or width <= 0:
            return "Invalid input: length and width must be positive integers."

        if shape_type == 'rectangle':
            return 2 * (length + width)
        elif shape_type == 'square':
            return 4 * length
        elif shape_type == 'triangle':
            return length + width + ((length**2 + width**2)**0.5)
        else:
            return "Invalid shape type."
