def make_http_request(url, method, header):
    retries = 3
    for retry in range(retries):
        try:
            response = requests.request(method, url, headers=header, timeout=5)
            response.raise_for_status()  # Raise an exception for 4xx and 5xx errors
            return response
        except requests.exceptions.Timeout:
            print("Connection timeout occurred. Retrying...")
        except requests.exceptions.HTTPError as err:
            print(f"HTTP error occurred: {err}")
            break
        except requests.exceptions.RequestException as err:
            print(f"An error occurred: {err}")
            break

    print("Failed to make HTTP request after maximum retries.")
    return None

def parse_response(response):
    if response:
        try:
            status_code = response.status_code
            headers = response.headers
            body = response.json()
            return status_code, headers, body
        except ValueError as err:
            print(f"Failed to parse response JSON: {err}")

    return None, None, None

def validate_response(status_code, headers, body):
    if status_code and headers and body:
        if 200 <= status_code <= 299:
            content_type = headers.get('content-type')
            if content_type == 'application/json':
                return True
            else:
                print(f"Invalid content type. Expected 'application/json', got '{content_type}'")
        else:
            print(f"Invalid status code. Expected 2xx, got {status_code}")
    else:
        print("Invalid response")

    return False

