Here is a C++ program to delete a node from a doubly linked list at a given position without using any extra variables or loops:

```cpp
#include<iostream>

using namespace std;

struct Node {
    int data;
    Node* prev;
    Node* next;
};

// Function to create a new node
Node* createNode(int data) {
    Node* newNode = new Node();
    newNode->data = data;
    newNode->prev = NULL;
    newNode->next = NULL;
    return newNode;
}

// Function to delete a node at a given position
void deleteNode(Node** head, int position) {
    // Check if list is empty
    if (*head == NULL) {
        cout << "List is empty." << endl;
        return;
    }

    Node* temp = *head;

    // If position is 0, delete the head node
    if (position == 0) {
        *head = temp->next;
        if (*head != NULL)
            (*head)->prev = NULL;
        delete temp;
        return;
    }

    // Traverse to the given position
    for (int i = 0; temp != NULL && i < position - 1; i++) {
        temp = temp->next;
    }

    // Check if position is valid
    if (temp == NULL || temp->next == NULL) {
        cout << "Invalid position." << endl;
        return;
    }

    // Store the next node and the node to be deleted
    Node* nextNode = temp->next->next;
    Node* deleteNode = temp->next;

    // Change the next of previous node
    if (nextNode != NULL)
        nextNode->prev = temp;

    // Unlink the node from the list
    delete deleteNode;

    // Update the link of previous node
    temp->next = nextNode;
}

// Function to print the doubly linked list
void printList(Node* head) {
    Node* temp = head;

    while (temp != NULL) {
        cout << temp->data << " ";
        temp = temp->next;
    }

    cout << endl;
}

int main() {
    // Create a doubly linked list
    Node* head = createNode(84);
    Node* second = createNode(13);
    Node* third = createNode(25);
    Node* fourth = createNode(48);
    Node* fifth = createNode(50);

    // Connect the nodes
    head->next = second;
    second->prev = head;
    second->next = third;
    third->prev = second;
    third->next = fourth;
    fourth->prev = third;
    fourth->next = fifth;
    fifth->prev = fourth;

    // Print the original list
    cout << "Original List: ";
    printList(head);

    // Delete node at position 3
    int position = 3;
    deleteNode(&head, position);

    // Print the updated list
    cout << "Updated List: ";
    printList(head);

    return 0;
}
```

