console.log(findFirstOccurrence([1, 2, 2, 2, 3, 4, 4, 5, 5, 5], 2)); // Output: 1
console.log(findFirstOccurrence([1, 2, 2, 2, 3, 4, 4, 5, 5, 5], 4)); // Output: 5
console.log(findFirstOccurrence([1, 2, 2, 2, 3, 4, 4, 5, 5, 5], 5)); // Output: 7
console.log(findFirstOccurrence([1, 2, 2, 2, 3, 4, 4, 5, 5, 5], 6)); // Output: -1
```

