import React from 'react';

class TextComponent extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      text: props.text,
      isUpperCase: false,
      isLowerCase: false,
      characterCount: props.text.length,
      highlightCharacter: '',
      isHighlightOn: false,
    };
  }

  componentDidUpdate(prevProps) {
    if (prevProps.text !== this.props.text) {
      this.setState({ 
        text: this.props.text,
        characterCount: this.props.text.length,
      });
    }
  }

  toggleUpperCase = () => {
    const { text, isUpperCase } = this.state;
    if (text.toUpperCase() !== text) {
      this.setState({
        text: text.toUpperCase(),
        characterCount: text.toUpperCase().length,
        isUpperCase: true,
        isLowerCase: false,
      });
    }
  }

  toggleLowerCase = () => {
    const { text, isLowerCase } = this.state;
    if (text.toLowerCase() !== text) {
      this.setState({
        text: text.toLowerCase(),
        characterCount: text.toLowerCase().length,
        isLowerCase: true,
        isUpperCase: false,
      });
    }
  }

  toggleCase = () => {
    const { text, isUpperCase, isLowerCase } = this.state;
    if (isUpperCase) {
      this.setState({
        text: text.toLowerCase(),
        characterCount: text.toLowerCase().length,
        isUpperCase: false,
        isLowerCase: true,
      });
    } else if (isLowerCase) {
      this.setState({
        text: text.toUpperCase(),
        characterCount: text.toUpperCase().length,
        isUpperCase: true,
        isLowerCase: false,
      });
    }
  }

  handleHighlightToggle = () => {
    this.setState(prevState => ({
      isHighlightOn: !prevState.isHighlightOn,
    }));
  }

  handleInputChange = (event) => {
    const { text } = this.state;
    const { value } = event.target;
    this.setState({
      highlightCharacter: value,
      text: text.replace(new RegExp(value, 'g'), `<span class="highlight">${value}</span>`),
    });
  }

  render() {
    const { text, characterCount, isHighlightOn, highlightCharacter } = this.state;
    return (
      <div>
        <p dangerouslySetInnerHTML={{ __html: text }}></p>
        <button onClick={this.toggleUpperCase}>Convert to Uppercase</button>
        <button onClick={this.toggleLowerCase}>Convert to Lowercase</button>
        <button onClick={this.toggleCase}>Toggle Case</button>
        <p>Character Count: {characterCount}</p>
        <div>
          <input type="text" value={highlightCharacter} onChange={this.handleInputChange} />
          <button onClick={this.handleHighlightToggle}>{isHighlightOn ? 'Disable' : 'Enable'} Highlight</button>
        </div>
      </div>
    );
  }
}

export default TextComponent;

