```cpp
#include <iostream>

void reverseArray(int arr[], int start, int end) {
    if (start >= end)
        return;

    int temp = arr[start];
    arr[start] = arr[end];
    arr[end] = temp;

    reverseArray(arr, start + 1, end - 1);
}

void reverse(int arr[], int size) {
    reverseArray(arr, 0, size - 1);
}

