```python
class CircularQueue:
    def __init__(self):
        self.queue = [None] * 10
        self.front = -1
        self.rear = -1

    def enqueue(self, obj):
        if self.is_full():
            raise Exception("Queue is already full")
        if self.is_empty():
            self.front = 0
        self.rear = (self.rear + 1) % len(self.queue)
        self.queue[self.rear] = obj

    def dequeue(self):
        if self.is_empty():
            raise Exception("Queue is already empty")
        obj = self.queue[self.front]
        self.queue[self.front] = None
        if self.front == self.rear:
            self.front = -1
            self.rear = -1
        else:
            self.front = (self.front + 1) % len(self.queue)
        return obj

    def is_empty(self):
        return self.front == -1

    def is_full(self):
        return (self.rear + 1) % len(self.queue) == self.front

    def get_size(self):
        if self.is_empty():
            return 0
        if self.rear >= self.front:
            return self.rear - self.front + 1
        else:
            return len(self.queue) - self.front + self.rear + 1

    def get_front(self):
        if self.is_empty():
            raise Exception("Queue is already empty")
        return self.queue[self.front]

    def get_rear(self):
        if self.is_empty():
            raise Exception("Queue is already empty")
        return self.queue[self.rear]

    def contains(self, obj):
        return obj in self.queue

    def get_all(self):
        if self.is_empty():
            return []
        if self.rear >= self.front:
            return self.queue[self.front:self.rear + 1]
        else:
            return self.queue[self.front:] + self.queue[:self.rear + 1]
```

Note that I have converted the individual functions into methods of a `CircularQueue` class. This allows us to maintain the state of the queue (front and rear pointers) within the class itself. Additionally, I have modified the `enqueue` and `dequeue` methods to handle the circular nature of the queue by using modulo arithmetic.

You can test the implementation with the following code:

```python
