queue.enqueue(1)
queue.enqueue(2)
queue.enqueue(3)
queue.enqueue(4)
queue.enqueue(5)
print(queue.get_all())  # Expected output: [1, 2, 3, 4, 5]

queue.enqueue(6)
print(queue.get_all())  # Expected output: [1, 2, 3, 4, 5, 6]

queue.enqueue(7)  # Expected output: Exception: Queue is already full

queue.dequeue()
print(queue.get_all())  # Expected output: [2, 3, 4, 5, 6]

print(queue.get_front())  # Expected output: 2

print(queue.get_rear())  # Expected output: 6

print(queue.contains(3))  # Expected output: True

print(queue.contains(7))  # Expected output: False

print(queue.get_all())  # Expected output: [2, 3, 4, 5, 6]
