def get_fifth_prime(numbers, count=0, index=0):
    def is_prime(n):
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    if index >= len(numbers):
        return None

    if is_prime(numbers[index]):
        count += 1

    if count == 5:
        return numbers[index]

    return get_fifth_prime(numbers, count, index + 1)

