import random
import time

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_prime_numbers(n):
    prime_numbers = set()
    while len(prime_numbers) < n:
        num = random.randint(1, 10000)
        if is_prime(num):
            prime_numbers.add(num)
    return sorted(prime_numbers)

