function groupAndSum(arr, groupBy, sumBy, threshold = 0) {
  let result = {};

  for (let i = 0; i < arr.length; i++) {
    let obj = arr[i];

    // Check if salary is above the threshold
    if (obj.salary > threshold) {
      let key = obj[groupBy];

      // Check if the group already exists
      if (result[key]) {
        result[key] += obj[sumBy];
      } else {
        result[key] = obj[sumBy];
      }
    }
  }

  return result;
}

