Here is a Node.js program that finds the maximum and minimum items from an array, while ignoring duplicates, and also returns the indices of these numbers in the original array:

```javascript
function findMaxAndMin(arr) {
  let max = Number.NEGATIVE_INFINITY;
  let min = Number.POSITIVE_INFINITY;
  let maxIndex = -1;
  let minIndex = -1;

  // Create a set to store unique elements
  const uniqueSet = new Set();

  for (let i = 0; i < arr.length; i++) {
    // Ignore duplicates
    if (uniqueSet.has(arr[i])) {
      continue;
    }

    uniqueSet.add(arr[i]);

    // Check for new maximum
    if (arr[i] > max) {
      max = arr[i];
      maxIndex = i;
    }

    // Check for new minimum
    if (arr[i] < min) {
      min = arr[i];
      minIndex = i;
    }
  }

  return {
    maximum: max,
    indexOfMaximum: maxIndex,
    minimum: min,
    indexOfMinimum: minIndex
  };
}

