class BookCollection {
    private Map<String, Book> booksByIsbn;
    private Map<String, List<Book>> booksByAuthor;
    private List<Book> booksByPublicationDate;

    public BookCollection() {
        booksByIsbn = new HashMap<>();
        booksByAuthor = new HashMap<>();
        booksByPublicationDate = new ArrayList<>();
    }

    public void addBook(Book book) {
        if (booksByIsbn.containsKey(book.getIsbn())) {
            throw new IllegalArgumentException("Book with ISBN " + book.getIsbn() + " already exists.");
        }

        booksByIsbn.put(book.getIsbn(), book);

        List<Book> books = booksByAuthor.getOrDefault(book.getAuthors(), new ArrayList<>());
        books.add(book);
        booksByAuthor.put(book.getAuthors(), books);

        booksByPublicationDate.add(book);
        Collections.sort(booksByPublicationDate, Comparator.comparing(Book::getPublicationDate));
    }

    public void removeBook(String isbn) {
        Book book = booksByIsbn.get(isbn);
        if (book == null) {
            throw new NoSuchElementException("Book with ISBN " + isbn + " does not exist.");
        }

        booksByIsbn.remove(isbn);

        List<Book> books = booksByAuthor.get(book.getAuthors());
        books.remove(book);

        booksByPublicationDate.remove(book);
    }

    public Book searchBookByIsbn(String isbn) {
        Book book = booksByIsbn.get(isbn);
        if (book == null) {
            throw new NoSuchElementException("Book with ISBN " + isbn + " does not exist.");
        }
        return book;
    }

    public void updateBookByIsbn(String isbn, String authors, String publicationDate, int numberOfPages) {
        Book book = booksByIsbn.get(isbn);
        if (book == null) {
            throw new NoSuchElementException("Book with ISBN " + isbn + " does not exist.");
        }

        book.setAuthors(authors);
        book.setPublicationDate(publicationDate);
        book.setNumberOfPages(numberOfPages);

        List<Book> books = booksByAuthor.get(book.getAuthors());
        Collections.sort(books, Comparator.comparing(Book::getPublicationDate));
    }

    public int getTotalNumberOfBooks() {
        return booksByIsbn.size();
    }

    public List<Book> getBooksByAuthor(String authors) {
        List<Book> books = booksByAuthor.get(authors);
        if (books == null) {
            return Collections.emptyList();
        }
        return books;
    }

    public List<Book> sortBooksByPublicationDate() {
        return new ArrayList<>(booksByPublicationDate);
    }

    public boolean hasBookByIsbn(String isbn) {
        return booksByIsbn.containsKey(isbn);
    }
}

