#!/usr/bin/perl

use strict;
use warnings;

sub count_vowels {
    my ($string) = @_;

    my %vowels;
    while ($string =~ /([aeiou])/ig) {
        $vowels{lc $1}++;
    }

    return %vowels;
}

sub print_sorted_vowels {
    my (%vowels) = @_;

    my @sorted_vowels = sort { $vowels{$b} <=> $vowels{$a} } keys %vowels;
    foreach my $vowel (@sorted_vowels) {
        print "$vowel: $vowels{$vowel}\n";
    }
}

sub sum_ascii_values {
    my ($string) = @_;

    my $sum = 0;
    while ($string =~ /([aeiou])/ig) {
        $sum += ord(lc $1);
    }

    return $sum;
}

sub find_next_vowel {
    my ($string, $index) = @_;

    while ($index < length($string)) {
        my $char = substr($string, $index, 1);
        return $char if $char =~ /[aeiou]/i;
        $index++;
    }

    return undef;
}

sub main {
    print "Enter a string: ";
    my $string = <STDIN>;
    chomp $string;

    my $eighth_char = substr($string, 7, 1);
    if ($eighth_char =~ /[aeiou]/i) {
        print "8th character: $eighth_char\n";
    } else {
        my $next_vowel = find_next_vowel($string, 8);
        if (defined $next_vowel) {
            print "Next vowel after 8th character: $next_vowel\n";
        } else {
            print "No vowel found after 8th character\n";
        }
    }

    my %vowels = count_vowels($string);
    print_sorted_vowels(%vowels);

    my $sum = sum_ascii_values($string);
    print "Sum of ASCII values of vowels: $sum\n";
}

main();
