import java.util.Arrays;
import java.util.Comparator;
import java.util.Optional;
import java.util.function.Function;
import java.util.stream.Collectors;

public class MostRepeatedCharacter {

    public static void main(String[] args) {
        String[] strings = args;

        // Merge all strings into a single string
        String mergedString = Arrays.stream(strings)
                .collect(Collectors.joining());

        // Create a frequency map of characters
        Optional<Character> mostRepeatedChar = mergedString.chars()
                .mapToObj(c -> (char) c)
                .collect(Collectors.groupingBy(Function.identity(), Collectors.counting()))
                .entrySet().stream()
                .max(Comparator.comparingLong(entry -> entry.getValue()))
                .map(entry -> entry.getKey());

        if (mostRepeatedChar.isPresent()) {
            System.out.println("Most repeated character: " + mostRepeatedChar.get());
        } else {
            System.out.println("No repeated characters found.");
        }
    }
}
```

Explanation:
1. The `main` method accepts the command-line arguments as an array of strings.
2. The strings are merged into a single string using the `Collectors.joining` method.
3. The merged string is converted to a stream of characters and grouped by their frequency using the `Collectors.groupingBy` method. The result is a map where the keys are characters and the values are their frequencies.
4. The entry set of the frequency map is streamed, and the entry with the maximum value (frequency) is selected using the `max` method and a custom comparator.
5. The most repeated character, if present, is extracted from the optional result using the `map` method.
6. Finally, the result is printed to the console.

