        Scanner scanner = new Scanner(System.in);

        System.out.println("Enter color(s) separated by commas:");
        String input = scanner.nextLine();

        String[] colors = input.split(",");

        for (String color : colors) {
            color = color.trim().toLowerCase();

            if (isValidColor(color)) {
                if (isPrimaryColor(color)) {
                    System.out.println(color + " is a primary color.");
                } else {
                    System.out.println(color + " is a secondary color.");
                }
            } else {
                System.out.println(color + " is not a valid color.");
            }
        }
    }

    public static boolean isValidColor(String color) {
        String[] validColors = {"red", "blue", "yellow", "green", "orange", "purple"};

        for (String validColor : validColors) {
            if (validColor.equals(color)) {
                return true;
            }
        }

        return false;
    }

    public static boolean isPrimaryColor(String color) {
        String[] primaryColors = {"red", "blue", "yellow"};

        for (String primaryColor : primaryColors) {
            if (primaryColor.equals(color)) {
                return true;
            }
        }

        return false;
    }
}

