find_max <- function(vec) {
  if (is.null(vec) || length(vec) == 0) {
    return(NA)
  }

  max_val <- -Inf
  for (elem in vec) {
    if (is.na(elem)) {
      next
    }

    if (is.character(elem)) {
      ascii_vals <- sapply(strsplit(elem, ""), function(x) as.numeric(charToRaw(x)))
      max_elem <- max(ascii_vals, na.rm = TRUE)
    } else if (is.list(elem) || is.vector(elem)) {
      max_elem <- find_max(elem)
    } else {
      max_elem <- elem
    }

    if (max_elem > max_val) {
      max_val <- max_elem
    }
  }

  return(max_val)
}
