Here is an implementation of a 3-dimensional point class in Python:

```python
import math

class Point3D:
    def __init__(self, x, y, z):
        self.x = x
        self.y = y
        self.z = z

    def get_x(self):
        return self.x

    def set_x(self, x):
        self.x = x

    def get_y(self):
        return self.y

    def set_y(self, y):
        self.y = y

    def get_z(self):
        return self.z

    def set_z(self, z):
        self.z = z

    def distance(self, other):
        return math.sqrt((self.x - other.get_x())**2 + (self.y - other.get_y())**2 + (self.z - other.get_z())**2)

    def midpoint(self, other):
        mid_x = (self.x + other.get_x()) / 2
        mid_y = (self.y + other.get_y()) / 2
        mid_z = (self.z + other.get_z()) / 2
        return Point3D(mid_x, mid_y, mid_z)

    def dot_product(self, other):
        return self.x * other.get_x() + self.y * other.get_y() + self.z * other.get_z()

    def cross_product(self, other):
        cross_x = self.y * other.get_z() - self.z * other.get_y()
        cross_y = self.z * other.get_x() - self.x * other.get_z()
        cross_z = self.x * other.get_y() - self.y * other.get_x()
        return Point3D(cross_x, cross_y, cross_z)

    def __eq__(self, other):
        return self.x == other.get_x() and self.y == other.get_y() and self.z == other.get_z()

    def serialize(self):
        return {'x': self.x, 'y': self.y, 'z': self.z}

    @classmethod
    def deserialize(cls, data):
        return cls(data['x'], data['y'], data['z'])

    def rotate(self, angle, axis):
        radians = math.radians(angle)
        sin_val = math.sin(radians)
        cos_val = math.cos(radians)

        if axis == 'x':
            new_y = self.y * cos_val - self.z * sin_val
            new_z = self.y * sin_val + self.z * cos_val
            self.y = new_y
            self.z = new_z
        elif axis == 'y':
            new_x = self.x * cos_val + self.z * sin_val
            new_z = -self.x * sin_val + self.z * cos_val
            self.x = new_x
            self.z = new_z
        elif axis == 'z':
            new_x = self.x * cos_val - self.y * sin_val
            new_y = self.x * sin_val + self.y * cos_val
            self.x = new_x
            self.y = new_y

    def translate(self, vector):
        self.x += vector.get_x()
        self.y += vector.get_y()
        self.z += vector.get_z()

    def scale(self, factor):
        self.x *= factor
        self.y *= factor
        self.z *= factor

    def angle_between(self, other):
        dot_product = self.dot_product(other)
        magnitude_product = self.magnitude() * other.magnitude()
        return math.degrees(math.acos(dot_product / magnitude_product))

    def magnitude(self):
        return math.sqrt(self.x**2 + self.y**2 + self.z**2)

    def __lt__(self, other):
        return self.magnitude() < other.magnitude()

    def project_on_plane(self, plane_normal):
        dot_product = self.dot_product(plane_normal)
        magnitude_square = plane_normal.magnitude()**2
        scale_factor = dot_product / magnitude_square
        projection = plane_normal.copy()
        projection.scale(scale_factor)
        return projection

    def intersection_with_plane(self, plane_normal, plane_point):
        t = (plane_normal.get_x() * (plane_point.get_x() - self.x) +
             plane_normal.get_y() * (plane_point.get_y() - self.y) +
             plane_normal.get_z() * (plane_point.get_z() - self.z)) / (plane_normal.magnitude()**2)
        intersect_x = self.x + t * plane_normal.get_x()
        intersect_y = self.y + t * plane_normal.get_y()
        intersect_z = self.z + t * plane_normal.get_z()
        return Point3D(intersect_x, intersect_y, intersect_z)

    def reflection_across_plane(self, plane_normal, plane_point):
        intersection = self.intersection_with_plane(plane_normal, plane_point)
        reflection_x = self.x - 2 * (intersection.get_x() - self.x)
        reflection_y = self.y - 2 * (intersection.get_y() - self.y)
        reflection_z = self.z - 2 * (intersection.get_z() - self.z)
        return Point3D(reflection_x, reflection_y, reflection_z)

    def rotate_around_arbitrary_axis(self, angle, axis_point, axis_direction):
        axis_vector = axis_direction.copy()
        axis_vector.scale(self.distance(axis_point))
        self.translate(axis_point)
        self.rotate(angle, 'x')
        self.rotate(angle, 'y')
        self.rotate(angle, 'z')
        self.translate(axis_vector)

    def angle_between_line_and_plane(self, line_direction, plane_normal):
        dot_product = abs(self.dot_product(plane_normal))
        magnitude_product = self.magnitude() * line_direction.magnitude()
        return math.degrees(math.acos(dot_product / magnitude_product))
```

Note that the implementation assumes that there is a separate Vector3D class that has the necessary operations and methods such as `magnitude()`, `scale()`, `copy()`, etc.

