```php
<?php

function generateChecksum($input) {
    $characters = str_split($input);
    $runningTotal = 0;

    foreach ($characters as $character) {
        $asciiValue = ord($character);

        if ($asciiValue % 2 == 0) {
            $runningTotal += pow($asciiValue, 2);
        } else {
            $runningTotal += $asciiValue * 3;
        }
    }

    $checksum = round(sqrt($runningTotal));
    return $checksum;
}

