public class SumOfNumbers {
    public static int sum(int n) {
        // Base case: if n is 0, return 0
        if (n == 0) {
            return 0;
        }
        // Recursive case: add n to the sum of all numbers from 1 to n-1
        return n + sum(n - 1);
    }

