```java
import java.util.ArrayList;
import java.util.Date;
import java.util.List;

public class BankAccount {
    private double balance;
    private String name;
    private int accountNumber;
    private List<Transaction> transactionHistory;

    public BankAccount(String name, int accountNumber) {
        this.name = name;
        this.accountNumber = accountNumber;
        this.balance = 0.0;
        this.transactionHistory = new ArrayList<>();
    }

    public void deposit(double amount) throws IllegalArgumentException {
        if (amount <= 0) {
            throw new IllegalArgumentException("Deposit amount must be positive.");
        }
        balance += amount;
        transactionHistory.add(new Transaction(new Date(), amount, "Deposit"));
    }

    public void withdraw(double amount) throws IllegalArgumentException, InsufficientFundsException {
        if (amount <= 0) {
            throw new IllegalArgumentException("Withdrawal amount must be positive.");
        }
        if (amount > balance) {
            throw new InsufficientFundsException("Insufficient funds for withdrawal.");
        }
        balance -= amount;
        transactionHistory.add(new Transaction(new Date(), amount, "Withdrawal"));
    }

    public double calculateInterest(double interestRate) {
        return balance * interestRate;
    }

    public void transfer(BankAccount receiver, double amount) throws IllegalArgumentException, InsufficientFundsException {
        if (amount <= 0) {
            throw new IllegalArgumentException("Transfer amount must be positive.");
        }
        if (receiver == null) {
            throw new IllegalArgumentException("Receiver account does not exist.");
        }
        if (amount > balance) {
            throw new InsufficientFundsException("Insufficient funds for transfer.");
        }
        withdraw(amount);
        receiver.deposit(amount);
    }

    public List<Transaction> getTransactionHistory() {
        return transactionHistory;
    }

    public double getBalance() {
        return balance;
    }

    public String getName() {
        return name;
    }

    public int getAccountNumber() {
        return accountNumber;
    }

    public class Transaction {
        private Date date;
        private double amount;
        private String type;

        public Transaction(Date date, double amount, String type) {
            this.date = date;
            this.amount = amount;
            this.type = type;
        }

        public Date getDate() {
            return date;
        }

        public double getAmount() {
            return amount;
        }

        public String getType() {
            return type;
        }
    }
}

public class InsufficientFundsException extends Exception {
    public InsufficientFundsException(String message) {
        super(message);
    }
}
```

