```
import java.util.ArrayList;
import java.util.List;

public class CombinationFinder {
    public static void main(String[] args) {
        int[] lst = {1, 2, 3, 4};
        int targetSum = 5;
        int maxLength = 3;

        List<List<Integer>> combinations = findCombinations(lst, targetSum, maxLength);
        for (List<Integer> combination : combinations) {
            System.out.println(combination);
        }
    }

    public static List<List<Integer>> findCombinations(int[] lst, int targetSum, int maxLength) {
        List<List<Integer>> combinations = new ArrayList<>();
        List<Integer> currentCombination = new ArrayList<>();
        findCombinationsHelper(lst, targetSum, maxLength, 0, currentCombination, combinations);
        return combinations;
    }

    public static void findCombinationsHelper(int[] lst, int targetSum, int maxLength, int index,
                                              List<Integer> currentCombination, List<List<Integer>> combinations) {
        if (targetSum <= 0 || maxLength == 0) {
            return;
        }

        for (int i = index; i < lst.length; i++) {
            currentCombination.add(lst[i]);
            int sum = getSum(currentCombination);

            if (sum > targetSum && currentCombination.size() <= maxLength && containsOddAndEven(currentCombination)) {
                combinations.add(new ArrayList<>(currentCombination));
            }

            if (currentCombination.size() < maxLength) {
                findCombinationsHelper(lst, targetSum, maxLength, i + 1, currentCombination, combinations);
            }

            currentCombination.remove(currentCombination.size() - 1);
        }
    }

    public static int getSum(List<Integer> combination) {
        int sum = 0;
        for (int num : combination) {
            sum += num;
        }
        return sum;
    }

    public static boolean containsOddAndEven(List<Integer> combination) {
        boolean oddFound = false;
        boolean evenFound = false;
        for (int num : combination) {
            if (num % 2 == 0) {
                evenFound = true;
            } else {
                oddFound = true;
            }
        }
        return oddFound && evenFound;
    }
}
```

The algorithm uses a recursive helper function, `findCombinationsHelper`, to generate all possible combinations of the given list of numbers. It keeps track of the current combination being built using a `currentCombination` list. 

At each step, it checks if the current combination satisfies the given requirements: the sum of the numbers must be greater than the target sum, the length of the combination must be less than or equal to the maximum length, and the combination must have at least one odd number and exactly one even number. If these conditions are met, the combination is added to the `combinations` list.

The algorithm also includes two utility functions: `getSum` calculates the sum of the numbers in a combination, and `containsOddAndEven` checks if a combination has at least one odd number and exactly one even number.

The main function `findCombinations` initializes the `combinations` list and the `currentCombination` list, and calls the `findCombinationsHelper` function to start the recursive process. Finally, it returns the `combinations` list.

