};

// Function to check if a year is a leap year
bool isLeapYear(int year) {
    if (year % 4 == 0) {
        if (year % 100 == 0) {
            if (year % 400 == 0) {
                return true;
            }
            return false;
        }
        return true;
    }
    return false;
}

// Function to get the number of days in a month
int getDaysInMonth(int month, int year) {
    if (month == 2) {
        if (isLeapYear(year)) {
            return 29;
        }
        return 28;
    }
    else if (month == 4 || month == 6 || month == 9 || month == 11) {
        return 30;
    }
    else {
        return 31;
    }
}

// Function to validate a date
bool isValidDate(int day, int month, int year) {
    if (year < 1900 || year > 2099) {
        return false;
    }
    if (month < 1 || month > 12) {
        return false;
    }
    if (day < 1 || day > getDaysInMonth(month, year)) {
        return false;
    }
    return true;
}

// Function to validate a time zone offset
bool isValidTimeZoneOffset(int offset) {
    if (offset < -12 || offset > 12) {
        return false;
    }
    return true;
}

// Function to calculate the difference between two dates
int calculateDateDifference(const DateTime& date1, const DateTime& date2) {
    struct std::tm timeinfo1 = { 0 };
    timeinfo1.tm_year = date1.date.year - 1900;
    timeinfo1.tm_mon = date1.date.month - 1;
    timeinfo1.tm_mday = date1.date.day;
    timeinfo1.tm_hour = date1.time.hours;
    timeinfo1.tm_min = date1.time.minutes;
    timeinfo1.tm_sec = date1.time.seconds;
    std::time_t time1 = std::mktime(&timeinfo1);

    struct std::tm timeinfo2 = { 0 };
    timeinfo2.tm_year = date2.date.year - 1900;
    timeinfo2.tm_mon = date2.date.month - 1;
    timeinfo2.tm_mday = date2.date.day;
    timeinfo2.tm_hour = date2.time.hours;
    timeinfo2.tm_min = date2.time.minutes;
    timeinfo2.tm_sec = date2.time.seconds;
    std::time_t time2 = std::mktime(&timeinfo2);

    int difference = std::difftime(time2, time1);
    return difference;
}

int main() {
    // Read input dates and time zones
    DateTime date1, date2;
    std::cout << "Enter Date 1 (DD MM YYYY): ";
