        !isValidDate(date2.date.day, date2.date.month, date2.date.year)) {
        std::cout << "Invalid input date. Please enter a valid date between January 1, 1900, and December 31, 2099." << std::endl;
        return 0;
    }
    if (!isValidTimeZoneOffset(date1.timeZoneOffset) ||
        !isValidTimeZoneOffset(date2.timeZoneOffset)) {
        std::cout << "Invalid time zone offset. Please enter a valid offset between -12 and +12." << std::endl;
        return 0;
    }

    // Calculate date difference
    int difference = calculateDateDifference(date1, date2);

    // Display the date difference
    std::cout << "Difference between Date 1 and Date 2: " << difference << " seconds" << std::endl;

    return 0;
}
