Here is an implementation of a circular doubly linked list in C language:

```c
#include <stdio.h>
#include <stdlib.h>

// Structure for a node
struct Node {
    int data;
    struct Node* next;
    struct Node* prev;
};

// Function to create a new node
struct Node* createNode(int data) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = data;
    newNode->next = NULL;
    newNode->prev = NULL;
    return newNode;
}

// Function to insert a node at the beginning of the list
void insertAtBeginning(struct Node** head, int data) {
    struct Node* newNode = createNode(data);
    if (*head == NULL) {
        *head = newNode;
        (*head)->next = *head;
        (*head)->prev = *head;
        return;
    }
    newNode->next = *head;
    newNode->prev = (*head)->prev;
    (*head)->prev->next = newNode;
    (*head)->prev = newNode;
    *head = newNode;
}

// Function to insert a node at the end of the list
void insertAtEnd(struct Node** head, int data) {
    struct Node* newNode = createNode(data);
    if (*head == NULL) {
        *head = newNode;
        (*head)->next = *head;
        (*head)->prev = *head;
        return;
    }
    newNode->next = *head;
    newNode->prev = (*head)->prev;
    (*head)->prev->next = newNode;
    (*head)->prev = newNode;
}

// Function to delete a node with a given value from the list
void deleteNode(struct Node** head, int key) {
    if (*head == NULL)
        return;
    struct Node* curr = *head;
    struct Node* prev = NULL;
    while (curr->data != key) {
        if (curr->next == *head) {
            printf("Node with the given value does not exist in the list.\n");
            return;
        }
        prev = curr;
        curr = curr->next;
    }
    if (curr->next == *head && prev == NULL) {
        *head = NULL;
        free(curr);
        return;
    }
    if (curr == *head) {
        prev = (*head)->prev;
        *head = (*head)->next;
        prev->next = *head;
        (*head)->prev = prev;
    } else if (curr->next == *head) {
        prev->next = *head;
        (*head)->prev = prev;
    } else {
        struct Node* temp = curr->next;
        prev->next = temp;
        temp->prev = prev;
    }
    free(curr);
}

// Function to search for a node with a given value in the list
void searchNode(struct Node* head, int key) {
    if (head == NULL) {
        printf("List is empty.\n");
        return;
    }
    struct Node* curr = head;
    do {
        if (curr->data == key) {
            printf("Node with the given value exists in the list.\n");
            return;
        }
        curr = curr->next;
    } while (curr != head);
    printf("Node with the given value does not exist in the list.\n");
}

// Function to print all the elements of the list in forward order
void printListForward(struct Node* head) {
    if (head == NULL) {
        printf("List is empty.\n");
        return;
    }
    struct Node* curr = head;
    do {
        printf("%d ", curr->data);
        curr = curr->next;
    } while (curr != head);
    printf("\n");
}

// Function to print all the elements of the list in backward order
void printListBackward(struct Node* head) {
    if (head == NULL) {
        printf("List is empty.\n");
        return;
    }
    struct Node* curr = head->prev;
    do {
        printf("%d ", curr->data);
        curr = curr->prev;
    } while (curr != head->prev);
    printf("\n");
}

// Function to reverse the circular doubly linked list
void reverseList(struct Node** head) {
    if (*head == NULL) {
