import java.util.concurrent.TimeUnit;

public class RandomIdGenerator {

    public static void main(String[] args) {
        String id = generateRandomId();
        System.out.println("Random ID: " + id);
    }

    public static String generateRandomId() {
        long currentTime = System.currentTimeMillis();
        long nanos = System.nanoTime() % 1000000;

        // Concatenate current time in milliseconds and nanoseconds
        String id = String.valueOf(currentTime) + String.valueOf(nanos);

        // If the concatenated ID is less than 20 digits, append random digits
        if (id.length() < 20) {
            int remainingDigits = 20 - id.length();
            for (int i = 0; i < remainingDigits; i++) {
                int randomDigit = (int) (Math.random() * 10);
                id += randomDigit;
            }
        }

        return id;
    }
}
