                calculate();
            }
        });

        add(panel);
        setVisible(true);
    }

    private void calculate() {
        try {
            int firstNumber = Integer.parseInt(firstNumberField.getText());
            int secondNumber = Integer.parseInt(secondNumberField.getText());

            if (isPrime(firstNumber) && isPrime(secondNumber)) {
                List<Integer> primes = findPrimes(firstNumber, secondNumber);
                if (primes.size() == 2) {
                    int lowerPrime = primes.get(0);
                    int upperPrime = primes.get(1);
                    if (lowerPrime < firstNumber && upperPrime > secondNumber) {
                        int result = (int) Math.pow(firstNumber, secondNumber);
                        resultLabel.setText(String.valueOf(result));
                    } else {
                        showError("Input numbers are not within the specified range.");
                    }
                } else {
                    showError("Could not find the specified range.");
                }
            } else {
                showError("Input numbers are not prime.");
            }
        } catch (NumberFormatException e) {
            showError("Invalid input format.");
        }
    }

    private List<Integer> findPrimes(int firstNumber, int secondNumber) {
        List<Integer> primes = new ArrayList<>();
        int lowerPrime = 0;
        int upperPrime = 0;
        for (int i = firstNumber - 1; i >= 2; i--) {
            if (isPrime(i)) {
                lowerPrime = i;
                break;
            }
        }
        for (int i = secondNumber + 1; ; i++) {
            if (isPrime(i)) {
                upperPrime = i;
                break;
            }
        }
        primes.add(lowerPrime);
        primes.add(upperPrime);
        return primes;
    }

    private boolean isPrime(int number) {
        if (number <= 1) {
            return false;
        }
        if (number <= 3) {
            return true;
        }
        if (number % 2 == 0 || number % 3 == 0) {
            return false;
        }
        int sqrt = (int) Math.sqrt(number);
        for (int i = 5; i <= sqrt; i += 6) {
            if (number % i == 0 || number % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }

    private void showError(String message) {
        JOptionPane.showMessageDialog(this, message, "Error", JOptionPane.ERROR_MESSAGE);
        resultLabel.setText("");
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(new Runnable() {
            @Override
            public void run() {
                new PrimePowerCalculator();
            }
        });
    }
}
