fn convert_to_title_case(input: &str) -> String {
    let mut result = String::new();
    let mut prev_char = ' ';

    for c in input.chars() {
        if c.is_alphabetic() {
            if prev_char.is_whitespace() || prev_char == '-' || prev_char == '\'' {
                result.push(c.to_ascii_uppercase());
            } else {
                result.push(c.to_ascii_lowercase());
            }
        } else {
            result.push(c);
        }
        prev_char = c;
    }

    result
}
