import random
import string
import math

def is_prime(n, k=5):
    """Check if a number is prime using Miller-Rabin primality test algorithm."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False

    def witness(a, s, d, n):
        x = pow(a, d, n)
        if x == 1 or x == n - 1:
            return False
        for _ in range(s - 1):
            x = pow(x, 2, n)
            if x == n - 1:
                return False
        return True

    s = 0
    d = n - 1
    while d % 2 == 0:
        d //= 2
        s += 1

    for _ in range(k):
        a = random.randint(2, n - 1)
        if witness(a, s, d, n):
            return False
    return True

def generate_prime_numbers():
    """Generate a list of 5 unique prime numbers."""
    primes = []
    while len(primes) < 5:
        num = random.randint(10, 100)
        if is_prime(num):
            primes.append(num)
    return primes

def generate_random_string(length=5):
    """Generate a random alphanumeric string of given length."""
    letters = string.ascii_letters + string.digits
    return ''.join(random.choice(letters) for _ in range(length))

