#include <stdio.h>

void fibonacci(int n) {
    int a = 0, b = 1, c;

    printf("Fibonacci Series up to %d: ", n);

    // Print first two terms
    printf("%d %d ", a, b);

    // Generate and print the Fibonacci sequence
