```php
function capitalizeWords($input) {
    $input = trim($input); // remove leading and trailing spaces
    $words = explode(" ", $input); // split the input string into an array of words

    // loop through each word and capitalize the first letter
    foreach ($words as &$word) {
        if (ctype_alpha($word[0])) { // check if the first character is a letter
            $word[0] = strtoupper($word[0]); // capitalize the first letter
        }
    }

    // join the words array back into a string
    $output = implode(" ", $words);

    if (ctype_alpha($output[0])) { // check if the first character of the output is a letter
        $output[0] = strtoupper($output[0]); // capitalize the first letter
    }

    return $output;
}
```

