function findCommonKeys(array1, array2) {
  // Filter objects with age > 18
  const filteredArray1 = array1.filter(obj => obj.age > 18);
  const filteredArray2 = array2.filter(obj => obj.age > 18);

  // Exclude objects with a name containing vowels
  const filteredArray1WithoutVowels = filteredArray1.filter(obj => !(/[aeiou]/i).test(obj.name));
  const filteredArray2WithoutVowels = filteredArray2.filter(obj => !(/[aeiou]/i).test(obj.name));

  // Find common keys
  const commonKeys = [];
  for (let obj1 of filteredArray1WithoutVowels) {
    for (let obj2 of filteredArray2WithoutVowels) {
      if (obj1.name === obj2.name) {
        commonKeys.push(obj1.name);
        break;
      }
    }
  }

  // Sort common keys in descending order based on name
  commonKeys.sort((a, b) => b.localeCompare(a));

  return commonKeys;
}

