import java.util.*;

public class StringSort {

    public static void main(String[] args) {
        List<String> strings = Arrays.asList("Apple", "banana", "Cherry", "date", "grape");
        List<String> sortedStrings = sortStrings(strings);
        System.out.println(sortedStrings);
    }

    public static List<String> sortStrings(List<String> strings) {
        Collections.sort(strings, new Comparator<String>() {
            @Override
            public int compare(String s1, String s2) {
                String normalizedS1 = normalizeString(s1);
                String normalizedS2 = normalizeString(s2);

                int result = normalizedS1.compareToIgnoreCase(normalizedS2);
                if (result == 0) {
                    result = s2.length() - s1.length();
                }

                return result;
            }
        });

        return strings;
    }

    public static String normalizeString(String s) {
        return s.replaceAll("[^a-zA-Z]", "");
    }
}

