def primes_up_to_n(n):
    if n <= 1:
        return []

    # Helper function to check if a number is prime using trial division
    def is_prime(num):
        if num in prime_cache:
            return prime_cache[num]
        if num <= 1:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                prime_cache[num] = False
                return False
        prime_cache[num] = True
        return True

    # Helper function to generate all possible prime factors of a number
    def prime_factors(num):
        if num in factors_cache:
            return factors_cache[num]
        factors = []
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                factors.extend(prime_factors(i))
                factors.extend(prime_factors(num // i))
                break
        else:
            factors = [num]
        factors_cache[num] = factors
        return factors

    prime_cache = {}
    factors_cache = {}
    primes = []
    for i in range(2, n + 1):
        if is_prime(i):
            primes.append(i)
    return primes
```

