    if not dictionary:
        return None

    # Check if key is a string
    if not isinstance(key, str):
        return None

    # Check if key is empty
    if not key:
        return None

    # Check if key contains invalid characters
    if not key.isalnum():
        return None

    # Split key into nested keys
    keys = key.split('.')

    # Iterate through nested keys
    for k in keys:
        # Check if key is present in dictionary
        if k in dictionary:
            dictionary = dictionary[k]
        # Check if key is present in list
        elif isinstance(dictionary, list):
            try:
                index = int(k)
                dictionary = dictionary[index]
            except:
                return None
        else:
