Here is an example implementation of a function in JavaScript that reads a CSV file and returns an array of objects:

```javascript
const fs = require('fs');

function readCSVFile(filePath) {
  try {
    // Read the contents of the CSV file
    const csvData = fs.readFileSync(filePath, 'utf-8');

    // Split the data into rows
    const rows = csvData.trim().split('\n');

    // Get the header row and extract the column names
    const headerRow = rows.shift().split(',');
    const columns = headerRow.map(columnName => columnName.trim());

    // Parse each row into an object
    const data = rows.map(row => {
      const values = row.split(',');
      if (values.length !== columns.length) {
        throw new Error('Number of values in row does not match number of columns');
      }
      return values.reduce((obj, value, index) => {
        obj[columns[index]] = value.trim();
        return obj;
      }, {});
    });

    return data;
  } catch (error) {
    throw new Error('Failed to read CSV file: ' + error.message);
  }
}
```

You can use this function by providing the path of the CSV file as the argument. It will return an array of objects, where each object represents a row in the file. If any errors occur during the process, it will throw a custom exception with a descriptive error message.

