```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>
#include <unordered_map>

class StringReverser {
private:
    std::string inputString;
    std::string reversedString;
    std::unordered_map<char, int> characterCounts;
    int totalStrings;
    int totalLength;

public:
    StringReverser() {
        totalStrings = 0;
        totalLength = 0;
    }

    void readInputStrings(const std::string& filename) {
        std::ifstream inputFile(filename);
        std::string line;
        while (std::getline(inputFile, line)) {
            processString(line);
        }
        inputFile.close();
    }

    void processString(const std::string& str) {
        totalStrings++;
        totalLength += str.length();
        inputString = str;
        reverseString();
        countCharacters();
        printOutput();
    }

    void reverseString() {
        reversedString = inputString;
        std::reverse(reversedString.begin(), reversedString.end());
    }

    void countCharacters() {
        characterCounts.clear();
        for (char c : inputString) {
            if (std::isalpha(c) || std::isspace(c)) {
                characterCounts[c]++;
            }
        }
    }

    void printOutput() {
        std::cout << "Reversed String: " << reversedString << std::endl;
        std::cout << "Unique Characters: ";
        for (auto it = characterCounts.begin(); it != characterCounts.end(); ++it) {
            std::cout << it->first << "(" << it->second << ") ";
        }
        std::cout << std::endl;
    }

    double calculateAverageLength() {
        return (double)totalLength / totalStrings;
    }
};

int main() {
    StringReverser stringReverser;
    stringReverser.readInputStrings("input.txt");
    double averageLength = stringReverser.calculateAverageLength();
    std::cout << "Average Length of Input Strings: " << averageLength << std::endl;

    return 0;
}
```

