```javascript
function findShortestWord(sentence) {
  // Remove special characters and convert to lowercase
  const cleanedSentence = sentence.replace(/[^\w\s]|_/g, "").toLowerCase();

  // Split sentence into words
  const words = cleanedSentence.split(" ");

  // Filter words based on conditions
  const filteredWords = words.filter(word => 
    word.length > 3 && 
    word.match(/[aeiou]/i) !== null && 
    word.match(/[A-Z]/) === null
  );

  // Find the shortest word
  let shortestWord = filteredWords[0];
  for (let i = 1; i < filteredWords.length; i++) {
    if (filteredWords[i].length < shortestWord.length) {
      shortestWord = filteredWords[i];
    }
  }

  return shortestWord;
}

