void printCombinations(char str1[], char str2[]) {
    int len1 = strlen(str1);
    int len2 = strlen(str2);
    int i, j, k;

    // Checking if first string contains at least one uppercase letter
    int hasUppercase = 0;
    for (i = 0; i < len1; i++) {
        if (str1[i] >= 'A' && str1[i] <= 'Z') {
            hasUppercase = 1;
            break;
        }
    }

    // Checking if second string contains at least one special character
    int hasSpecialChar = 0;
    for (i = 0; i < len2; i++) {
        if (str2[i] == '!' || str2[i] == '@' || str2[i] == '#' || str2[i] == '$' ||
            str2[i] == '%' || str2[i] == '^' || str2[i] == '&' || str2[i] == '*') {
            hasSpecialChar = 1;
            break;
        }
    }

    // Printing combinations in reverse order
    if (hasUppercase && hasSpecialChar) {
        for (i = len1 - 1; i >= 0; i--) {
            for (j = len2 - 1; j >= 0; j--) {
                printf("%c%c\n", str1[i], str2[j]);
            }
        }
    }
    else {
        printf("No valid combinations found.\n");
    }
}

