import React, { useState } from 'react';
import { Table, TableHead, TableBody, TableRow, TableCell, TextField, InputAdornment, IconButton } from '@material-ui/core';
import { Search, Sort } from '@material-ui/icons';

const DataTable = ({ data }) => {
  const [filterValues, setFilterValues] = useState({});
  const [sortColumn, setSortColumn] = useState(null);
  const [sortDirection, setSortDirection] = useState('asc');

  const handleFilterChange = (e, column) => {
    const { value } = e.target;
    setFilterValues((prevFilterValues) => ({
      ...prevFilterValues,
      [column]: value
    }));
  };

  const handleSort = (column) => {
    if (column === sortColumn) {
      setSortDirection((prevSortDirection) => (prevSortDirection === 'asc' ? 'desc' : 'asc'));
    } else {
      setSortColumn(column);
      setSortDirection('asc');
    }
  };

  const filteredData = data.filter((row) => {
    return Object.keys(filterValues).every((column) => {
      if (!filterValues[column]) return true;
      return row[column].toString().toLowerCase().includes(filterValues[column].toLowerCase());
    });
  });

  const sortedData = filteredData.sort((a, b) => {
    if (sortColumn) {
      if (sortDirection === 'asc') {
        return a[sortColumn] - b[sortColumn];
      } else {
        return b[sortColumn] - a[sortColumn];
      }
    }
    return 0;
  });

  return (
    <Table>
      <TableHead>
        <TableRow>
          <TableCell>
            <TextField
              size="small"
              onChange={(e) => handleFilterChange(e, 'id')}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <Search />
                  </InputAdornment>
                )
              }}
            />
          </TableCell>
          <TableCell>
            <TextField
              size="small"
              onChange={(e) => handleFilterChange(e, 'name')}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <Search />
                  </InputAdornment>
                )
              }}
            />
          </TableCell>
          <TableCell>
            <TextField
              size="small"
              onChange={(e) => handleFilterChange(e, 'age')}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <Search />
                  </InputAdornment>
                )
              }}
            />
          </TableCell>
          <TableCell>
            <TextField
              size="small"
              onChange={(e) => handleFilterChange(e, 'salary')}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <Search />
                  </InputAdornment>
                )
              }}
            />
          </TableCell>
        </TableRow>
        <TableRow>
          <TableCell onClick={() => handleSort('id')}>
            ID {sortColumn === 'id' && <Sort />}
          </TableCell>
          <TableCell onClick={() => handleSort('name')}>
            Name {sortColumn === 'name' && <Sort />}
          </TableCell>
          <TableCell onClick={() => handleSort('age')}>
            Age {sortColumn === 'age' && <Sort />}
          </TableCell>
          <TableCell onClick={() => handleSort('salary')}>
            Salary {sortColumn === 'salary' && <Sort />}
          </TableCell>
        </TableRow>
      </TableHead>
      <TableBody>
        {sortedData.map((row) => (
          <TableRow key={row.id}>
            <TableCell>{row.id}</TableCell>
            <TableCell>{row.name}</TableCell>
            <TableCell>{row.age}</TableCell>
            <TableCell>{row.salary}</TableCell>
          </TableRow>
        ))}
      </TableBody>
    </Table>
  );
};

export default DataTable;
