function getType(variable) {
  const type = typeof variable;

  // Check for primitives
  if (type !== 'object' || variable === null) {
    return type;
  }

  // Handle circular references
  const circularRefs = new WeakSet();
  function detectCircularReferences(obj) {
    if (circularRefs.has(obj)) {
      return '[Circular Reference]';
    }
    circularRefs.add(obj);
    return false;
  }

  // Handle custom types
  const customTypes = new Map();
  function detectCustomTypes(obj) {
    for (const [typeName, typeChecker] of customTypes) {
      if (typeChecker(obj)) {
        return typeName;
      }
    }
    return false;
  }

  // Check for arrays
  if (Array.isArray(variable)) {
    const circularRef = detectCircularReferences(variable);
    if (circularRef) {
      return circularRef;
    }
    const customType = detectCustomTypes(variable);
    if (customType) {
      return customType;
    }
    const nestedTypes = variable.map(getType);
    return `Array[${nestedTypes.join(', ')}]`;
  }

  // Check for objects
  if (type === 'object') {
    const circularRef = detectCircularReferences(variable);
    if (circularRef) {
      return circularRef;
    }
    const customType = detectCustomTypes(variable);
    if (customType) {
      return customType;
    }
    const nestedTypes = Object.entries(variable)
      .map(([key, value]) => `${key}: ${getType(value)}`);
    return `Object{${nestedTypes.join(', ')}}`;
  }

  // Handle functions
  if (type === 'function') {
    return 'function';
  }

  return 'unknown';
}
```

