```scala
import scala.math.sqrt

class CustomException(message: String) extends Exception(message)

def squareWithChecks(x: Long): Long = {
  val startTime = System.nanoTime()

  if (x <= 0) {
    throw new CustomException("Input must be a positive number")
  }

  if (x % 3 != 0) {
    throw new CustomException("Input is not divisible by 3")
  }

  if (isPrime(x)) {
    throw new CustomException("Input is a prime number and cannot be squared")
  }

  val square: Long = try {
    Math.multiplyExact(x, x)
  } catch {
    case _: ArithmeticException =>
      throw new CustomException("Square of input is too large to be computed")
  }

  if (isPerfectSquare(square)) {
    throw new CustomException("Input is already a square number")
  }

  val endTime = System.nanoTime()
  val executionTime = endTime - startTime
  println(s"Execution time: ${executionTime} nanoseconds")

  square
}

def isPrime(n: Long): Boolean = {
  if (n < 2) {
    return false
  }

  for (i <- 2 to sqrt(n).toInt) {
    if (n % i == 0) {
      return false
    }
  }

  true
}

def isPerfectSquare(n: Long): Boolean = {
  val sqrtValue = sqrt(n).toLong
  sqrtValue * sqrtValue == n
}
```

