Here is a JavaScript program that finds all the words in a string that start with a specific letter (in this case 'j') and are followed by a vowel:

```javascript
function findWordsWithLetterAndVowel(str, letter) {
  // Convert the string to lowercase for case-insensitive comparison
  str = str.toLowerCase();

  // Split the string into an array of words
  var words = str.split(" ");

  // Array to store the matched words
  var matchedWords = [];

  // Iterate over each word in the array
  for (var i = 0; i < words.length; i++) {
    var word = words[i];

    // Check if the word starts with the specified letter
    if (word.charAt(0) === letter.toLowerCase()) {

      // Check if the word is followed by a vowel
      if (/[aeiou]/.test(word.charAt(1))) {
        // Add the matched word to the array
        matchedWords.push(word);
      }
    }
  }

  // Return the array of matched words
  return matchedWords;
}

// Test the function
