```java
import java.util.ArrayList;
import java.util.List;
import java.util.Random;

public class UniqueAlphanumericIDGenerator {
    public static void main(String[] args) {
        String id = generateUniqueID();
        System.out.println("Unique ID: " + id);
    }

    public static String generateUniqueID() {
        List<Character> characters = new ArrayList<>();
        Random random = new Random();

        // Generate distinct letters (A-Z)
        for (int i = 0; i < 4; i++) {
            char letter = (char) (random.nextInt(26) + 'A');
            if (!characters.contains(letter)) {
                characters.add(letter);
            } else {
                i--;
            }
        }

        // Generate distinct numbers (0-9)
        for (int i = 0; i < 4; i++) {
            char number = (char) (random.nextInt(10) + '0');
            if (!characters.contains(number)) {
                characters.add(number);
            } else {
                i--;
            }
        }

        // Fill remaining digits with random alphanumeric characters
        while (characters.size() < 12) {
            char character = (char) (random.nextInt(36) + 'A');
            if (!characters.contains(character)) {
                characters.add(character);
            }
        }

        // Convert character list to string
