  calculateAverageGrade() {
    if (this.numCourses === 0) return 0;

    let sum = 0;
    for (let i = 0; i < this.grades.length; i++) {
      sum += this.grades[i].grade;
    }

    return sum / this.numCourses;
  }

  calculateWeightedAverageGrade() {
    if (this.numCourses === 0) return 0;

    let weightedSum = 0;
    let totalCredits = 0;

    for (let i = 0; i < this.grades.length; i++) {
      const { course, grade } = this.grades[i];
      const credits = course.credits; // Assuming each course has a 'credits' property
      weightedSum += grade * credits;
      totalCredits += credits;
    }

    return weightedSum / totalCredits;
  }

  calculateHighestGrade() {
    if (this.numCourses === 0) return 0;

    let highestGrade = this.grades[0].grade;

    for (let i = 1; i < this.grades.length; i++) {
      if (this.grades[i].grade > highestGrade) {
        highestGrade = this.grades[i].grade;
      }
    }

    return highestGrade;
  }

  calculateLowestGrade() {
    if (this.numCourses === 0) return 0;

    let lowestGrade = this.grades[0].grade;

    for (let i = 1; i < this.grades.length; i++) {
      if (this.grades[i].grade < lowestGrade) {
        lowestGrade = this.grades[i].grade;
      }
    }

    return lowestGrade;
  }

  calculateGPA() {
    // Assuming a grade scale where A=4, B=3, C=2, D=1, F=0
    const gradePoints = {
      A: 4,
      B: 3,
      C: 2,
      D: 1,
      F: 0
    };

    let totalGradePoints = 0;
    let totalCredits = 0;

    for (let i = 0; i < this.grades.length; i++) {
      const { course, grade } = this.grades[i];
      const credits = course.credits; // Assuming each course has a 'credits' property
      totalGradePoints += gradePoints[grade] * credits;
      totalCredits += credits;
    }

    return totalGradePoints / totalCredits;
  }

  getCoursesAboveGradeThreshold(gradeThreshold) {
    return this.grades.filter(grade => grade.grade > gradeThreshold).map(grade => grade.course);
  }

  getCoursesBelowGradeThreshold(gradeThreshold) {
    return this.grades.filter(grade => grade.grade < gradeThreshold).map(grade => grade.course);
  }

  calculateCumulativeGPA() {
    // Assuming a grade scale where A=4, B=3, C=2, D=1, F=0
    const gradePoints = {
      A: 4,
      B: 3,
      C: 2,
      D: 1,
      F: 0
    };

    let totalGradePoints = 0;
    let totalCredits = 0;

    for (let i = 0; i < this.grades.length; i++) {
      const { course, grade } = this.grades[i];
      const credits = course.credits; // Assuming each course has a 'credits' property
      totalGradePoints += gradePoints[grade] * credits;
      totalCredits += credits;
    }

    return totalGradePoints / totalCredits;
  }

  checkEligibilityForScholarship(scholarshipGPA) {
    return this.calculateCumulativeGPA() >= scholarshipGPA;
  }

  updateMajor(major) {
    this.major = major;
  }

  calculateAverageGradeForSemester(semester) {
    const semesterGrades = this.grades.filter(grade => grade.course.semester === semester);

    if (semesterGrades.length === 0) return 0;

    let sum = 0;
    for (let i = 0; i < semesterGrades.length; i++) {
      sum += semesterGrades[i].grade;
    }

    return sum / semesterGrades.length;
  }

  calculateExpectedGraduationDate() {
    // Assuming a standard 4-year degree program
    const currentYear = new Date().getFullYear();
