import math

def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def prime_numbers():
    primes = []
    for num in range(100000):
        if is_prime(num):
            primes.append(num)
    return primes

print(prime_numbers())
