```cpp
#include <iostream>

int main() {
    int arr[] = {10, 5, 12, -6, 7, 8, 15, -9, 0, 3};
    int size = sizeof(arr) / sizeof(arr[0]);

    int sum = 0;
    int count = 0;

    for (int i = 0; i < size; i++) {
        if (arr[i] % 3 == 0) {
            continue;
        }
        sum += arr[i];
        count++;
    }

    double average = static_cast<double>(sum) / count;

    std::cout << "Sum: " << sum << std::endl;
    std::cout << "Average: " << average << std::endl;

    return 0;
}
```

