    elif color_model == "HSL":
        return generate_hsl_color(hue, saturation, brightness, transparency)
    elif color_model == "CMYK":
        return generate_cmyk_color(hue, saturation, brightness, transparency)

def generate_rgb_color(hue, saturation, brightness, transparency):
    r, g, b = hsl_to_rgb(hue / 360, saturation, brightness)
    r = int(r * 255)
    g = int(g * 255)
    b = int(b * 255)
    return f"#{r:02x}{g:02x}{b:02x}"

def generate_hsl_color(hue, saturation, brightness, transparency):
    return f"hsl({hue}, {saturation * 100}%, {brightness * 100}%)"

def generate_cmyk_color(hue, saturation, brightness, transparency):
    c, m, y, k = hsl_to_cmyk(hue / 360, saturation, brightness)
    return f"cmyk({c * 100}%, {m * 100}%, {y * 100}%, {k * 100}%)"

def hsl_to_rgb(h, s, l):
    c = (1 - abs(2 * l - 1)) * s
    x = c * (1 - abs((h / 60) % 2 - 1))
    m = l - c / 2

    if 0 <= h < 60:
        r, g, b = c, x, 0
    elif 60 <= h < 120:
        r, g, b = x, c, 0
    elif 120 <= h < 180:
        r, g, b = 0, c, x
    elif 180 <= h < 240:
        r, g, b = 0, x, c
    elif 240 <= h < 300:
        r, g, b = x, 0, c
    else:
        r, g, b = c, 0, x

    return r + m, g + m, b + m

def hsl_to_cmyk(h, s, l):
    c = (1 - abs(2 * l - 1)) * s
    x = c * (1 - abs((h / 60) % 2 - 1))
    m = l - c / 2

    if 0 <= h < 60:
        return c + m, x + m, m, 0
    elif 60 <= h < 120:
        return x + m, c + m, m, 0
    elif 120 <= h < 180:
        return m, c + m, x + m, 0
    elif 180 <= h < 240:
        return m, x + m, c + m, 0
    elif 240 <= h < 300:
        return x + m, m, c + m, 0
    else:
        return c + m, m, x + m, 0

