import java.util.ArrayList;
import java.util.List;

public class Student {
    private String id;
    private String name;
    private List<Integer> grades;

    public Student(String id, String name, List<Integer> grades) {
        this.id = id;
        this.name = name;
        this.grades = grades;
    }

    public double calculateAverageGrade() {
        if (grades.isEmpty()) {
            throw new IllegalArgumentException("No grades available");
        }

        int sum = 0;
        for (int grade : grades) {
            if (grade < 0 || grade > 100) {
                throw new IllegalArgumentException("Invalid grade: " + grade);
            }
            sum += grade;
        }

        return (double) sum / grades.size();
    }

    public int calculateHighestGrade() {
        if (grades.isEmpty()) {
            throw new IllegalArgumentException("No grades available");
        }

        int maxGrade = grades.get(0);
        for (int grade : grades) {
            if (grade > maxGrade) {
                maxGrade = grade;
            }
        }

        return maxGrade;
    }

    public int calculateLowestGrade() {
        if (grades.isEmpty()) {
            throw new IllegalArgumentException("No grades available");
        }

        int minGrade = grades.get(0);
        for (int grade : grades) {
            if (grade < minGrade) {
                minGrade = grade;
            }
        }

        return minGrade;
    }

    public int calculateGradesAboveThreshold(int threshold) {
        if (grades.isEmpty()) {
            throw new IllegalArgumentException("No grades available");
        }

        int count = 0;
        for (int grade : grades) {
            if (grade > threshold) {
                count++;
            }
        }

        return count;
    }

    public double calculatePercentageGradesAboveThreshold(int threshold) {
        if (grades.isEmpty()) {
            throw new IllegalArgumentException("No grades available");
        }

        int countAboveThreshold = calculateGradesAboveThreshold(threshold);

        return (double) countAboveThreshold / grades.size() * 100;
    }
}
```

