```R
compute_minimum <- function(lst) {
  if (length(lst) == 0) {
    return("Empty list")
  }

  if (is.na(lst[[1]])) {
    return(compute_minimum(lst[-1]))
  }

  if (is.character(lst[[1]]) || is.logical(lst[[1]])) {
    return("List contains non-numeric values")
  }

  if (length(lst) == 1) {
    return(lst[[1]])
  }

  min_value <- compute_minimum(lst[-1])

  if (is.numeric(min_value) && lst[[1]] < min_value) {
    return(lst[[1]])
  } else {
    return(min_value)
  }
}

