        self.width = width
        self.name = ""

    def calculateArea(self):
        pass

    def printArea(self):
        area = self.calculateArea()
        print("The area of the", self.name, "is", area)

    def getPerimeter(self):
        return 2 * (self.length + self.width)

    @staticmethod
    def compareAreas(shape1, shape2):
        area1 = shape1.calculateArea()
        area2 = shape2.calculateArea()
        return abs(area1 - area2)

    def printName(self):
        print("The name of the shape is", self.name)

    @staticmethod
    def comparePerimeters(shape1, shape2):
        perimeter1 = shape1.getPerimeter()
        perimeter2 = shape2.getPerimeter()
        return abs(perimeter1 - perimeter2)


class CompoundShape(Shape):
    def __init__(self, shapes):
        self.shapes = shapes
        self.name = "Compound Shape"

    def calculateArea(self):
        total_area = 0
        for shape in self.shapes:
            total_area += shape.calculateArea()
        return total_area


class Triangle(Shape):
    def __init__(self, base, height):
        super().__init__(base, height)
        self.name = "Triangle"

    def calculateArea(self):
        return (self.length * self.width) / 2


class Circle(Shape):
    def __init__(self, radius):
        super().__init__(radius, radius)
        self.name = "Circle"

    def calculateArea(self):
        return math.pi * self.length * self.width


class Rectangle(Shape):
    def __init__(self, length, width):
        super().__init__(length, width)
        self.name = "Rectangle"

    def calculateArea(self):
        return self.length * self.width


