Here is a C++ program that takes two integers as input, n and k, and prints the value of the binomial coefficient C(n, k):

```c++
#include <iostream>

using namespace std;

// Function to calculate the factorial of a number
int factorial(int num) {
    int fact = 1;
    for (int i = 1; i <= num; i++) {
        fact *= i;
    }
    return fact;
}

// Function to calculate the binomial coefficient
int binomialCoefficient(int n, int k) {
    if (k > n) {
        cout << "Error: k cannot be greater than n." << endl;
        return -1;
    }

    int result = factorial(n) / (factorial(k) * factorial(n - k));
    return result;
}

int main() {
    int n, k;

    // Taking input for n and k
    cout << "Enter the value of n: ";
    cin >> n;
    cout << "Enter the value of k: ";
    cin >> k;

    // Calculating and printing the binomial coefficient
    int coefficient = binomialCoefficient(n, k);
    if (coefficient != -1) {
        cout << "C(" << n << ", " << k << ") = " << coefficient << endl;
    }

    return 0;
}
```

In this program, the `factorial` function calculates the factorial of a number using a loop. The `binomialCoefficient` function first checks if k is greater than n and returns an error message if true. Otherwise, it calculates the binomial coefficient using the formula C(n, k) = n! / (k!(n-k)!). Finally, in the `main` function, the user is prompted to enter the values of n and k, and the binomial coefficient is calculated and printed.

