function convertOctalToDecimal(octal) {
  // Handle empty input strings
  if (octal.length === 0) {
    return "";
  }

  // Initialize the decimal number
  let decimal = 0;

  // Loop through each digit in the octal number
  for (let i = octal.length - 1; i >= 0; i--) {
    // Convert the digit to a number
    const digit = parseInt(octal[i]);

    // Check if the digit is valid
    if (isNaN(digit) || digit < 0 || digit > 7) {
      return "Invalid input";
    }

    // Calculate the decimal value of the digit
