Here's a JavaScript program that converts a given number of seconds into the equivalent time in weeks, days, hours, minutes, and seconds:

```javascript
function convertSecondsToTime(seconds) {
  const SECONDS_IN_MINUTE = 60;
  const MINUTES_IN_HOUR = 60;
  const HOURS_IN_DAY = 24;
  const DAYS_IN_WEEK = 7;

  let weeks = Math.floor(seconds / (SECONDS_IN_MINUTE * MINUTES_IN_HOUR * HOURS_IN_DAY * DAYS_IN_WEEK));
  seconds %= SECONDS_IN_MINUTE * MINUTES_IN_HOUR * HOURS_IN_DAY * DAYS_IN_WEEK;

  let days = Math.floor(seconds / (SECONDS_IN_MINUTE * MINUTES_IN_HOUR * HOURS_IN_DAY));
  seconds %= SECONDS_IN_MINUTE * MINUTES_IN_HOUR * HOURS_IN_DAY;

  let hours = Math.floor(seconds / (SECONDS_IN_MINUTE * MINUTES_IN_HOUR));
  seconds %= SECONDS_IN_MINUTE * MINUTES_IN_HOUR;

  let minutes = Math.floor(seconds / SECONDS_IN_MINUTE);
  seconds %= SECONDS_IN_MINUTE;

  return {
    weeks: weeks,
    days: days,
    hours: hours,
    minutes: minutes,
    seconds: seconds
  };
}

