public class AnagramChecker {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.println("Enter the first string: ");
        String string1 = scanner.nextLine();

        System.out.println("Enter the second string: ");
        String string2 = scanner.nextLine();

        boolean areAnagrams = checkIfAnagrams(string1, string2);

        if (areAnagrams) {
            System.out.println("The two strings are anagrams.");
        } else {
            System.out.println("The two strings are not anagrams.");
        }
    }

    private static boolean checkIfAnagrams(String string1, String string2) {
        // Remove spaces and punctuation, and convert to lowercase
        string1 = string1.replaceAll("[^\\p{L}]", "").toLowerCase();
        string2 = string2.replaceAll("[^\\p{L}]", "").toLowerCase();

        // Create character frequency maps for both strings
        Map<Character, Integer> frequencyMap1 = createFrequencyMap(string1);
        Map<Character, Integer> frequencyMap2 = createFrequencyMap(string2);

        // Compare the two frequency maps
        return frequencyMap1.equals(frequencyMap2);
    }

    private static Map<Character, Integer> createFrequencyMap(String str) {
        Map<Character, Integer> frequencyMap = new HashMap<>();

        for (int i = 0; i < str.length(); i++) {
            char c = str.charAt(i);
            frequencyMap.put(c, frequencyMap.getOrDefault(c, 0) + 1);
        }

        return frequencyMap;
    }
}
