```python
class Node:
    def __init__(self, value):
        self.value = value
        self.next = None

class LinkedList:
    def __init__(self):
        self.head = None

    def add_element(self, value):
        new_node = Node(value)
        if self.head is None:
            self.head = new_node
        else:
            current = self.head
            while current.next:
                current = current.next
            current.next = new_node

    def remove_element(self, value):
        if self.head is None:
            return

        if self.head.value == value:
            self.head = self.head.next
            return

        current = self.head
        prev = None
        while current:
            if current.value == value:
                prev.next = current.next
                return
            prev = current
            current = current.next

    def exists(self, value):
        current = self.head
        while current:
            if current.value == value:
                return True
            current = current.next
        return False


