function findMedian(arr) {
  if (arr.length === 0) {
    return NaN;
  }

  // Sort the array using a sorting algorithm with O(n log n) time complexity
  arr = mergeSort(arr);

  // Calculate the median based on the length of the array
  if (arr.length % 2 === 1) {
    // For arrays with odd length, return the middle value
    return arr[Math.floor(arr.length / 2)];
  } else {
    // For arrays with even length, return the average of the two middle values
    const midIndex = arr.length / 2;
    return (arr[midIndex - 1] + arr[midIndex]) / 2;
  }
}

// Merge sort implementation
function mergeSort(arr) {
  if (arr.length <= 1) {
    return arr;
  }

  const midIndex = Math.floor(arr.length / 2);
  const left = arr.slice(0, midIndex);
  const right = arr.slice(midIndex);

  return merge(mergeSort(left), mergeSort(right));
}

function merge(left, right) {
  const result = [];
  let leftIndex = 0;
  let rightIndex = 0;

  while (leftIndex < left.length && rightIndex < right.length) {
    if (left[leftIndex] < right[rightIndex]) {
      result.push(left[leftIndex]);
      leftIndex++;
    } else {
      result.push(right[rightIndex]);
      rightIndex++;
    }
  }

  return result.concat(left.slice(leftIndex)).concat(right.slice(rightIndex));
}
```

