```java
public class SquareRootCalculator {
    public static int calculateSquareRoot(int n) {
        if (n == 0 || n == 1) {
            return n;
        }

        int start = 1, end = n, ans = 0;
        while (start <= end) {
            int mid = (start + end) / 2;

            if (mid * mid == n) {
                return mid;
            }

            if (mid * mid < n) {
                start = mid + 1;
                ans = mid;
            } else {
                end = mid - 1;
            }
        }

        return ans;
    }

    public static void main(String[] args) {
        int n = 16;
        int squareRoot = calculateSquareRoot(n);
        System.out.println("Square root of " + n + " is " + squareRoot);
    }
}
