// Function to check whether a number is prime or not
int isPrime(int num) {
    if (num <= 1)
        return 0;

    for (int i = 2; i <= sqrt(num); i++) {
        if (num % i == 0)
            return 0;
    }

    return 1;
}

int main() {
    int N;

    printf("Enter the value of N: ");
    scanf("%d", &N);

    int arr[N][N];
    int primeCount = 0;
    int primeSum = 0;
    int largestPrime = 0;
    int largestPrimeRow, largestPrimeCol;

    int num = 2; // Starting number for prime calculation

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            while (!isPrime(num))
                num++;

            arr[i][j] = num;
            primeCount++;
            primeSum += num;

            if (num > largestPrime) {
                largestPrime = num;
                largestPrimeRow = i;
                largestPrimeCol = j;
            }

            num++;
        }
    }

    printf("The 2D array with unique prime numbers:\n");
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            printf("%d ", arr[i][j]);
        }
        printf("\n");
    }

    printf("Sum of all prime numbers: %d\n", primeSum);
    printf("Largest prime number: %d\n", largestPrime);
    printf("Position of largest prime number: [%d][%d]\n", largestPrimeRow, largestPrimeCol);

    return 0;
}
```

