Here is a JavaScript code that processes the CSV string into an array of objects, following the given conditions:

```javascript
function processCSV(csvString, delimiter) {
  const rows = csvString.split('\n');
  const headers = rows[0].split(delimiter);
  const dataArray = [];

  for (let i = 1; i < rows.length; i++) {
    const values = rows[i].split(delimiter);
    const dataObject = {};

    if (values.length === headers.length) {
      for (let j = 0; j < headers.length; j++) {
        const header = headers[j].trim().toLowerCase();
        const value = values[j].trim();

        if (header === 'name') {
          dataObject.name = value;
        } else if (header === 'age') {
          const age = parseInt(value);
          if (age >= 0) {
            dataObject.age = age;
          } else {
            continue;
          }
        } else if (header === 'gender') {
          const gender = value.toLowerCase();
          if (gender === 'male' || gender === 'female') {
            dataObject.gender = gender;
          } else {
            continue;
          }
        } else if (header === 'country') {
          dataObject.country = value;
        }
      }

      if (Object.keys(dataObject).length === 4) {
        dataArray.push(dataObject);
      }
    }
  }

  return dataArray;
}

// Example usage:
