#include <iostream>
#include <complex>

void findRoots(std::complex<double> a, std::complex<double> b, std::complex<double> c, std::complex<double> d) {
    std::complex<double> disc, Q, R, D, S, T, Im;

    Q = (3.0 * c - (b * b)) / 9.0;
    R = (9.0 * b * c - 27.0 * a * d - 2.0 * (b * b * b)) / 54.0;
    disc = (Q * Q * Q) + (R * R);

    if (disc.real() > 0) {
        std::cout << "The equation has one real root and two complex conjugate roots." << std::endl;
        D = std::sqrt(disc);
        S = std::cbrt(R + D);
        T = std::cbrt(R - D);

        std::complex<double> root1 = (-b / 3.0) + S + T;
        std::complex<double> root2 = (-b / 3.0) - ((S + T) / 2.0) + Im * ((S - T) * std::sqrt(3.0)) / 2.0;
        std::complex<double> root3 = (-b / 3.0) - ((S + T) / 2.0) - Im * ((S - T) * std::sqrt(3.0)) / 2.0;

        std::cout << "Root 1: " << root1 << std::endl;
        std::cout << "Root 2: " << root2 << std::endl;
        std::cout << "Root 3: " << root3 << std::endl;
    }
    else if (disc.real() == 0) {
        std::cout << "The equation has three real and equal roots." << std::endl;
        S = std::cbrt(R);
        std::complex<double> root1 = (-b / 3.0) + (2.0 * S);
        std::complex<double> root2 = (-b / 3.0) - S;
        std::complex<double> root3 = (-b / 3.0) - S;

        std::cout << "Root 1: " << root1 << std::endl;
        std::cout << "Root 2: " << root2 << std::endl;
        std::cout << "Root 3: " << root3 << std::endl;
    }
    else {
        std::cout << "The equation has three distinct real roots." << std::endl;
        double theta = std::acos(R / std::sqrt(-Q * Q * Q));
        double root1 = -2.0 * std::sqrt(-Q) * std::cos(theta / 3.0) - (b / 3.0);
        double root2 = -2.0 * std::sqrt(-Q) * std::cos((theta + 2.0 * M_PI) / 3.0) - (b / 3.0);
        double root3 = -2.0 * std::sqrt(-Q) * std::cos((theta + 4.0 * M_PI) / 3.0) - (b / 3.0);

        std::cout << "Root 1: " << root1 << std::endl;
        std::cout << "Root 2: " << root2 << std::endl;
        std::cout << "Root 3: " << root3 << std::endl;
    }
}

