from multiprocessing import Pool

def is_prime(num):
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def get_primes(arr):
    primes = []
    pool = Pool()
    results = pool.map(is_prime, arr)
    for i, result in enumerate(results):
        if result:
            primes.append(arr[i])
    return sorted(primes, reverse=True)

