Here is an algorithm in Python to calculate the compound interest, considering all the additional requirements mentioned:

```python
def calculate_compound_interest(principal, interest_rate, time_period, compounding_periods, interest_type, compounding_interval, fees):
    try:
        # Check for negative values
        if principal < 0 or interest_rate < 0 or time_period < 0 or compounding_periods < 0:
            raise ValueError("Values cannot be negative")

        # Calculate the compound interest
        interest = 0
        if interest_type == "simple":
            interest = principal * (1 + (interest_rate / 100) * time_period)
        elif interest_type == "compound":
            rate_per_period = interest_rate / (100 * compounding_periods)
            periods = compounding_periods * time_period

            if compounding_interval == "daily":
                interest = principal * (1 + rate_per_period) ** periods
            elif compounding_interval == "weekly":
                interest = principal * (1 + rate_per_period) ** (periods / 7)
            elif compounding_interval == "monthly":
                interest = principal * (1 + rate_per_period) ** (periods / 30)
            elif compounding_interval == "quarterly":
                interest = principal * (1 + rate_per_period) ** (periods / 90)
            elif compounding_interval == "annually":
                interest = principal * (1 + rate_per_period) ** (periods / 365)

        # Apply fees
        total_amount = interest - fees

        return round(total_amount, 2)

    except ValueError as e:
        return str(e)
    except ZeroDivisionError:
        return "Cannot divide by zero"
    except:
        return "An error occurred"

