def binary_search_first(nums, target):
    low = 0
    high = len(nums) - 1

    while low <= high:
        mid = (low + high) // 2

        if nums[mid] == target:
            if mid == 0 or nums[mid - 1] != target:
                return mid
            else:
                high = mid - 1
        elif nums[mid] > target:
            high = mid - 1
        else:
            low = mid + 1

    return -1

