```java
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Student {
    private String name;
    private Map<String, List<Integer>> marks;
    private List<Integer> attendance;

    public Student(String name) {
        this.name = name;
        this.marks = new HashMap<>();
        this.attendance = new ArrayList<>();
    }

    public void addMarks(String subject, List<Integer> assessmentMarks) {
        marks.put(subject, assessmentMarks);
    }

    public void addAttendance(int attendanceRecord) {
        attendance.add(attendanceRecord);
    }

    public double calculateSubjectAverage(String subject) {
        List<Integer> subjectMarks = marks.get(subject);
        if (subjectMarks == null || subjectMarks.isEmpty()) {
            return 0.0;
        }
        int sum = 0;
        for (int mark : subjectMarks) {
            sum += mark;
        }
        return (double) sum / subjectMarks.size();
    }

    public double calculateOverallAverage() {
        if (marks.isEmpty()) {
            return 0.0;
        }
        int totalMarks = 0;
        int totalAssessments = 0;
        for (List<Integer> subjectMarks : marks.values()) {
            for (int mark : subjectMarks) {
                totalMarks += mark;
                totalAssessments++;
            }
        }
        return (double) totalMarks / totalAssessments;
    }

    public double calculateOverallAttendancePercentage() {
        if (attendance.isEmpty()) {
            return 0.0;
        }
        int totalClasses = attendance.size();
        int totalAttendedClasses = 0;
        for (int attendanceRecord : attendance) {
            if (attendanceRecord == 1) {
                totalAttendedClasses++;
            }
        }
        return (double) totalAttendedClasses / totalClasses * 100;
    }
}
