int factorial(int num);

int main() {
    int num;

    printf("Enter a number: ");
    scanf("%d", &num);

    printf("The factorial of %d is %d\n", num, factorial(num));

    return 0;
}

int factorial(int num) {
    int result = 1;

    if (num == 0 || num == 1) {
        return result;
    }

    // Multiply the number with the factorial of (num-1) recursively
    result = num * factorial(num - 1);

    return result;
}
