    for (let i = 0; i < len - 1; i++) {
      if (evenNumbers[i] < evenNumbers[i + 1]) {
        let temp = evenNumbers[i];
        evenNumbers[i] = evenNumbers[i + 1];
        evenNumbers[i + 1] = temp;
        sorted = false;
      }
    }
