```python
class Matrix:
    def __init__(self, matrix):
        self.matrix = matrix

    def __str__(self):
        rows = []
        for row in self.matrix:
            rows.append(' '.join(str(elem) for elem in row))
        return '\n'.join(rows)

    def multiply(self, other):
        result = []
        for i in range(len(self.matrix)):
            row = []
            for j in range(len(other.matrix[0])):
                elem = 0
                for k in range(len(other.matrix)):
                    elem += self.matrix[i][k] * other.matrix[k][j]
                row.append(elem)
            result.append(row)
        return Matrix(result)

    def add(self, other):
        result = []
        for i in range(len(self.matrix)):
            row = []
            for j in range(len(self.matrix[0])):
                row.append(self.matrix[i][j] + other.matrix[i][j])
            result.append(row)
        return Matrix(result)

    def determinant(self):
        if len(self.matrix) == 2 and len(self.matrix[0]) == 2:
            return self.matrix[0][0] * self.matrix[1][1] - self.matrix[0][1] * self.matrix[1][0]
        det = 0
        for col in range(len(self.matrix[0])):
            sub_matrix = []
            for i in range(1, len(self.matrix)):
                sub_matrix_row = []
                for j in range(len(self.matrix[0])):
                    if j != col:
                        sub_matrix_row.append(self.matrix[i][j])
                sub_matrix.append(sub_matrix_row)
            det += self.matrix[0][col] * pow(-1, col) * Matrix(sub_matrix).determinant()
        return det


