#include <iostream>
#include <string>
#include <vector>

std::vector<int> searchSubString(const std::string& str, const std::string& subStr) {
    std::vector<int> indices;

    if (subStr.length() > str.length())
        return indices;

    int n = str.length();
    int m = subStr.length();
    int j;

    for (int i = 0; i <= n - m; i++) {
        for (j = 0; j < m; j++) {
            if (str[i + j] != subStr[j])
                break;
        }

        if (j == m) // subStr found at index i
            indices.push_back(i);
    }

    return indices;
}

int main() {
    std::string str = "This is a test string. This string contains multiple test words.";
    std::string subStr = "test";

    std::vector<int> indices = searchSubString(str, subStr);

    if (indices.empty()) {
        std::cout << "Substring not found." << std::endl;
    } else {
        std::cout << "Substring found at indices: ";
        for (int index : indices) {
            std::cout << index << " ";
        }
        std::cout << std::endl;
    }

    return 0;
}
```

This code uses a brute-force approach to search for the sub-string in the given string. It iterates through each possible starting index in the given string and checks if the characters from that index match the characters of the sub-string. If a match is found, the starting index is added to a vector of indices.

The time complexity of this algorithm is O(n), where n is the length of the given string. The worst-case scenario is when the sub-string is not present in the string or when it appears at the end of the string. In both cases, the algorithm will have to iterate through all the characters in the given string.

