use strict;
use warnings;

my $sum = 0;
my $count = 0;

for(my $num = 2; $num <= 1000; $num++) {
    my $is_prime = 1;
    for(my $i = 2; $i <= sqrt($num); $i++) {
        if($num % $i == 0) {
            $is_prime = 0;
            last;
        }
    }
    if($is_prime) {
        $sum += $num;
        $count++;
    }
}

