```java
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Student {
    private String name;
    private String grade;
    private List<Subject> subjects;
    private double averageGrade;
    private int gradeUpdates;

    public Student(String name, String grade) {
        this.name = name;
        this.grade = grade;
        this.subjects = new ArrayList<>();
    }

    public void addSubject(String name, int grade, int maxGrade) {
        Subject subject = new Subject(name, grade, maxGrade);
        this.subjects.add(subject);
    }

    public void updateGrade(String subjectName, int newGrade) {
        for (Subject subject : subjects) {
            if (subject.getName().equals(subjectName)) {
                subject.setGrade(newGrade);
                subject.incrementGradeUpdates();
            }
        }
    }

    public double calculateAverageGrade() {
        double totalGrade = 0;
        for (Subject subject : subjects) {
            totalGrade += subject.getGrade();
        }
        averageGrade = totalGrade / subjects.size();
        return averageGrade;
    }

    public int getHighestGrade() {
        int highestGrade = Integer.MIN_VALUE;
        for (Subject subject : subjects) {
            if (subject.getGrade() > highestGrade) {
                highestGrade = subject.getGrade();
            }
        }
        return highestGrade;
    }

    public int getLowestGrade() {
        int lowestGrade = Integer.MAX_VALUE;
        for (Subject subject : subjects) {
            if (subject.getGrade() < lowestGrade) {
                lowestGrade = subject.getGrade();
            }
        }
        return lowestGrade;
    }

    public boolean isEligibleForScholarship(double minAverageGrade, int minSubjectGrade) {
        for (Subject subject : subjects) {
            if (subject.getGrade() < minSubjectGrade) {
                return false;
            }
        }
        return calculateAverageGrade() >= minAverageGrade;
    }

    public void sortSubjectsByGradeDescending() {
        Collections.sort(subjects, (s1, s2) -> s2.getGrade() - s1.getGrade());
    }

    public double calculateStandardDeviation() {
        double sum = 0;
        for (Subject subject : subjects) {
            sum += Math.pow(subject.getGrade() - averageGrade, 2);
        }
        double variance = sum / subjects.size();
        return Math.sqrt(variance);
    }

    public Subject getSubjectWithHighestGrade() {
        Subject subjectWithHighestGrade = null;
        int highestGrade = Integer.MIN_VALUE;
        for (Subject subject : subjects) {
            if (subject.getGrade() > highestGrade) {
                highestGrade = subject.getGrade();
                subjectWithHighestGrade = subject;
            }
        }
        return subjectWithHighestGrade;
    }

    public Subject getSubjectWithLowestGrade() {
        Subject subjectWithLowestGrade = null;
        int lowestGrade = Integer.MAX_VALUE;
        for (Subject subject : subjects) {
            if (subject.getGrade() < lowestGrade) {
                lowestGrade = subject.getGrade();
                subjectWithLowestGrade = subject;
            }
        }
        return subjectWithLowestGrade;
    }

    public double calculateAverageGradeForSubject(String subjectName) {
        double totalGrade = 0;
        int count = 0;
        for (Subject subject : subjects) {
            if (subject.getName().equals(subjectName)) {
                totalGrade += subject.getGrade();
                count++;
            }
        }
        return totalGrade / count;
    }

    public int getGradeUpdatesForSubject(String subjectName) {
        for (Subject subject : subjects) {
            if (subject.getName().equals(subjectName)) {
                return subject.getGradeUpdates();
            }
        }
        return 0;
    }

    public class Subject {
        private String name;
        private int grade;
        private int maxGrade;
        private int gradeUpdates;

        public Subject(String name, int grade, int maxGrade) {
            this.name = name;
            this.grade = grade;
            this.maxGrade = maxGrade;
        }

        public String getName() {
            return name;
        }

        public int getGrade() {
            return grade;
        }

        public void setGrade(int grade) {
            this.grade = grade;
        }

        public int getMaxGrade() {
            return maxGrade;
        }

        public int getGradeUpdates() {
            return gradeUpdates;
        }

        public void incrementGradeUpdates() {
            gradeUpdates++;
        }
    }
}
