function getMinMaxValues(arr) {
  let max = arr[0];
  let min = arr[0];
  let maxIndexes = [];
  let minIndexes = [];
  let counts = {};

  for (let i = 0; i < arr.length; i++) {
    const num = arr[i];

    // Update maximum value and its indexes
    if (num > max) {
      max = num;
      maxIndexes = [i];
    } else if (num === max) {
      maxIndexes.push(i);
    }

    // Update minimum value and its indexes
    if (num < min) {
      min = num;
      minIndexes = [i];
    } else if (num === min) {
      minIndexes.push(i);
    }

    // Update count of each unique value
    if (counts[num]) {
      counts[num]++;
    } else {
      counts[num] = 1;
    }
  }

  return {
    maximumValue: max,
    minimumValue: min,
    indexesOfMaximumValue: maxIndexes,
    indexesOfMinimumValue: minIndexes,
    countOfEachUniqueValue: counts
  };
}

