    public static string CalculateArea(string radius)
    {
        if (string.IsNullOrWhiteSpace(radius))
        {
            return "Error: No radius value provided.";
        }

        decimal radiusValue;
        if (!decimal.TryParse(radius, out radiusValue))
        {
            return "Error: Invalid radius value.";
        }

        if (radiusValue < 0)
        {
            return "Error: Negative radius value is not allowed.";
        }

