        }

        if (radiusValue.ToString().Length - radiusValue.ToString().IndexOf('.') > 20)
        {
            return "Error: Precision exceeds limit.";
        }

        if (radiusValue.ToString().IndexOf('.') > 0 && radiusValue.ToString().Length - radiusValue.ToString().IndexOf('.') < 4)
        {
            return "Error: Precision is too low.";
        }

        return Math.Round(area, 4).ToString("0.0000");
    }
