            return helloCalls;
        } else if (methodName.equals("sayGoodbye")) {
            return goodbyeCalls;
        } else {
            throw new IllegalArgumentException("Invalid method name.");
        }
    }

    public void resetTotalCalls() {
        helloCalls = 0;
        goodbyeCalls = 0;
    }
}
