int sumEvenFibonacci(int n) {
    if (n <= 0) {
        return 0;
    }

    int sum = 0;
    for (int i = 0; fibonacci(i) <= n; i++) {
        if (fibonacci(i) % 2 == 0) {
            sum += fibonacci(i);
        }
    }

    return sum;
}

void printFibonacciSequence(int n) {
    std::cout << "Fibonacci sequence up to " << n << ":" << std::endl;
    for (int i = 0; fibonacci(i) <= n; i++) {
