```php
class ActivityLogger {
  private $db;

  public function __construct($db) {
    $this->db = $db;
  }

  public function logActivity($userId, $activityType, $duration) {
    $activityTime = date('Y-m-d H:i:s');

    $stmt = $this->db->prepare("INSERT INTO activity_logs (user_id, activity_type, activity_time, duration) VALUES (?, ?, ?, ?)");
    $stmt->bind_param("issi", $userId, $activityType, $activityTime, $duration);
    $stmt->execute();
    $stmt->close();
  }

  public function getTotalDuration() {
    $stmt = $this->db->query("SELECT SUM(duration) as total_duration FROM activity_logs");
    $result = $stmt->fetch_assoc();
    $stmt->close();

    return $result['total_duration'];
  }

  public function getActivityLogsByType($activityType) {
    $stmt = $this->db->prepare("SELECT * FROM activity_logs WHERE activity_type = ?");
    $stmt->bind_param("s", $activityType);
    $stmt->execute();
    $result = $stmt->get_result();
    $stmt->close();

    return $result->fetch_all(MYSQLI_ASSOC);
  }
}
