        if any(char in value for char in "!@#$%^&*()+=-[]{}|:;,<>?"):
            raise ValueError("Make must not contain special characters.")
        self._make = value

    @property
    def model(self):
        return self._model

    @model.setter
    def model(self, value):
        if not isinstance(value, str):
            raise TypeError("Model must be a string.")
        if len(value) < 3:
            raise ValueError("Model must be at least 3 characters long.")
        if any(char in value for char in "!@#$%^&*()+=-[]{}|:;,<>?"):
            raise ValueError("Model must not contain special characters.")
        self._model = value

    @property
    def year(self):
        return self._year

    @year.setter
    def year(self, value):
        if not isinstance(value, int):
            raise TypeError("Year must be an integer.")
        if value < 1900 or value > datetime.now().year:
            raise ValueError("Year must be between 1900 and the current year.")
