import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.*;

public class ParallelAtkinSieve {

    private static final int MAX_RANGE = 10000000;
    private static final int THREADS = 4;

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        long startTime = System.currentTimeMillis();

        ExecutorService executor = Executors.newFixedThreadPool(THREADS);
        List<Future<List<Integer>>> primeFutures = new ArrayList<>();

        int chunkSize = MAX_RANGE / THREADS;

        for (int i = 0; i < THREADS; i++) {
            int start = i * chunkSize + 1;
            int end = (i + 1) * chunkSize;
            if (i == THREADS - 1) {
                end = MAX_RANGE;
            }
            Callable<List<Integer>> task = new SieveTask(start, end);
            Future<List<Integer>> future = executor.submit(task);
            primeFutures.add(future);
        }

        List<Integer> allPrimes = new ArrayList<>();

        for (Future<List<Integer>> future : primeFutures) {
            List<Integer> primes = future.get();
            allPrimes.addAll(primes);
        }

        executor.shutdown();

        int largestPrime = 0;
        for (int prime : allPrimes) {
            if (prime > largestPrime) {
                largestPrime = prime;
            }
        }

        long endTime = System.currentTimeMillis();

        System.out.println("Prime numbers between 1 million and 2 million:");
        for (int prime : allPrimes) {
            System.out.println(prime);
        }

        System.out.println("Largest prime number: " + largestPrime);
        System.out.println("Execution time: " + (endTime - startTime) + " ms");
    }

    static class SieveTask implements Callable<List<Integer>> {

        private final int start;
        private final int end;

        SieveTask(int start, int end) {
            this.start = start;
            this.end = end;
        }

        @Override
        public List<Integer> call() {
            List<Integer> primes = new ArrayList<>();
            boolean[] isPrime = new boolean[end - start + 1];

            int sqrt = (int) Math.sqrt(end);
            boolean[] sieve = new boolean[sqrt + 1];

            for (int x = 1; x <= sqrt; x++) {
                for (int y = 1; y <= sqrt; y++) {
                    int n = 4 * x * x + y * y;
                    if (n <= end && (n % 12 == 1 || n % 12 == 5)) {
                        sieve[n] = !sieve[n];
                    }

                    n = 3 * x * x + y * y;
                    if (n <= end && n % 12 == 7) {
                        sieve[n] = !sieve[n];
                    }

                    n = 3 * x * x - y * y;
                    if (x > y && n <= end && n % 12 == 11) {
                        sieve[n] = !sieve[n];
                    }
                }
            }

            for (int r = 5; r <= sqrt; r++) {
                if (sieve[r]) {
                    for (int i = r * r; i <= sqrt; i += r * r) {
                        sieve[i] = false;
                    }
                }
            }

            for (int i = 5; i <= sqrt; i++) {
                if (sieve[i]) {
                    for (int j = i * i; j <= end; j += i * i) {
                        isPrime[j - start] = false;
                    }
                }
            }

            for (int i = start; i <= end; i++) {
                if (isPrime[i - start]) {
                    primes.add(i);
                }
            }

            return primes;
        }
    }
}

