def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(num ** 0.5) + 1):
        if num % i == 0:
            return False
    return True

def digit_sum(num):
    return sum(int(digit) for digit in str(num))

def product_of_digits(num):
    product = 1
    for digit in str(num):
        product *= int(digit)
    return product

def find_filtered_primes(limit):
    primes = []
    for num in range(2, limit):
        if is_prime(num):
            digit_sum_prime = digit_sum(num)
            product_prime = product_of_digits(num)
            if is_prime(digit_sum_prime) and is_prime(product_prime):
                primes.append(num)
    return primes

