```python
import requests
import json
from datetime import datetime, timedelta

class APIWrapper:
    def __init__(self, base_url, cache_timeout=60):
        self.base_url = base_url
        self.cache_timeout = timedelta(seconds=cache_timeout)
        self.cache = {}

    def _request(self, method, url, params=None, data=None):
        try:
            response = requests.request(method, url, params=params, data=data)
            response.raise_for_status()
            return response.json()
        except requests.exceptions.RequestException as e:
            print(f"Error occurred during API call: {e}")
            return None

    def _get_cached_response(self, key):
        if key in self.cache:
            timestamp, response = self.cache[key]
            if datetime.now() - timestamp < self.cache_timeout:
                return response
            else:
                del self.cache[key]
        return None

    def _cache_response(self, key, response):
        self.cache[key] = (datetime.now(), response)

    def get_all_users(self):
        url = f"{self.base_url}/users"
        cached_response = self._get_cached_response(url)
        if cached_response:
            return cached_response
        response = self._request("GET", url)
        if response:
            self._cache_response(url, response)
        return response

    def get_user_by_id(self, user_id):
        url = f"{self.base_url}/users/{user_id}"
        cached_response = self._get_cached_response(url)
        if cached_response:
            return cached_response
        response = self._request("GET", url)
        if response:
            self._cache_response(url, response)
        return response

    def create_user(self, user_data):
        url = f"{self.base_url}/users"
        response = self._request("POST", url, data=user_data)
        if response:
            self._cache_response(url, response)
        return response

    def update_user(self, user_id, user_data):
        url = f"{self.base_url}/users/{user_id}"
        response = self._request("PUT", url, data=user_data)
        if response:
            self._cache_response(url, response)
        return response

    def delete_user(self, user_id):
        url = f"{self.base_url}/users/{user_id}"
        response = self._request("DELETE", url)
        if response:
            del self.cache[url]
        return response
```

In this implementation, the `APIWrapper` class takes the base URL of the API as a parameter and an optional cache timeout value (default is 60 seconds). The cache is implemented as a dictionary where the key is the API endpoint URL and the value is a tuple containing the timestamp when the response was cached and the response itself.

The `_request` method is a private helper method that handles making the API call using the `requests` library. It catches any exceptions that may occur during the request and returns `None` if an error occurs.

The `_get_cached_response` method checks if a response for a given URL exists in the cache and if it is still within the cache timeout period. If the cached response is valid, it returns the response, otherwise it returns `None`.

The `_cache_response` method stores a response in the cache with the current timestamp.

The remaining methods (`get_all_users`, `get_user_by_id`, `create_user`, `update_user`, `delete_user`) correspond to the API operations and use the `_request` and cache methods to handle the API calls. If a response is obtained successfully, it is stored in the cache before returning it.

Note that this implementation assumes that the API responses are in JSON format. You may need to modify the code accordingly if the API returns responses in a different format.

