  public static <T extends Comparable<T>> void sort(T[] array, boolean ascending) {
    if (array == null) {
      throw new IllegalArgumentException("Input array cannot be null.");
    }

    if (array.length <= 1) {
      return;
    }

    T[] tempArray = Arrays.copyOf(array, array.length);
    mergeSort(array, tempArray, 0, array.length - 1, ascending);
  }

  private static <T extends Comparable<T>> void mergeSort(
      T[] array, T[] tempArray, int left, int right, boolean ascending) {
    if (left < right) {
      int mid1 = left + (right - left) / 3;
      int mid2 = left + 2 * (right - left) / 3;

      mergeSort(array, tempArray, left, mid1, ascending);
      mergeSort(array, tempArray, mid1 + 1, mid2, ascending);
      mergeSort(array, tempArray, mid2 + 1, right, ascending);

      merge(array, tempArray, left, mid1, mid2, right, ascending);
    }
  }

  private static <T extends Comparable<T>> void merge(
      T[] array, T[] tempArray, int left, int mid1, int mid2, int right, boolean ascending) {
    int i = left;
    int j = mid1 + 1;
    int k = mid2 + 1;

    while (i <= mid1 && j <= mid2 && k <= right) {
      if (shouldSwap(array[j], array[i], ascending) && shouldSwap(array[j], array[k], ascending)) {
        tempArray[i++] = array[j++];
      } else if (shouldSwap(array[k], array[i], ascending) && shouldSwap(array[k], array[j], ascending)) {
        tempArray[i++] = array[k++];
      } else {
        tempArray[i++] = array[i++];
      }
    }

    while (i <= mid1 && j <= mid2) {
      if (shouldSwap(array[j], array[i], ascending)) {
        tempArray[i++] = array[j++];
      } else {
        tempArray[i++] = array[i++];
      }
    }

    while (i <= mid1 && k <= right) {
      if (shouldSwap(array[k], array[i], ascending)) {
        tempArray[i++] = array[k++];
      } else {
        tempArray[i++] = array[i++];
      }
    }

    while (j <= mid2 && k <= right) {
      if (shouldSwap(array[k], array[j], ascending)) {
        tempArray[i++] = array[k++];
      } else {
        tempArray[i++] = array[j++];
      }
    }

    while (i <= mid1) {
      tempArray[i++] = array[i++];
    }

    while (j <= mid2) {
      tempArray[i++] = array[j++];
    }

    while (k <= right) {
      tempArray[i++] = array[k++];
    }

    System.arraycopy(tempArray, left, array, left, right - left + 1);
  }

  private static <T> boolean shouldSwap(T a, T b, boolean ascending) {
    return ascending ? a.compareTo(b) > 0 : a.compareTo(b) < 0;
  }

  public static void main(String[] args) {
    Integer[] array = {4, 2, 9, 5, 1, 6, 8, 3, 7};
    sort(array, true);
    System.out.println(Arrays.toString(array));
  }
}
```

