import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

public class RemoveDuplicatesAndSort {

    public static void main(String[] args) {
        int[] array = {5, 3, 2, 5, 4, 3, 1, 2, 4, 5}; // Sample input array
        int[] sortedArray = removeDuplicatesAndSort(array);

        System.out.println("Sorted array after removing duplicates: " + Arrays.toString(sortedArray));
        System.out.println("Frequency of each unique element:");
        displayFrequency(sortedArray);
    }

    public static int[] removeDuplicatesAndSort(int[] array) {
        if (array.length <= 1) {
            return array;
        }

        Map<Integer, Integer> frequencyMap = new HashMap<>();

        // Count the frequency of each element
        for (int num : array) {
            frequencyMap.put(num, frequencyMap.getOrDefault(num, 0) + 1);
        }

        // Create an array with unique elements
        int[] uniqueArray = new int[frequencyMap.size()];
        int index = 0;
        for (int num : frequencyMap.keySet()) {
            uniqueArray[index++] = num;
        }

        // Sort the array
        Arrays.sort(uniqueArray);

        return uniqueArray;
    }

    public static void displayFrequency(int[] array) {
        Map<Integer, Integer> frequencyMap = new HashMap<>();

        // Count the frequency of each element
        for (int num : array) {
            frequencyMap.put(num, frequencyMap.getOrDefault(num, 0) + 1);
        }

        // Display the frequency of each element
        for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
            System.out.println(entry.getKey() + " occurs " + entry.getValue() + " time(s)");
        }
    }
}
```

