  if (!isPrime(lowerBound) || !isPrime(upperBound)) {
    return "Lower and upper bounds must be prime numbers.";
  }

  // Check if the number is within the range
  if (number >= lowerBound && number <= upperBound) {
    return true;
  } else {
    return false;
  }
}

