class Point3D {
  constructor(x, y, z) {
    this.x = x;
    this.y = y;
    this.z = z;
  }

  distanceFromOrigin() {
    return Math.sqrt(this.x ** 2 + this.y ** 2 + this.z ** 2);
  }

  translate(dx, dy, dz) {
    this.x += dx;
    this.y += dy;
    this.z += dz;
  }

  isOrigin() {
    return this.x === 0 && this.y === 0 && this.z === 0;
  }

  static midpoint(point1, point2) {
    const x = (point1.x + point2.x) / 2;
    const y = (point1.y + point2.y) / 2;
    const z = (point1.z + point2.z) / 2;
    return new Point3D(x, y, z);
  }

  rotateX(angle) {
    const radian = (Math.PI / 180) * angle;
    const y = this.y * Math.cos(radian) - this.z * Math.sin(radian);
    const z = this.y * Math.sin(radian) + this.z * Math.cos(radian);
    this.y = y;
    this.z = z;
  }

  rotateY(angle) {
    const radian = (Math.PI / 180) * angle;
    const x = this.x * Math.cos(radian) + this.z * Math.sin(radian);
    const z = -this.x * Math.sin(radian) + this.z * Math.cos(radian);
    this.x = x;
    this.z = z;
  }

  rotateZ(angle) {
    const radian = (Math.PI / 180) * angle;
    const x = this.x * Math.cos(radian) - this.y * Math.sin(radian);
    const y = this.x * Math.sin(radian) + this.y * Math.cos(radian);
    this.x = x;
    this.y = y;
  }

  toString() {
    return `(${this.x},${this.y},${this.z})`;
  }
}

