Here's an implementation of a doubly linked list data structure in Python:

```python
class Node:
    def __init__(self, data):
        self.data = data
        self.prev = None
        self.next = None

class DoublyLinkedList:
    def __init__(self):
        self.head = None
        self.tail = None

    def insert_at_front(self, data):
        new_node = Node(data)
        if self.head is None:
            self.head = self.tail = new_node
        else:
            new_node.next = self.head
            self.head.prev = new_node
            self.head = new_node

    def insert_at_end(self, data):
        new_node = Node(data)
        if self.head is None:
            self.head = self.tail = new_node
        else:
            new_node.prev = self.tail
            self.tail.next = new_node
            self.tail = new_node

    def delete_at_front(self):
        if self.head is None:
            return
        if self.head == self.tail:
            self.head = self.tail = None
        else:
            self.head = self.head.next
            self.head.prev = None

    def delete_at_end(self):
        if self.head is None:
            return
        if self.head == self.tail:
            self.head = self.tail = None
        else:
            self.tail = self.tail.prev
            self.tail.next = None

    def reverse(self):
        if self.head is None:
            return
        current_node = self.head
        while current_node:
            temp = current_node.prev
            current_node.prev = current_node.next
            current_node.next = temp
            current_node = current_node.prev
        self.head, self.tail = self.tail, self.head

    def find(self, value):
        current_node = self.head
        while current_node:
            if current_node.data == value:
                return current_node
            current_node = current_node.next
        return None
```

This implementation uses a `Node` class to represent each node in the doubly linked list. The `DoublyLinkedList` class has methods to perform the desired operations:

- `insert_at_front` creates a new node with the given data and inserts it at the front of the list.
- `insert_at_end` creates a new node with the given data and inserts it at the end of the list.
- `delete_at_front` removes the first node from the list.
- `delete_at_end` removes the last node from the list.
- `reverse` reverses the order of the nodes in the list.
- `find` searches for a specific value in the list and returns the node that contains it, or `None` if the value is not found.

The time complexity for each operation is O(1) except for the `find` operation, which has a time complexity of O(n) in the worst case since it may need to traverse the entire list. The space complexity is O(1) for each operation.

