```javascript
// Function to generate the Fibonacci sequence in reverse order and calculate the sum
function fibonacciReverseAndSum(num) {
  let fibonacciSeq = [];

  // Recursive function to calculate the Fibonacci numbers
  function fibonacci(n) {
    if (n <= 1) {
      return n;
    }
    return fibonacci(n - 1) + fibonacci(n - 2);
  }

  // Generate the Fibonacci sequence up to the given number
  for (let i = num; i >= 0; i--) {
    fibonacciSeq.push(fibonacci(i));
  }

  // Print the Fibonacci sequence in reverse order
  console.log("Fibonacci sequence (reverse order):");
  console.log(fibonacciSeq.join(", "));

  // Calculate the sum of all numbers in the Fibonacci sequence
  let sum = fibonacciSeq.reduce((acc, curr) => acc + curr, 0);
  console.log("Sum of Fibonacci sequence:", sum);
}

