public class Student {
  private String id;
  private String name;
  private ArrayList<Integer> grades;

  public Student(String id, String name) {
    this.id = id;
    this.name = name;
    this.grades = new ArrayList<Integer>();
  }

  public void addGrade(int grade) {
    if (grade < 0 || grade > 100) {
      throw new IllegalArgumentException("Invalid grade. Grade must be between 0 and 100, inclusive.");
    }
    grades.add(grade);
  }

  public double calculateAverageGrade() {
    if (grades.isEmpty()) {
      throw new IllegalStateException("No grades available.");
    }
    int sum = 0;
    for (int grade : grades) {
      sum += grade;
    }
    return (double) sum / grades.size();
  }

  public int calculateHighestGrade() {
    if (grades.isEmpty()) {
      throw new IllegalStateException("No grades available.");
    }
    int highest = grades.get(0);
    for (int i = 1; i < grades.size(); i++) {
      if (grades.get(i) > highest) {
        highest = grades.get(i);
      }
    }
    return highest;
  }

  public int calculateLowestGrade() {
    if (grades.isEmpty()) {
      throw new IllegalStateException("No grades available.");
    }
    int lowest = grades.get(0);
    for (int i = 1; i < grades.size(); i++) {
      if (grades.get(i) < lowest) {
        lowest = grades.get(i);
      }
    }
    return lowest;
  }

  public int countGradesAboveThreshold(int threshold) {
    if (grades.isEmpty()) {
      throw new IllegalStateException("No grades available.");
    }
    int count = 0;
    for (int grade : grades) {
      if (grade > threshold) {
        count++;
      }
    }
    return count;
  }

  public double calculatePercentageAboveThreshold(int threshold) {
    if (grades.isEmpty()) {
      throw new IllegalStateException("No grades available.");
    }
    int countAboveThreshold = countGradesAboveThreshold(threshold);
    return (double) countAboveThreshold / grades.size() * 100;
  }
}

