```cpp
#include <iostream>
#include <vector>

// Function to calculate the inverse of a 2-D array
std::vector<std::vector<int>> inverseArray(const std::vector<std::vector<int>>& arr) {
    // Get the size of the array
    int size = arr.size();

    // Create a result array with the same size as the input array
    std::vector<std::vector<int>> result(size, std::vector<int>(size));

    // Calculate the determinant of the input array
    int determinant = (arr[0][0] * (arr[1][1] * arr[2][2] - arr[1][2] * arr[2][1])) - (arr[0][1] * (arr[1][0] * arr[2][2] - arr[1][2] * arr[2][0])) + (arr[0][2] * (arr[1][0] * arr[2][1] - arr[1][1] * arr[2][0]));

    // Check if the determinant is zero (array is not invertible)
    if (determinant == 0) {
        std::cout << "Array is not invertible!" << std::endl;
        return result;
    }

    // Calculate the cofactor matrix of the input array
    for (int i = 0; i < size; i++) {
        for (int j = 0; j < size; j++) {
            int sign = ((i + j) % 2 == 0) ? 1 : -1;
            int subDeterminant = (arr[(j + 1) % size][(i + 1) % size] * arr[(j + 2) % size][(i + 2) % size]) - (arr[(j + 1) % size][(i + 2) % size] * arr[(j + 2) % size][(i + 1) % size]);
            result[i][j] = sign * subDeterminant;
        }
    }

    // Calculate the adjugate matrix of the cofactor matrix
    for (int i = 0; i < size; i++) {
        for (int j = 0; j < size; j++) {
            result[i][j] /= determinant;
        }
    }

    return result;
}

int main() {
    std::vector<std::vector<int>> arr = {{1, 2, 3}, {4, 5, 6}, {7, 8, 9}};
    std::vector<std::vector<int>> result = inverseArray(arr);

    // Print the inverse array
    for (const auto& row : result) {
        for (const auto& element : row) {
            std::cout << element << " ";
        }
        std::cout << std::endl;
    }

    return 0;
}
