private static boolean isAnagram(String word) {
    // Create a frequency map to count the occurrences of each character in the word
    int[] frequencyMap = new int[26];
    for (int i = 0; i < word.length(); i++) {
        frequencyMap[word.charAt(i) - 'a']++;
    }

    // Check if the frequency map is symmetric, meaning that there are an even number of occurrences for each character
    int oddCount = 0;
    for (int count : frequencyMap) {
        if (count % 2 != 0) {
            oddCount++;
        }
    }

    // If there is at most one character with an odd number of occurrences, the word is an anagram
    return oddCount <= 1;
}

private static boolean isPalindrome(String word) {
    // Compare characters from both ends of the word until the middle
    int start = 0;
    int end = word.length() - 1;
    while (start < end) {
        if (word.charAt(start) != word.charAt(end)) {
            return false;
        }
        start++;
        end--;
    }
    return true;
}

