```javascript
function generateRandomString() {
  const lowercase = 'abcdefghijklmnopqrstuvwxyz';
  const uppercase = lowercase.toUpperCase();
  const digits = '0123456789';
  const specialCharacters = '!@#$%^&*()_+-={}[]|:;"<>,.?/~';

  let randomString = '';

  // Randomly select one character from each category
  const randomLowercase = lowercase[Math.floor(Math.random() * lowercase.length)];
  const randomUppercase = uppercase[Math.floor(Math.random() * uppercase.length)];
  const randomDigit = digits[Math.floor(Math.random() * digits.length)];
  const randomSpecialCharacter = specialCharacters[Math.floor(Math.random() * specialCharacters.length)];

  // Add the randomly selected characters to the string
  randomString += randomLowercase;
  randomString += randomUppercase;
  randomString += randomDigit;
  randomString += randomSpecialCharacter;

  const characters = lowercase + uppercase + digits + specialCharacters;

  // Generate the remaining random characters
  for (let i = 0; i < 16; i++) {
    const randomCharacter = characters[Math.floor(Math.random() * characters.length)];

    // Check if the character is already in the string
    if (!randomString.includes(randomCharacter)) {
      randomString += randomCharacter;
    } else {
      // If the character is already in the string, decrement the loop counter
      i--;
    }
  }

  return randomString;
}

