    return true;
}

int main() {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<int> dist(100, 1000);

    std::vector<int> primes;
    int product = 1;

    for (int i = 0; i < 10; i++) {
        int num;
        do {
            num = dist(gen);
        } while (!isPrime(num));
        primes.push_back(num);
        product *= num;
    }

    std::sort(primes.begin(), primes.end(), std::greater<int>());
    int median = primes[primes.size() / 2];

    std::cout << "Product of prime numbers: " << product << std::endl;
    std::cout << "Median of prime numbers: " << median << std::endl;

    std::cout << "Sorted prime numbers in descending order: ";
    for (int prime : primes) {
        std::cout << prime << " ";
    }
    std::cout << std::endl;

    return 0;
}
```

This code generates 10 random prime numbers in the range [100,1000], calculates their product, finds the median, and sorts the array in descending order. The prime numbers, product, median, and sorted array are then printed out.

