```c++
#include <iostream>
#include <cmath>

int calculateVolume(int length, int width, int height) {
    int volume = 0;
    int sign = (length < 0) ^ (width < 0) ^ (height < 0) ? -1 : 1;

    for (int i = 0; i < std::abs(length); ++i) {
        for (int j = 0; j < std::abs(width); ++j) {
