```python
import json
import xml.etree.ElementTree as ET
from xml.dom import minidom
from lxml import etree

def json_to_xml(json_array):
    try:
        # Convert JSON array to XML string
        root = ET.Element('root')
        for obj in json_array:
            element = ET.SubElement(root, 'person')
            for key, value in obj.items():
                if key == 'address':
                    address = ET.SubElement(element, 'address')
                    for addr_key, addr_value in value.items():
                        addr_element = ET.SubElement(address, addr_key)
                        addr_element.text = str(addr_value)
                else:
                    sub_element = ET.SubElement(element, key)
                    sub_element.text = str(value)

        # Create a formatted XML string
        xml_str = minidom.parseString(ET.tostring(root)).toprettyxml(indent="  ")
        return xml_str

    except Exception as e:
        return str(e)

def validate_xml(xml_str, xsd_file_path):
    try:
        # Load XSD schema file
        xsd_doc = etree.parse(xsd_file_path)
        xsd = etree.XMLSchema(xsd_doc)

        # Parse the XML string
        xml_doc = etree.fromstring(xml_str)

        # Validate the XML against the XSD schema
        xsd.validate(xml_doc)

        return "Validation successful."

    except etree.XMLSyntaxError as err:
        return f"XML syntax error: {err}"
    except etree.DocumentInvalid as err:
        return f"Invalid XML: {err}"
    except Exception as e:
        return str(e)


