```python
import datetime

class CalendarDate:
    def __init__(self, year, month, day):
        self.year = year
        self.month = month
        self.day = day

    def __str__(self):
        return f"{self.year}-{self.month:02d}-{self.day:02d}"

    def get_weekday(self):
        weekday = datetime.date(self.year, self.month, self.day).strftime("%A")
        return weekday

    def is_leap_year(self):
        if (self.year % 4 == 0 and self.year % 100 != 0) or self.year % 400 == 0:
            return True
        return False

    def add_days(self, n):
        date = datetime.date(self.year, self.month, self.day) + datetime.timedelta(days=n)
        self.year = date.year
        self.month = date.month
        self.day = date.day

    def subtract_days(self, n):
        date = datetime.date(self.year, self.month, self.day) - datetime.timedelta(days=n)
        self.year = date.year
        self.month = date.month
        self.day = date.day

    def add_months(self, n):
        year = self.year + (self.month + n - 1) // 12
        month = (self.month + n - 1) % 12 + 1
        day = min(self.day, self.get_month_length(month, year))
        self.year = year
        self.month = month
        self.day = day

    def subtract_months(self, n):
        year = self.year + (self.month - n - 1) // 12
        month = (self.month - n - 1) % 12 + 1
        day = min(self.day, self.get_month_length(month, year))
        self.year = year
        self.month = month
        self.day = day

    def add_years(self, n):
        self.year += n

    def subtract_years(self, n):
        self.year -= n

    def compare_dates(self, date):
        if self.year < date.year:
            return -1
        elif self.year > date.year:
            return 1
        elif self.month < date.month:
            return -1
        elif self.month > date.month:
            return 1
        elif self.day < date.day:
            return -1
        elif self.day > date.day:
            return 1
        else:
            return 0

    def get_month_length(self, month=None, year=None):
        if month is None:
            month = self.month
        if year is None:
            year = self.year
        if month in [1, 3, 5, 7, 8, 10, 12]:
            return 31
        elif month == 2:
            if self.is_leap_year(year):
                return 29
            else:
                return 28
        else:
            return 30

    def get_year_length(self):
        if self.is_leap_year():
            return 366
        else:
            return 365

    def get_season(self):
        seasons = {
            (1, 2, 3): "Winter",
            (4, 5, 6): "Spring",
            (7, 8, 9): "Summer",
            (10, 11, 12): "Fall"
        }
        for months, season in seasons.items():
            if self.month in months:
                return season

    def is_weekend(self):
        weekday = datetime.date(self.year, self.month, self.day).weekday()
        if weekday >= 5:  # Saturday is 5, Sunday is 6
            return True
        return False

    def get_quarter(self):
        quarters = {
            (1, 2, 3): "Q1",
            (4, 5, 6): "Q2",
            (7, 8, 9): "Q3",
            (10, 11, 12): "Q4"
        }
        for months, quarter in quarters.items():
            if self.month in months:
                return quarter

    def is_holiday(self):
        holidays = [
            CalendarDate(self.year, 1, 1),  # New Year's Day
            CalendarDate(self.year, 12, 25)  # Christmas Day
            # Add more holidays as needed
        ]
        if self in holidays:
            return True
        return False
```

This implementation uses the `datetime` module to handle some of the operations, such as getting the weekday and checking leap years. The `add_days()` and `subtract_days()` methods use `timedelta` to perform date arithmetic. The `add_months()` and `subtract_months()` methods handle the case where adding or subtracting months may change the year as well.

The additional methods `get_month_length()`, `get_year_length()`, `get_season()`, `is_weekend()`, `get_quarter()`, and `is_holiday()` provide additional functionality as requested.

Note: This implementation assumes that the input dates are in the Gregorian calendar. If you need to support different calendar systems, you would need to modify the code accordingly.

