import java.util.Arrays;

public class DeleteElementFromArray {
    public static void main(String[] args) {
        int[] array = {1, 3, 5, 6, 8};
        int position = 3;

        try {
            int[] updatedArray = deleteElement(array, position);
            System.out.println(Arrays.toString(updatedArray));
        } catch (Exception e) {
            System.out.println(e.getMessage());
        }
    }

    public static int[] deleteElement(int[] array, int position) throws Exception {
        if (array.length == 0) {
            throw new Exception("Error: The array is empty.");
        }

        if (position < 1 || position > array.length) {
            throw new Exception("Error: The position is outside the range of the array.");
        }

        int[] updatedArray = new int[array.length - 1];

        int index = 0;
        for (int i = 0; i < array.length; i++) {
            if (i != position - 1) {
                updatedArray[index++] = array[i];
            }
        }

        return updatedArray;
    }
}
