Here is an implementation of the function in JavaScript:

```javascript
function parseJSON(json) {
  // Validation: check if the input is a string and has a length less than or equal to 10^6 characters
  if (typeof json !== 'string' || json.length > 10 ** 6) {
    throw new Error('Invalid input');
  }

  // Validation: check if the input is an empty string or contains only whitespace characters
  if (/^\s*$/.test(json)) {
    return {};
  }

  let index = 0;

  // Helper function to skip whitespace characters
  function skipWhitespace() {
    while (index < json.length && /\s/.test(json[index])) {
      index++;
    }
  }

  // Helper function to parse a JSON value
  function parseValue() {
    skipWhitespace();

    if (json[index] === '{') {
      return parseObject();
    } else if (json[index] === '[') {
      return parseArray();
    } else if (json[index] === '"') {
      return parseString();
    } else if (json[index] === 't') {
      return parseTrue();
    } else if (json[index] === 'f') {
      return parseFalse();
    } else if (json[index] === 'n') {
      return parseNull();
    } else {
      return parseNumber();
    }
  }

  // Helper function to parse a JSON object
  function parseObject() {
    index++; // Skip the opening curly brace
    skipWhitespace();

    const obj = {};

    while (json[index] !== '}') {
      skipWhitespace();

      // Parse the key
      const key = parseString();

      skipWhitespace();
      if (json[index] !== ':') {
        throw new Error('Invalid JSON');
      }
      index++; // Skip the colon

      // Parse the value
      const value = parseValue();

      obj[key] = value;

      skipWhitespace();

      if (json[index] === ',') {
        index++; // Skip the comma
      } else if (json[index] !== '}') {
        throw new Error('Invalid JSON');
      }
    }

    index++; // Skip the closing curly brace

    return obj;
  }

  // Helper function to parse a JSON array
  function parseArray() {
    index++; // Skip the opening square bracket
    skipWhitespace();

    const arr = [];

    while (json[index] !== ']') {
      skipWhitespace();

      // Parse the value
      const value = parseValue();

      arr.push(value);

      skipWhitespace();

      if (json[index] === ',') {
        index++; // Skip the comma
      } else if (json[index] !== ']') {
        throw new Error('Invalid JSON');
      }
    }

    index++; // Skip the closing square bracket

    return arr;
  }

  // Helper function to parse a JSON string
  function parseString() {
    index++; // Skip the opening double quote

    let str = '';

    while (json[index] !== '"') {
      if (json[index] === '\\') {
        index++; // Skip the backslash

        // Handle escape characters
        if (json[index] === 'n') {
          str += '\n';
        } else if (json[index] === 'r') {
          str += '\r';
        } else if (json[index] === 't') {
          str += '\t';
        } else if (json[index] === 'b') {
          str += '\b';
        } else if (json[index] === 'f') {
          str += '\f';
        } else if (json[index] === '"') {
          str += '"';
        } else if (json[index] === '\\') {
          str += '\\';
        } else {
          throw new Error('Invalid JSON');
        }
      } else {
        str += json[index];
      }

      index++;
    }

    index++; // Skip the closing double quote

    return str;
  }

  // Helper function to parse a JSON number
  function parseNumber() {
    let numStr = '';

    while (index < json.length && /[0-9.-]/.test(json[index])) {
      numStr += json[index];
      index++;
    }

    const num = Number(numStr);

    if (isNaN(num)) {
      throw new Error('Invalid JSON');
    }

    return num;
  }

  // Helper function to parse the JSON value true
  function parseTrue() {
    if (json.substr(index, 4) === 'true') {
      index += 4;
      return true;
    } else {
      throw new Error('Invalid JSON');
    }
  }

  // Helper function to parse the JSON value false
  function parseFalse() {
    if (json.substr(index, 5) === 'false') {
      index += 5;
      return false;
    } else {
      throw new Error('Invalid JSON');
    }
  }

  // Helper function to parse the JSON value null
  function parseNull() {
    if (json.substr(index, 4) === 'null') {
      index += 4;
      return null;
    } else {
      throw new Error('Invalid JSON');
    }
  }

  // Parse the JSON string
  const result = parseValue();

  skipWhitespace();

  // Check if the entire input has been consumed
  if (index < json.length) {
    throw new Error('Invalid JSON');
  }

  return result;
}
```

This implementation follows the given requirements and handles the provided scenarios. It uses a recursive approach to parse the JSON string character by character. It also includes error handling for invalid JSON strings and checks for input size and whitespace.

