    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def generate_matrix():
    matrix = [[0 for _ in range(5)] for _ in range(5)]
    row_sums = [0 for _ in range(5)]
    column_sums = [0 for _ in range(5)]

