        for j in range(5):
            while True:
                num = random.randint(1, 100)
                if num not in matrix[i] and num not in [matrix[k][j] for k in range(5)]:
                    matrix[i][j] = num
                    row_sums[i] += num
                    column_sums[j] += num
                    break

    for i in range(5):
        while not is_prime(row_sums[i]):
            for j in range(5):
                num = random.randint(1, 100)
                if num != matrix[i][j] and num not in [matrix[i][k] for k in range(5)]:
                    row_sums[i] += num - matrix[i][j]
                    matrix[i][j] = num

    for j in range(5):
        while not is_prime(column_sums[j]):
            for i in range(5):
                num = random.randint(1, 100)
                if num != matrix[i][j] and num not in [matrix[k][j] for k in range(5)]:
                    column_sums[j] += num - matrix[i][j]
