Here is a C program that sorts an array in either ascending or descending order using the QuickSort algorithm:

```c
#include <stdio.h>

void swap(int* a, int* b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

int partition(int arr[], int low, int high) {
    int pivot = arr[high];
    int i = (low - 1);

    for (int j = low; j <= high - 1; j++) {
        if (arr[j] > pivot) {
            i++;
            swap(&arr[i], &arr[j]);
        }
    }
    swap(&arr[i + 1], &arr[high]);
    return (i + 1);
}

void quickSort(int arr[], int low, int high) {
    if (low < high) {
        int pi = partition(arr, low, high);
        quickSort(arr, low, pi - 1);
        quickSort(arr, pi + 1, high);
    }
}

void printArray(int arr[], int size) {
    for (int i = 0; i < size; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");
}

int main() {
    int size;
    printf("Enter the size of the array: ");
    scanf("%d", &size);

    int arr[size];
    printf("Enter the elements of the array: ");
    for (int i = 0; i < size; i++) {
        scanf("%d", &arr[i]);
    }

    char order;
    printf("Enter 'A' for ascending order or 'D' for descending order: ");
    scanf(" %c", &order);

    if (order == 'D') {
        quickSort(arr, 0, size - 1);
    } else if (order == 'A') {
        // Reverse the order of elements to perform ascending order sort
        for (int i = 0, j = size - 1; i < j; i++, j--) {
            swap(&arr[i], &arr[j]);
        }
        quickSort(arr, 0, size - 1);
    } else {
        printf("Invalid input.\n");
        return 0;
    }

    if (order == 'D') {
        printf("Sorted array in descending order: ");
    } else if (order == 'A') {
        printf("Sorted array in ascending order: ");
    }
    printArray(arr, size);

    return 0;
}
```

This program allows the user to input the size of the array, the elements of the array, and select whether they want to sort the array in ascending or descending order. The program then uses the QuickSort algorithm to sort the array and displays the sorted array to the user.

function bubbleSort(arr) {
  // Validate input array
  if (!Array.isArray(arr) || arr.length < 2 || arr.length > 100) {
    throw new Error("Input array must have a length between 2 and 100");
  }

  const uniqueElements = new Set(arr);
  if (uniqueElements.size !== arr.length) {
    throw new Error("Input array must contain unique elements");
  }

  for (let i = 0; i < arr.length - 1; i++) {
    let swapped = false;

    for (let j = 0; j < arr.length - i - 1; j++) {
      if (arr[j] > arr[j + 1]) {
        // Swap elements
        const temp = arr[j];
        arr[j] = arr[j + 1];
        arr[j + 1] = temp;

        swapped = true;
      }
    }

    if (!swapped) {
      // If no swaps were made in this pass, the array is already sorted
      break;
    }
  }

  const totalComparisons = (arr.length * (arr.length - 1)) / 2;

  return {
    sortedArray: arr,
    totalComparisons: totalComparisons
  };
}

// Test case
