One way to delete a specific element from a linked list in C++ without using the `delete` keyword is by rearranging the pointers of the surrounding nodes.

Here's an example of how this can be done:

```cpp
#include <iostream>

struct Node {
    int data;
    Node* next;
};

// Function to delete a specific element from a linked list
void deleteElement(Node** head, int target) {
    Node* current = *head;
    Node* prev = nullptr;

    // If the first element itself is the target
    if (current != nullptr && current->data == target) {
        *head = current->next;  // Update head
        delete current;         // Delete the node
        return;
    }

    // Search for the target node and keep track of previous node
    while (current != nullptr && current->data != target) {
        prev = current;
        current = current->next;
    }

    // If the target is not found in the list
    if (current == nullptr) {
        std::cout << "Element not found." << std::endl;
        return;
    }

    // Unlink the node from the linked list
    prev->next = current->next;
    delete current;  // Delete the node
}

// Function to print the linked list
void printList(Node* head) {
    Node* current = head;
    while (current != nullptr) {
        std::cout << current->data << " ";
        current = current->next;
    }
    std::cout << std::endl;
}

int main() {
    Node* head = nullptr;
    Node* second = nullptr;
    Node* third = nullptr;

    // Allocate 3 nodes in the heap
    head = new Node();
    second = new Node();
    third = new Node();

    head->data = 1;
    head->next = second;

    second->data = 2;
    second->next = third;

    third->data = 3;
    third->next = nullptr;

    std::cout << "Original List: ";
    printList(head);

    int target = 2;
    deleteElement(&head, target);

    std::cout << "List after deleting " << target << ": ";
    printList(head);

    return 0;
}
```

In the above example, the `deleteElement` function takes a pointer to the head of the linked list and the target element to be deleted. It traverses the linked list, searching for the target element. Once found, it rearranges the pointers of the surrounding nodes to skip the target node. Finally, it deletes the target node using the `delete` keyword.

