    private static void displayMenu() {
        System.out.println("Choose an option:");
        System.out.println("1. Calculate area of a circle");
        System.out.println("2. Calculate circumference of a circle");
        System.out.println("3. Exit");
    }

    private static int getChoice(Scanner scanner) {
        int choice = 0;
        boolean isValidChoice = false;

        while (!isValidChoice) {
            System.out.print("Enter your choice: ");
            if (scanner.hasNextInt()) {
                choice = scanner.nextInt();
                isValidChoice = true;
            } else {
                System.out.println("Invalid choice. Please enter a valid option.");
                scanner.next(); // clear the invalid input
            }
        }

        return choice;
    }

    private static double getRadius(Scanner scanner) {
        double radius = 0;
        boolean isValidRadius = false;

        while (!isValidRadius) {
            System.out.print("Enter the radius of the circle: ");
            if (scanner.hasNextDouble()) {
                radius = scanner.nextDouble();
                if (radius > 0 && radius <= MAX_RADIUS) {
                    isValidRadius = true;
                } else {
                    System.out.println("Invalid radius. Please enter a positive value less than or equal to " + MAX_RADIUS + ".");
                }
            } else {
                System.out.println("Invalid radius. Please enter a valid number.");
                scanner.next(); // clear the invalid input
            }
        }

        return radius;
    }

    private static void calculateArea(Scanner scanner) {
        double radius = getRadius(scanner);
        double area = Math.PI * Math.pow(radius, 2);
        System.out.printf("Area of the circle: %.2f%n", area);
        circleCounter++;
        System.out.println("Total circles calculated: " + circleCounter);
    }

    private static void calculateCircumference(Scanner scanner) {
        double radius = getRadius(scanner);
        double circumference = 2 * Math.PI * radius;
        System.out.printf("Circumference of the circle: %.2f%n", circumference);
        circleCounter++;
        System.out.println("Total circles calculated: " + circleCounter);
    }
}
