```cpp
#include <iostream>

// Function to calculate the sum of elements in the array using recursion
int calculateSum(int arr[], int size, int index = 0, int sum = 0) {
    if (index >= size) {
        return sum;
    }
    return calculateSum(arr, size, index + 1, sum + arr[index]);
}

int main() {
    int fibonacciArray[10];

    // Assigning the first two elements
    fibonacciArray[0] = 0;
    fibonacciArray[1] = 1;

    // Assigning the remaining elements as the sum of the previous two elements
    for (int i = 2; i < 10; i++) {
        fibonacciArray[i] = fibonacciArray[i - 1] + fibonacciArray[i - 2];
    }

    // Printing the array
    std::cout << "Fibonacci Array: ";
    for (int i = 0; i < 10; i++) {
        std::cout << fibonacciArray[i] << " ";
    }
    std::cout << std::endl;

    // Calculating the sum of the elements using recursion
    int sum = calculateSum(fibonacciArray, 10);
    std::cout << "Sum of Elements: " << sum << std::endl;

    return 0;
}
