Here is an implementation of the BinarySearchTree class in C++ that includes all the required functionalities:

```cpp
#include <iostream>

class Node {
public:
    int data;
    Node* left;
    Node* right;

    Node(int value) {
        data = value;
        left = nullptr;
        right = nullptr;
    }
};

class BinarySearchTree {
private:
    Node* root;

    Node* insertHelper(Node* node, int value) {
        if (node == nullptr) {
            return new Node(value);
        }

        if (value < node->data) {
            node->left = insertHelper(node->left, value);
        }
        else {
            node->right = insertHelper(node->right, value);
        }

        return node;
    }

    Node* searchHelper(Node* node, int value) {
        if (node == nullptr || node->data == value) {
            return node;
        }

        if (value < node->data) {
            return searchHelper(node->left, value);
        }

        return searchHelper(node->right, value);
    }

    Node* findMin(Node* node) {
        if (node == nullptr || node->left == nullptr) {
            return node;
        }

        return findMin(node->left);
    }

    Node* deleteHelper(Node* node, int value) {
        if (node == nullptr) {
            return node;
        }
        else if (value < node->data) {
            node->left = deleteHelper(node->left, value);
        }
        else if (value > node->data) {
            node->right = deleteHelper(node->right, value);
        }
        else {
            // Node to be deleted is found

            // Case 1: No child or only one child
            if (node->left == nullptr) {
                Node* temp = node->right;
                delete node;
                return temp;
            }
            else if (node->right == nullptr) {
                Node* temp = node->left;
                delete node;
                return temp;
            }

            // Case 2: Two children
            Node* temp = findMin(node->right);
            node->data = temp->data;
            node->right = deleteHelper(node->right, temp->data);
        }

        return node;
    }

    void inOrderTraversal(Node* node) {
        if (node != nullptr) {
            inOrderTraversal(node->left);
            std::cout << node->data << " ";
            inOrderTraversal(node->right);
        }
    }

    int calculateHeight(Node* node) {
        if (node == nullptr) {
            return -1;
        }

        int leftHeight = calculateHeight(node->left);
        int rightHeight = calculateHeight(node->right);

        return 1 + std::max(leftHeight, rightHeight);
    }

    bool isBalancedHelper(Node* node) {
        if (node == nullptr) {
            return true;
        }

        int leftHeight = calculateHeight(node->left);
        int rightHeight = calculateHeight(node->right);

        int heightDiff = std::abs(leftHeight - rightHeight);
        if (heightDiff > 1) {
            return false;
        }

        return isBalancedHelper(node->left) && isBalancedHelper(node->right);
    }

public:
    BinarySearchTree() {
        root = nullptr;
    }

    void insert(int value) {
        root = insertHelper(root, value);
    }

    bool search(int value) {
        return searchHelper(root, value) != nullptr;
    }

    void remove(int value) {
        root = deleteHelper(root, value);
    }

    void inOrderTraversal() {
        inOrderTraversal(root);
    }

    int findMin() {
        Node* minNode = findMin(root);
        return minNode->data;
    }

    int findMax() {
        Node* maxNode = root;
        while (maxNode->right != nullptr) {
            maxNode = maxNode->right;
        }
        return maxNode->data;
    }

    int calculateHeight() {
        return calculateHeight(root);
    }

    bool isBalanced() {
        return isBalancedHelper(root);
    }
};

int main() {
    BinarySearchTree bst;
    bst.insert(50);
    bst.insert(30);
    bst.insert(20);
    bst.insert(40);
    bst.insert(70);
    bst.insert(60);
    bst.insert(80);

    std::cout << "In-order traversal: ";
    bst.inOrderTraversal();
    std::cout << std::endl;

    std::cout << "Minimum element: " << bst.findMin() << std::endl;
    std::cout << "Maximum element: " << bst.findMax() << std::endl;

    std::cout << "Height of the tree: " << bst.calculateHeight() << std::endl;

    std::cout << "Is the tree balanced? " << (bst.isBalanced() ? "Yes" : "No") << std::endl;

    bst.remove(30);
    bst.remove(60);

    std::cout << "In-order traversal after removing 30 and 60: ";
    bst.inOrderTraversal();
    std::cout << std::endl;

    return 0;
}
```

This implementation handles the edge cases properly and provides efficient operations for inserting, searching, deleting, traversing, finding the minimum and maximum elements, calculating the height, and checking if the tree is balanced.

