        if string[i] == '%':
            if i + 1 < len(string):
                format_code = string[i + 1]
                if format_code in values:
                    value = values[format_code]
                    if isinstance(value, str) and format_code == 's':
                        result += value
                    elif isinstance(value, int) and format_code == 'd':
                        result += str(value)
                    elif isinstance(value, float) and format_code == 'f':
                        result += str(value)
                    else:
                        raise TypeError(f"Incompatible type for format code {format_code}")
                    i += 2
                else:
                    result += string[i]
                    i += 1
            else:
                result += string[i]
                i += 1
        else:
