function filterStringByArray(str, arr) {
  let result = [];
  for (let i = 0; i < str.length; i++) {
    for (let j = 0; j < arr.length; j++) {
      if (str.includes(arr[j]) && !result.includes(str[i])) {
        result.push(str[i]);
      }
    }
  }
  return result;
}
