Here is the implementation of the 'Student' class with the functionalities mentioned above:

```cpp
#include <iostream>
#include <unordered_map>
#include <vector>
#include <limits>

class Student {
private:
    int age;
    std::string name;
    int studentId;
    std::unordered_map<std::string, int> grades;

public:
    Student(int age, const std::string& name, int studentId) {
        this->age = age;
        this->name = name;
        this->studentId = studentId;
    }

    void addGrade(const std::string& subject, int grade) {
        grades[subject] = grade;
    }

    double getAverageGrade() const {
        if (grades.empty()) {
            std::cerr << "No grades available." << std::endl;
            return 0.0;
        }

        int sum = 0;
        for (const auto& grade : grades) {
            sum += grade.second;
        }
        return static_cast<double>(sum) / grades.size();
    }

    int getHighestGrade() const {
        if (grades.empty()) {
            std::cerr << "No grades available." << std::endl;
            return std::numeric_limits<int>::min();
        }

        int highestGrade = std::numeric_limits<int>::min();
        for (const auto& grade : grades) {
            if (grade.second > highestGrade) {
                highestGrade = grade.second;
            }
        }
        return highestGrade;
    }

    std::string getSubjectWithHighestGrade() const {
        if (grades.empty()) {
            std::cerr << "No grades available." << std::endl;
            return "";
        }

        int highestGrade = std::numeric_limits<int>::min();
        std::string subjectWithHighestGrade;
        for (const auto& grade : grades) {
            if (grade.second > highestGrade) {
                highestGrade = grade.second;
                subjectWithHighestGrade = grade.first;
            }
        }
        return subjectWithHighestGrade;
    }

    std::string getSubjectWithLowestGrade() const {
        if (grades.empty()) {
            std::cerr << "No grades available." << std::endl;
            return "";
        }

        int lowestGrade = std::numeric_limits<int>::max();
        std::string subjectWithLowestGrade;
        for (const auto& grade : grades) {
            if (grade.second < lowestGrade) {
                lowestGrade = grade.second;
                subjectWithLowestGrade = grade.first;
            }
        }
        return subjectWithLowestGrade;
    }
};

int main() {
    Student student(20, "John", 1234);
    student.addGrade("Math", 85);
    student.addGrade("Science", 92);
    student.addGrade("English", 78);

    std::cout << "Average grade: " << student.getAverageGrade() << std::endl;
    std::cout << "Highest grade: " << student.getHighestGrade() << std::endl;
    std::cout << "Subject with highest grade: " << student.getSubjectWithHighestGrade() << std::endl;
    std::cout << "Subject with lowest grade: " << student.getSubjectWithLowestGrade() << std::endl;

    return 0;
}
```

In the above implementation, I have used an `unordered_map` to store the grades for each subject, where the subject name is the key and the grade is the value. The member functions `addGrade`, `getAverageGrade`, `getHighestGrade`, `getSubjectWithHighestGrade`, and `getSubjectWithLowestGrade` have been implemented according to the given requirements. Proper error handling has been included for cases where no grades are available or invalid input is provided.

