Here is a JavaScript program that finds the greatest common divisor of multiple numbers, including prime factors and highest powers that divide all the numbers:

```javascript
// Function to find the greatest common divisor (GCD) of two numbers
function gcd(a, b) {
  if (b === 0) {
    return a;
  }
  return gcd(b, a % b);
}

// Function to find the prime factors of a number
function primeFactors(num) {
  const factors = [];
  let n = num;

  while (n % 2 === 0) {
    factors.push(2);
    n /= 2;
  }

  for (let i = 3; i <= Math.sqrt(n); i += 2) {
    while (n % i === 0) {
      factors.push(i);
      n /= i;
    }
  }

  if (n > 2) {
    factors.push(n);
  }

  return factors;
}

// Function to find the highest power of a prime factor that divides all the numbers
function highestPowerOfPrime(prime, numbers) {
  let power = Infinity;

  for (let i = 0; i < numbers.length; i++) {
    let count = 0;
    let n = numbers[i];

    while (n % prime === 0) {
      count++;
      n /= prime;
    }

    power = Math.min(power, count);
  }

  return power;
}

// Function to find the greatest common divisor among all the numbers in all the arrays
function findGCD(numberArrays) {
  let gcdResult = 1;

  for (let i = 0; i < numberArrays.length; i++) {
    const numbers = numberArrays[i].map(num => Math.abs(num));
    gcdResult = gcd(gcdResult, ...numbers);
  }

  const primeFactorsResult = primeFactors(gcdResult);
  const primePowers = {};

  for (let i = 0; i < primeFactorsResult.length; i++) {
    const prime = primeFactorsResult[i];
    primePowers[prime] = highestPowerOfPrime(prime, [...numbers]);
  }

  return {
    gcd: gcdResult,
    primeFactors: primeFactorsResult,
    primePowers: primePowers
  };
}

// Example usage
const numberArrays = [[1024, 768, 256], [128, 64, 32], [512, 256, 128]];
const result = findGCD(numberArrays);

console.log("Greatest Common Divisor:", result.gcd);
console.log("Prime Factors:", result.primeFactors);
console.log("Highest Powers of Prime Factors:", result.primePowers);
```

This program uses the Euclidean algorithm to efficiently find the greatest common divisor. It also implements the primeFactors function to find the prime factors of a number, and the highestPowerOfPrime function to find the highest power of a prime factor that divides all the numbers.

The findGCD function takes an array of arrays of numbers as input. It iterates over each inner array, finds the absolute values of the numbers, and calculates the greatest common divisor using the gcd function. It then calculates the prime factors of the gcd using the primeFactors function, and determines the highest powers of the prime factors that divide all the numbers using the highestPowerOfPrime function.

Finally, the program prints the greatest common divisor, prime factors, and highest powers of prime factors to the console.

To create a dictionary in JavaScript that meets the given requirements, we can use a combination of an object and a doubly linked list. The object will store the key-value pairs, and the doubly linked list will keep track of the order of elements based on their usage. Here's an implementation:

```javascript
class LRUDictionary {
  constructor(capacity) {
    this.capacity = capacity;
    this.count = 0;
    this.cache = {};
    this.head = null;
    this.tail = null;
  }

  insert(key, value) {
    if (typeof key !== 'string' || typeof value !== 'number') {
      console.log('Invalid key or value type. Only string keys and integer values are allowed.');
      return;
    }

    if (this.cache[key]) {
      this.cache[key].value = value;
      this.updateUsage(this.cache[key]);
      return;
    }

    if (this.count >= this.capacity) {
      delete this.cache[this.tail.key];
      this.removeElement(this.tail);
      this.count--;
    }

    const node = { key, value, prev: null, next: null };
    this.cache[key] = node;
    this.addElement(node);
    this.count++;
  }

  get(key) {
    if (this.cache[key]) {
      this.updateUsage(this.cache[key]);
      return this.cache[key].value;
    }

    return null;
  }

  remove(key) {
    if (this.cache[key]) {
      const node = this.cache[key];
      delete this.cache[key];
      this.removeElement(node);
      this.count--;
    }
  }

  addElement(node) {
    if (this.head === null) {
      this.head = node;
      this.tail = node;
    } else {
      node.next = this.head;
      this.head.prev = node;
      this.head = node;
    }
  }

  removeElement(node) {
    if (node.prev === null) {
      this.head = node.next;
    } else {
      node.prev.next = node.next;
    }

    if (node.next === null) {
      this.tail = node.prev;
    } else {
      node.next.prev = node.prev;
    }
  }

  updateUsage(node) {
    this.removeElement(node);
    this.addElement(node);
  }
}
```

Now, let's see how we can use this `LRUDictionary`:

```javascript
const dictionary = new LRUDictionary(100);
dictionary.insert('key1', 100);
dictionary.insert('key2', 200);
console.log(dictionary.get('key1')); // Output: 100
console.log(dictionary.get('key2')); // Output: 200
dictionary.insert('key3', 300);
console.log(dictionary.get('key1')); // Output: null (LRU element got evicted)
console.log(dictionary.get('key3')); // Output: 300
dictionary.remove('key2');
console.log(dictionary.get('key2')); // Output: null
```

In this implementation, the `insert` method handles inserting or updating an element, the `get` method retrieves the value for a given key, and the `remove` method deletes an element based on its key. The `addElement` method adds an element to the front of the linked list, the `removeElement` method removes an element from the linked list, and the `updateUsage` method moves an element to the front of the linked list when it is accessed.

