function fibonacciSeries(n) {
  var fib = [];
  fib[0] = 0;
  fib[1] = 1;
  var sum = fib[0] + fib[1];
  for (var i = 2; i < n; i++) {
    fib[i] = fib[i - 1] + fib[i - 2];
    if (fib[i] % 3 !== 0 || fib[i] % 5 !== 0) {
      sum += fib[i];
    }
  }
  return { fib: fib.slice(0, n), sum: sum };
