Here's an implementation of the Quick Sort algorithm in C++ that satisfies all the given requirements:

```cpp
#include <iostream>
#include <random>
using namespace std;

// Function to swap two elements
void swap(int* a, int* b) {
    int t = *a;
    *a = *b;
    *b = t;
}

// Partition function to select a pivot and place it in the correct position
int partition(int arr[], int low, int high, bool ascending) {
    int pivot = arr[high]; // Selecting the last element as the pivot
    int i = (low - 1);

    for (int j = low; j <= high - 1; j++) {
        if ((ascending && arr[j] <= pivot) || (!ascending && arr[j] >= pivot)) {
            i++;
            swap(&arr[i], &arr[j]);
        }
    }
    swap(&arr[i + 1], &arr[high]);
    return (i + 1);
}

// Quick Sort function
void quickSort(int arr[], int low, int high, bool ascending) {
    if (low < high) {
        int pi = partition(arr, low, high, ascending);

        // Recursive calls to sort the sub-arrays
        quickSort(arr, low, pi - 1, ascending);
        quickSort(arr, pi + 1, high, ascending);
    }
}

// Function to print the sorted array
void printArray(int arr[], int size) {
    for (int i = 0; i < size; i++)
        cout << arr[i] << " ";
    cout << endl;
}

int main() {
    const int SIZE = 10; // Size of the array
    int arr[SIZE];

    // Randomly generate integers in the range of -10^9 to 10^9
    random_device rd;
    mt19937 gen(rd());
    uniform_int_distribution<> dis(-1000000000, 1000000000);
    for (int i = 0; i < SIZE; i++) {
        arr[i] = dis(gen);
    }

    cout << "Original array: ";
    printArray(arr, SIZE);

    // Sort the array in ascending order
    quickSort(arr, 0, SIZE - 1, true);
    cout << "Ascending order: ";
    printArray(arr, SIZE);

    // Sort the array in descending order
    quickSort(arr, 0, SIZE - 1, false);
    cout << "Descending order: ";
    printArray(arr, SIZE);

    return 0;
}
```

Explanation:
- The `swap` function is used to swap two elements in the array.
- The `partition` function selects the last element as the pivot and rearranges the array such that all elements smaller than the pivot are placed before it and all elements greater than the pivot are placed after it.
- The `quickSort` function recursively calls itself to sort the sub-arrays before and after the pivot.
- The `printArray` function is used to print the sorted array.
- In the `main` function, an array of random integers in the range of -10^9 to 10^9 is generated using the `random_device` and `uniform_int_distribution` classes.
- The original array is printed, then the `quickSort` function is called to sort the array in both ascending and descending order.
- Finally, the sorted arrays are printed.

To handle attributes in the XML document, you can modify the existing code by checking for attributes while parsing the XML elements. Here's the updated code:

```javascript
function parseXML(xml) {
  let result = {};

  function parseNode(node, obj) {
    if (node.nodeType === 3) { // text node
      if (node.nodeValue.trim()) {
        obj["text"] = node.nodeValue.trim();
      }
    } else if (node.nodeType === 1) { // element node
      let nodeName = node.nodeName;
      let children = node.childNodes;
      let attributes = node.attributes;

      if (!obj[nodeName]) {
        obj[nodeName] = [];
      }

      let item = {};

      if (attributes.length > 0) {
        item["@attributes"] = {};
        for (let i = 0; i < attributes.length; i++) {
          let attribute = attributes[i];
          item["@attributes"][attribute.nodeName] = attribute.nodeValue;
        }
      }

      for (let i = 0; i < children.length; i++) {
        parseNode(children[i], item);
      }

      obj[nodeName].push(item);
    }
  }

  parseNode(xml.documentElement, result);

  return result;
}
```

