import java.util.ArrayList;
import java.util.List;

public class UniqueLimitedArrayList implements List<Integer> {
    private static final int MAX_SIZE = 10;
    private List<Integer> elements;

    public UniqueLimitedArrayList() {
        elements = new ArrayList<>();
    }

    @Override
    public boolean add(Integer element) {
        if (elements.contains(element)) {
            throw new DuplicateElementException("Element already exists in the list");
        }
        if (elements.size() >= MAX_SIZE) {
            throw new MaximumSizeExceededException("Maximum size of the list has been reached");
        }
        return elements.add(element);
    }

    @Override
    public int get(int index) {
        if (index < 0 || index >= elements.size()) {
            throw new InvalidIndexException("Invalid index");
        }
        return elements.get(index);
    }

    @Override
    public boolean remove(Object element) {
        return elements.remove(element);
    }

    @Override
    public void clear() {
        elements.clear();
    }

    @Override
    public int size() {
        return elements.size();
    }

    @Override
    public boolean isEmpty() {
        return elements.isEmpty();
    }

    // Other List interface methods are not implemented for brevity

    // Custom exceptions

    public static class MaximumSizeExceededException extends RuntimeException {
        public MaximumSizeExceededException(String message) {
            super(message);
        }
    }

    public static class InvalidIndexException extends RuntimeException {
        public InvalidIndexException(String message) {
            super(message);
        }
    }

    public static class DuplicateElementException extends RuntimeException {
        public DuplicateElementException(String message) {
            super(message);
        }
    }
}
