To print the textual representation of an AVL tree with balance factors and return the total number of nodes, you can follow these steps:

1. Define a class `Node` to represent each node of the AVL tree. Each node should have three attributes: `data` to store the value of the node, `left` and `right` to store references to the left and right child nodes, and `balance_factor` to store the difference in height between its left and right subtree.

2. Define a class `AVLTree` to represent the AVL tree. The class should have an attribute `root` to store the reference to the root node.

3. Implement the `__init__` method of the `AVLTree` class to initialize an empty AVL tree with the root node set to `None`.

4. Implement the `insert` method of the `AVLTree` class to insert a new node into the AVL tree. When inserting a new node, you need to update the balance factors of the affected nodes and perform AVL tree rotations if necessary to maintain the balance of the tree.

5. Implement a helper method `update_balance_factor` that recursively updates the balance factors of the nodes in the AVL tree.

6. Implement a helper method `print_tree` that recursively prints the textual representation of the AVL tree with balance factors.

7. Implement a helper method `count_nodes` that recursively counts the total number of nodes in the AVL tree.

Here's the code implementation in Python:

```python
class Node:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None
        self.balance_factor = 0

class AVLTree:
    def __init__(self):
        self.root = None

    def insert(self, data):
        if not self.root:
            self.root = Node(data)
        else:
            self._insert_recursive(data, self.root)

    def _insert_recursive(self, data, node):
        if data < node.data:
            if node.left:
                self._insert_recursive(data, node.left)
            else:
                node.left = Node(data)
        else:
            if node.right:
                self._insert_recursive(data, node.right)
            else:
                node.right = Node(data)

        self.update_balance_factor(node)

    def update_balance_factor(self, node):
        left_height = self.get_height(node.left)
        right_height = self.get_height(node.right)
        node.balance_factor = right_height - left_height

        if node.left:
            self.update_balance_factor(node.left)
        if node.right:
            self.update_balance_factor(node.right)

    def get_height(self, node):
        if not node:
            return 0
        left_height = self.get_height(node.left)
        right_height = self.get_height(node.right)
        return max(left_height, right_height) + 1

    def print_tree(self):
        self._print_tree_recursive(self.root)

    def _print_tree_recursive(self, node):
        if node:
            self._print_tree_recursive(node.left)
            print(f"{node.data} ({node.balance_factor})")
            self._print_tree_recursive(node.right)

    def count_nodes(self):
        return self._count_nodes_recursive(self.root)

    def _count_nodes_recursive(self, node):
        if node:
            return 1 + self._count_nodes_recursive(node.left) + self._count_nodes_recursive(node.right)
        else:
            return 0

# Example usage:
avl_tree = AVLTree()
avl_tree.insert(5)
avl_tree.insert(3)
avl_tree.insert(2)
avl_tree.insert(4)
avl_tree.insert(7)
avl_tree.insert(6)
avl_tree.insert(8)

avl_tree.print_tree()
print(f"Total number of nodes: {avl_tree.count_nodes()}")
```

