function mergeJSONObjects(obj1, obj2) {
  // Check if both objects have the same keys
  const keys1 = Object.keys(obj1);
  const keys2 = Object.keys(obj2);
  if (!isEqual(keys1, keys2)) {
    throw new Error("Objects do not have the same keys");
  }

  // Check if the "data" key in both objects is an array
  if (!Array.isArray(obj1.data) || !Array.isArray(obj2.data)) {
    throw new Error("The 'data' key is not an array");
  }

  // Merge the "data" arrays of both objects into a single array
  const mergedArray = obj1.data.concat(obj2.data);

  // Sort the merged array in ascending order based on the values of the "name" key
  mergedArray.sort((a, b) => a.name.localeCompare(b.name));

  // Remove any duplicate entries from the merged array
  const uniqueArray = mergedArray.filter(
    (value, index, self) =>
      self.findIndex((v) => v.name === value.name) === index
  );

  // Create a new object with the merged and sorted array as the "data" key's value
  const newObj = { data: uniqueArray };

  // Assign the "name" key of the first object to the "name" key of the new object
  newObj.name = obj1.name;

  // Return the new object
  return newObj;
}

