def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def cube_of_primes(n):
    primes_dict = {}
    count = 0
    for num in range(2, n+1):
        if is_prime(num):
            primes_dict[num] = num ** 3
            count += 1
    return primes_dict, count

