Here's an example implementation of the 2D vector class in Java:

```java
import java.util.Objects;

public class Vector2D {
    private double x;
    private double y;

    public Vector2D(double x, double y) {
        this.x = x;
        this.y = y;
    }

    public double getX() {
        return x;
    }

    public double getY() {
        return y;
    }

    public void setX(double x) {
        this.x = x;
    }

    public void setY(double y) {
        this.y = y;
    }

    public double getMagnitude() {
        return Math.sqrt(x * x + y * y);
    }

    public double dotProduct(Vector2D other) {
        return x * other.getX() + y * other.getY();
    }

    public double angleBetween(Vector2D other) {
        double dotProduct = dotProduct(other);
        double magnitudeProduct = getMagnitude() * other.getMagnitude();
        return Math.acos(dotProduct / magnitudeProduct);
    }

    public double crossProduct(Vector2D other) {
        return x * other.getY() - y * other.getX();
    }

    public Vector2D add(Vector2D other) {
        return new Vector2D(x + other.getX(), y + other.getY());
    }

    public Vector2D subtract(Vector2D other) {
        return new Vector2D(x - other.getX(), y - other.getY());
    }

    public Vector2D multiply(double scalar) {
        return new Vector2D(x * scalar, y * scalar);
    }

    public Vector2D projectOnto(Vector2D other) {
        double dotProduct = dotProduct(other);
        double magnitudeSquared = other.getMagnitude() * other.getMagnitude();
        double scalar = dotProduct / magnitudeSquared;
        return other.multiply(scalar);
    }

    public Vector2D perpendicular() {
        return new Vector2D(-y, x);
    }

    public Vector2D unitVector() {
        double magnitude = getMagnitude();
        if (magnitude != 0) {
            return new Vector2D(x / magnitude, y / magnitude);
        } else {
            throw new IllegalStateException("Cannot calculate unit vector for a zero vector.");
        }
    }

    public double angleWithXAxis() {
        return Math.atan2(y, x);
    }

    public double angleWithYAxis() {
        return Math.atan2(x, y);
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        Vector2D vector2D = (Vector2D) o;
        return Double.compare(vector2D.x, x) == 0 &&
                Double.compare(vector2D.y, y) == 0;
    }

    @Override
    public int hashCode() {
        return Objects.hash(x, y);
    }

    @Override
    public String toString() {
        return "(" + x + ", " + y + ")";
    }
}
```

