using System;

class Program
{
    static void Main()
    {
        // Prompt the user to enter a string
        Console.Write("Enter a string: ");
        string input = Console.ReadLine();

        // Remove leading and trailing spaces
        input = input.Trim();

        // Remove additional spaces between words
        input = RemoveExtraSpaces(input);

        // Convert the string to title case
        input = ToTitleCase(input);

        // Prompt the user to enter a specific word and its replacement
        Console.Write("Enter the specific word to be replaced: ");
        string specificWord = Console.ReadLine().Trim();

        Console.Write("Enter the replacement word: ");
        string replacementWord = Console.ReadLine().Trim();

        // Replace all occurrences of the specific word with the replacement word
        input = input.Replace(specificWord, replacementWord);

        // Output the final string
        Console.WriteLine(input);
    }

    static string RemoveExtraSpaces(string input)
    {
        string[] words = input.Split(' ', StringSplitOptions.RemoveEmptyEntries);
        return string.Join(' ', words);
    }

    static string ToTitleCase(string input)
    {
        string[] words = input.Split(' ');
        for (int i = 0; i < words.Length; i++)
        {
            if (!string.IsNullOrEmpty(words[i]))
            {
                string firstLetter = words[i][0].ToString().ToUpper();
                string remainingLetters = words[i].Substring(1).ToLower();
                words[i] = firstLetter + remainingLetters;
            }
        }
        return string.Join(' ', words);
    }
}
