public class LinearSearch 
{ 
    /**
     * Linear search implementation
     * 
     * @param arr the array of elements to search
     * @param target the element to search for
     * @return the index of the element if found, -1 otherwise
     */
    public static int linearSearch(int[] arr, int target) 
    { 
        for (int i = 0; i < arr.length; i++) 
        { 
            if (arr[i] == target) 
            { 
                return i; 
            } 
        } 
        return -1;
    } 
    public static void main(String[] args) 
    { 
        int[] arr = {7, 9, 15, 11};
        int target = 15; 
        int index = linearSearch(arr, target); 
        if (index == -1) 
            System.out.println("Element not found"); 
        else
            System.out.println("Element found at index: " + index); 
    } 
}

Here is a JavaScript function that validates a password based on the given rules:

```javascript
function validatePassword(password) {
  // Rule 1: The password must be at least 16 characters long.
  if (password.length < 16) {
    return false;
  }

  // Rule 2: The password must contain at least two uppercase letters and two lowercase letters.
  if (
    !/(?=(.*[A-Z]){2,})(?=(.*[a-z]){2,})/.test(password)
  ) {
    return false;
  }

  // Rule 3: The password must contain at least two special characters (!@#$%^&*).
  if (!/[!@#$%^&*]{2,}/.test(password)) {
    return false;
  }

  // Rule 4: The password must not contain any spaces.
  if (/\s/.test(password)) {
    return false;
  }

  // Rule 5: The password must not contain any consecutive repeating characters.
  if (/(.)\1{1,}/.test(password)) {
    return false;
  }

  // Rule 6: The password must not be a common password.
  const commonPasswords = [
    'password123',
    'qwerty',
    '123456',
    // Add more common passwords here...
  ];

  if (commonPasswords.includes(password)) {
    return false;
  }

  // Rule 7: The password must contain at least three numbers.
  if (
    !/(?=(.*\d){3,})/.test(password)
  ) {
    return false;
  }

  // If all rules pass, the password is valid.
  return true;
}
```

